INSERT INTO event VALUES('evt_0deeb1e040017wVHdSgM673x6m','ses_f211dfcd4ffevS1Yoddwab036g',462,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0deeb179d001b4mbIICGY8Pi59","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0deeb033b001d6j0ukgVYq4PWz","type":"text","text":"Confirmed a genuine bug in the installer. You''re on **Plasma/Wayland**, and it set `Theme=Blood` in `kdeglobals` — but no `Blood` icon theme exists anywhere. The repo has no `icons/` directory, so Plasma will fail to resolve the name and you''ll get missing icons across the desktop. The README even hints at the fix (\"inherits from BeautyLine + hicolor\") but the theme was never shipped.","time":{"start":1790446344093,"end":1790446345732}},"time":1790446345732}');
