INSERT INTO event VALUES('evt_0deeb3586001aXEseW1V65iXQt','ses_f211dfcd4ffevS1Yoddwab036g',479,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0deeb31e0001oWK9j15KCXIuz4","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0deeb2573001cH2dVOTa86gbEH","type":"tool","callID":"call_function_q638foyuon64_1","tool":"bash","state":{"status":"running","input":{"command":"set -e\nBLOOD=~/.local/share/icons/Blood\nmkdir -p \"$BLOOD\"\n# symlink every icon dir BeautyLine provides\nfor d in /usr/share/icons/BeautyLine/*/; do\n  ln -sfn \"${d%/}\" \"$BLOOD/$(basename \"$d\")\"\ndone\n# index.theme = BeautyLine''s, renamed, with documented fallback chain\nsed -e ''s/^Name=BeautyLine$/Name=Blood/'' \\\n    -e ''s/^Inherits=.*/Inherits=BeautyLine,hicolor/'' \\\n    /usr/share/icons/BeautyLine/index.theme > \"$BLOOD/index.theme\"\nls -la \"$BLOOD\"\necho \"--- verify resolution ---\"\nhead -3 \"$BLOOD/index.theme\""},"metadata":{"output":""},"time":{"start":1790446351750}}},"time":1790446351750}');
