INSERT INTO event VALUES('evt_0deee7672001JVJEWSHWJzZZFC','ses_f211dfcd4ffevS1Yoddwab036g',814,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0deee765d001K4AutcMZORNev8","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0deee5d7a001tMVNmbfmnsBcRg","type":"tool","callID":"call_function_t98wswwe0mzt_2","tool":"read","state":{"status":"completed","input":{"filePath":"/home/livings/.cache/paru/clone/hermes-agent/PKGBUILD"},"output":"<path>/home/livings/.cache/paru/clone/hermes-agent/PKGBUILD</path>\n<type>file</type>\n<content>\n1: # Maintainer: Youcef <youcef.nafa@gmail.com>\n2: # Co-maintainer: Evert <evorster at gmail dot com>\n3: # The Python environment is bundled because upstream pins a large, partly native\n4: # dependency set. uv''s relocatable mode keeps the packaged environment usable\n5: # after makepkg moves it under /opt.\n6: pkgname=hermes-agent\n7: pkgver=0.21.5\n8: _tagver=2026.9.24\n9: pkgrel=1\n10: pkgdesc=\"Locally-run AI agent with tool use, web browsing, and automation\"\n11: arch=(''x86_64'')\n12: url=\"https://github.com/NousResearch/hermes-agent\"\n13: license=(''MIT'')\n14: groups=()\n15: depends=(\n16:     ''python311''\n17:     ''nodejs''\n18:     ''uv''\n19:     ''ripgrep''\n20:     ''ffmpeg''\n21:     ''nss''\n22:     ''atk''\n23:     ''at-spi2-core''\n24:     ''cups''\n25:     ''libdrm''\n26:     ''libxkbcommon''\n27:     ''mesa''\n28:     ''pango''\n29:     ''cairo''\n30:     ''alsa-lib''\n31: )\n32: \n33: makedepends=(''npm'' ''rsync'')\n34: source=(\"${pkgname}-${_tagver}.tar.gz::https://github.com/NousResearch/hermes-agent/archive/refs/tags/v${_tagver}.tar.gz\")\n35: sha256sums=(''15b15ce4e6ec8ea424a081823709d1e17f0943e7b42b59597d24ebb94cbd1742'')\n36: validpgpkeys=()\n37: \n38: build() {\n39:   cd \"${pkgname}-${_tagver}\"\n40: \n41:   # vite-plugin-tailwindcss uses the ignore package which walks up the tree to read\n42:   # .gitignore files. Creating an empty .git directory stops the scan at this level.\n43:   [ ! -d .git ] && mkdir .git\n44: \n45:   npm ci --ignore-scripts --no-fund --no-audit --progress=false --include=dev\n46:   npm run build --workspace web\n47:   npm run build:ink --workspace ui-tui\n48:   npm run build --workspace ui-tui\n49: \n50:   UV_PYTHON_DOWNLOADS=never uv venv \\\n51:     --python /usr/bin/python3.11 \\\n52:     --relocatable \\\n53:     venv\n54:     \n55:   UV_PYTHON_DOWNLOADS=never \\\n56:     UV_PROJECT_ENVIRONMENT=\"$PWD/venv\" \\\n57:     uv lock \n58:   \n59:   UV_PYTHON_DOWNLOADS=never \\\n60:     UV_PROJECT_ENVIRONMENT=\"$PWD/venv\" \\\n61:     uv sync --locked --no-dev --no-install-project --extra all,messaging\n62: }\n63: \n64: check() {\n65:   cd \"${pkgname}-${_tagver}\"\n66: \n67:   test -s hermes_cli/web_dist/index.html\n68:   test -s ui-tui/dist/entry.js\n69:   PYTHONPATH=\"$PWD\" venv/bin/python -c ''import hermes_cli.main''\n70: }\n71: \n72: package() {\n73:   cd \"${pkgname}-${_tagver}\"\n74: \n75:   # Install to /opt\n76:   _optdir=\"$pkgdir/opt/$pkgname\"\n77:   install -d \"$_optdir\"\n78: \n79:   # Copy application files\n80:   rsync -a --exclude=''__pycache__'' --exclude=''.git'' \\\n81:   --exclude=''node_modules'' --exclude=''web/src'' \\\n82:   --exclude=''web/package.json'' --exclude=''web/package-lock.json'' \\\n83:   --exclude=''web/vite.config.ts'' --exclude=''web/tsconfig*.json'' \\\n84:   --exclude=''web/eslint.config.js'' --exclude=''web/README.md'' \\\n85:   --exclude=''ui-tui/src'' --exclude=''ui-tui/node_modules'' \\\n86:   --exclude=''scripts/tests'' --exclude=''scripts/install.*'' \\\n87:   --exclude=''build'' \\\n88:   . \"$_optdir/\"\n89: \n90:   echo \"console.log(''skipping build, using prebuilt dist/entry.js'')\" > \"$_optdir/ui-tui/scripts/build.mjs\"\n91: \n92:   # Ship the prebuilt TUI into hermes_cli/tui_dist/ so that\n93:   # _find_bundled_tui() finds it and skips the npm install step (which\n94:   # would fail with EACCES on the root-owned /opt tree).\n95:   # Note: hermes_cli is imported from /opt/hermes-agent/hermes_cli/ via\n96:   # the .pth file, NOT from the venv site-packages, so we copy there.\n97:   _tuidir=\"$_optdir/hermes_cli/tui_dist\"\n98:   install -d \"$_tuidir\"\n99:   if [ -d \"ui-tui/dist\" ]; then\n100:     cp -a ui-tui/dist/* \"$_tuidir/\"\n101:   fi\n102: \n103:   install -d \"$_optdir/venv/lib/python3.11/site-packages\"\n104:   {\n105:       echo \"import sys; sys.path.insert(0, \\\"/opt/$pkgname\\\")\"\n106:   } > \"$_optdir/venv/lib/python3.11/site-packages/hermes.pth\"\n107: \n108:   install -d \"$pkgdir/usr/bin\"\n109:   {\n110:     echo \"#!/bin/bash\"\n111:     echo \"unset PYTHONPATH\"\n112:     echo \"unset PYTHONHOME\"\n113:     echo '': \"${XDG_DATA_HOME:=$HOME/.local/share}\"''\n114:     echo ''export HERMES_DISABLE_LAZY_INSTALLS=1''\n115:     echo ''export HERMES_LAZY_INSTALL_TARGET=\"$XDG_DATA_HOME/hermes-agent/python\"''\n116:     echo \"exec /opt/$pkgname/venv/bin/python -m hermes_cli.main\" ''\"$@\"''\n117:   } > \"$pkgdir/usr/bin/hermes\"\n118: \n119:   chmod 755 \"$pkgdir/usr/bin/hermes\"\n120: \n121:   install -Dm644 LICENSE \"$pkgdir/usr/share/licenses/$pkgname/LICENSE\"\n122: }\n\n(End of file - total 122 lines)\n</content>","title":"home/livings/.cache/paru/clone/hermes-agent/PKGBUILD","metadata":{"preview":"# Maintainer: Youcef <youcef.nafa@gmail.com>\n# Co-maintainer: Evert <evorster at gmail dot com>\n# The Python environment is bundled because upstream pins a large, partly native\n# dependency set. uv''s relocatable mode keeps the packaged environment usable\n# after makepkg moves it under /opt.\npkgname=hermes-agent\npkgver=0.21.5\n_tagver=2026.9.24\npkgrel=1\npkgdesc=\"Locally-run AI agent with tool use, web browsing, and automation\"\narch=(''x86_64'')\nurl=\"https://github.com/NousResearch/hermes-agent\"\nlicense=(''MIT'')\ngroups=()\ndepends=(\n    ''python311''\n    ''nodejs''\n    ''uv''\n    ''ripgrep''\n    ''ffmpeg''","truncated":false,"loaded":[],"display":{"type":"file","path":"/home/livings/.cache/paru/clone/hermes-agent/PKGBUILD","text":"# Maintainer: Youcef <youcef.nafa@gmail.com>\n# Co-maintainer: Evert <evorster at gmail dot com>\n# The Python environment is bundled because upstream pins a large, partly native\n# dependency set. uv''s relocatable mode keeps the packaged environment usable\n# after makepkg moves it under /opt.\npkgname=hermes-agent\npkgver=0.21.5\n_tagver=2026.9.24\npkgrel=1\npkgdesc=\"Locally-run AI agent with tool use, web browsing, and automation\"\narch=(''x86_64'')\nurl=\"https://github.com/NousResearch/hermes-agent\"\nlicense=(''MIT'')\ngroups=()\ndepends=(\n    ''python311''\n    ''nodejs''\n    ''uv''\n    ''ripgrep''\n    ''ffmpeg''\n    ''nss''\n    ''atk''\n    ''at-spi2-core''\n    ''cups''\n    ''libdrm''\n    ''libxkbcommon''\n    ''mesa''\n    ''pango''\n    ''cairo''\n    ''alsa-lib''\n)\n\nmakedepends=(''npm'' ''rsync'')\nsource=(\"${pkgname}-${_tagver}.tar.gz::https://github.com/NousResearch/hermes-agent/archive/refs/tags/v${_tagver}.tar.gz\")\nsha256sums=(''15b15ce4e6ec8ea424a081823709d1e17f0943e7b42b59597d24ebb94cbd1742'')\nvalidpgpkeys=()\n\nbuild() {\n  cd \"${pkgname}-${_tagver}\"\n\n  # vite-plugin-tailwindcss uses the ignore package which walks up the tree to read\n  # .gitignore files. Creating an empty .git directory stops the scan at this level.\n  [ ! -d .git ] && mkdir .git\n\n  npm ci --ignore-scripts --no-fund --no-audit --progress=false --include=dev\n  npm run build --workspace web\n  npm run build:ink --workspace ui-tui\n  npm run build --workspace ui-tui\n\n  UV_PYTHON_DOWNLOADS=never uv venv \\\n    --python /usr/bin/python3.11 \\\n    --relocatable \\\n    venv\n    \n  UV_PYTHON_DOWNLOADS=never \\\n    UV_PROJECT_ENVIRONMENT=\"$PWD/venv\" \\\n    uv lock \n  \n  UV_PYTHON_DOWNLOADS=never \\\n    UV_PROJECT_ENVIRONMENT=\"$PWD/venv\" \\\n    uv sync --locked --no-dev --no-install-project --extra all,messaging\n}\n\ncheck() {\n  cd \"${pkgname}-${_tagver}\"\n\n  test -s hermes_cli/web_dist/index.html\n  test -s ui-tui/dist/entry.js\n  PYTHONPATH=\"$PWD\" venv/bin/python -c ''import hermes_cli.main''\n}\n\npackage() {\n  cd \"${pkgname}-${_tagver}\"\n\n  # Install to /opt\n  _optdir=\"$pkgdir/opt/$pkgname\"\n  install -d \"$_optdir\"\n\n  # Copy application files\n  rsync -a --exclude=''__pycache__'' --exclude=''.git'' \\\n  --exclude=''node_modules'' --exclude=''web/src'' \\\n  --exclude=''web/package.json'' --exclude=''web/package-lock.json'' \\\n  --exclude=''web/vite.config.ts'' --exclude=''web/tsconfig*.json'' \\\n  --exclude=''web/eslint.config.js'' --exclude=''web/README.md'' \\\n  --exclude=''ui-tui/src'' --exclude=''ui-tui/node_modules'' \\\n  --exclude=''scripts/tests'' --exclude=''scripts/install.*'' \\\n  --exclude=''build'' \\\n  . \"$_optdir/\"\n\n  echo \"console.log(''skipping build, using prebuilt dist/entry.js'')\" > \"$_optdir/ui-tui/scripts/build.mjs\"\n\n  # Ship the prebuilt TUI into hermes_cli/tui_dist/ so that\n  # _find_bundled_tui() finds it and skips the npm install step (which\n  # would fail with EACCES on the root-owned /opt tree).\n  # Note: hermes_cli is imported from /opt/hermes-agent/hermes_cli/ via\n  # the .pth file, NOT from the venv site-packages, so we copy there.\n  _tuidir=\"$_optdir/hermes_cli/tui_dist\"\n  install -d \"$_tuidir\"\n  if [ -d \"ui-tui/dist\" ]; then\n    cp -a ui-tui/dist/* \"$_tuidir/\"\n  fi\n\n  install -d \"$_optdir/venv/lib/python3.11/site-packages\"\n  {\n      echo \"import sys; sys.path.insert(0, \\\"/opt/$pkgname\\\")\"\n  } > \"$_optdir/venv/lib/python3.11/site-packages/hermes.pth\"\n\n  install -d \"$pkgdir/usr/bin\"\n  {\n    echo \"#!/bin/bash\"\n    echo \"unset PYTHONPATH\"\n    echo \"unset PYTHONHOME\"\n    echo '': \"${XDG_DATA_HOME:=$HOME/.local/share}\"''\n    echo ''export HERMES_DISABLE_LAZY_INSTALLS=1''\n    echo ''export HERMES_LAZY_INSTALL_TARGET=\"$XDG_DATA_HOME/hermes-agent/python\"''\n    echo \"exec /opt/$pkgname/venv/bin/python -m hermes_cli.main\" ''\"$@\"''\n  } > \"$pkgdir/usr/bin/hermes\"\n\n  chmod 755 \"$pkgdir/usr/bin/hermes\"\n\n  install -Dm644 LICENSE \"$pkgdir/usr/share/licenses/$pkgname/LICENSE\"\n}","lineStart":1,"lineEnd":122,"totalLines":122,"truncated":false}},"time":{"start":1790446564959,"end":1790446564978}}},"time":1790446564978}');
