web\n\n=== is engine-strict forced on? ===\n  src/.npmrc: # needed to prevent bad npm that has min-release-age but not exclude\n  src/.npmrc: engine-strict=true\n  src/.npmrc: \n  src/.npmrc: min-release-age=14\n  src/.npmrc: # allow assistant-ui packages & a couple specific deps since they update a LOT.\n  src/.npmrc: # remove this when we stabilize (or we haven''t updated in 2 wks)\n  src/.npmrc: min-release-age-exclude[]=@assistant-ui/*\n  src/.npmrc: min-release-age-exclude[]=assistant-cloud\n  src/.npmrc: min-release-age-exclude[]=assistant-stream\n  src/.npmrc: min-release-age-exclude[]=@radix-ui/*\n  src/.npmrc: min-release-age-exclude[]=radix-ui\n  src/.npmrc: min-release-age-exclude[]=safe-content-frame\n  src/.npmrc: \n  src/.npmrc: # react-router 8.3.0 includes fixes for vulns. remove this when 8.3.0 is > 2wks old.\n  src/.npmrc: min-release-age-exclude[]=react-router\n  src/.npmrc: \n  src/.npmrc: # eslint 10.8.0 includes fixes for vulns. remove this when 10.8.0 is > 2wks old.\n  src/.npmrc: min-release-age-exclude[]=eslint\n  src/.npmrc: min-release-age-exclude[]=@eslint/*\n  src/.npmrc: \n  src/.npmrc: # tar 7.5.21 includes fixes for vulns. remove this when 7.5.21 is > 2wks  old\n  src/.npmrc: min-release-age-exclude[]=tar\n  src/.npmrc: \n  src/.npmrc: # concurrently 10.0.4 includes fixes for vulns. remove this when 10.0.4 is > 2wks  old\n  src/.npmrc: min-release-age-exclude[]=concurrently\n  src/.npmrc: \n  src/.npmrc: # fast-uri 3.1.4 includes fixes for vulns. remove this when 3.1.4 is > 2wks  old\n  src/.npmrc: min-release-age-exclude[]=fast-uri\n  src/.npmrc: \n  src/.npmrc: # minimatch 10.2.6 includes fixes for vulns. remove this when 10.2.6 is > 2wks  old\n  src/.npmrc: min-release-age-exclude[]=minimatch\n  src/.npmrc: \n  src/.npmrc: \n  src/.npmrc: # brace-expansion 5.0.9 includes fixes for vulns. remove this when 5.0.9 is > 2wks  old\n  src/.npmrc: min-release-age-exclude[]=brace-expansion\n  src/.npmrc: \n  src/.npmrc: # js-yaml 4.3.1 incl