INSERT INTO event VALUES('evt_0def04917001ciaie78Mvv8FmL','ses_f211dfcd4ffevS1Yoddwab036g',1000,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0def03fc70017jJeKXXzIGQ4qL","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0def01dd8001P073EPsx9B4x9V","type":"text","text":"Passwordless sudo is the wrong lever here — that failure is **unprivileged**. It died in `build()`, before packaging. Real diagnosis:\n\n| | |\n|---|---|\n| Required | `node: ^22.22.0 \\|\\| ^24.11.0 \\|\\| >=26.0.0` |\n| Installed | `node v20.20.2` |\n| Enforced by | hermes-agent''s own `.npmrc` → `engine-strict=true` |\n\nThat''s an **AUR packaging bug**: `PKGBUILD:17` declares `depends=(''nodejs'')`, but upstream demands Node ≥22 and the repo now carries **26.10.0**. The maintainer''s dep is too loose, so it resolves to a Node that upstream refuses. Sudo can''t fix that; only a Node upgrade can.","time":{"start":1790446682055,"end":1790446684439}},"time":1790446684439}');
