INSERT INTO event VALUES('evt_0def10dca001nBHM9qQUfoS3za','ses_f211dfcd4ffevS1Yoddwab036g',1023,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0def10dc8002zHlIoePsFTUpzm","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0def10dc8001PBw96uqz86OuMx","type":"text","text":"sudo pacman -Rns nodejs-lts-iron && sudo pacman -S nodejs\n[sudo] password for livings:\nchecking dependencies...\nerror: failed to prepare transaction (could not satisfy dependencies)\n:: removing nodejs-lts-iron breaks dependency ''nodejs'' required by node-gyp\n:: removing nodejs-lts-iron breaks dependency ''nodejs'' required by nodejs-nopt\n:: removing nodejs-lts-iron breaks dependency ''nodejs>=20.17.0'' required by npm\n:: removing nodejs-lts-iron breaks dependency ''nodejs'' required by semver\n:: removing nodejs-lts-iron breaks dependency ''nodejs'' required by yarn "},"time":1790446734794}');
