INSERT INTO event VALUES('evt_0defe54d6001rfueCr1gbxHgQg','ses_f211dfcd4ffevS1Yoddwab036g',1171,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0defe4d1e001NXX8xhAk9nhS8F","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0defe2149001P9NiKqeKpPVzKo","type":"tool","callID":"call_function_33ysa4kbso05_1","tool":"bash","state":{"status":"running","input":{"command":"echo \"=== opencode sessions: total + date range ===\"\nsqlite3 -header -column /tmp/opencode/oc-snapshot.db \"\nSELECT COUNT(*) AS sessions, datetime(MIN(time_created)/1000,''unixepoch'') AS oldest,\n       datetime(MAX(time_created)/1000,''unixepoch'') AS newest FROM session;\" 2>&1\necho\necho \"=== hermes installed yet? (so: any hermes sessions?) ===\"\npacman -Q hermes-agent 2>&1 | head -1\nls ~/.hermes 2>&1\necho\necho \"=== machine age: earliest file in home ===\"\nfind /home/livings -maxdepth 2 -newermt \"2026-01-01\" -printf ''%T+ %p\\n'' 2>/dev/null | sort | head -3\necho\necho \"=== steam / proton / wine present? ===\"\nfor p in steam steam-native proton wine wine-staging; do pacman -Q $p >/dev/null 2>&1 && echo \"  installed: $p $(pacman -Q $p 2>/dev/null|awk ''{print $2}'')\" || echo \"  absent: $p\"; done\nls -d ~/.steam ~/.local/share/Steam 2>/dev/null | sed ''s/^/  /'' || echo \"  no steam data dirs\""},"metadata":{"output":""},"time":{"start":1790447604950}}},"time":1790447604950}');
