INSERT INTO event VALUES('evt_0df04175b001XLOvaAk0yNJytZ','ses_f211dfcd4ffevS1Yoddwab036g',1509,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df0412400015tirWrzxaiy4Cn","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df03f337001Ue0FKgYCOfUzoF","type":"tool","callID":"call_function_355nlm3xm31k_1","tool":"bash","state":{"status":"running","input":{"command":"chmod 600 ~/Desktop/token.txt\n# take the single-line token, strip trailing newline, store 600 outside Baloo''s reach\ntr -d ''\\n\\r'' < ~/Desktop/token.txt > ~/.config/gh/token.clean\nchmod 600 ~/.config/gh/token.clean\nprintf ''  stored token: %s chars\\n'' \"$(tr -d ''\\n'' < ~/.config/gh/token.clean | wc -c)\"\necho\necho \"=== token valid? (repo count) ===\"\ncurl -s -H \"Authorization: Bearer $(cat ~/.config/gh/token.clean)\" \\\n  \"https://api.github.com/user\" 2>&1 | python3 -c \"\nimport json,sys\nd=json.load(sys.stdin)\nif ''login'' in d:\n    print(f\\\"  AUTH OK as {d[''login'']}\\\")\n    print(f\\\"  token scope: {d.get(''scopes'',''(fine-grained - see header)'')}\\\")\nelse:\n    print(''  AUTH FAILED:'', d.get(''message''))\" 2>&1"},"metadata":{"output":""},"time":{"start":1790447982427}}},"time":1790447982427}');
