INSERT INTO event VALUES('evt_0df0429e2001QIsQEDH2X4HzXl','ses_f211dfcd4ffevS1Yoddwab036g',1525,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df0425af00124557RvHuvFOrF","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df041b760010tKgY7LipUlWMt","type":"tool","callID":"call_function_3svkjo5se1gl_1","tool":"bash","state":{"status":"running","input":{"command":"cd /tmp/opencode\nT=$(cat ~/.config/gh/token.clean)\n# page through ALL repos; -L follows pagination\ncurl -sL -H \"Authorization: Bearer $T\" \\\n  \"https://api.github.com/user/repos?per_page=100&affiliation=owner&sort=updated\" \\\n  -o allrepos.json\npython3 - <<''PY''\nimport json\nd=json.load(open(''/tmp/opencode/allrepos.json''))\nprint(f\"  TOTAL REPOS: {len(d)}\")\npub=[r for r in d if not r[''private'']]\npri=[r for r in d if r[''private'']]\nprint(f\"    public  : {len(pub)}\")\nprint(f\"    private : {len(pri)}\")\nprint(f\"    archived: {sum(1 for r in d if r[''archived''])}\")\nprint(f\"    forks   : {sum(1 for r in d if r[''fork''])}\")\nprint()\nfrom collections import Counter\nc=Counter((r[''language''] or ''-'') for r in d)\nprint(\"  by language:\")\nfor k,v in c.most_common(): print(f\"    {k:<22} {v}\")\nPY"},"time":{"start":1790447987170}}},"time":1790447987170}');
