INSERT INTO event VALUES('evt_0df0dde1b001NSOiHz9gmkyIAA','ses_f211dfcd4ffevS1Yoddwab036g',2021,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df0dd8ea001hLAkK9a2uyboq3","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df0dc9a600171vp0ELKhKajgu","type":"tool","callID":"call_function_3ovx977d1fir_1","tool":"bash","state":{"status":"running","input":{"command":"echo \"=== disk reality check ===\"\ndf -h /home /tmp / 2>/dev/null | grep -v tmpfs | sed ''s/^/  /''\necho\necho \"=== where the space actually goes ===\"\ndu -sh ~/.cache/paru 2>/dev/null | sed ''s/^/  paru build cache: /''\ndu -sh ~/.cache 2>/dev/null | sed ''s/^/  all user cache  : /''\ndu -sh ~/Projects 2>/dev/null | sed ''s/^/  Projects/        : /''\ndu -sh ~/.local 2>/dev/null | sed ''s/^/  ~/.local         : /''\necho\necho \"=== 120 repos, total clone size ===\"\npython3 -c \"\nimport json\nd=json.load(open(''/tmp/opencode/repos_all.json''))\nprint(f''  {len(d)} repos, {sum(r[\\\"size\\\"] for r in d)/1024:.0f} MB of git history total'')\""},"metadata":{"output":""},"time":{"start":1790448623131}}},"time":1790448623131}');
