INSERT INTO event VALUES('evt_0df0e3a29001oj274IlTBI2rqZ','ses_f211dfcd4ffevS1Yoddwab036g',2121,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df0e324c001vaw00NYfvQRUih","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df0e2b6d001bS2MP2Tz85p09N","type":"text","text":"Found why it''s stuck — and this one matters.\n\n`void-bin`''s PKGBUILD pulls `code.sh` from `gitlab.archlinux.org` via a `git`-based source, which Arch''s packaging **redirects to a full Chromium mirror clone**. So `paru -S void-bin` is silently cloning all of Chromium — a multi-gigabyte, multi-hour operation with no progress output. It''s been doing that for 50 minutes.\n\nThat''s a bug in the AUR packaging, not something you did. It''s also why \"once void is done downloading\" was never going to finish soon.","time":{"start":1790448644684,"end":1790448646697}},"time":1790448646697}');
