INSERT INTO event VALUES('evt_0df0eda97001PMHrK4ZC7NvczH','ses_f211dfcd4ffevS1Yoddwab036g',2164,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df0ed459001zkopfGMsKUXpbr","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df0eb6610014X1bp0cscKis0i","type":"tool","callID":"call_function_b9xo8g46rf4r_1","tool":"bash","state":{"status":"running","input":{"command":"cd /tmp/opencode\nT=$(cat ~/.config/gh/token.clean)\n# sample a few of the 16 Shell repos to learn house style, read-only\npython3 - <<''PY'' > shellrepos.txt\nimport json\nd=json.load(open(''/tmp/opencode/repos_all.json''))\nfor r in d:\n    if r[''language'']==''Shell'': print(r[''full_name''], r[''private''])\nPY\nhead -6 shellrepos.txt | sed ''s/^/  /''\necho\necho \"=== sample install.sh style from a Shell repo ===\"\nfor repo in $(head -2 shellrepos.txt | awk ''{print $1}''); do\n  echo \"  --- $repo ---\"\n  curl -s -H \"Authorization: Bearer $(cat ~/.config/gh/token.clean)\" \\\n    \"https://api.github.com/repos/$repo/contents/\" 2>/dev/null | python3 -c \"\nimport json,sys\ntry:\n  d=json.load(sys.stdin)\n  for f in d[:12]: print(''   '',f[''type''][0],f[''name''])\nexcept Exception as e: print(''    (err)'')\" 2>&1\ndone"},"time":{"start":1790448687767}}},"time":1790448687767}');
