INSERT INTO event VALUES('evt_0df13fc54001i7Ib75bOfBbSfW','ses_f211dfcd4ffevS1Yoddwab036g',2701,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df13f5b8001TRl86vcBETpNVh","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df13edfd001VsgayDlYns28Gf","type":"tool","callID":"call_function_eoyie1rib76s_1","tool":"bash","state":{"status":"running","input":{"command":"cd ~/Projects/hermes-blood\n# Bold: Great Vibes has only Regular on disk, so use synthetic emboldening via fontconfig\nmkdir -p ~/.config/fontconfig/conf.d\ncat > ~/.config/fontconfig/conf.d/99-greatvibes-bold.conf << ''EOF''\n<?xml version=\"1.0\"?>\n<!DOCTYPE fontconfig SYSTEM \"urn:fontconfig:fonts.dtd\">\n<fontconfig>\n  <!-- Great Vibes ships only a Regular weight. Synthesize a bolder outline\n       so bold text renders as bold instead of silently falling back to Regular. -->\n  <match target=\"pattern\">\n    <test name=\"family\"><string>Great Vibes</string></test>\n    <test name=\"weight\"><const>bold</const></test>\n    <edit name=\"embolden\" mode=\"assign\"><bool>true</bool></edit>\n  </match>\n</fontconfig>\nEOF\nfc-cache -f >/dev/null 2>&1\necho \"  [✓] synthetic bold rule written + fontconfig cache rebuilt\"\necho\necho \"=== does bold now resolve to a synthesized bold? ===\"\nfc-match \"Great Vibes:weight=bold\" | cut -d: -f2- | xargs | sed ''s/^/  /''"},"metadata":{"output":""},"time":{"start":1790449024084}}},"time":1790449024084}');
