INSERT INTO event VALUES('evt_0df14def9001GkzhaO7U25188O','ses_f211dfcd4ffevS1Yoddwab036g',2866,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df14d715001yabxH0XbFpjsDm","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df14cf13001eSi3HcaPMjYuSR","type":"tool","callID":"call_function_qu8dk2nathnv_1","tool":"edit","state":{"status":"running","input":{"filePath":"/home/livings/Projects/hermes-blood/scripts/install.sh","oldString":"cp \"$REPO_DIR/opencode/voidlit.json\" \"$HOME/.config/opencode/themes/voidlit.json\"\necho \"  [✓] OpenCode\"","newString":"cp \"$REPO_DIR/opencode/voidlit.json\" \"$HOME/.config/opencode/themes/voidlit.json\"\n\n# Also install to theme/ (opencode''s documented lookup path) and activate it.\n# Without the \"theme\" key in opencode.jsonc the file is inert.\nmkdir -p \"$HOME/.config/opencode/theme\"\ncp \"$REPO_DIR/opencode/voidlit.json\" \"$HOME/.config/opencode/theme/voidlit.json\"\n\nOC_CONFIG=\"$HOME/.config/opencode/opencode.jsonc\"\nif [ -f \"$OC_CONFIG\" ]; then\n    cp \"$OC_CONFIG\" \"$BACKUP_DIR/opencode.jsonc\" 2>/dev/null || true\n    if grep -q ''\"theme\"'' \"$OC_CONFIG\" 2>/dev/null; then\n        sed -i -E ''s/(\"theme\"[[:space:]]*:[[:space:]]*)\"[^\"]*\"/\\1\"voidlit\"/'' \"$OC_CONFIG\"\n    elif grep -q ''^\\s*\\{'' \"$OC_CONFIG\" 2>/dev/null; then\n        sed -i -E ''s/^(\\s*)\\}$/\\1  \"theme\": \"voidlit\"\\n}/'' \"$OC_CONFIG\"\n    else\n        printf ''{\\n  \"$schema\": \"https://opencode.ai/config.json\",\\n  \"theme\": \"voidlit\"\\n}\\n'' > \"$OC_CONFIG\"\n    fi\nfi\necho \"  [✓] OpenCode (voidlit installed + activated)\""},"time":{"start":1790449082105}}},"time":1790449082105}');
