INSERT INTO event VALUES('evt_0df1541ed0010pbxPL38g8wrMm','ses_f211dfcd4ffevS1Yoddwab036g',2948,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df153c68001vmsKUbhFkYwnH7","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df152570001cpR380iQxDehVJ","type":"tool","callID":"call_function_ijc7r9hsdqve_1","tool":"edit","state":{"status":"running","input":{"oldString":"import json, re, sys\np = sys.argv[1]\nraw = open(p).read()\n# strip // and /* */ comments that are not inside strings\nstripped = re.sub(r''/\\*.*?\\*/'', '''', raw, flags=re.S)\nstripped = re.sub(r''(?m)(^\\s*|[:,{}\\[\\]])//.*$'', r''\\1'', stripped)\ntry:\n    cfg = json.loads(stripped)\nexcept Exception:\n    sys.exit(1)\ncfg[''theme''] = ''voidlit''\nopen(p, ''w'').write(json.dumps(cfg, indent=2) + ''\\n'')","filePath":"/home/livings/Projects/hermes-blood/scripts/install.sh","newString":"import json, re, sys\n\ndef strip_comments(src):\n    \"\"\"Remove // and /* */ comments, skipping string literals so URLs survive.\"\"\"\n    out, i, n = [], 0, len(src)\n    while i < n:\n        c = src[i]\n        if c == ''\"'':\n            out.append(c); i += 1\n            while i < n:                      # copy string verbatim, honouring escapes\n                out.append(src[i])\n                if src[i] == ''\\\\'':\n                    i += 1\n                    if i < n: out.append(src[i])\n                elif src[i] == ''\"'':\n                    i += 1\n                    break\n                i += 1\n            continue\n        if src.startswith(''//'', i):\n            while i < n and src[i] != ''\\n'': i += 1\n            continue\n        if src.startswith(''/*'', i):\n            end = src.find(''*/'', i + 2)\n            i = n if end == -1 else end + 2\n            continue\n        out.append(c); i += 1\n    return ''''.join(out)\n\np = sys.argv[1]\ntry:\n    cfg = json.loads(strip_comments(open(p).read()))\nexcept Exception:\n    sys.exit(1)\ncfg[''theme''] = ''voidlit''\nopen(p, ''w'').write(json.dumps(cfg, indent=2) + ''\\n'')"},"time":{"start":1790449107437}}},"time":1790449107437}');
