30: echo \"[*] Installing systemd service...\"\n     31: sudo tee /etc/systemd/system/bde-daemon.service > /dev/null << SVCEOF\n     47: # 5) Install PAM config\n     48: echo \"[*] Installing PAM config...\"\n     49: sudo install -Dm644 \"$BDE_DIR/pam/modules/bde-auth.pam\" /etc/pam.d/bde-auth\n     54: sudo chmod 700 /var/lib/bde-daemon\n     81: echo \"  bde-auth              - PAM helper (called by system)\"\n     86: echo \"  3. Add to PAM (see docs/pam-bde-integration.md)\"\n"},"time":{"start":1790449162078}}},"time":1790449162343}');
