INSERT INTO event VALUES('evt_0df1ad5d0001v00yLyWzKN7Eli','ses_f211dfcd4ffevS1Yoddwab036g',3512,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df1ace11001lKaLsClYwiaYRR","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df1ac26b001fas7UUYvE43RWj","type":"tool","callID":"call_function_104wy4qsv5f7_1","tool":"edit","state":{"status":"running","input":{"filePath":"/home/livings/Projects/zen-hardening/faillock.conf","oldString":"# Failures are tracked per-user, not per-user-per-tty. Means one noisy\n# terminal cannot be used to lock you out of every other session.\ndeny_tally = user\n\n# --- Even counts (root) ---\n# NOT enabled. This is the setting that would exempt an account from\n# locking entirely, and it is deliberately left off: it applies to root by\n# default, and turning it on for a normal admin account is the mechanism\n# an attacker would target.\n\n# --- Logging ---\n# Log denials to authpriv so failed attempts are visible in the journal.\n# Useful when a real intrusion attempt is the reason for a lockout.\naudit = silent","newString":"# --- Even counts (root) ---\n# NOT enabled. This is the setting that would exempt an account from\n# locking entirely, and it is deliberately left off: it applies to root by\n# default, and turning it on for a normal admin account is the mechanism\n# an attacker would target.\n\n# --- Logging ---\n# audit = silent logs the user name when an unknown user attempts login.\n# That is the brute-force-enumeration signal: watching for it makes a\n# password-spraying attempt visible in the journal.\naudit = silent"},"time":{"start":1790449472976}}},"time":1790449472976}');
INSERT INTO event VALUES('evt_0df1ad5d4001n2M7Oq864BPSQ9','ses_f211dfcd4ffevS1Yoddwab036g',3513,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df1ace11001lKaLsClYwiaYRR","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df1ac26b001fas7UUYvE43RWj","type":"tool","callID":"call_function_104wy4qsv5f7_1","tool":"edit","state":{"status":"running","input":{"filePath":"/home/livings/Projects/zen-hardening/faillock.conf","oldString":"# Failures are tracked per-user, not per-user-per-tty. Means one noisy\n# terminal cannot be used to lock you out of every other session.\ndeny_tally = user\n\n# --- Even counts (root) ---\n# NOT enabled. This is the setting that would exempt an account from\n# locking entirely, and it is deliberately left off: it applies to root by\n# default, and turning it on for a normal admin account is the mechanism\n# an attacker would target.\n\n# --- Logging ---\n# Log denials to authpriv so failed attempts are visible in the journal.\n# Useful when a real intrusion attempt is the reason for a lockout.\naudit = silent","newString":"# --- Even counts (root) ---\n# NOT enabled. This is the setting that would exempt an account from\n# locking entirely, and it is deliberately left off: it applies to root by\n# default, and turning it on for a normal admin account is the mechanism\n# an attacker would target.\n\n# --- Logging ---\n# audit = silent logs the user name when an unknown user attempts login.\n# That is the brute-force-enumeration signal: watching for it makes a\n# password-spraying attempt visible in the journal.\naudit = silent"},"metadata":{"diff":"Index: /home/livings/Projects/zen-hardening/faillock.conf\n===================================================================\n--- /home/livings/Projects/zen-hardening/faillock.conf\n+++ /home/livings/Projects/zen-hardening/faillock.conf\n@@ -23,18 +23,15 @@\n # from a single attempt, short enough that a fat-fingered admin is never\n # stranded. Default is 600s (10 min).\n unlock_time = 1800\n \n-# Failures are tracked per-user, not per-user-per-tty. Means one noisy\n-# terminal cannot be used to lock you out of every other session.\n-deny_tally = user\n-\n # --- Even counts (root) ---\n # NOT enabled. This is the setting that would exempt an account from\n # locking entirely, and it is deliberately left off: it applies to root by\n # default, and turning it on for a normal admin account is the mechanism\n # an attacker would target.\n \n # --- Logging ---\n-# Log denials to authpriv so failed attempts are visible in the journal.\n-# Useful when a real intrusion attempt is the reason for a lockout.\n+# audit = silent logs the user name when an unknown user attempts login.\n+# That is the brute-force-enumeration signal: watching for it makes a\n+# password-spraying attempt visible in the journal.\n audit = silent\n","filediff":{"file":"/home/livings/Projects/zen-hardening/faillock.conf","patch":"Index: /home/livings/Projects/zen-hardening/faillock.conf\n===================================================================\n--- /home/livings/Projects/zen-hardening/faillock.conf\n+++ /home/livings/Projects/zen-hardening/faillock.conf\n@@ -23,18 +23,15 @@\n # from a single attempt, short enough that a fat-fingered admin is never\n # stranded. Default is 600s (10 min).\n unlock_time = 1800\n \n-# Failures are tracked per-user, not per-user-per-tty. Means one noisy\n-# terminal cannot be used to lock you out of every other session.\n-deny_tally = user\n-\n # --- Even counts (root) ---\n # NOT enabled. This is the setting that would exempt an account from\n # locking entirely, and it is deliberately left off: it applies to root by\n # default, and turning it on for a normal admin account is the mechanism\n # an attacker would target.\n \n # --- Logging ---\n-# Log denials to authpriv so failed attempts are visible in the journal.\n-# Useful when a real intrusion attempt is the reason for a lockout.\n+# audit = silent logs the user name when an unknown user attempts login.\n+# That is the brute-force-enumeration signal: watching for it makes a\n+# password-spraying attempt visible in the journal.\n audit = silent\n","additions":3,"deletions":6},"diagnostics":{}},"time":{"start":1790449472976}}},"time":1790449472980}');
