INSERT INTO event VALUES('evt_0df1b8bb4001syzREq9Rg3boAL','ses_f20e5cfc2ffeSFa4odnoYLiUOk',162,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df1b7c9d001lAaxCBzwUUAKFL","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df1b6e7a001j75u5H2HGfILqR","type":"tool","callID":"call_function_133ztc0381vy_1","tool":"read","state":{"status":"completed","input":{"filePath":"/usr/share/makepkg/source/git.sh"},"output":"<path>/usr/share/makepkg/source/git.sh</path>\n<type>file</type>\n<content>\n1: #!/usr/bin/bash\n2: #\n3: #   git.sh - function for handling the download and \"extraction\" of Git sources\n4: #\n5: #   Copyright (c) 2015-2025 Pacman Development Team <pacman-dev@lists.archlinux.org>\n6: #\n7: #   This program is free software; you can redistribute it and/or modify\n8: #   it under the terms of the GNU General Public License as published by\n9: #   the Free Software Foundation; either version 2 of the License, or\n10: #   (at your option) any later version.\n11: #\n12: #   This program is distributed in the hope that it will be useful,\n13: #   but WITHOUT ANY WARRANTY; without even the implied warranty of\n14: #   MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n15: #   GNU General Public License for more details.\n16: #\n17: #   You should have received a copy of the GNU General Public License\n18: #   along with this program.  If not, see <http://www.gnu.org/licenses/>.\n19: #\n20: \n21: [[ -n \"$LIBMAKEPKG_SOURCE_GIT_SH\" ]] && return\n22: LIBMAKEPKG_SOURCE_GIT_SH=1\n23: \n24: \n25: MAKEPKG_LIBRARY=${MAKEPKG_LIBRARY:-''/usr/share/makepkg''}\n26: \n27: source \"$MAKEPKG_LIBRARY/util/error.sh\"\n28: source \"$MAKEPKG_LIBRARY/util/message.sh\"\n29: source \"$MAKEPKG_LIBRARY/util/pkgbuild.sh\"\n30: \n31: export GIT_CONFIG_GLOBAL=/dev/null\n32: export GIT_CONFIG_SYSTEM=${MAKEPKG_GIT_CONFIG:-''/etc/makepkg.d/gitconfig''}\n33: \n34: download_git() {\n35: \t# abort early if parent says not to fetch\n36: \tif declare -p get_vcs > /dev/null 2>&1; then\n37: \t\t(( get_vcs )) || return\n38: \tfi\n39: \n40: \tlocal netfile=$1\n41: \n42: \tlocal dir=$(get_filepath \"$netfile\")\n43: \t[[ -z \"$dir\" ]] && dir=\"$SRCDEST/$(get_filename \"$netfile\")\"\n44: \n45: \tlocal repo=$(get_filename \"$netfile\")\n46: \n47: \tlocal url=$(get_url \"$netfile\")\n48: \turl=${url#git+}\n49: \turl=${url%%#*}\n50: \turl=${url%%\\?*}\n51: \n52: \tif [[ ! -d \"$dir\" ]] || dir_is_empty \"$dir\" ; then\n53: \t\tmsg2 \"$(gettext \"Cloning %s %s repo...\")\" \"${repo}\" \"git\"\n54: \t\tif ! git clone --origin=origin --mirror \"$url\" \"$dir\"; then\n55: \t\t\terror \"$(gettext \"Failure while downloading %s %s repo\")\" \"${repo}\" \"git\"\n56: \t\t\tplainerr \"$(gettext \"Aborting...\")\"\n57: \t\t\texit 1\n58: \t\tfi\n59: \telif (( ! HOLDVER )); then\n60: \t\tcd_safe \"$dir\"\n61: \t\t# When invoking git on a potentially bare repository, we should pass -c safe.bareRepository=all\n62: \t\t# to avoid breaking when the option is globally set to explicit\n63: \n64: \t\t# Make sure we are fetching the right repo\n65: \t\tlocal remote_url=\"$(git -c safe.bareRepository=all config --get remote.origin.url)\"\n66: \t\tif [[ \"${url%%.git}\" != \"${remote_url%%.git}\" ]] ; then\n67: \t\t\terror \"$(gettext \"%s is not a clone of %s\")\" \"$dir\" \"$url\"\n68: \t\t\tplainerr \"$(gettext \"Aborting...\")\"\n69: \t\t\texit $E_NOT_A_CLONE_OF\n70: \t\tfi\n71: \t\tmsg2 \"$(gettext \"Updating %s %s repo...\")\" \"${repo}\" \"git\"\n72: \t\tif ! git -c safe.bareRepository=all fetch --all -p; then\n73: \t\t\t# only warn on failure to allow offline builds\n74: \t\t\twarning \"$(gettext \"Failure while updating %s %s repo\")\" \"${repo}\" \"git\"\n75: \t\tfi\n76: \tfi\n77: \n78: \t# Sanitize the cloned repo\n79: \t# $GIT_DIR/info/attributes overrides .gitattributes, and thus no files in the repository\n80: \t# can be altered by git features like export-subst or export-ignore\n81: \tlocal MAKEPKG_GIT_DIR=\"$(git -c safe.bareRepository=all -C \"$dir\" rev-parse --absolute-git-dir)\"\n82: \tmkdir -p \"$MAKEPKG_GIT_DIR/info\"\n83: \techo \"* -export-subst -export-ignore\" > \"$MAKEPKG_GIT_DIR/info/attributes\"\n84: }\n85: \n86: extract_git() {\n87: \tlocal netfile=$1 tagname\n88: \n89: \tlocal fragment=$(get_uri_fragment \"$netfile\")\n90: \tlocal repo=$(get_filename \"$netfile\")\n91: \n92: \tlocal dir=$(get_filepath \"$netfile\")\n93: \t[[ -z \"$dir\" ]] && dir=\"$SRCDEST/$(get_filename \"$netfile\")\"\n94: \n95: \tmsg2 \"$(gettext \"Creating working copy of %s %s repo...\")\" \"${repo}\" \"git\"\n96: \tpushd \"$srcdir\" &>/dev/null\n97: \n98: \tlocal updating=0\n99: \tif [[ -d \"${dir##*/}\" ]]; then\n100: \t\tupdating=1\n101: \t\tcd_safe \"${dir##*/}\"\n102: \t\tif ! git fetch; then\n103: \t\t\terror \"$(gettext \"Failure while updating working copy of %s %s repo\")\" \"${repo}\" \"git\"\n104: \t\t\tplainerr \"$(gettext \"Aborting...\")\"\n105: \t\t\texit 1\n106: \t\tfi\n107: \t\tcd_safe \"$srcdir\"\n108: \telif ! git clone --origin=origin -s \"$dir\" \"${dir##*/}\"; then\n109: \t\terror \"$(gettext \"Failure while creating working copy of %s %s repo\")\" \"${repo}\" \"git\"\n110: \t\tplainerr \"$(gettext \"Aborting...\")\"\n111: \t\texit 1\n112: \tfi\n113: \n114: \tcd_safe \"${dir##*/}\"\n115: \n116: \tlocal ref=origin/HEAD\n117: \tif [[ -n $fragment ]]; then\n118: \t\tcase ${fragment%%=*} in\n119: \t\t\tcommit|tag)\n120: \t\t\t\tref=${fragment##*=}\n121: \t\t\t\t;;\n122: \t\t\tbranch)\n123: \t\t\t\tref=origin/${fragment##*=}\n124: \t\t\t\t;;\n125: \t\t\t*)\n126: \t\t\t\terror \"$(gettext \"Unrecognized reference: %s\")\" \"${fragment}\"\n127: \t\t\t\tplainerr \"$(gettext \"Aborting...\")\"\n128: \t\t\t\texit 1\n129: \t\tesac\n130: \tfi\n131: \n132: \tif [[ ${fragment%%=*} = tag ]]; then\n133: \t\ttagname=\"$(git tag -l --format=''%(tag)'' \"$ref\")\"\n134: \t\tif [[ -n $tagname && $tagname != \"$ref\" ]]; then\n135: \t\t\terror \"$(gettext \"Failure while checking out version %s, the git tag has been forged\")\" \"$ref\"\n136: \t\t\tplainerr \"$(gettext \"Aborting...\")\"\n137: \t\t\texit 1\n138: \t\tfi\n139: \tfi\n140: \n141: \tif [[ $ref != \"origin/HEAD\" ]] || (( updating )) ; then\n142: \t\tif ! git checkout --force --no-track -B makepkg \"$ref\" --; then\n143: \t\t\terror \"$(gettext \"Failure while creating working copy of %s %s repo\")\" \"${repo}\" \"git\"\n144: \t\t\tplainerr \"$(gettext \"Aborting...\")\"\n145: \t\t\texit 1\n146: \t\tfi\n147: \tfi\n148: \n149: \tpopd &>/dev/null\n150: }\n151: \n152: calc_checksum_git() {\n153: \tlocal netfile=$1 integ=$2 ret=0 shellopts dir url fragment sum\n154: \n155: \t# this function requires pipefail - save current status to restore later\n156: \tshellopts=$(shopt -p -o pipefail)\n157: \tshopt -s -o pipefail\n158: \n159: \tdir=$(get_filepath \"$netfile\")\n160: \turl=$(get_url \"$netfile\")\n161: \tfragment=$(get_uri_fragment \"$url\")\n162: \n163: \tcase ${fragment%%=*} in\n164: \t\ttag|commit)\n165: \t\t\tfragval=${fragment##*=}\n166: \t\t\tsum=$(git -c core.abbrev=no -C \"$dir\" archive --format tar \"$fragval\" | \"${integ}sum\" 2>&1) || ret=1\n167: \t\t\tsum=\"${sum%% *}\"\n168: \t\t\t;;\n169: \t\t*)\n170: \t\t\tsum=\"SKIP\"\n171: \t\t\t;;\n172: \tesac\n173: \n174: \teval \"$shellopts\"\n175: \tprintf ''%s'' \"$sum\"\n176: \treturn $ret\n177: }\n\n(End of file - total 177 lines)\n</content>","title":"usr/share/makepkg/source/git.sh","metadata":{"preview":"#!/usr/bin/bash\n#\n#   git.sh - function for handling the download and \"extraction\" of Git sources\n#\n#   Copyright (c) 2015-2025 Pacman Development Team <pacman-dev@lists.archlinux.org>\n#\n#   This program is free software; you can redistribute it and/or modify\n#   it under the terms of the GNU General Public License as published by\n#   the Free Software Foundation; either version 2 of the License, or\n#   (at your option) any later version.\n#\n#   This program is distributed in the hope that it will be useful,\n#   but WITHOUT ANY WARRANTY; without even the implied warranty of\n#   MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n#   GNU General Public License for more details.\n#\n#   You should have received a copy of the GNU General Public License\n#   along with this program.  If not, see <http://www.gnu.org/licenses/>.\n#\n","truncated":false,"loaded":[],"display":{"type":"file","path":"/usr/share/makepkg/source/git.sh","text":"#!/usr/bin/bash\n#\n#   git.sh - function for handling the download and \"extraction\" of Git sources\n#\n#   Copyright (c) 2015-2025 Pacman Development Team <pacman-dev@lists.archlinux.org>\n#\n#   This program is free software; you can redistribute it and/or modify\n#   it under the terms of the GNU General Public License as published by\n#   the Free Software Foundation; either version 2 of the License, or\n#   (at your option) any later version.\n#\n#   This program is distributed in the hope that it will be useful,\n#   but WITHOUT ANY WARRANTY; without even the implied warranty of\n#   MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n#   GNU General Public License for more details.\n#\n#   You should have received a copy of the GNU General Public License\n#   along with this program.  If not, see <http://www.gnu.org/licenses/>.\n#\n\n[[ -n \"$LIBMAKEPKG_SOURCE_GIT_SH\" ]] && return\nLIBMAKEPKG_SOURCE_GIT_SH=1\n\n\nMAKEPKG_LIBRARY=${MAKEPKG_LIBRARY:-''/usr/share/makepkg''}\n\nsource \"$MAKEPKG_LIBRARY/util/error.sh\"\nsource \"$MAKEPKG_LIBRARY/util/message.sh\"\nsource \"$MAKEPKG_LIBRARY/util/pkgbuild.sh\"\n\nexport GIT_CONFIG_GLOBAL=/dev/null\nexport GIT_CONFIG_SYSTEM=${MAKEPKG_GIT_CONFIG:-''/etc/makepkg.d/gitconfig''}\n\ndownload_git() {\n\t# abort early if parent says not to fetch\n\tif declare -p get_vcs > /dev/null 2>&1; then\n\t\t(( get_vcs )) || return\n\tfi\n\n\tlocal netfile=$1\n\n\tlocal dir=$(get_filepath \"$netfile\")\n\t[[ -z \"$dir\" ]] && dir=\"$SRCDEST/$(get_filename \"$netfile\")\"\n\n\tlocal repo=$(get_filename \"$netfile\")\n\n\tlocal url=$(get_url \"$netfile\")\n\turl=${url#git+}\n\turl=${url%%#*}\n\turl=${url%%\\?*}\n\n\tif [[ ! -d \"$dir\" ]] || dir_is_empty \"$dir\" ; then\n\t\tmsg2 \"$(gettext \"Cloning %s %s repo...\")\" \"${repo}\" \"git\"\n\t\tif ! git clone --origin=origin --mirror \"$url\" \"$dir\"; then\n\t\t\terror \"$(gettext \"Failure while downloading %s %s repo\")\" \"${repo}\" \"git\"\n\t\t\tplainerr \"$(gettext \"Aborting...\")\"\n\t\t\texit 1\n\t\tfi\n\telif (( ! HOLDVER )); then\n\t\tcd_safe \"$dir\"\n\t\t# When invoking git on a potentially bare repository, we should pass -c safe.bareRepository=all\n\t\t# to avoid breaking when the option is globally set to explicit\n\n\t\t# Make sure we are fetching the right repo\n\t\tlocal remote_url=\"$(git -c safe.bareRepository=all config --get remote.origin.url)\"\n\t\tif [[ \"${url%%.git}\" != \"${remote_url%%.git}\" ]] ; then\n\t\t\terror \"$(gettext \"%s is not a clone of %s\")\" \"$dir\" \"$url\"\n\t\t\tplainerr \"$(gettext \"Aborting...\")\"\n\t\t\texit $E_NOT_A_CLONE_OF\n\t\tfi\n\t\tmsg2 \"$(gettext \"Updating %s %s repo...\")\" \"${repo}\" \"git\"\n\t\tif ! git -c safe.bareRepository=all fetch --all -p; then\n\t\t\t# only warn on failure to allow offline builds\n\t\t\twarning \"$(gettext \"Failure while updating %s %s repo\")\" \"${repo}\" \"git\"\n\t\tfi\n\tfi\n\n\t# Sanitize the cloned repo\n\t# $GIT_DIR/info/attributes overrides .gitattributes, and thus no files in the repository\n\t# can be altered by git features like export-subst or export-ignore\n\tlocal MAKEPKG_GIT_DIR=\"$(git -c safe.bareRepository=all -C \"$dir\" rev-parse --absolute-git-dir)\"\n\tmkdir -p \"$MAKEPKG_GIT_DIR/info\"\n\techo \"* -export-subst -export-ignore\" > \"$MAKEPKG_GIT_DIR/info/attributes\"\n}\n\nextract_git() {\n\tlocal netfile=$1 tagname\n\n\tlocal fragment=$(get_uri_fragment \"$netfile\")\n\tlocal repo=$(get_filename \"$netfile\")\n\n\tlocal dir=$(get_filepath \"$netfile\")\n\t[[ -z \"$dir\" ]] && dir=\"$SRCDEST/$(get_filename \"$netfile\")\"\n\n\tmsg2 \"$(gettext \"Creating working copy of %s %s repo...\")\" \"${repo}\" \"git\"\n\tpushd \"$srcdir\" &>/dev/null\n\n\tlocal updating=0\n\tif [[ -d \"${dir##*/}\" ]]; then\n\t\tupdating=1\n\t\tcd_safe \"${dir##*/}\"\n\t\tif ! git fetch; then\n\t\t\terror \"$(gettext \"Failure while updating working copy of %s %s repo\")\" \"${repo}\" \"git\"\n\t\t\tplainerr \"$(gettext \"Aborting...\")\"\n\t\t\texit 1\n\t\tfi\n\t\tcd_safe \"$srcdir\"\n\telif ! git clone --origin=origin -s \"$dir\" \"${dir##*/}\"; then\n\t\terror \"$(gettext \"Failure while creating working copy of %s %s repo\")\" \"${repo}\" \"git\"\n\t\tplainerr \"$(gettext \"Aborting...\")\"\n\t\texit 1\n\tfi\n\n\tcd_safe \"${dir##*/}\"\n\n\tlocal ref=origin/HEAD\n\tif [[ -n $fragment ]]; then\n\t\tcase ${fragment%%=*} in\n\t\t\tcommit|tag)\n\t\t\t\tref=${fragment##*=}\n\t\t\t\t;;\n\t\t\tbranch)\n\t\t\t\tref=origin/${fragment##*=}\n\t\t\t\t;;\n\t\t\t*)\n\t\t\t\terror \"$(gettext \"Unrecognized reference: %s\")\" \"${fragment}\"\n\t\t\t\tplainerr \"$(gettext \"Aborting...\")\"\n\t\t\t\texit 1\n\t\tesac\n\tfi\n\n\tif [[ ${fragment%%=*} = tag ]]; then\n\t\ttagname=\"$(git tag -l --format=''%(tag)'' \"$ref\")\"\n\t\tif [[ -n $tagname && $tagname != \"$ref\" ]]; then\n\t\t\terror \"$(gettext \"Failure while checking out version %s, the git tag has been forged\")\" \"$ref\"\n\t\t\tplainerr \"$(gettext \"Aborting...\")\"\n\t\t\texit 1\n\t\tfi\n\tfi\n\n\tif [[ $ref != \"origin/HEAD\" ]] || (( updating )) ; then\n\t\tif ! git checkout --force --no-track -B makepkg \"$ref\" --; then\n\t\t\terror \"$(gettext \"Failure while creating working copy of %s %s repo\")\" \"${repo}\" \"git\"\n\t\t\tplainerr \"$(gettext \"Aborting...\")\"\n\t\t\texit 1\n\t\tfi\n\tfi\n\n\tpopd &>/dev/null\n}\n\ncalc_checksum_git() {\n\tlocal netfile=$1 integ=$2 ret=0 shellopts dir url fragment sum\n\n\t# this function requires pipefail - save current status to restore later\n\tshellopts=$(shopt -p -o pipefail)\n\tshopt -s -o pipefail\n\n\tdir=$(get_filepath \"$netfile\")\n\turl=$(get_url \"$netfile\")\n\tfragment=$(get_uri_fragment \"$url\")\n\n\tcase ${fragment%%=*} in\n\t\ttag|commit)\n\t\t\tfragval=${fragment##*=}\n\t\t\tsum=$(git -c core.abbrev=no -C \"$dir\" archive --format tar \"$fragval\" | \"${integ}sum\" 2>&1) || ret=1\n\t\t\tsum=\"${sum%% *}\"\n\t\t\t;;\n\t\t*)\n\t\t\tsum=\"SKIP\"\n\t\t\t;;\n\tesac\n\n\teval \"$shellopts\"\n\tprintf ''%s'' \"$sum\"\n\treturn $ret\n}","lineStart":1,"lineEnd":177,"totalLines":177,"truncated":false}},"time":{"start":1790449515683,"end":1790449519540}}},"time":1790449519540}');
