INSERT INTO event VALUES('evt_0df1ce8430018HxAdfvtE0T7C1','ses_f20e5cfc2ffeSFa4odnoYLiUOk',176,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df1cdb6b001lcoSgqyPLokXVn","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df1b8bbd001vEcIYds2eZwNSO","type":"text","text":"Confirmed the exact failure point in `git.sh:54` — makepkg runs `git clone --origin=origin --mirror` for VCS sources, which is an **unshallow full-history mirror** of `chromium/chromium` (37 GiB, 29.5M objects). That''s what died.\n\nReading the rest of `git.sh` gives me the fix: if `$dir` already exists, `download_git` only does `git fetch --all -p` and treats failure as a *warning* (`git.sh:72-74`). So a pre-seeded **shallow** mirror is fully sufficient — `calc_checksum_git` only needs the tag, and `extract_git` clones from it locally.","time":{"start":1790449605484,"end":1790449608771}},"time":1790449608771}');
