INSERT INTO event VALUES('evt_0df1d405a001J3rRPtNomxh26g','ses_f20e5cfc2ffeSFa4odnoYLiUOk',225,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df1d3bd3001e0j4MTyVVC5i53","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df1d2981001pRmVYfD9blkm4I","type":"text","text":"No `SRCDEST` and no makepkg gitconfig, so sources live in the build dir itself. Now seeding a **shallow** mirror — I deliberately avoid `--mirror` on the clone command itself, because `git clone --mirror` uses refspec `+refs/*:refs/*` and would shallow-fetch all ~200k release branch tips. Instead I init bare and fetch exactly one ref:","time":{"start":1790449630163,"end":1790449631322}},"time":1790449631322}');
