INSERT INTO event VALUES('evt_0df201004001cgPw0WPS4QmPgD','ses_f211dfcd4ffevS1Yoddwab036g',3970,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df200c3e001eeQPqbAbeyqVXn","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df2004e2001UlRq5tI51hZbJh","type":"reasoning","text":"The `faillock_denial` rule matches \"faillock\" anywhere, which catches the user''s own `sudo cp /etc/security/faillock.conf` commands. That''s a false positive — it''s the admin doing legitimate work. I need to tighten the rule: require actual pam_faillock denials, not just the word \"faillock\".\n\nReal pam_faillock denial lines look like:\n- `pam_faillock(preauth): ... Authentication failure`\n- `User livings (uid=1000) tries to authenticate but locked out`\n- `pam_faillock(authfail): auth fail; user=...`\n\nLet me fix this to be much more specific.","time":{"start":1790449814590,"end":1790449815556}},"time":1790449815556}');
