INSERT INTO event VALUES('evt_0df201523001Codl32A7wW9U9p','ses_f211dfcd4ffevS1Yoddwab036g',3973,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df2010e3001ZdG6oFMtpR4Ao5","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df2004e2001UlRq5tI51hZbJh","type":"tool","callID":"call_function_g8h3lacdzwal_1","tool":"edit","state":{"status":"running","input":{"oldString":"    (\n        \"faillock_denial\",\n        re.compile(r\"faillock|account .* locked|Unlocking account\", re.I),\n        \"ACCOUNT LOCKOUT TRIGGERED\",\n        \"critical\",\n    ),","filePath":"/home/livings/Projects/nyan-gfsf-alert/gfsf-watch.py","newString":"    (\n        # Match pam_faillock''s ACTUAL denial output, not the bare word\n        # \"faillock\" — otherwise this fires on the admin''s own\n        # `sudo cp /etc/security/faillock.conf` commands.\n        \"faillock_denial\",\n        re.compile(\n            r\"(tries to authenticate but locked out\"\n            r\"|pam_faillock\\(authfail\\)\"\n            r\"|pam_faillock\\(preauth\\).*(fail|denied)\"\n            r\"|Unlocking account \\S+)\"\n        ),\n        \"ACCOUNT LOCKOUT TRIGGERED\",\n        \"critical\",\n    ),"},"time":{"start":1790449816867}}},"time":1790449816867}');
