INSERT INTO event VALUES('evt_0df203702001Jlaeg5ZrgtLIBe','ses_f211dfcd4ffevS1Yoddwab036g',4001,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df2033260018agDm0ByRohI5Q","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df2028cf0010Gb8NyooPMVFY6","type":"tool","callID":"call_function_4bhbkuzp764w_1","tool":"edit","state":{"status":"running","input":{"oldString":"    (\n        \"sudo_failure\",\n        re.compile(r\"sudo:.*(incorrect password|authentication failure|a password is required)\", re.I),\n        \"UNAUTHORIZED PRIVILEGE ESCALATION\",\n        \"critical\",\n    ),","filePath":"/home/livings/Projects/nyan-gfsf-alert/gfsf-watch.py","newString":"    (\n        # sudo: the actor name is the field right after \"sudo:\". \"a password\n        # is required\" fires on every non-interactive sudo attempt, including\n        # the admin''s own — so only flag it when the actor is NOT the local\n        # user. \"incorrect password\" is always a real failure.\n        \"sudo_failure\",\n        re.compile(r\"sudo:.*incorrect password\", re.I),\n        \"UNAUTHORIZED PRIVILEGE ESCALATION\",\n        \"critical\",\n    ),\n    (\n        # Non-interactive sudo attempt from someone other than us.\n        \"sudo_unattended\",\n        re.compile(r\"sudo:\\s*(?P<actor>\\w+)\\s*:.*a password is required\", re.I),\n        \"UNAUTHORIZED PRIVILEGE ESCALATION\",\n        \"critical\",\n    ),"},"time":{"start":1790449825537}}},"time":1790449825537}');
INSERT INTO event VALUES('evt_0df2037070018DH0964eZ8HADh','ses_f211dfcd4ffevS1Yoddwab036g',4002,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df202f6a0011Ad1KLDgBpA5M4","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df2028cf0010Gb8NyooPMVFY6","type":"text","text":"Two problems. The sudo rule can''t tell `livings` from `attacker` — that''s the serious one, since it fired on your own commands. Fixing both:","time":{"start":1790449823594,"end":1790449825542}},"time":1790449825542}');
INSERT INTO event VALUES('evt_0df20371200196dZjA3S6S2Bf2','ses_f211dfcd4ffevS1Yoddwab036g',4003,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df2033260018agDm0ByRohI5Q","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df2028cf0010Gb8NyooPMVFY6","type":"tool","callID":"call_function_4bhbkuzp764w_1","tool":"edit","state":{"status":"running","input":{"oldString":"    (\n        \"sudo_failure\",\n        re.compile(r\"sudo:.*(incorrect password|authentication failure|a password is required)\", re.I),\n        \"UNAUTHORIZED PRIVILEGE ESCALATION\",\n        \"critical\",\n    ),","filePath":"/home/livings/Projects/nyan-gfsf-alert/gfsf-watch.py","newString":"    (\n        # sudo: the actor name is the field right after \"sudo:\". \"a password\n        # is required\" fires on every non-interactive sudo attempt, including\n        # the admin''s own — so only flag it when the actor is NOT the local\n        # user. \"incorrect password\" is always a real failure.\n        \"sudo_failure\",\n        re.compile(r\"sudo:.*incorrect password\", re.I),\n        \"UNAUTHORIZED PRIVILEGE ESCALATION\",\n        \"critical\",\n    ),\n    (\n        # Non-interactive sudo attempt from someone other than us.\n        \"sudo_unattended\",\n        re.compile(r\"sudo:\\s*(?P<actor>\\w+)\\s*:.*a password is required\", re.I),\n        \"UNAUTHORIZED PRIVILEGE ESCALATION\",\n        \"critical\",\n    ),"},"metadata":{"diff":"Index: /home/livings/Projects/nyan-gfsf-alert/gfsf-watch.py\n===================================================================\n--- /home/livings/Projects/nyan-gfsf-alert/gfsf-watch.py\n+++ /home/livings/Projects/nyan-gfsf-alert/gfsf-watch.py\n@@ -65,14 +65,25 @@\n     \"ACCOUNT LOCKOUT TRIGGERED\",\n     \"critical\",\n ),\n (\n+    # sudo: the actor name is the field right after \"sudo:\". \"a password\n+    # is required\" fires on every non-interactive sudo attempt, including\n+    # the admin''s ow