     \"sddm_failure\",\n     re.compile(r\"(sddm|lightdm|gdm).*(failed|auth|login).*fail\", re.I),\n     \"LOGIN SCREEN AUTH FAILURE\",\n     \"critical\",\n","additions":12,"deletions":1},"diagnostics":{}},"time":{"start":1790449825537}}},"time":1790449825554}');
