INSERT INTO event VALUES('evt_0df204f840013jHxUESoCNa73s','ses_f211dfcd4ffevS1Yoddwab036g',4024,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df204755001MQC41J8PDa4jK0","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df2040aa001S4JiMrdHebQ6PA","type":"tool","callID":"call_function_m6z9jokmoz1f_1","tool":"edit","state":{"status":"running","input":{"oldString":"def classify(lines: list[str]) -> list[dict]:\n    \"\"\"Run every rule over every line, collect unique hits.\"\"\"\n    found: dict[str, dict] = {}\n    for line in lines:\n        for name, pattern, label, severity in RULES:\n            if not pattern.search(line):\n                continue\n            key = f\"{name}:{label}\"\n            if key in found:\n                found[key][\"count\"] += 1\n            else:\n                found[key] = {\n                    \"rule\": name, \"label\": label,\n                    \"severity\": severity, \"count\": 1,\n                    \"sample\": line.strip()[:200],\n                }\n    return list(found.values())","filePath":"/home/livings/Projects/nyan-gfsf-alert/gfsf-watch.py","newString":"LOCAL_USER = os.environ.get(\"USER\") or getpass.getuser()\n\n\ndef is_local_admin_actor(match: re.Match) -> bool:\n    \"\"\"\n    True if the sudo actor is the logged-in user doing their own thing.\n    Guards the rules that would otherwise fire on normal admin activity.\n    \"\"\"\n    actor = (match.groupdict().get(\"actor\") or \"\").strip().lower()\n    return bool(actor) and actor == LOCAL_USER.lower()\n\n\ndef classify(lines: list[str]) -> list[dict]:\n    \"\"\"Run every rule over every line, collect unique hits.\"\"\"\n    found: dict[str, dict] = {}\n    for line in lines:\n        for name, pattern, label, severity in RULES:\n            m = pattern.search(line)\n            if not m:\n                continue\n            # Skip our own sudo attempts — not an intrusion.\n            if name == \"sudo_unattended\" and is_local_admin_actor(m):\n                continue\n            key = f\"{name}:{label}\"\n            if key in found:\n                found[key][\"count\"] += 1\n            else:\n                found[key] = {\n                    \"rule\": name, \"label\": label,\n                    \"severity\": severity, \"count\": 1,\n                    \"sample\": line.strip()[:200],\n                }\n    return list(found.values())"},"time":{"start":1790449831812}}},"time":1790449831812}');
