INSERT INTO event VALUES('evt_0df230922001ZtlczMXKHnKW9w','ses_f211dfcd4ffevS1Yoddwab036g',4209,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df22e1db001OqY3W48VUpEL4O","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df22d38f001RHPD0PMvlWIx7G","type":"tool","callID":"call_function_1bzr428vmvcu_1","tool":"edit","state":{"status":"running","input":{"oldString":"def gui(payload: dict) -> int:\n    from PyQt6.QtCore import Qt, QTimer\n    from PyQt6.QtGui import QColor, QFont, QPainter\n    from PyQt6.QtWidgets import QApplication, QWidget\n\n    sev = payload.get(\"severity\", \"warning\")\n    crit = sev == \"critical\"\n    bg = QColor(\"#120000\") if crit else QColor(\"#1a1400\")\n    body = QColor(\"#ff2d2d\") if crit else QColor(\"#ffb000\")\n    light = QColor(\"#ffd7d7\") if crit else QColor(\"#fff0c0\")\n    ink = QColor(\"#1a0000\")\n    flame_cols = [QColor(\"#ff3c00\"), QColor(\"#ff8c00\"), QColor(\"#ffd000\")]\n\n    class Alert(QWidget):\n        def __init__(self):\n            super().__init__()\n            self.setWindowTitle(\"INTRUSION ALERT\")\n            self.frames = 0\n\n        def pixel_map(self, rows, palette, cell, ox, oy):\n            out = []\n            for r, row in enumerate(rows):\n                for c, ch in enumerate(row):\n                    if ch == \".\":\n                        continue\n                    color = palette.get(ch)\n                    if color:\n                        out.append((ox + c * cell, oy + r * cell, cell, cell, color))\n            return out\n\n        def paintEvent(self, ev):\n            p = QPainter(self)\n            p.fillRect(self.rect(), bg)\n\n            # drifting starfield, like nyan cat\n            w, h = self.width(), self.height()\n            for i in range(60):\n                x = (i * 137 + self.frames * 7) % w\n                y = (i * 83) % (h // 2)\n                p.fillRect(x, y, 3, 3, QColor(\"#332222\"))\n\n            cw = min(w, 1100) // 24\n            ch = cw // 2\n            total_h = len(CAT) * ch + len(FLAME) * ch\n            ox = (w - 13 * cw) // 2\n            oy = (h - total_h) // 2 - 40\n\n            pal = {\"B\": body, \"K\": ink, \"W\": QColor(\"#ffffff\")}\n            # trail\n            for i, col in enumerate(flame_cols[:2]):\n                p.setPen(col)\n                p.setOpacity(0.25 - i * 0.1)\n                p.drawRect(ox - (3 - i) * cw * 2, oy + ch, 3 * cw * 2, len(CAT) * ch)\n            p.setOpacity(1.0)\n\n            for x, y, ww, hh, color in self.pixel_map(CAT, pal, cw, ox, oy):\n                p.fillRect(x, y, ww, hh, color)\n\n            # animated flames: cycle the palette by frame\n            fpal = {\"Y\": flame_cols[self.frames % 3], \"O\": flame_cols[0]}\n            foy = oy + len(CAT) * ch\n            for x, y, ww, hh, color in self.pixel_map(FLAME, fpal, ch, ox, foy):\n                p.fillRect(x, y, ww, hh, color)\n\n            # GFSF wordmark\n            p.setPen(light)\n            f = QFont(\"DejaVu Sans Mono\", max(28, cw), QFont.Bold)\n            p.setFont(f)\n            p.drawText(0, foy + len(FLAME) * ch + 70, w, 60,\n                       Qt.AlignmentFlag.AlignHCenter, \"GFSF\")\n\n            # banner\n            p.setPen(QColor(\"#ff2d2d\") if crit else QColor(\"#ffb000\"))\n            bf = QFont(\"DejaVu Sans\", 34, QFont.Bold)\n            p.setFont(bf)\n            p.drawText(0, 60, w, 50, Qt.AlignmentFlag.AlignHCenter,\n                       \"INTRUSION DETECTED\" if crit else \"SECURITY EVENT\")\n\n            # details\n            p.setPen(light)\n            sf = QFont(\"DejaVu Sans Mono\", 13)\n            p.setFont(sf)\n            lines = [f\"severity: {sev}\",\n                     f\"time:     {payload.get(''timestamp'')}\"]\n            for e in payload.get(\"events\", [])[:6]:\n                lines.append(f\"  [{e.get(''count'')}x] {e.get(''label'')}\")\n                if e.get(\"sample\"):\n                    lines.append(f\"        {e[''sample''][:88]}\")\n            y = h - 30 - 22 * len(lines)\n            p.drawText(60, y, w - 120, 22 * len(lines) + 20,\n                       Qt.AlignmentFlag.AlignLeft, \"\\n\".join(lines))\n\n            p.drawText(0, h - 30, w, 20, Qt.AlignmentFlag.AlignHCenter,\n                       \"press ESC or click to dismiss\")\n\n        def keyPressEvent(self, e):\n            if e.key() == Qt.Key.Key_Escape:\n                self.close()\n\n    class Ticker(Alert):\n        def timerEvent(self, e):\n            self.frames += 1\n            self.update()\n\n    app = QApplication(sys.argv)\n    app.setQuitOnLastWindowClosed(True)\n    w = Ticker()\n    w.setWindowFlags(Qt.WindowType.FramelessWindowHint | Qt.WindowType.WindowStaysOnTopHint)\n    w.showFullScreen()\n    def advance():\n        w.frames += 1\n        w.update()\n\n    t = QTimer()\n    t.timeout.connect(advance)\n    t.start(120)\n    QTimer.singleShot(DURATION_MS, w.close)\n    return app.exec()","filePath":"/home/livings/Projects/nyan-gfsf-alert/alert.py","newString":"def _build_widget_classes():\n    \"\"\"\n    Build the Qt widget classes. Imported lazily so that the module can be\n    imported (and the terminal fallback used) on a machine with no Qt.\n    \"\"\"\n    from PyQt6.QtCore import Qt\n    from PyQt6.QtGui import QColor\n    from PyQt6.QtWidgets import QWidget\n\n    class Alert(QWidget):\n        def __init__(self, payload: dict):\n            super().__init__()\n            self.payload = payload\n            self.sev = payload.get(\"severity\", \"warning\")\n            self.crit = self.sev == \"critical\"\n            self.bg = QColor(\"#120000\") if self.crit else QColor(\"#1a1400\")\n            self.body = QColor(\"#ff2d2d\") if self.crit else QColor(\"#ffb000\")\n            self.light = QColor(\"#ffd7d7\") if self.crit else QColor(\"#fff0c0\")\n            self.ink = QColor(\"#1a0000\")\n            self.flame_cols = [QColor(\"#ff3c00\"), QColor(\"#ff8c00\"), QColor(\"#ffd000\")]\n            self.frames = 0\n            self.setWindowTitle(\"INTRUSION ALERT\")\n\n        def pixel_map(self, rows, palette, cell, ox, oy):\n            out = []\n            for r, row in enumerate(rows):\n                for c, ch in enumerate(row):\n                    if ch == \".\":\n                        continue\n                    color = palette.get(ch)\n                    if color is not None:\n                        out.append((ox + c * cell, oy + r * cell, cell, cell, color))\n            return out\n\n        def paintEvent(self, ev):\n            from PyQt6.QtGui import QFont, QPainter\n            from PyQt6.QtCore import Qt as _Qt\n\n            p = QPainter(self)\n            p.fillRect(self.rect(), self.bg)\n\n            w, h = self.width(), self.height()\n            if w <= 0 or h <= 0:\n                return\n\n            # drifting starfield\n            for i in range(60):\n                x = (i * 137 + self.frames * 7) % w\n                y = (i * 83) % max(1, h // 2)\n                p.fillRect(x, y, 3, 3, QColor(\"#332222\"))\n\n            cw = max(8, min(w, 1100) // 24)\n            ch = max(4, cw // 2)\n            total_h = len(CAT) * ch + len(FLAME) * ch\n            ox = (w - 13 * cw) // 2\n            oy = (h - total_h) // 2 - 40\n\n            # comet trail behind the cat\n            for i, col in enumerate(self.flame_cols[:2]):\n                p.setPen(col)\n                p.setOpacity(0.25 - i * 0.1)\n                p.drawRect(ox - (3 - i) * cw * 2, oy + ch, 3 * cw * 2, len(CAT) * ch)\n            p.setOpacity(1.0)\n\n            pal = {\"B\": self.body, \"K\": self.ink, \"W\": QColor(\"#ffffff\")}\n            for x, y, ww, hh, color in self.pixel_map(CAT, pal, cw, ox, oy):\n                p.fillRect(x, y, ww, hh, color)\n\n            # animated flames\n            fpal = {\"Y\": self.flame_cols[self.frames % 3], \"O\": self.flame_cols[0]}\n            foy = oy + len(CAT) * ch\n            for x, y, ww, hh, color in self.pixel_map(FLAME, fpal, ch, ox, foy):\n                p.fillRect(x, y, ww, hh, color)\n\n            # GFSF wordmark\n            p.setPen(self.light)\n            p.setFont(QFont(\"DejaVu Sans Mono\", max(28, cw), QFont.Bold))\n            p.drawText(0, foy + len(FLAME) * ch + 70, w, 60,\n                       _Qt.AlignmentFlag.AlignHCenter, \"GFSF\")\n\n            # banner\n            p.setPen(QColor(\"#ff2d2d\") if self.crit else QColor(\"#ffb000\"))\n            p.setFont(QFont(\"DejaVu Sans\", 34, QFont.Bold))\n            p.drawText(0, 60, w, 50, _Qt.AlignmentFlag.AlignHCenter,\n                       \"INTRUSION DETECTED\" if self.crit else \"SECURITY EVENT\")\n\n            # details\n            p.setPen(self.light)\n            p.setFont(QFont(\"DejaVu Sans Mono\", 13))\n            lines = [f\"severity: {self.sev}\",\n                     f\"time:     {self.payload.get(''timestamp'')}\"]\n            for e in self.payload.get(\"events\", [])[:6]:\n                lines.append(f\"  [{e.get(''count'')}x] {e.get(''label'')}\")\n                if e.get(\"sample\"):\n                    lines.append(f\"        {e[''sample''][:88]}\")\n            y = h - 40 - 22 * len(lines)\n            p.drawText(60, max(40, y), w - 120, 22 * len(lines) + 20,\n                       _Qt.AlignmentFlag.AlignLeft, \"\\n\".join(lines))\n\n            p.drawText(0, h - 30, w, 20, _Qt.AlignmentFlag.AlignHCenter,\n                       \"press ESC or click to dismiss\")\n\n        def keyPressEvent(self, e):\n            from PyQt6.QtCore import Qt as _Qt\n            if e.key() == _Qt.Key.Key_Escape:\n                self.close()\n\n        def mousePressEvent(self, e):\n            self.close()\n\n    return Alert\n\n\ndef gui(payload: dict) -> int:\n    from PyQt6.QtCore import QTimer\n    from PyQt6.QtWidgets import QApplication\n\n    Alert = _build_widget_classes()\n    app = QApplication.instance() or QApplication(sys.argv)\n    app.setQuitOnLastWindowClosed(True)\n    w = Alert(payload)\n    from PyQt6.QtCore import Qt\n    w.setWindowFlags(Qt.WindowType.FramelessWindowHint | Qt.WindowType.WindowStaysOnTopHint)\n    w.showFullScreen()\n\n    def advance():\n        w.frames += 1\n        w.update()\n\n    t = QTimer()\n    t.timeout.connect(advance)\n    t.start(120)\n    QTimer.singleShot(DURATION_MS, w.close)\n    return app.exec()"},"time":{"start":1790450010401}}},"time":1790450010401}');
