         # Silent run for cron\"\n      35\techo \"\"\n      36\techo \"Setting up daily cron job...\"\n      37\t# Add daily cron job at 7 AM\n      38\t(crontab -l 2>/dev/null | grep -v \"business-health\"; echo \"0 7 * * * $HOME/.local/bin/business-health --cron\") | crontab -\n      39\techo \"✅ Cron job installed (daily at 7:00 AM)\"\n      40\techo \"\"\n      41\techo \"Run your first scan:\"\n      42\techo \"  business-health --scan\"\n"},"time":{"start":1790450359680}}},"time":1790450359688}');
