INSERT INTO event VALUES('evt_0df28c4ac001JRE1d8kxzSy6Bc','ses_f211dfcd4ffevS1Yoddwab036g',4453,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df28bbdc001lmIBiohC8AESou","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df28b4ae001KlCq5PdOBqNQhE","type":"tool","callID":"call_function_u04ed51roggq_1","tool":"edit","state":{"status":"running","input":{"filePath":"/home/livings/Projects/business-health-monitor/install.sh","newString":"echo \"  business-health --heal          # Scan + auto-heal\"\necho \"  business-health --status        # Health dashboard\"\necho \"  business-health --report        # Generate HTML report\"\necho \"  business-health --cron          # Silent run for scheduler\"\necho \"\"\n\n# Schedule via a systemd USER timer, not cron.\n# cron is not installed on this system (no cronie/crond), so the previous\n# crontab line silently failed and the daily job would never have run.\nif command -v systemctl >/dev/null 2>&1; then\n    UNIT_DIR=\"$HOME/.config/systemd/user\"\n    mkdir -p \"$UNIT_DIR\"\n    cp \"$SCRIPT_DIR/systemd/business-health.service\" \"$UNIT_DIR/\"\n    cp \"$SCRIPT_DIR/systemd/business-health.timer\" \"$UNIT_DIR/\"\n    systemctl --user daemon-reload\n    systemctl --user enable --now business-health.timer\n    echo \"✅ systemd user timer installed (daily at 07:00)\"\n    echo \"   status: systemctl --user list-timers business-health.timer\"\nelse\n    echo \"⚠️  systemctl not found — timer NOT installed.\"\n    echo \"   Run manually:  business-health --cron\"\nfi\necho \"\"\necho \"Run your first scan:\"\necho \"  business-health --scan\"","oldString":"echo \"  business-health --heal          # Scan + auto-heal\"\necho \"  business-health --status        # Health dashboard\"\necho \"  business-health --report        # Generate HTML report\"\necho \"  business-health --cron          # Silent run for cron\"\necho \"\"\necho \"Setting up daily cron job...\"\n# Add daily cron job at 7 AM\n(crontab -l 2>/dev/null | grep -v \"business-health\"; echo \"0 7 * * * $HOME/.local/bin/business-health --cron\") | crontab -\necho \"✅ Cron job installed (daily at 7:00 AM)\"\necho \"\"\necho \"Run your first scan:\"\necho \"  business-health --scan\""},"time":{"start":1790450386092}}},"time":1790450386092}');
