INSERT INTO event VALUES('evt_0df2ed263001CMffTAVBGyvc6a','ses_f20e5cfc2ffeSFa4odnoYLiUOk',932,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df2ecd370015eLzz45KmB58S4","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df2eabcb001tELmQjd53vSQwu","type":"tool","callID":"call_function_2zeggi7flz1s_2","tool":"bash","state":{"status":"running","input":{"command":"cd ~/Projects/shield-kitty && ./shield-kitty-alert.py ''{\"severity\":\"warning\",\"events\":[{\"rule\":\"usb_attach\",\"label\":\"USB DEVICE ATTACHED\",\"severity\":\"warning\",\"count\":8,\"sample\":\"usb usb1: Product: xHCI Host Controller\"}],\"timestamp\":\"2026-09-26 12:30:00\"}'' >/dev/null 2>&1 &\nsleep 3\necho \"=== did a warning-severity alert actually put a window on the display? ===\"\nif command -v qdbus >/dev/null 2>&1; then qdbus org.kde.KWin /KWin org.kde.KWin.queryWindowInfo 2>/dev/null | head -5; fi\npgrep -af \"shield-kitty-alert\" || echo \"  (alert process already exited)\"\necho \"=== wayland/x11 ===\"; echo \"XDG_SESSION_TYPE=${XDG_SESSION_TYPE:-unset}  WAYLAND_DISPLAY=${WAYLAND_DISPLAY:-unset}  DISPLAY=${DISPLAY:-unset}\""},"metadata":{"output":""},"time":{"start":1790450782819}}},"time":1790450782819}');
INSERT INTO event VALUES('evt_0df2ed265001rOXGx4ec9C9IrB','ses_f20e5cfc2ffeSFa4odnoYLiUOk',933,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df2ecd370015eLzz45KmB58S4","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df2eabcb001tELmQjd53vSQwu","type":"tool","callID":"call_function_2zeggi7flz1s_2","tool":"bash","state":{"status":"running","input":{"command":"cd ~/Projects/shield-kitty && ./shield-kitty-alert.py ''{\"severity\":\"warning\",\"events\":[{\"rule\":\"usb_attach\",\"label\":\"USB DEVICE ATTACHED\",\"severity\":\"warning\",\"count\":8,\"sample\":\"usb usb1: Product: xHCI Host Controller\"}],\"timestamp\":\"2026-09-26 12:30:00\"}'' >/dev/null 2>&1 &\nsleep 3\necho \"=== did a warning-severity alert actually put a window on the display? ===\"\nif command -v qdbus >/dev/null 2>&1; then qdbus org.kde.KWin /KWin org.kde.KWin.queryWindowInfo 2>/dev/null | head -5; fi\npgrep -af \"shield-kitty-alert\" || echo \"  (alert process already exited)\"\necho \"=== wayland/x11 ===\"; echo \"XDG_SESSION_TYPE=${XDG_SESSION_TYPE:-unset}  WAYLAND_DISPLAY=${WAYLAND_DISPLAY:-unset}  DISPLAY=${DISPLAY:-unset}\""},"metadata":{"output":""},"time":{"start":1790450782819}}},"time":1790450782821}');
INSERT INTO event VALUES('evt_0df2ed268001Mkx36oxBJQ9ihC','ses_f20e5cfc2ffeSFa4odnoYLiUOk',934,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df2ec6b1001AsEIui8aWHIBbJ","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df2eabcb001tELmQjd53vSQwu","type":"text","text":"Found it. Two distinct things:\n\n**The real false positive — `usb_attach` (8 hits, all benign):**\n```\nusb usb1: Product: xHCI Host Controller\nusb usb2: Product: xHCI Host Controller\n```\nThe regex `usb .*(?:new high-speed USB device|Product:)` matches the kernel enumerating the machine''s **own built-in USB controllers at every boot**. It will also fire on any mouse dongle, phone, or drive you plug in.\n\n**The two `critical` hits are test artifacts, not attacks:**\n```\nlivings[186777]: sshd[99999]: Failed password for invalid user root from 198.51.100.42\n```\nPID `99999` is synthetic and `198.51.100.42` is TEST-NET-2 (RFC 5737 documentation range) — those are the selftest probe strings a previous session injected into the journal.\n\nLet me confirm warnings also take over the screen:","time":{"start":1790450779825,"end":1790450782824}},"time":1790450782824}');
