INSERT INTO event VALUES('evt_0df2ed79d001Dn0e5py7oWAtAN','ses_f20e5cfc2ffeSFa4odnoYLiUOk',935,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df2ed115001QsRL3ZSRbmyBEP","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df2e7fed001lzIbXI6L260Pz3","type":"tool","callID":"call_function_txxpuo47dj4w_2","tool":"bash","state":{"status":"running","input":{"command":"cd ~/Projects/shield-kitty\necho \"=== what matches the usb_attach rule in the last 24h? ===\"\njournalctl --no-pager -q --since \"-24h\" 2>/dev/null | grep -icE \"usb .*(new high-speed USB device|Product:)\"\necho \"  ^ count of USB attach lines (each would show a fullscreen nyan cat)\"\necho\necho \"=== sample of them ===\"\njournalctl --no-pager -q --since \"-24h\" -o short-iso 2>/dev/null | grep -iE \"usb .*(new high-speed USB device|Product:)\" | tail -3 | cut -c1-140\necho\necho \"=== own sudo failures in last 24h? ===\"\njournalctl --no-pager -q --since \"-24h\" 2>/dev/null | grep -icE \"sudo:.*incorrect password\"\necho \"=== pam_unix auth failures (fires login_failure) in last 24h? ===\"\njournalctl --no-pager -q --since \"-24h\" 2>/dev/null | grep -cE \"pam_unix\\([^)]*:auth\\): authentication failure\""},"metadata":{"output":""},"time":{"start":1790450784156}}},"time":1790450784157}');
