INSERT INTO event VALUES('evt_0df2f1e2a001EqX24CuoR1LhyZ','ses_f20e5cfc2ffeSFa4odnoYLiUOk',995,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df2f150b001MF66UQ4art2PyQ","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df2ee8b00010nXkl1TwTDM1a7","type":"tool","callID":"call_function_yj4zpsdul4b1_1","tool":"question","state":{"status":"running","input":{"questions":[{"header":"Alert policy","options":[{"label":"Gate on severity (recommended)","description":"Only ''critical'' events (auth failures, lockouts, privesc) get the fullscreen cat. ''warning'' events log to the journal only. Tighten usb_attach to ignore built-in xHCI root hubs. Real attacks still take over the screen."},{"label":"Severity gate + quiet hours","description":"Severity gate as above, plus a notification-only mode during hours you choose, so nothing ever fullscreens while you''re working."},{"label":"Disable the service entirely","description":"Stop the fullscreen alert completely. shield-kitty keeps logging detections to the journal but never touches your display. You read the journal when you want."},{"label":"Leave it, just document","description":"Leave detection as-is and only fix the stale systemd unit so it doesn''t crash-loop. You keep getting the cat on USB events."}],"question":"How should Shield Kitty behave? (I will not weaken the critical/attack detection either way.)","multiple":false}]},"time":{"start":1790450802218}}},"time":1790450802218}');
INSERT INTO event VALUES('evt_0df2f1e57001MncQ7jyjvLWN4P','ses_f20e5cfc2ffeSFa4odnoYLiUOk',996,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df2f0bdc001TxcBuv052Vow0K","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df2ee8b00010nXkl1TwTDM1a7","type":"text","text":"Diagnosis is complete. Here''s exactly why it displays against you:\n\n**Root cause: `warning` severity is not gated.** In `shield-kitty-watch.py:286-294`, `fire_alert(events)` fires on *any* non-empty event list — there''s no severity check. And `shield-kitty-alert.py:178-179` unconditionally does `FramelessWindowHint | WindowStaysOnTopHint` + `showFullScreen()`. The `severity` value is only read for on-screen text (line 69). So a `warning`-level event = fullscreen takeover.\n\n**The trigger you''re hitting: `usb_attach`** (`shield-kitty-watch.py:100-104`)\n```python\nre.compile(r\"usb .*(?:new high-speed USB device|Product:)\", re.I)\n```\nThis matches the kernel enumerating your own built-in controllers at every boot:\n```\nusb usb1: Product: xHCI Host Controller\nusb usb2: Product: xHCI Host Controller\n```\n8 hits in the last 6457 journal lines, all at `10:48:05` (boot). Plus it fires on any mouse dongle, phone, or drive.\n\nSo the tool is doing its job as written — it''s just that \"warning\" was never meant to be quieter, and the USB rule is far too broad.\n\nOne thing I won''t decide for you, because it trades off against real protection:","time":{"start":1790450797532,"end":1790450802262}},"time":1790450802263}');
INSERT INTO event VALUES('evt_0df2f2084001zGMaVf5LzZnyiQ','ses_f20e5cfc2ffeSFa4odnoYLiUOk',997,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df2f183f001bI4umGCpXC3U5p","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df2f0ab9001guyLpru4pb4x06","type":"tool","callID":"call_function_fpyv6609j6st_1","tool":"question","state":{"status":"running","input":{"questions":[{"header":"Which fixes","question":"Which false-positive fixes should I make? I recommend all five.","multiple":true,"options":[{"description":"Stop matching keyring/polkit/cron auth, demote non-sshd auth failures to warning, and add self-exemption for your own sudo typos. Keeps real SSH attacks critical.","label":"Fix sudo self-exemption + narrow login_failure"},{"description":"Stop matching your own xHCI host controllers so the rule stops firing at every boot.","label":"Fix USB self-match"},{"description":"Only critical takes over the screen; warnings become a passive notification. This is the single biggest fix for ''displays against me''.","label":"Make warnings stop going fullscreen"},{"description":"Make selftest fail when it should and use an unmistakable probe, so this cannot regress silently.","label":"Fix the unsound selftest"},{"description":"Reinstall the unit from the repo so ExecStart points at shield-kitty/ and stops crash-looping.","label":"Repair stale systemd unit"}]},{"header":"USB rule future","question":"How should the USB attach rule behave going forward?","options":[{"description":"Keep it but only for genuine new devices, excluding root hubs and built-in controllers. Keeps some physical-tamper signal.","label":"Keep, but match real devices only"},{"description":"Silently drop the rule. Physical device attachment is not a meaningful intrusion signal on a laptop.","label":"Remove the USB rule entirely"},{"description":"Keep detecting but never display it; journal only.","label":"Keep as log-only, never display"}]}]},"time":{"start":1790450802820}}},"time":1790450802820}');
