INSERT INTO event VALUES('evt_0df306376001DpVYM7HY4Y5pGj','ses_f20e5cfc2ffeSFa4odnoYLiUOk',1033,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df305ea6001BRBTe9P8zYT15Q","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df304f2d001C64J3r4jLRKNXR","type":"tool","callID":"call_function_w0a7mjtidi30_1","tool":"edit","state":{"status":"running","input":{"filePath":"/home/livings/Projects/shield-kitty/shield-kitty-watch.py","oldString":"    (\n        \"usb_attach\",\n        re.compile(r\"usb .*(?:new high-speed USB device|Product:)\", re.I),\n        \"USB DEVICE ATTACHED\",\n        \"warning\",\n    ),\n]","newString":"    (\n        # Only real peripherals, never the machine''s own root hubs.\n        # A genuine attach has a bus-PORT path (\"usb 3-7:\") and always logs\n        # a \"New USB device found, idVendor=...\" line. Root hubs log as\n        # \"usb1:\"/\"usb2:\" (bus only, no port) and are just the controller\n        # enumerating itself at every boot.\n        \"usb_attach\",\n        re.compile(\n            r\"\\busb\\s+\\d+-\\d+(?:\\.\\d+)*:\\s+new\\s+(?:full|low|high)-speed\\s+USB\\s+device\"\n        ),\n        \"USB DEVICE ATTACHED\",\n        \"warning\",\n    ),\n]"},"time":{"start":1790450885494}}},"time":1790450885494}');
