INSERT INTO event VALUES('evt_0df306397001pp6ZmBljmffWj5','ses_f20e5cfc2ffeSFa4odnoYLiUOk',1036,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df305a9f001qKkKBA3YCZsNyQ","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df304f2d001C64J3r4jLRKNXR","type":"text","text":"Now I can see the distinction clearly. Your real devices always have a **bus-port** path (`usb 3-7:`, `usb 3-2:`) and always emit a `New USB device found, idVendor=...` line. Root hubs are `usb1:`/`usb2:` (bus-only) with no port.","time":{"start":1790450883231,"end":1790450885527}},"time":1790450885527}');
