INSERT INTO event VALUES('evt_0df3070cc001mi7mfSGjqXyO1T','ses_f20e5cfc2ffeSFa4odnoYLiUOk',1046,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df3069d7001zWaCsWuPsqOsLB","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df3063a4001H5bvfOVU2Ny5I1","type":"tool","callID":"call_function_gkemribtmp6e_1","tool":"edit","state":{"status":"running","input":{"filePath":"/home/livings/Projects/shield-kitty/shield-kitty-watch.py","newString":"def most_severe(events: list[dict]) -> str:\n    if any(e[\"severity\"] == \"critical\" for e in events):\n        return \"critical\"\n    return \"warning\"\n\n\ndef log_events(events: list[dict]) -> None:\n    \"\"\"Record a non-displaying event to the journal.\n\n    Warnings are evidence, not emergencies. They are written to the journal\n    so they are still auditable, but they never take over the display --\n    a fullscreen takeover for a USB mouse is a nuisance, not a warning.\n    \"\"\"\n    payload = {\n        \"severity\": most_severe(events),\n        \"events\": events,\n        \"timestamp\": time.strftime(\"%Y-%m-%d %H:%M:%S\"),\n    }\n    log(f\"WARN (no display): {len(events)} event(s)\")\n    for e in events:\n        log(f\"        {e[''label'']} x{e[''count'']}\")\n    try:\n        subprocess.run(\n            [\"logger\", \"-t\", \"shield-kitty\", \"-p\", \"user.notice\", json.dumps(payload)],\n            capture_output=True, timeout=10,\n        )\n    except Exception:\n        pass\n\n\ndef fire_alert(events: list[dict]) -> None:","oldString":"def most_severe(events: list[dict]) -> str:\n    if any(e[\"severity\"] == \"critical\" for e in events):\n        return \"critical\"\n    return \"warning\"\n\n\ndef fire_alert(events: list[dict]) -> None:"},"time":{"start":1790450888908}}},"time":1790450888908}');
INSERT INTO event VALUES('evt_0df3070cf0010079Y9hTHkHPab','ses_f20e5cfc2ffeSFa4odnoYLiUOk',1047,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df3068d1001vDbwXjZAF7wHIz","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df3063a4001H5bvfOVU2Ny5I1","type":"text","text":"Now the core fix — gate the display on severity, and only take the screen for `critical`:","time":{"start":1790450886865,"end":1790450888911}},"time":1790450888911}');
