INSERT INTO event VALUES('evt_0df32515c0013A4hYkQVnL5jum','ses_f211dfcd4ffevS1Yoddwab036g',5421,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df324c460017ojAZZ4EwcGeKV","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df3243c6001VMsRPRyPpmi612","type":"tool","callID":"call_function_zosaglgza7k0_2","tool":"bash","state":{"status":"running","input":{"command":"echo \"═══ 9. TOOLCHAIN ═══\"\nfor t in business-health business-debug buildlog; do\n  printf \"  %-18s \" $t; command -v $t >/dev/null 2>&1 && echo \"on PATH\" || echo \"MISSING\"\ndone\nprintf \"  %-18s \" \"lin-antimalware\"; [ -x ~/Projects/lin-antimalware/venv/bin/python ] && echo \"venv ok\" || echo \"venv missing\"\nprintf \"  %-18s \" \"hermes-agent\"; pacman -Q hermes-agent 2>/dev/null | awk ''{print $2}'' || echo \"not installed\"\necho\necho \"═══ 10. PROJECTS ═══\"\nfor d in ~/Projects/*/; do\n  [ -d \"$d/.git\" ] || continue\n  n=$(basename $d)\n  dirty=$(git -C \"$d\" status --porcelain 2>/dev/null | wc -l | tr -d '' '')\n  printf \"  %-26s %s commit(s), %s uncommitted\\n\" \"$n\" \"$(git -C \"$d\" rev-list --count HEAD 2>/dev/null)\" \"$dirty\"\ndone"},"metadata":{"output":""},"time":{"start":1790451011931}}},"time":1790451011931}');
