INSERT INTO event VALUES('evt_0df339bc40014JKLUJM4vvI786','ses_f211dfcd4ffevS1Yoddwab036g',5582,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df3398a80013C7YdZgbWHnxsV","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df336299001cZk2F8VKXEAL6p","type":"tool","callID":"call_function_7tgwx2f7o7ob_1","tool":"bash","state":{"status":"running","input":{"command":"echo \"=== what directives does faillock actually have? ===\"\nman faillock.conf 2>/dev/null | grep -oiE \"^\\s{0,10}(deny|unlock_time|even_deny|even_deny_groot|dir|fail_interval|audit|silent|root)\\b\" | sort -u | sed ''s/^/  /''\necho\necho \"=== exact semantics of even_deny, from the man page ===\"\nman faillock.conf 2>/dev/null | sed -n ''/even_deny/,/^$/p'' | head -20 | sed ''s/^/  /''"},"metadata":{"output":""},"time":{"start":1790451096516}}},"time":1790451096516}');
