INSERT INTO event VALUES('evt_0df339c49001Z8PDP8SZOlkvPK','ses_f211dfcd4ffevS1Yoddwab036g',5587,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df3398a80013C7YdZgbWHnxsV","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df336299001cZk2F8VKXEAL6p","type":"tool","callID":"call_function_7tgwx2f7o7ob_1","tool":"bash","state":{"status":"running","input":{"command":"echo \"=== what directives does faillock actually have? ===\"\nman faillock.conf 2>/dev/null | grep -oiE \"^\\s{0,10}(deny|unlock_time|even_deny|even_deny_groot|dir|fail_interval|audit|silent|root)\\b\" | sort -u | sed ''s/^/  /''\necho\necho \"=== exact semantics of even_deny, from the man page ===\"\nman faillock.conf 2>/dev/null | sed -n ''/even_deny/,/^$/p'' | head -20 | sed ''s/^/  /''"},"metadata":{"output":"=== what directives does faillock actually have? ===\n       audit\n           deny\n       deny\n           Deny\n       dir\n       fail_interval\n           Root\n           silent\n       silent\n           unlock_time\n       unlock_time\n\n=== exact semantics of even_deny, from the man page ===\n       even_deny_root\n           Root account can become locked as well as regular accounts.\n  \n           This option implies even_deny_root option. Allow access after  n  sec‐\n           onds  to  root account after the account is locked. In case the option\n           is not specified the value is the same as of the unlock_time option.\n  \n           tions even_deny_root and root_unlock_time will apply to them.  By  de‐\n           fault the option is not set.\n  \n"},"time":{"start":1790451096516}}},"time":1790451096649}');
