INSERT INTO event VALUES('evt_0df3752450012XGJz6jxZc7q4s','ses_f211dfcd4ffevS1Yoddwab036g',5846,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df374d77001eJ5qo4FLhg5urL","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df373b36001ZhB3qcMgMPZLIU","type":"tool","callID":"call_function_py9umjnnuyo8_1","tool":"bash","state":{"status":"running","input":{"command":"echo \"═══ DOES fail2ban 1.1.1 SUPPORT PERMANENT BANS? ═══\"\ngrep -rE \"bantime.*-1|permanent\" /etc/fail2ban/jail.conf 2>/dev/null | head -5 | sed ''s/^/  /''\necho\necho \"  bantime semantics:\"\ngrep -A3 \"^bantime\" /etc/fail2ban/jail.conf 2>/dev/null | head -6 | sed ''s/^/    /''\necho\necho \"═══ DEFAULT JAILS AVAILABLE ═══\"\ngrep -E \"^\\[(sshd|sddm|sudo|recidive)\\]\" /etc/fail2ban/jail.conf 2>/dev/null | sed ''s/^/  /''\necho\necho \"  recidive = bans repeat offenders permanently. Present? ^\""},"metadata":{"output":""},"time":{"start":1790451339845}}},"time":1790451339845}');
