INSERT INTO event VALUES('evt_0df3bf1f7001ooMgH0N1pwxZNa','ses_f211dfcd4ffevS1Yoddwab036g',6274,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df3bdcbe001HKOfRv76gO2U5E","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df3bd1ed001T3NWtt5QiYbsnW","type":"text","text":"Found the root cause — and it''s my `backend = auto`. Per the shipped docs, `auto` tries only **pyinotify, polling**. It does *not* include systemd, so my `journalctl` logpath lines were never used as journal sources.","time":{"start":1790451637438,"end":1790451642871}},"time":1790451642871}');
