INSERT INTO event VALUES('evt_0df4592c2001fzZXucVw0cOczu','ses_f211dfcd4ffevS1Yoddwab036g',6763,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df458a02001lSoR5zK6JMUFd4","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df4576ba001ESgiik4X0wj0K9","type":"text","text":"Now it''s clear. Two separate things, and neither is a failure:\n\n**1. The socket error was a race.** `systemctl restart` returned `active` before fail2ban''s Python process had created the socket. The socket now exists (`/run/fail2ban/fail2ban.sock`, created 12:50).\n\n**2. The socket is `srwx------ root:root`** — root-only by design. My unprivileged probe just now returned `Permission denied to socket`, which is *proof* it''s live: a dead socket gives \"Failed to access socket path\" instead. Your `sudo` call was correct; it just fired ~seconds too early.\n\nVerifying the jails loaded:","time":{"start":1790452271618,"end":1790452273858}},"time":1790452273858}');
