INSERT INTO event VALUES('evt_0df46a79e001eSemH20b4zybog','ses_f211dfcd4ffevS1Yoddwab036g',6783,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df46a79c0028NMDIPVbENVHkJ","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df46a79c001h4ya3Vj1h1MqJ8","type":"text","text":"sudo sed -i ''s/^enabled  = false/enabled  = true/'' /etc/fail2ban/jail.d/shield-kitty.conf\nsudo systemctl restart fail2ban\nuntil sudo fail2ban-client ping >/dev/null 2>&1; do sleep 0.3; done\nsudo fail2ban-client status recidive\nfish: Unknown command: until\nfish:\nuntil sudo fail2ban-client ping >/dev/null 2>&1; do sleep 0.3; done\n^~~~^\nfish: Unknown command: do\nfish:\nuntil sudo fail2ban-client ping >/dev/null 2>&1; do sleep 0.3; done\n^^\nfish: Unknown command: done\nfish:\nuntil sudo fail2ban-client ping >/dev/null 2>&1; do sleep 0.3; done\n^~~^\n2026-09-26 12:52:13,051 fail2ban                [203544]: ERROR   NOK: (''recidive'',)\nSorry but the jail ''recidive'' does not exist "},"time":1790452344734}');
