INSERT INTO event VALUES('evt_0df47717b001FWgKTR3kQmEtDU','ses_f211dfcd4ffevS1Yoddwab036g',6873,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df47699e001SLmve4j691hdno","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df47402c0019bvf73ctzn4W7t","type":"tool","callID":"call_function_zqyh0ea9dtpy_2","tool":"bash","state":{"status":"running","input":{"command":"echo \"═══ HARDCWARE IDENTIFIERS (survive hostname change) ═══\"\nfor f in product_name product_uuid board_name bios_vendor chassis_asset_tag; do\n  v=$(cat /sys/class/dmi/id/$f 2>/dev/null)\n  [ -n \"$v\" ] && printf \"  %-18s %s\\n\" \"$f\" \"$v\"\ndone\necho\necho \"  machine-id   : $(cat /etc/machine-id 2>/dev/null)\"\necho \"  product-id   : $(cat /sys/class/dmi/id/product_uuid 2>/dev/null | head -c 20)...\"\necho\necho \"═══ MAC ADDRESS RANDOMIZATION ═══\"\nfor c in $(nmcli -t -f NAME,TYPE connection show --active 2>/dev/null | cut -d: -f1); do\n  mode=$(nmcli -g 802-11-wireless.mac-address-mode con show \"$c\" 2>/dev/null)\n  mac=$(nmcli -g 802-11-wireless.mac-address con show \"$c\" 2>/dev/null)\n  printf \"  %-18s mode=%-12s mac=%s\\n\" \"$c\" \"${mode:-unset}\" \"${mac:-<permanently random>}\"\ndone"},"time":{"start":1790452396411}}},"time":1790452396411}');
