INSERT INTO event VALUES('evt_0df478e69001X4pJxaW7lCA8y7','ses_f211dfcd4ffevS1Yoddwab036g',6897,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df478733001wmPeVaE3aZaP5k","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df477d1b001GUKLfrFY7XTTZI","type":"tool","callID":"call_function_omltva8m9u5t_1","tool":"bash","state":{"status":"running","input":{"command":"echo \"═══ /etc/hosts — hardcodes the old name ═══\"\ngrep -n \"127.0.1.1\" /etc/hosts 2>/dev/null | sed ''s/^/  /'' || echo \"  no 127.0.1.1 entry\"\necho\necho \"═══ mDNS / AVAHI — broadcasts hostname to every LAN ═══\"\nsystemctl is-active avahi-daemon 2>/dev/null | sed ''s/^/  avahi: /''\nnmcli -g GENERAL.CONNECTION dev show wlo1 2>/dev/null | sed ''s/^/  wlo1: /''\necho\necho \"═══ BLUETOOTH NAME (defaults to hostname, visible while paired) ═══\"\nfor a in $(bluetoothctl list 2>/dev/null | awk -F''Controller'' ''/Controller/{print $1}''); do\n  bn=$(bluetoothctl show \"$a\" 2>/dev/null | grep -i \"Name:\" | head -1)\n  echo \"  $bn\"\ndone"},"metadata":{"output":""},"time":{"start":1790452403817}}},"time":1790452403817}');
