INSERT INTO event VALUES('evt_0df489bfa001noiHaaGQ7wao1v','ses_f211dfcd4ffevS1Yoddwab036g',6986,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df489340001csChUa9w0WhZae","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df48583c001tlH6cTf9CCDAjt","type":"tool","callID":"call_function_zyn51r1ow1gd_2","tool":"bash","state":{"status":"running","input":{"command":"echo \"═══ FIREWALL BACKEND (matters for transparent proxy) ═══\"\nfirewall-cmd --get-default-zone 2>/dev/null | sed ''s/^/  default zone: /''\nfirewall-cmd --get-ip6tables 2>/dev/null | sed ''s/^/  ip6tables: /''\necho \"  nft ruleset loaded: $(nft list ruleset 2>/dev/null | wc -l) lines\"\necho \"  iptables backend:   $(iptables --version 2>/dev/null)\"\necho\necho \"═══ DNS — the usual Tor leak vector ═══\"\nresolvectl status wlo1 2>/dev/null | grep -A2 \"DNS Servers\" | head -4 | sed ''s/^/  /''\ngrep -E \"^nameserver\" /etc/resolv.conf 2>/dev/null | head -3 | sed ''s/^/  resolv.conf: /''\necho\necho \"  -> if DNS stays on your ISP, your resolver sees every domain you visit\"\necho \"     even with a Tor browser. This is the #1 anonymity leak.\""},"metadata":{"output":""},"time":{"start":1790452472826}}},"time":1790452472826}');
