INSERT INTO event VALUES('evt_0df48cc66001BkgeXHQVIzdzJy','ses_f211dfcd4ffevS1Yoddwab036g',7028,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df48cc66001uJUX0Dc2KBC1Ra","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df48bd51001GOGWIwRJw4YivB","type":"step-start"},"time":1790452485222}');
