INSERT INTO event VALUES('evt_0df4b810500151mFVk8VTs6o8R','ses_f211dfcd4ffevS1Yoddwab036g',7135,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df4b786d001Fd9jQMdjWHFfGY","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df4b73f4001oM3slqXobp0qk9","type":"text","text":"Good news: your system is **already** nearly fully locked down. firewalld default-denies unlisted traffic, so `kdeconnectd` (1716) and mDNS (5353) are already blocked despite their sockets being bound to `*`.\n\nThe real finding is a standing hole:","time":{"start":1790452660333,"end":1790452662533}},"time":1790452662533}');
