INSERT INTO event VALUES('evt_0df4d3c49001gQDbRpdzV9DZ4J','ses_f211dfcd4ffevS1Yoddwab036g',7166,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df4d36d2001cMfwPUdbNhVKGi","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df4d16c0001hHmums0QyQz0Tr","type":"text","text":"Sensible call — a \"trusted\" zone only means something if you actually control the network (no rogue DHCP, no other devices, WPA2-AES or WPA3). An untrusted network with a trusted zone is worse than no zone at all.","time":{"start":1790452774610,"end":1790452776009}},"time":1790452776009}');
