k] allowed: kdeconnectd, mdns, dhcpv6-client — nothing else\"\n\n# ── BIND SSID ────────────────────────────────────────────────────────────\nhr \"Binding ''${SSID}'' to ${ZONE}\"\nfirewall-cmd --permanent --zone=\"$ZONE\" --change-interface=wlo0 2>/dev/null || true\nnmcli con mod \"$conn\" connection.zone \"$ZONE\"\nnmcli con up \"$conn\" >/dev/null\necho \"  [ok] ''${conn}'' now uses zone ${ZONE}\"\n\nhr \"Result\"\necho \"  Verify:\"\necho \"    firewall-cmd --get-zone-of-interface=wlo0\"\necho \"    firewall-cmd --zone=${ZONE} --list-all\"\necho\necho \"  REVERT (back to fully strict):\"\necho \"    nmcli con mod \\\"${conn}\\\" connection.zone public\"\necho \"    nmcli con up \\\"${conn}\\\"\"\necho \"    sudo firewall-cmd --permanent --zone=${ZONE} --remove-service=kdeconnectd\"\n","filePath":"/home/livings/Projects/zen-hardening/set-home-trusted-zone.sh"},"output":"Wrote file successfully.","title":"home/livings/Projects/zen-hardening/set-home-trusted-zone.sh","metadata":{"diagnostics":{},"filepath":"/home/livings/Projects/zen-hardening/set-home-trusted-zone.sh","exists":false,"truncated":false},"time":{"start":1790452796841,"end":1790452796855}}},"time":1790452796856}');
