INSERT INTO event VALUES('evt_0df4db8e3001nOAmNrYlf2QsXt','ses_f211dfcd4ffevS1Yoddwab036g',7230,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df4db8cf001WHiJ8PCvLH9v7d","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df4dacff001DdsildB2OF6gSm","type":"tool","callID":"call_function_sj07cvy8hpn4_1","tool":"read","state":{"status":"completed","input":{"filePath":"/home/livings/Projects/zen-hardening/firewalld-workstation.conf"},"output":"<path>/home/livings/Projects/zen-hardening/firewalld-workstation.conf</path>\n<type>file</type>\n<content>\n1: <?xml version=\"1.0\" encoding=\"utf-8\"?>\n2: <!--\n3:   Workstation firewall — Garuda Linux / Arch\n4:   Install:  sudo cp firewalld-workstation.conf /etc/firewalld/zones/public.xml\n5:             sudo firewall-cmd --reload\n6:   Revert:   sudo rm /etc/firewalld/zones/public.xml && sudo firewall-cmd --reload\n7: \n8:   Zone: public (Garuda''s default active zone)\n9:   Opens: SSH only.\n10: \n11:   Steam needs more and is NOT configured here. Add explicitly when ready:\n12:     sudo firewall-cmd --add-port=27015-27016/udp --permanent   # matchmaking\n13:     sudo firewall-cmd --add-port=27017-27019/tcp --permanent   # in-home streaming\n14: -->\n15: <zone>\n16:   <short>Public</short>\n17:   <description>Workstation profile: deny incoming except SSH.</description>\n18: \n19: \n20:   <!-- No mdns or SMB chatter on untrusted networks -->\n21:   <service name=\"mdns\" disable=\"yes\"/>\n22:   <service name=\"samba-client\" enable=\"no\"/>\n23: \n24:   <!-- ICMP: keep ping for diagnostics -->\n25:   <protocol value=\"icmp\"/>\n26:   <protocol value=\"ipv6-icmp\"/>\n27: \n28:   <masquerade/>\n29: </zone>\n\n(End of file - total 29 lines)\n</content>","title":"home/livings/Projects/zen-hardening/firewalld-workstation.conf","metadata":{"preview":"<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<!--\n  Workstation firewall — Garuda Linux / Arch\n  Install:  sudo cp firewalld-workstation.conf /etc/firewalld/zones/public.xml\n            sudo firewall-cmd --reload\n  Revert:   sudo rm /etc/firewalld/zones/public.xml && sudo firewall-cmd --reload\n\n  Zone: public (Garuda''s default active zone)\n  Opens: SSH only.\n\n  Steam needs more and is NOT configured here. Add explicitly when ready:\n    sudo firewall-cmd --add-port=27015-27016/udp --permanent   # matchmaking\n    sudo firewall-cmd --add-port=27017-27019/tcp --permanent   # in-home streaming\n-->\n<zone>\n  <short>Public</short>\n  <description>Workstation profile: deny incoming except SSH.</description>\n\n\n  <!-- No mdns or SMB chatter on untrusted networks -->","truncated":false,"loaded":[],"display":{"type":"file","path":"/home/livings/Projects/zen-hardening/firewalld-workstation.conf","text":"<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<!--\n  Workstation firewall — Garuda Linux / Arch\n  Install:  sudo cp firewalld-workstation.conf /etc/firewalld/zones/public.xml\n            sudo firewall-cmd --reload\n  Revert:   sudo rm /etc/firewalld/zones/public.xml && sudo firewall-cmd --reload\n\n  Zone: public (Garuda''s default active zone)\n  Opens: SSH only.\n\n  Steam needs more and is NOT configured here. Add explicitly when ready:\n    sudo firewall-cmd --add-port=27015-27016/udp --permanent   # matchmaking\n    sudo firewall-cmd --add-port=27017-27019/tcp --permanent   # in-home streaming\n-->\n<zone>\n  <short>Public</short>\n  <description>Workstation profile: deny incoming except SSH.</description>\n\n\n  <!-- No mdns or SMB chatter on untrusted networks -->\n  <service name=\"mdns\" disable=\"yes\"/>\n  <service name=\"samba-client\" enable=\"no\"/>\n\n  <!-- ICMP: keep ping for diagnostics -->\n  <protocol value=\"icmp\"/>\n  <protocol value=\"ipv6-icmp\"/>\n\n  <masquerade/>\n</zone>","lineStart":1,"lineEnd":29,"totalLines":29,"truncated":false}},"time":{"start":1790452807891,"end":1790452807907}}},"time":1790452807907}');
