INSERT INTO event VALUES('evt_0df4de827002mvU2rZ3z5Q2cwq','ses_f211dfcd4ffevS1Yoddwab036g',7257,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df4dde03001208oe4AC2g3vUv","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df4dd779001Lrr3AaoVH1JUT3","type":"reasoning","text":"Now I see the picture clearly:\n- The live `/etc/firewalld/zones/public.xml` IS a copy of the old source (with ssh), just with comments stripped.\n- The live zone shows `dhcpv6-client ssh` — so `dhcpv6-client` comes from the BUILT-IN firewalld public.xml, meaning firewalld MERGES the /etc override with the built-in defaults. Good — that''s the answer.\n\nActually wait. Does it merge? The live zone shows `dhcpv6-client ssh`. The live /etc file only has `ssh` (explicitly), plus mdns disabled, samba disabled. So `dhcpv6-client` must be inherited from the built-in public.xml. That confirms MERGE behavior.\n\nGood. So:\n- Removing `ssh` from the source is correct; the built-in dhcpv6-client stays via merge.\n- I need to ALSO remove ssh from the live /etc file, or the merge will keep it.\n\nNow let me fix the stale comments in the source file since \"Opens: SSH only\" is now false.\n\nLet me update the header and description.\n\nLet me fix the file.","time":{"start":1790452817411,"end":1790452820007}},"time":1790452820007}');
