INSERT INTO event VALUES('evt_0df4e4f6c0019fghP1DiUCSTy6','ses_f211dfcd4ffevS1Yoddwab036g',7325,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df4e4f6c001XbVkfSLZhbu1QI","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df4e4889001vlVK7AYPWJsqCu","type":"step-start"},"time":1790452846444}');
INSERT INTO event VALUES('evt_0df4e4f6e001F1AZog23R2L5BV','ses_f211dfcd4ffevS1Yoddwab036g',7326,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df4e4f6e001i749snIx4IRY5c","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df4e4889001vlVK7AYPWJsqCu","type":"text","text":"","time":{"start":1790452846446}},"time":1790452846446}');
INSERT INTO event VALUES('evt_0df4e61f70016TeM2Jrjt6MYrb','ses_f211dfcd4ffevS1Yoddwab036g',7327,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df4e4f6e001i749snIx4IRY5c","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df4e4889001vlVK7AYPWJsqCu","type":"text","text":"Pushed. Your deferral is recorded as code, not just a decision.\n\n## Applied now (needs your sudo)\n\n```bash\nsudo firewall-cmd --permanent --zone=public --remove-service=ssh\nsudo cp ~/Projects/zen-hardening/firewalld-workstation.conf /etc/firewalld/zones/public.xml\nsudo firewall-cmd --reload\n```\n\nVerify: `firewall-cmd --zone=public --list-services` should show only `dhcpv6-client`.\n\nI copied the file this time rather than using the CLI, because the source also carries the corrected comments and the mdns/samba disables.\n\n## Deferred, as you asked\n\n`set-home-trusted-zone.sh` is written and **not applied** — dry run confirms no `home-net` zone was created. KDE Connect stays blocked on every network. When you have a home network you administer:\n\n```bash\n./set-home-trusted-zone.sh                                    # dry run\nsudo ./set-home-trusted-zone.sh --apply \"YourHomeSSID\"\n```\n\nIt refuses to proceed on an open or WEP network, and uses `target=default` rather than firewalld''s `trusted` target — the built-in `trusted` target accepts *all* inbound, which is the opposite of what you want. The script''s failure mode is closed, not open.\n\n## Two things I found and fixed without asking\n\n1. **The zone file was never valid XML.** `--` is illegal inside XML comments, and the file had `--reload` in them. firewalld''s parser is lenient enough that it loaded anyway, but any stricter tool would have rejected it. Fixed and verified well-formed.\n\n2. **A comment claimed \"keep ping for diagnostics.\"** Left as-is that''s an invitation for someone to block ICMP later for \"security,\" which would break IPv6 and stall large downloads. Rewritten to state that PMTU and IPv6 NDP *must* pass.\n\n## Still outstanding\n\n- `set-anon-identity.sh` is written but **not yet run** — hostname is still `living-asustufdashf15fx517zcfx517zc` and `wlo1` still broadcasts your real MAC `f4:a4:75:e8:00:b2`\n- No browser installed, so tor''s SOCKS port has nothing using it\n- `machine-id` still unique — separate decision, flagged in the script\n- fail2ban jail list still unverified (`sddm`, `sudo`, `sshd`, `recidive`)","time":{"start":1790452846446,"end":1790452851191}},"time":1790452851191}');
