INSERT INTO event VALUES('evt_0df51c674001AEmTGsReq4dkuB','ses_f211dfcd4ffevS1Yoddwab036g',7555,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df51c55a001e0eTYvNvMUjB50","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df51bb04001SUFDIdmX6uG5jj","type":"tool","callID":"call_function_xhml1khxqg2l_1","tool":"bash","state":{"status":"running","input":{"command":"python3 - <<''PY'' 2>&1 | sed ''s/^/  /''\nimport inspect\nfrom firewall.core.io import zone as zmod\nprint(inspect.getsource(zmod.zone_reader))\nPY"},"metadata":{"output":""},"time":{"start":1790453073520}}},"time":1790453073523}');
INSERT INTO event VALUES('evt_0df51c6d1001zaZ5Nvucm0R9fZ','ses_f211dfcd4ffevS1Yoddwab036g',7556,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df51c55a001e0eTYvNvMUjB50","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df51bb04001SUFDIdmX6uG5jj","type":"tool","callID":"call_function_xhml1khxqg2l_1","tool":"bash","state":{"status":"running","input":{"command":"python3 - <<''PY'' 2>&1 | sed ''s/^/  /''\nimport inspect\nfrom firewall.core.io import zone as zmod\nprint(inspect.getsource(zmod.zone_reader))\nPY"},"metadata":{"output":"  def zone_reader(filename, path, check_name_len=True):\n      zone = Zone()\n      if not filename.endswith(\".xml\"):\n          raise FirewallError(\n              errors.INVALID_NAME, \"''%s'' is missing .xml suffix\" % filename\n          )\n      zone.name = filename[:-4]\n      zone.check_name(zone.name, check_name_len=check_name_len)\n      zone.filename = filename\n      zone.path = path\n      zone.builtin = False if path.startswith(config.ETC_FIREWALLD) else True\n      zone.default = zone.builtin\n      # new Zone() objects default this to True, but if reading on disk\n      # configuration we have to assume False, because the absence of\n      # <forward> element indicates False. Presence indicates True.\n      zone.forward = False\n      handler = zone_ContentHandler(zone)\n      parser = sax.make_parser()\n      parser.setContentHandler(handler)\n      name = \"%s/%s\" % (path, filename)\n      with open(name, \"rb\") as f:\n          source = sax.InputSource(None)\n          source.setByteStream(f)\n          try:\n              parser.parse(source)\n          except sax.SAXParseException as msg:\n              raise FirewallError(\n                  errors.INVALID_ZONE, \"not a valid zone file: %s\" % msg.getException()\n              )\n      del handler\n      del parser\n      return zone\n  \n"},"time":{"start":1790453073520}}},"time":1790453073617}');
INSERT INTO event VALUES('evt_0df51c6d5001z3i1fxcTDXskc3','ses_f211dfcd4ffevS1Yoddwab036g',7557,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df51c55a001e0eTYvNvMUjB50","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df51bb04001SUFDIdmX6uG5jj","type":"tool","callID":"call_function_xhml1khxqg2l_1","tool":"bash","state":{"status":"completed","input":{"command":"python3 - <<''PY'' 2>&1 | sed ''s/^/  /''\nimport inspect\nfrom firewall.core.io import zone as zmod\nprint(inspect.getsource(zmod.zone_reader))\nPY"},"output":"  def zone_reader(filename, path, check_name_len=True):\n      zone = Zone()\n      if not filename.endswith(\".xml\"):\n          raise FirewallError(\n              errors.INVALID_NAME, \"''%s'' is missing .xml suffix\" % filename\n          )\n      zone.name = filename[:-4]\n      zone.check_name(zone.name, check_name_len=check_name_len)\n      zone.filename = filename\n      zone.path = path\n      zone.builtin = False if path.startswith(config.ETC_FIREWALLD) else True\n      zone.default = zone.builtin\n      # new Zone() objects default this to True, but if reading on disk\n      # configuration we have to assume False, because the absence of\n      # <forward> element indicates False. Presence indicates True.\n      zone.forward = False\n      handler = zone_ContentHandler(zone)\n      parser = sax.make_parser()\n      parser.setContentHandler(handler)\n      name = \"%s/%s\" % (path, filename)\n      with open(name, \"rb\") as f:\n          source = sax.InputSource(None)\n          source.setByteStream(f)\n          try:\n              parser.parse(source)\n          except sax.SAXParseException as msg:\n              raise FirewallError(\n                  errors.INVALID_ZONE, \"not a valid zone file: %s\" % msg.getException()\n              )\n      del handler\n      del parser\n      return zone\n  \n","title":"python3 - <<''PY'' 2>&1 | sed ''s/^/  /''\nimport inspect\nfrom firewall.core.io import zone as zmod\nprint(inspect.getsource(zmod.zone_reader))\nPY","metadata":{"output":"  def zone_reader(filename, path, check_name_len=True):\n      zone = Zone()\n      if not filename.endswith(\".xml\"):\n          raise FirewallError(\n              errors.INVALID_NAME, \"''%s'' is missing .xml suffix\" % filename\n          )\n      zone.name = filename[:-4]\n      zone.check_name(zone.name, check_name_len=check_name_len)\n      zone.filename = filename\n      zone.path = path\n      zone.builtin = False if path.startswith(config.ETC_FIREWALLD) else True\n      zone.default = zone.builtin\n      # new Zone() objects default this to True, but if reading on disk\n      # configuration we have to assume False, because the absence of\n      # <forward> element indicates False. Presence indicates True.\n      zone.forward = False\n      handler = zone_ContentHandler(zone)\n      parser = sax.make_parser()\n      parser.setContentHandler(handler)\n      name = \"%s/%s\" % (path, filename)\n      with open(name, \"rb\") as f:\n          source = sax.InputSource(None)\n          source.setByteStream(f)\n          try:\n              parser.parse(source)\n          except sax.SAXParseException as msg:\n              raise FirewallError(\n                  errors.INVALID_ZONE, \"not a valid zone file: %s\" % msg.getException()\n              )\n      del handler\n      del parser\n      return zone\n  \n","exit":0,"truncated":false},"time":{"start":1790453073520,"end":1790453073621}}},"time":1790453073621}');
