INSERT INTO event VALUES('evt_0df525300001IjYbEJ07kBUdPu','ses_f211dfcd4ffevS1Yoddwab036g',7663,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df52485a001h2hF12t2wlo2g4","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df5228f4001lFpF6TocXbqSQZ","type":"text","text":"`remove-service` doesn''t exist in firewalld 2.5.2 at all. So a zone file simply **cannot** suppress an inherited service — the built-in `public` name is the problem, since same-name files get merged.\n\nLet me verify the correct pattern: a custom zone starts empty and inherits nothing.","time":{"start":1790453106778,"end":1790453109504}},"time":1790453109504}');
