INSERT INTO event VALUES('evt_0df529d81001okRqxvmIjk1rTa','ses_f211dfcd4ffevS1Yoddwab036g',7700,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df529906001qE9018y2Uwd0co","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df5291350016djL6MlFqB0mV8","type":"tool","callID":"call_function_fztilhkrs4z6_1","tool":"bash","state":{"status":"running","input":{"command":"cd /tmp/opencode\nrm -rf ztest && mkdir -p ztest\ncp ~/Projects/zen-hardening/workstation.xml ztest/\npython3 - <<''PY'' 2>&1 | sed ''s/^/  /''\nfrom firewall.core.io.zone import zone_reader\nfrom firewall import errors\ntry:\n    z = zone_reader(\"workstation.xml\", \"/tmp/opencode/ztest\")\n    print(\"  [ok] PARSES against real firewalld 2.5.2 schema\")\n    print(\"     name        :\", z.name)\n    print(\"     services    :\", sorted(z.get_services()))\n    print(\"     protocols   :\", sorted(z.get_protocols()))\n    print(\"     icmp_blocks :\", sorted(z.get_icmp_blocks()) or \"none (PMTU+NDP pass)\")\n    print(\"     masquerade  :\", z.get_masquerade())\n    print(\"     target      :\", z.get_target())\nexcept errors.FirewallError as e:\n    print(\"  [!!] REJECTED:\", e)\nPY"},"time":{"start":1790453128577}}},"time":1790453128577}');
