INSERT INTO event VALUES('evt_0df56713e001Qv4clMnd5BwMm3','ses_f211dfcd4ffevS1Yoddwab036g',7875,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df566b3a001hszIxCj2k7XX1Y","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df562d73001CWEaOvf6i5gcVW","type":"tool","callID":"call_function_3uto3birh12t_1","tool":"bash","state":{"status":"running","input":{"command":"echo \"═══ CURRENT ICMP-BLOCK STATE (authoritative) ═══\"\necho \"  --- public zone ---\"\nfirewall-cmd --zone=public --list-icmp-blocks 2>&1 | sed ''s/^/    /''\necho \"  --- default zone per interface ---\"\nfirewall-cmd --get-zone-of-interface=wlo1 2>&1 | sed ''s/^/    wlo1: /''\necho\necho \"═══ ARE THE CRITICAL TYPES BLOCKED ANYWHERE? ═══\"\nfor t in packet-too-big destination-unreachable time-exceeded \\\n         v6-neighbour-solicit v6-neighbour-advert v6-redirect echo-request; do\n  for z in public; do\n    v=$(firewall-cmd --zone=$z --query-icmp-block=\"$t\" 2>&1)\n    [ \"$v\" = \"yes\" ] && printf \"    [BLOCKED] %-24s in %s\\n\" \"$t\" \"$z\"\n  done\ndone\necho \"  (nothing listed above = none blocked, PMTU and NDP are open)\""},"metadata":{"output":""},"time":{"start":1790453379390}}},"time":1790453379390}');
