INSERT INTO event VALUES('evt_0df567142001vDMAFtTycQ40Lq','ses_f211dfcd4ffevS1Yoddwab036g',7877,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df5665a4001UInOjmmtvTd1MK","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df562d73001CWEaOvf6i5gcVW","type":"text","text":"Found it — each `INVALID_ICMPTYPE` was immediately preceded by a **polkit password dialog**:\n\n```\n12:57:18  Request: \"Password: \"   →  COMPLETED: true\n12:57:18  ERROR: INVALID_ICMPTYPE: v6-neighbour-advert\n12:57:20  Request: \"Password: \"   →  COMPLETED: true\n12:57:20  ERROR: INVALID_ICMPTYPE: v6-redirect\n```\n\nThree privileged `firewall-cmd` calls, each prompting for your password, each rejected. Something ran three `--add-icmp-block` commands under `sudo` at 12:57. Let me check whether any ICMP block actually took effect — that''s the part that matters:","time":{"start":1790453376421,"end":1790453379394}},"time":1790453379394}');
