INSERT INTO event VALUES('evt_0df5dd21a001Ya2vGpEqegh7Eb','ses_f211dfcd4ffevS1Yoddwab036g',8143,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df5dcc16001Kra6MIEiSX6j5o","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df5da62100159i5pItFkL4lfO","type":"text","text":"`table inet firewalld` means the table **exists** — that''s enforcement confirmed. In firewalld 2.x the nftables backend uses a single `inet firewalld` table holding the filter, nat, and mangle chains, so one table is exactly right. Not empty.\n\nTo see the zone actually wired in:\n\n```bash\nsudo nft list chains table inet firewalld | grep -i workstation\n```\n\nThat should show `filter_IN_workstation_allow`. Combined with the zone dump from before — `services: dhcpv6-client`, nothing else — the firewall is up and strict.\n\nLet me push the working configs now, since they''re validated against your live system:","time":{"start":1790453861398,"end":1790453862938}},"time":1790453862938}');
