INSERT INTO event VALUES('evt_0df5e0fbf001hPe7U4CWBIhsmE','ses_f211dfcd4ffevS1Yoddwab036g',8200,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df5e0fbf001PEweJLkXb5azEh","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df5e071c001ZNXFB55T406h8a","type":"step-start"},"time":1790453878719}');
