INSERT INTO event VALUES('evt_0df5e8059001vSLkWxg3LeAnYK','ses_f20e5cfc2ffeSFa4odnoYLiUOk',1746,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df5e7ae20010B0lAbhgXxIeUC","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df5e7102001CfhNwvs8yXpXmk","type":"tool","callID":"call_function_hrkbdlxnzf6f_1","tool":"edit","state":{"status":"running","input":{"filePath":"/home/livings/Projects/buildlog/seed-vcs-sources.sh","newString":"    if [ -n \"$ref\" ]; then\n        git -C \"$dest\" config remote.origin.fetch \"+${ref}:${ref}\"\n        if git -C \"$dest\" fetch --depth 1 --no-tags origin \"${ref}:${ref}\" >/dev/null 2>&1; then\n            echo \"  ok     $name ($frag)\"\n            return 0\n        fi\n        # A tag/branch pin that will not fetch shallowly is a hard stop. Do\n        # NOT fall through to the default branch: for nodejs/node that means\n        # pulling ~330k objects of history to satisfy a v20.19.1 pin that a\n        # full clone would have resolved anyway. Leave it absent and let\n        # makepkg do the one clone it cannot avoid.\n        echo \"  DEFER  $name ($frag not fetchable shallowly; makepkg will clone)\"\n        rm -rf \"$dest\"\n        return 1\n    fi","oldString":"    if [ -n \"$ref\" ]; then\n        git -C \"$dest\" config remote.origin.fetch \"+${ref}:${ref}\"\n        if git -C \"$dest\" fetch --depth 1 --no-tags origin \"${ref}:${ref}\" >/dev/null 2>&1; then\n            echo \"  ok     $name ($frag)\"\n            return 0\n        fi\n    fi"},"time":{"start":1790453907545}}},"time":1790453907545}');
