INSERT INTO event VALUES('evt_0df622f650013O9lUiXnYREUdD','ses_f211dfcd4ffevS1Yoddwab036g',8347,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df622796001jY7PiymiPz6YOW","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df6210a2001Ws4L9LoZ6b0eMQ","type":"text","text":"The function needs defining before use — it was a suggestion, not something already in your shell. Inline version:\n\n```fish\nwhile not sudo fail2ban-client status 2>/dev/null | grep -q \"Jail list\"\n    sleep 0.5\nend\nsudo fail2ban-client status\n```\n\nThis keeps you in `fail2ban-client status` until jails are actually registered, so the race can''t bite again.\n\nSince this has now cost us three round-trips, let me make it permanent:","time":{"start":1790454146966,"end":1790454148964}},"time":1790454148964}');
