INSERT INTO event VALUES('evt_0df623ffb001nP6QAWWtjTMhLO','ses_f211dfcd4ffevS1Yoddwab036g',8359,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df623a6a0015U3x3052Mdx9ER","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df622f93001A8sMvyJ0lpywY5","type":"tool","callID":"call_function_605ei07xphxs_1","tool":"bash","state":{"status":"running","input":{"command":"cat >> ~/.config/fish/config.fish <<''EOF''\n\n# ── fail2ban readiness helper ───────────────────────────────────────────\n# fail2ban creates its control socket during Python init, so `systemctl\n# restart` returns (and reports \"active\") BEFORE the socket exists. Querying\n# immediately yields \"Failed to access socket path\". `ping` is also not a\n# sufficient gate: it answers once the server accepts connections, which is\n# before jails finish registering. Wait on the jail list instead.\nfunction f2bready\n    while not sudo fail2ban-client status 2>/dev/null | grep -q \"Jail list\"\n        sleep 0.5\n    end\n    sudo fail2ban-client status\nend\nEOF\necho \"  [ok] appended to ~/.config/fish/config.fish\"\necho\necho \"═══ verify it parses in fish ═══\"\nfish -c ''source ~/.config/fish/config.fish; functions -q f2bready; and echo \"  [ok] f2bready defined\"'' 2>&1 | sed ''s/^/  /''"},"metadata":{"output":""},"time":{"start":1790454153211}}},"time":1790454153211}');
