INSERT INTO event VALUES('evt_0df62526c0011fj3RPs5xHsoGH','ses_f211dfcd4ffevS1Yoddwab036g',8372,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df624be6001QSoiaHLr2c6vgO","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df62423c001JdH10MdzwSN9Xp","type":"text","text":"`f2bready` is now in `~/.config/fish/config.fish` and verified. Load it in your current shell:\n\n```fish\nsource ~/.config/fish/config.fish\n```\n\nOr just paste this to check the jails right now:\n\n```fish\nwhile not sudo fail2ban-client status 2>/dev/null | grep -q \"Jail list\"\n    sleep 0.5\nend\nsudo fail2ban-client status\n```\n\nExpect **2 jails** — `recidive` and `sshd`. If you see 3, recidive didn''t take and the `sed` didn''t match.\n\nOnce confirmed I''ll push the config. Current tally for this session: firewall strict and verified, hostname `zero`, fail2ban 24h bans with the two dead jails removed.","time":{"start":1790454156262,"end":1790454157932}},"time":1790454157932}');
