INSERT INTO event VALUES('evt_0df65151b001gUBC0vhIR3dqmc','ses_f211dfcd4ffevS1Yoddwab036g',8537,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df650f54001YwSzq0hfmP7Jwq","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df64dfff001ozkEnbfEGTgF6r","type":"text","text":"Not a new bug — my fault. My rewritten file ships `recidive` with `enabled = false` (the bootstrap-order default), so copying it over **undid** the `sed` you''d already run.\n\n```\nline 73:  enabled = true    <- sshd\nline 98:  enabled = false   <- recidive, reset by my file\n```\n\nClean restarts throughout, no errors. Recidive is just disabled in config again:","time":{"start":1790454337364,"end":1790454338843}},"time":1790454338843}');
