INSERT INTO event VALUES('evt_0df692e8d001DXYFMqrlAdfrXu','ses_f211dfcd4ffevS1Yoddwab036g',8678,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df6928eb001CfuRbxHdLBV2iI","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df690752001yMA1fNZE8c542G","type":"tool","callID":"call_function_3nxn5yfkfxpg_1","tool":"bash","state":{"status":"running","input":{"command":"echo \"═══ MAC RANDOMIZATION — did set-anon-identity.sh actually work? ═══\"\nfor c in $(nmcli -t -f UUID connection show --active 2>/dev/null | cut -d: -f1); do\n  nm=$(nmcli -g connection.id con show \"$c\")\n  mode=$(nmcli -g 802-11-wireless.mac-address-mode con show \"$c\")\n  mac=$(nmcli -g 802-11-wireless.mac-address con show \"$c\")\n  printf \"  %-14s mode=%-10s mac=%s\\n\" \"$nm\" \"${mode:-<unset>}\" \"${mac:-<random per net>}\"\ndone\necho\necho \"  current kernel-level MAC: $(cat /sys/class/net/wlo1/address)\"\necho\necho \"  NOTE: mode must read ''random''. ''stable''/''preserve'' = permanent MAC.\""},"time":{"start":1790454607501}}},"time":1790454607501}');
