INSERT INTO event VALUES('evt_0df69670b001Q18vTbTpPy20dd','ses_f211dfcd4ffevS1Yoddwab036g',8708,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df69621d0011hpg90PaA564Ck","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df693cc3001j5kxqIZqFW1JS5","type":"tool","callID":"call_function_69io2znjxqm9_1","tool":"bash","state":{"status":"running","input":{"command":"echo \"═══ ROOT CAUSE: wrong property name for this NetworkManager ═══\"\nnmcli -v | sed ''s/^/  /''\necho\necho \"  my script used:  802-11-wireless.mac-address-mode      <-- does not exist\"\necho \"  correct here:   802-11-wireless.mac-address-randomization\"\necho\necho \"═══ CURRENT VALUE (0=permanent 1=random 2=stable) ═══\"\nfor c in $(nmcli -t -f UUID connection show --active 2>/dev/null | cut -d: -f1); do\n  nm=$(nmcli -g connection.id con show \"$c\")\n  r=$(nmcli -g 802-11-wireless.mac-address-randomization con show \"$c\" 2>/dev/null)\n  d=$(nmcli -g 802-11-wireless.mac-address-denylist con show \"$c\" 2>/dev/null)\n  printf \"  %-14s randomization=%-4s denylist=%s\\n\" \"$nm\" \"${r:-0}\" \"${d:-<none>}\"\ndone\necho\necho \"  0 or unset = permanent hardware MAC in use\""},"metadata":{"output":""},"time":{"start":1790454621963}}},"time":1790454621963}');
