INSERT INTO event VALUES('evt_0df69671b001HYMi90vDRZNrKt','ses_f211dfcd4ffevS1Yoddwab036g',8711,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df6960be001NdMGZg4SbLlthS","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df693cc3001j5kxqIZqFW1JS5","type":"text","text":"Found a real bug in my own script. MAC randomization was **never applied** — `wlo1` is still broadcasting `f4:a4:75:e8:00:b2`, your actual hardware MAC.","time":{"start":1790454620350,"end":1790454621979}},"time":1790454621979}');
