INSERT INTO event VALUES('evt_0df6973520028nJnrJK3RIsdry','ses_f211dfcd4ffevS1Yoddwab036g',8724,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df697352001D8gpqzmbPC3bJL","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df696782001EH1z55MY5VXciY","type":"tool","callID":"call_function_32v8xq8i08sl_1","tool":"edit","state":{"status":"pending","input":{},"raw":""}},"time":1790454625106}');
INSERT INTO event VALUES('evt_0df69841e0010jjdIn8i4mp0Qj','ses_f211dfcd4ffevS1Yoddwab036g',8725,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df697352001D8gpqzmbPC3bJL","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df696782001EH1z55MY5VXciY","type":"tool","callID":"call_function_32v8xq8i08sl_1","tool":"edit","state":{"status":"running","input":{"filePath":"/home/livings/Projects/zen-hardening/set-anon-identity.sh","newString":"hr \"2. Per-network random MAC on wifi\"\n\n# Without this, NetworkManager uses the permanent hardware MAC on every\n# network the machine ever joins, which is the strongest cross-network\n# tracking signal there is.\n#\n# PROPERTY NAME DIFFERS BY NetworkManager VERSION. Verified on 1.58.1:\n#   802-11-wireless.mac-address-randomization   (this version)\n#       0 = default, 1 = random (per network), 2 = stable\n# Older releases used 802-11-wireless.mac-address-mode with values\n# random/stable/preserve. Detect which one this build accepts rather than\n# assuming, and fail loudly if neither works -- a silent no-op here means\n# the hardware MAC keeps broadcasting.\nset_mac_prop=\"\"\nif nmcli -g 802-11-wireless.mac-address-randomization con show \"$(nmcli -t -f UUID con show | head -1)\" >/dev/null 2>&1; then\n  set_mac_prop=\"802-11-wireless.mac-address-randomization\"\n  set_mac_val=\"1\"\nelse\n  set_mac_prop=\"802-11-wireless.mac-address-mode\"\n  set_mac_val=\"random\"\nfi\necho \"  using property: ${set_mac_prop} = ${set_mac_val}\"\n\nwhile read -r uuid; do\n  [ -z \"$uuid\" ] && continue\n  con_id=$(nmcli -g connection.id con show \"$uuid\")\n  cur=$(nmcli -g \"$set_mac_prop\" con show \"$uuid\" 2>/dev/null)\n  if [ \"$cur\" = \"$set_mac_val\" ] || [ \"$cur\" = \"random\" ]; then\n    echo \"  ''${con_id}'': already randomized — skipping\"\n  else\n    if ! nmcli con mod \"$uuid\" \"$set_mac_prop\" \"$set_mac_val\"; then\n      echo \"  [!!] FAILED to set MAC randomization on ''${con_id}''\" >&2\n      MAC_FAILED=1\n    else\n      CHANGED=1\n      echo \"  [ok] ''${con_id}'': mac randomization -> ${set_mac_val}\"\n    fi\n  fi\ndone < <(nmcli -t -f UUID,TYPE con show | awk -F: ''$2==\"802-11-wireless\"{print $1}'')","oldString":"hr \"2. Per-network random MAC on wifi\"\n\n# Without this, NetworkManager uses the permanent hardware MAC on every\n# network the machine ever joins, which is the strongest cross-network\n# tracking signal there is.\nwhile read -r uuid; do\n  [ -z \"$uuid\" ] && continue\n  con_id=$(nmcli -g connection.id con show \"$uuid\")\n  if nmcli -g 802-11-wireless.mac-address-mode con show \"$uuid\" 2>/dev/null | grep -qx random; then\n    echo \"  ''${con_id}'': already random — skipping\"\n  else\n    nmcli con mod \"$uuid\" 802-11-wireless.mac-address-mode random\n    CHANGED=1\n    echo \"  [ok] ''${con_id}'': mac-address-mode -> random\"\n  fi\ndone < <(nmcli -t -f UUID,TYPE con show | awk -F: ''$2==\"802-11-wireless\"{print $1}'')"},"time":{"start":1790454629406}}},"time":1790454629406}');
INSERT INTO event VALUES('evt_0df698420001p5dcS88EERk6af','ses_f211dfcd4ffevS1Yoddwab036g',8726,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df697020001Q1SsmUYLhHpidq","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df696782001EH1z55MY5VXciY","type":"text","text":"Confirmed. `randomization=default` (0) — permanent MAC. My script used `mac-address-mode`, which this NetworkManager 1.58 doesn''t have, so `nmcli con mod` failed and `set -e` aborted the script at step 2 — which also means **step 3, DHCP hostname suppression, never ran.** Fixing both:","time":{"start":1790454624288,"end":1790454629407}},"time":1790454629408}');
INSERT INTO event VALUES('evt_0df698425001a9sCkE7lU1HxgI','ses_f211dfcd4ffevS1Yoddwab036g',8727,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df697352001D8gpqzmbPC3bJL","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df696782001EH1z55MY5VXciY","type":"tool","callID":"call_function_32v8xq8i08sl_1","tool":"edit","state":{"status":"running","input":{"filePath":"/home/livings/Projects/zen-hardening/set-anon-identity.sh","newString":"hr \"2. Per-network random MAC on wifi\"\n\n# Without this, NetworkManager uses the permanent hardware MAC on every\n# network the machine ever joins, which is the strongest cross-network\n# tracking signal there is.\n#\n# PROPERTY NAME DIFFERS BY NetworkManager VERSION. Verified on 1.58.1:\n#   802-11-wireless.mac-address-randomization   (this version)\n#       0 = default, 1 = random (per network), 2 = stable\n# Older releases used 802-11-wireless.mac-address-mode with values\n# random/stable/preserve. Detect which one this build accepts rather than\n# assuming, and fail loudly if neither works -- a silent no-op here means\n# the hardware MAC keeps broadcasting.\nset_mac_prop=\"\"\nif nmcli -g 802-11-wireless.mac-address-randomization con show \"$(nmcli -t -f UUID con show | head -1)\" >/dev/null 2>&1; then\n  set_mac_prop=\"802-11-wireless.mac-address-randomization\"\n  set_mac_val=\"1\"\nelse\n  set_mac_prop=\"802-11-wireless.mac-address-mode\"\n  set_mac_val=\"random\"\nfi\necho \"  using property: ${set_mac_prop} = ${set_mac_val}\"\n\nwhile read -r uuid; do\n  [ -z \"$uuid\" ] && continue\n  con_id=$(nmcli -g connection.id con show \"$uuid\")\n  cur=$(nmcli -g \"$set_mac_prop\" con show \"$uuid\" 2>/dev/null)\n  if [ \"$cur\" = \"$set_mac_val\" ] || [ \"$cur\" = \"random\" ]; then\n    echo \"  ''${con_id}'': already randomized — skipping\"\n  else\n    if ! nmcli con mod \"$uuid\" \"$set_mac_prop\" \"$set_mac_val\"; then\n      echo \"  [!!] FAILED to set MAC randomization on ''${con_id}''\" >&2\n      MAC_FAILED=1\n    else\n      CHANGED=1\n      echo \"  [ok] ''${con_id}'': mac randomization -> ${set_mac_val}\"\n    fi\n  fi\ndone < <(nmcli -t -f UUID,TYPE con show | awk -F: ''$2==\"802-11-wireless\"{print $1}'')","oldString":"hr \"2. Per-network random MAC on wifi\"\n\n# Without this, NetworkManager uses the permanent hardware MAC on every\n# network the machine ever joins, which is the strongest cross-network\n# tracking signal there is.\nwhile read -r uuid; do\n  [ -z \"$uuid\" ] && continue\n  con_id=$(nmcli -g connection.id con show \"$uuid\")\n  if nmcli -g 802-11-wireless.mac-address-mode con show \"$uuid\" 2>/dev/null | grep -qx random; then\n    echo \"  ''${con_id}'': already random — skipping\"\n  else\n    nmcli con mod \"$uuid\" 802-11-wireless.mac-address-mode random\n    CHANGED=1\n    echo \"  [ok] ''${con_id}'': mac-address-mode -> random\"\n  fi\ndone < <(nmcli -t -f UUID,TYPE con show | awk -F: ''$2==\"802-11-wireless\"{print $1}'')"},"metadata":{"diff":"Index: /home/livings/Projects/zen-hardening/set-anon-identity.sh\n===================================================================\n--- /home/livings/Projects/zen-hardening/set-anon-identity.sh\n+++ /home/livings/Projects/zen-hardening/set-anon-identity.sh\n@@ -47,17 +47,40 @@\n \n # Without this, NetworkManager uses the permanent hardware MAC on every\n # network the machine ever joins, which is the strongest cross-network\n # tracking signal there is.\n+#\n+# PROPERTY NAME DIFFERS BY NetworkManager VERSION. Verified on 1.58.1:\n+#   802-11-wireless.mac-address-randomization   (this version)\n+#       0 = default, 1 = random (per network), 2 = stable\n+# Older releases used 802-11-wireless.mac-address-mode with values\n+# random/stable/preserve. Detect which one this build accepts rather than\n+# assuming, and fail loudly if neither works -- a silent no-op here means\n+# the hardware MAC keeps broadcasting.\n+set_mac_prop=\"\"\n+if nmcli -g 802-11-wireless.mac-address-randomization con show \"$(nmcli -t -f UUID con show | head -1)\" >/dev/null 2>&1; then\n+  set_mac_prop=\"802-11-wireless.mac-address-randomization\"\n+  set_mac_val=\"1\"\n+else\n+  set_mac_prop=\"802-11-wireless.mac-address-mode\"\n+  set_mac_val=\"random\"\n+fi\n+echo \"  using property: ${set_mac_prop} = ${set_mac_val}\"\n+\n while read -r uuid; do\n   [ -z \"$uuid\" ] && continue\n   con_id=$(nmcli -g connection.id con show \"$uuid\")\n-  if nmcli -g 802-11-wireless.mac-address-mode con show \"$uuid\" 2>/dev/null | grep -qx random; then\n-    echo \"  ''${con_id}'': already random — skipping\"\n+  cur=$(nmcli -g \"$set_mac_prop\" con show \"$uuid\" 2>/dev/null)\n+  if [ \"$cur\" = \"$set_mac_val\" ] || [ \"$cur\" = \"random\" ]; then\n+    echo \"  ''${con_id}'': already randomized — skipping\"\n   else\n-    nmcli con mod \"$uuid\" 802-11-wireless.mac-address-mode random\n-    CHANGED=1\n-    echo \"  [ok] ''${con_id}'': mac-address-mode -> random\"\n+    if ! nmcli con mod \"$uuid\" \"$set_mac_prop\" \"$set_mac_val\"; then\n+      echo \"  [!!] FAILED to set MAC randomization on ''${con_id}''\" >&2\n+      MAC_FAILED=1\n+    else\n+      CHANGED=1\n+      echo \"  [ok] ''${con_id}'': mac randomization -> ${set_mac_val}\"\n+    fi\n   fi\n done < <(nmcli -t -f UUID,TYPE con show | awk -F: ''$2==\"802-11-wireless\"{print $1}'')\n \n hr \"3. Suppress DHCP hostname on every connection\"\n","filediff":{"file":"/home/livings/Projects/zen-hardening/set-anon-identity.sh","patch":"Index: /home/livings/Projects/zen-hardening/set-anon-identity.sh\n===================================================================\n--- /home/livings/Projects/zen-hardening/set-anon-identity.sh\n+++ /home/livings/Projects/zen-hardening/set-anon-identity.sh\n@@ -47,17 +47,40 @@\n \n # Without this, NetworkManager uses the permanent hardware MAC on every\n # network the machine ever joins, which is the strongest cross-network\n # tracking signal there is.\n+#\n+# PROPERTY NAME DIFF