INSERT INTO event VALUES('evt_0df69d7bb001cRLZtmfhwuWQwf','ses_f211dfcd4ffevS1Yoddwab036g',8766,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df69d44c001lPORs7Tuz5ZPyX","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df69c55f001e3HqntkKar86sU","type":"tool","callID":"call_function_pqypenfdrshr_1","tool":"bash","state":{"status":"running","input":{"command":"echo \"═══ TOR DAEMON HEALTH ═══\"\nsystemctl is-active tor | sed ''s/^/  tor: /''\nss -tln 2>/dev/null | grep -E \"9050|9051\" | sed ''s/^/  /''\necho\necho \"═══ tor actually reaching the network? ═══\"\ntorpid=$(pgrep -x tor | head -1)\n[ -n \"$torpid\" ] && journalctl -u tor -S \"-30min\" --no-pager 2>&1 | grep -iE \"bootstrapped|error\" | tail -4 | sed ''s/^/  /'' || echo \"  no tor process\""},"metadata":{"output":""},"time":{"start":1790454650811}}},"time":1790454650811}');
