INSERT INTO event VALUES('evt_0df69d7d8001T6Nx4ZQLH5aKg9','ses_f211dfcd4ffevS1Yoddwab036g',8768,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df69ceec001gkx5SUIS8uSnR6","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df69c55f001e3HqntkKar86sU","type":"text","text":"Detection logic works. DHCP suppression was already `-1` (suppressed) by NetworkManager''s default, so that gap was harmless. Run the fixed script:\n\n```bash\nsudo bash /home/livings/Projects/zen-hardening/set-anon-identity.sh\n```\n\nMAC changes take effect on the next reconnect. Then verify:\n\n```bash\nsudo nmcli con mod \"USL - Public\" 802-11-wireless.mac-address-randomization 1\nsudo nmcli con up \"USL - Public\"\ncat /sys/class/net/wlo1/address\n```\n\nThe address should **change** from `f4:a4:75:e8:00:b2` to a locally-administered one (second nibble of the first octet will be `2`, `6`, `a`, or `e`).\n\nNow the bigger piece — the missing browser:","time":{"start":1790454648556,"end":1790454650840}},"time":1790454650840}');
