INSERT INTO event VALUES('evt_0df6b542f001pkL7j027GE7Njr','ses_f20e5cfc2ffeSFa4odnoYLiUOk',2014,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df6b53600019ktXJqfI58tsjf","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df6b4b8e001OFe43hTkrh09O5","type":"tool","callID":"call_function_acegx7a358z8_2","tool":"bash","state":{"status":"running","input":{"command":"echo \"=== install-hardlock.sh ===\"; cat ~/Projects/bde-security-biometrics/hardlock/install-hardlock.sh 2>/dev/null | head -80 || echo \"  ABSENT\""},"metadata":{"output":"=== install-hardlock.sh ===\n#!/bin/bash\n# BDE HardLock Installer for BlackArch Linux\n# Enforces biometric authentication at boot and system lock\nset -euo pipefail\n\necho \"=== BDE HardLock Patch for BlackArch ===\"\n\n# 1) Install PAM biometrics stack\necho \"[*] Installing PAM biometrics...\"\nsudo pacman -S --noconfirm --needed pam-biometric libfprint 2>/dev/null || true\n\n# 2) Deploy BDE hardlock PAM config\necho \"[*] Deploying BDE hardlock PAM config...\"\nsudo install -Dm644 /opt/bde/hardlock/bde-hardlock.pam /etc/pam.d/bde-hardlock\n\n# 3) Enable biometric authentication for login, sudo, gdm, ssh\necho \"[*] Configuring system services...\"\nfor service in login sudo gdm-password sshd su; do\n  if [ -f \"/etc/pam.d/$service\" ]; then\n    if ! grep -q \"bde-hardlock\" \"/etc/pam.d/$service\" 2>/dev/null; then\n      echo \"auth [success=1 default=ignore] /usr/local/bin/bde-auth\" | sudo tee -a \"/etc/pam.d/$service\" >/dev/null\n      echo \"auth required pam_deny.so\" | sudo tee -a \"/etc/pam.d/$service\" >/dev/null\n    fi\n  fi\ndone\n\n# 4) Deploy systemd lock service\necho \"[*] Installing BDE lock service...\"\nsudo install -Dm644 /opt/bde/hardlock/bde-hardlock.service /etc/systemd/system/bde-hardlock.service\nsudo systemctl daemon-reload\nsudo systemctl enable --now bde-hardlock.service\n\n# 5) Deploy BlackArch-style package\necho \"[*] Building BlackArch package...\"\nif command -v pacman >/dev/null 2>&1 && [ -d /usr/share/blackarch ]; then\n  sudo cp -r /opt/bde/blackarch/bde-hardlock /usr/share/blackarch/ 2>/dev/null || true\n  sudo pacman -U --noconfirm /usr/share/blackarch/bde-hardlock/*.pkg.tar.zst 2>/dev/null || true\nfi\n\necho \"[+] BDE HardLock patch installed successfully\"\necho \"[*] Reboot to enforce biometric lock\"\n"},"time":{"start":1790454748194}}},"time":1790454748207}');
INSERT INTO event VALUES('evt_0df6b54340013QzBFje0x4khSY','ses_f20e5cfc2ffeSFa4odnoYLiUOk',2015,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df6b53600019ktXJqfI58tsjf","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df6b4b8e001OFe43hTkrh09O5","type":"tool","callID":"call_function_acegx7a358z8_2","tool":"bash","state":{"status":"completed","input":{"command":"echo \"=== install-hardlock.sh ===\"; cat ~/Projects/bde-security-biometrics/hardlock/install-hardlock.sh 2>/dev/null | head -80 || echo \"  ABSENT\""},"output":"=== install-hardlock.sh ===\n#!/bin/bash\n# BDE HardLock Installer for BlackArch Linux\n# Enforces biometric authentication at boot and system lock\nset -euo pipefail\n\necho \"=== BDE HardLock Patch for BlackArch ===\"\n\n# 1) Install PAM biometrics stack\necho \"[*] Installing PAM biometrics...\"\nsudo pacman -S --noconfirm --needed pam-biometric libfprint 2>/dev/null || true\n\n# 2) Deploy BDE hardlock PAM config\necho \"[*] Deploying BDE hardlock PAM config...\"\nsudo install -Dm644 /opt/bde/hardlock/bde-hardlock.pam /etc/pam.d/bde-hardlock\n\n# 3) Enable biometric authentication for login, sudo, gdm, ssh\necho \"[*] Configuring system services...\"\nfor service in login sudo gdm-password sshd su; do\n  if [ -f \"/etc/pam.d/$service\" ]; then\n    if ! grep -q \"bde-hardlock\" \"/etc/pam.d/$service\" 2>/dev/null; then\n      echo \"auth [success=1 default=ignore] /usr/local/bin/bde-auth\" | sudo tee -a \"/etc/pam.d/$service\" >/dev/null\n      echo \"auth required pam_deny.so\" | sudo tee -a \"/etc/pam.d/$service\" >/dev/null\n    fi\n  fi\ndone\n\n# 4) Deploy systemd lock service\necho \"[*] Installing BDE lock service...\"\nsudo install -Dm644 /opt/bde/hardlock/bde-hardlock.service /etc/systemd/system/bde-hardlock.service\nsudo systemctl daemon-reload\nsudo systemctl enable --now bde-hardlock.service\n\n# 5) Deploy BlackArch-style package\necho \"[*] Building BlackArch package...\"\nif command -v pacman >/dev/null 2>&1 && [ -d /usr/share/blackarch ]; then\n  sudo cp -r /opt/bde/blackarch/bde-hardlock /usr/share/blackarch/ 2>/dev/null || true\n  sudo pacman -U --noconfirm /usr/share/blackarch/bde-hardlock/*.pkg.tar.zst 2>/dev/null || true\nfi\n\necho \"[+] BDE HardLock patch installed successfully\"\necho \"[*] Reboot to enforce biometric lock\"\n","title":"echo \"=== install-hardlock.sh ===\"; cat ~/Projects/bde-security-biometrics/hardlock/install-hardlock.sh 2>/dev/null | head -80 || echo \"  ABSENT\"","metadata":{"output":"=== install-hardlock.sh ===\n#!/bin/bash\n# BDE HardLock Installer for BlackArch Linux\n# Enforces biometric authentication at boot and system lock\nset -euo pipefail\n\necho \"=== BDE HardLock Patch for BlackArch ===\"\n\n# 1) Install PAM biometrics stack\necho \"[*] Installing PAM biometrics...\"\nsudo pacman -S --noconfirm --needed pam-biometric libfprint 2>/dev/null || true\n\n# 2) Deploy BDE hardlock PAM config\necho \"[*] Deploying BDE hardlock PAM config...\"\nsudo install -Dm644 /opt/bde/hardlock/bde-hardlock.pam /etc/pam.d/bde-hardlock\n\n# 3) Enable biometric authentication for login, sudo, gdm, ssh\necho \"[*] Configuring system services...\"\nfor service in login sudo gdm-password sshd su; do\n  if [ -f \"/etc/pam.d/$service\" ]; then\n    if ! grep -q \"bde-hardlock\" \"/etc/pam.d/$service\" 2>/dev/null; then\n      echo \"auth [success=1 default=ignore] /usr/local/bin/bde-auth\" | sudo tee -a \"/etc/pam.d/$service\" >/dev/null\n      echo \"auth required pam_deny.so\" | sudo tee -a \"/etc/pam.d/$service\" >/dev/null\n    fi\n  fi\ndone\n\n# 4) Deploy systemd lock service\necho \"[*] Installing BDE lock service...\"\nsudo install -Dm644 /opt/bde/hardlock/bde-hardlock.service /etc/systemd/system/bde-hardlock.service\nsudo systemctl daemon-reload\nsudo systemctl enable --now bde-hardlock.service\n\n# 5) Deploy BlackArch-style package\necho \"[*] Building BlackArch package...\"\nif command -v pacman >/dev/null 2>&1 && [ -d /usr/share/blackarch ]; then\n  sudo cp -r /opt/bde/blackarch/bde-hardlock /usr/share/blackarch/ 2>/dev/null || true\n  sudo pacman -U --noconfirm /usr/share/blackarch/bde-hardlock/*.pkg.tar.zst 2>/dev/null || true\nfi\n\necho \"[+] BDE HardLock patch installed successfully\"\necho \"[*] Reboot to enforce biometric lock\"\n","exit":0,"truncated":false},"time":{"start":1790454748194,"end":1790454748212}}},"time":1790454748212}');
