"\nimport json\nimport os\nimport socket\nimport sys\nimport struct\nimport hashlib\n\nSOCKET_PATH = os.environ.get(\"BDE_SOCK\", \"/run/user/1000/bde-daemon.sock\")\n\ndef talk(payload: bytes) -> dict:\n    s = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)\n    s.settimeout(10.0)\n    s.connect(SOCKET_PATH)\n    s.sendall(json.dumps({\n        \"action\": \"verify\",\n        \"identity\": \"user\",\n        \"payload\": payload.hex()\n    }).encode())\n    data = b\"\"\n    while True:\n        chunk = s.recv(4096)\n        if not chunk:\n            break\n        data += chunk\n        if b\"\\n\" in data:\n            break\n    s.close()\n    return json.loads(data.decode() or \"{}\")\n\ndef capture_live() -> bytes:\n    s = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)\n    s.settimeout(15.0)\n    s.connect(SOCKET_PATH)\n    s.sendall(json.dumps({\"action\": \"capture\"}).encode())\n","title":"echo \"=== bde-hardlock.pam ===\"; cat ~/Projects/bde-security-biometrics/hardlock/bde-hardlock.pam 2>/dev/null\necho; echo \"=== the bde-auth it references ===\"; find ~/Projects/bde-security-biometrics/pam -type f 2>/dev/null | head; echo \"---\"; cat ~/Projects/bde-security-biometrics/pam/modules/* 2>/dev/null | head -40","metadata":{"output":"=== bde-hardlock.pam ===\n# /etc/pam.d/bde-hardlock\n# BDE HardLock biometrics PAM stack\n# Enforces bioelectrical biometrics for all system access\n\nauth [success=1 default=ignore] /usr/local/bin/bde-auth\nauth required pam_deny.so\n\n=== the bde-auth it references ===\n/home/livings/Projects/bde-security-biometrics/pam/daemon/__pycache__/bde-daemon.cpython-314.pyc\n/home/livings/Projects/bde-security-biometrics/pam/daemon/bde-daemon.py\n/home/livings/Projects/bde-security-biometrics/pam/daemon/bde-daemon.service\n/home/livings/Projects/bde-security-biometrics/pam/daemon/bde-sensor.py\n/home/livings/Projects/bde-security-biometrics/pam/daemon/bde-touchpad.py\n/home/livings/Projects/bde-security-biometrics/pam/modules/