first, or the PAM entry denies everything.\" >&2\n+        exit 1\n+    fi\n+fi\n+\n # 1) Install PAM biometrics stack\n-echo \"[*] Installing PAM biometrics...\"\n-sudo pacman -S --noconfirm --needed pam-biometric libfprint 2>/dev/null || true\n+echo \"[*] PAM biometrics packages...\"\n+run sudo pacman -S --noconfirm --needed pam-biometric libfprint\n \n # 2) Deploy BDE hardlock PAM config\n-echo \"[*] Deploying BDE hardlock PAM config...\"\n-sudo install -Dm644 /opt/bde/hardlock/bde-hardlock.pam /etc/pam.d/bde-hardlock\n+echo \"[*] Deploying bde-hardlock.pam...\"\n+run sudo install -Dm644 /opt/bde/hardlock/bde-hardlock.pam /etc/pam.d/bde-hardlock\n \n-# 3) Enable biometric authentication for login, sudo, gdm, ssh\n-echo \"[*] Configuring system services...\"\n-for service in login sudo gdm-password sshd su; do\n-  if [ -f \"/etc/pam.d/$service\" ]; then\n-    if ! grep -q \"bde-hardlock\" \"/etc/pam.d/$service\" 2>/dev/null; then\n-      echo \"auth [success=1 default=ignore] /usr/local/bin/bde-auth\" | sudo tee -a \"/etc/pam.d/$service\" >/dev/null\n-      echo \"auth required pam_deny.so\" | sudo tee -a \"/etc/pam.d/$service\" >/dev/null\n+# 3) Hook into PAM stacks\n+echo \"[*] Hooking PAM services...\"\n+for service in \"${BDE_SERVICES[@]}\"; do\n+    [ -f \"/etc/pam.d/$service\" ] || continue\n+    if grep -q \"bde-hardlock\" \"/etc/pam.d/$service\" 2>/dev/null; then\n+        echo \"    $service: already hooked, skipping\"\n+        continue\n     fi\n-  fi\n+    echo \"    $service: backing up\"\n+    run sudo cp -a \"/etc/pam.d/$service\" \"/etc/pam.d/$service.bde-backup.$(date +%Y%m%d%H%M%S)\"\n+    # bde-auth returns 0 (skip the next line) only on a real biometric match.\n+    # On failure it returns non-zero, which `default=ignore` swallows, so the\n+    # normal password module still runs. There is deliberately NO pam_deny.so\n+    # here: that line turned every daemon hiccup into a locked-out session.\n+    run sudo sh -c \"printf ''%s\\n'' \\\n+        ''auth [success=1 default=ignore] /usr/local/bin/bde-auth'' \\\n+        >> /etc/pam.d/$service\"\n+    echo \"    $service: hooked\"\n done\n \n # 4) Deploy systemd lock service\n-echo \"[*] Installing BDE lock service...\"\n-sudo install -Dm644 /opt/bde/hardlock/bde-hardlock.service /etc/systemd/system/bde-hardlock.service\n-sudo systemctl daemon-reload\n-sudo systemctl enable --now bde-hardlock.service\n+echo \"[*] Installing bde-hardlock.service...\"\n+run sudo install -Dm644 /opt/bde/hardlock/bde-hardlock.service /etc/systemd/system/bde-hardlock.service\n+run sudo systemctl daemon-reload\n+run sudo systemctl enable --now bde-hardlock.service\n \n-# 5) Deploy BlackArch-style package\n-echo \"[*] Building BlackArch package...\"\n-if command -v pacman >/dev/null 2>&1 && [ -d /usr/share/blackarch ]; then\n-  sudo cp -r /opt/bde/blackarch/bde-hardlock /usr/share/blackarch/ 2>/dev/null || true\n-  sudo pacman -U --noconfirm /usr/share/blackarch/bde-hardlock/*.pkg.tar.zst 2>/dev/null || true\n+echo\n+if [ \"$DRY_RUN\" = \"1\" ]; then\n+    echo \"[+] DRY RUN complete. Re-run without --dry-run to apply.\"\n+else\n+    echo \"[+] BDE HardLock installed (failmode=${BDE_FAILMODE:-open}).\"\n+    echo \"[*] Backups of every touched /etc/pam.d file are alongside it as *.bde-backup.*\"\n+    echo \"[*] To undo: restore those backups, then ''sudo systemctl disable --now bde-hardlock''.\"\n fi\n \n-echo \"[+] BDE HardLock patch installed successfully\"\n-echo \"[*] Reboot to enforce biometric lock\"\n","additions":71,"deletions":26},"truncated":false},"time":{"start":1790454928728,"end":1790454928741}}},"time":1790454928741}');
