INSERT INTO event VALUES('evt_0df6e32f2001d5AypFHADYWU6Q','ses_f20e5cfc2ffeSFa4odnoYLiUOk',2099,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df6e2947001Us3TtvVjLHqcT9","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df6e1587001OhWZ154yJLL7Z8","type":"tool","callID":"call_function_dom3bcxxllq2_1","tool":"edit","state":{"status":"running","input":{"filePath":"/home/livings/Projects/bde-security-biometrics/hardlock/bde-hardlock.pam","newString":"# /etc/pam.d/bde-hardlock\n# BDE HardLock biometrics PAM stack\n# Enforces bioelectrical biometrics for all system access\n#\n# The pam_deny.so line that used to sit here made this stack fail CLOSED:\n# bde-auth returning non-zero for any reason at all -- daemon down, socket\n# missing, a timeout -- was treated as a failed login. Combined with an\n# installer that hooked login, sudo and sshd, that is a lockout.\n#\n# bde-auth now distinguishes \"denied\" (exit 1, a real biometric mismatch) from\n# \"unavailable\" (exit 2, no verdict because the daemon is not running), and\n# honours BDE_FAILMODE, which defaults to \"open\". Omit pam_deny.so so that\n# `default=ignore` hands control back to the normal password module.\nauth [success=1 default=ignore] /usr/local/bin/bde-auth\n","oldString":"# /etc/pam.d/bde-hardlock\n# BDE HardLock biometrics PAM stack\n# Enforces bioelectrical biometrics for all system access\n\nauth [success=1 default=ignore] /usr/local/bin/bde-auth\nauth required pam_deny.so\n"},"time":{"start":1790454936305}}},"time":1790454936306}');
