INSERT INTO event VALUES('evt_0df6f04b20010KRqFVAQwRK0HG','ses_f211dfcd4ffevS1Yoddwab036g',9147,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df6f0088001ynFA4aKrIEM7ps","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df6ed897001pGTX8pSTk3J5iF","type":"tool","callID":"call_function_qnnnc1xl296d_1","tool":"bash","state":{"status":"running","input":{"command":"u=$(nmcli -t -f UUID,NAME con show | awk -F: ''$2==\"USL - Public\"{print $1}'')\necho \"  current: $(nmcli -g 802-11-wireless.mac-address-randomization con show \"$u\")\"\necho\necho \"═══ does NM accept the keyword ''yes''? ═══\"\nif nmcli con mod \"$u\" 802-11-wireless.mac-address-randomization yes 2>&1; then\n  echo \"  [ok] accepted ''yes'' -> now reports: $(nmcli -g 802-11-wireless.mac-address-randomization con show \"$u\")\"\nelse\n  echo \"  [!!] rejected ''yes'', trying ''random''\"\n  nmcli con mod \"$u\" 802-11-wireless.mac-address-randomization random 2>&1 | sed ''s/^/  /''\n  echo \"  now reports: $(nmcli -g 802-11-wireless.mac-address-randomization con show \"$u\")\"\nfi"},"metadata":{"output":""},"time":{"start":1790454990002}}},"time":1790454990002}');
