INSERT INTO event VALUES('evt_0df6f0cf1001ugzXWC3sZTODii','ses_f211dfcd4ffevS1Yoddwab036g',9163,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df6f0a8d001ePHOcqKKNTNCRx","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df6f0522001TE00DA0WacMmzM","type":"reasoning","text":"NM 1.58.1 accepts only: `default`, `never`, `always`.\n\nSo the correct value is `always`. And `1` mapped to `never` (flag 1 = NO).\n\nLet me set `always` and verify, then reconnect to get a new MAC.","time":{"start":1790454991501,"end":1790454992113}},"time":1790454992113}');
