INSERT INTO event VALUES('evt_0df6f1a04001LsfztU0naQBGh5','ses_f211dfcd4ffevS1Yoddwab036g',9166,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df6f0f30001EARJ1pYUga9WtT","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df6f0522001TE00DA0WacMmzM","type":"tool","callID":"call_function_i932wg84m38z_1","tool":"edit","state":{"status":"running","input":{"filePath":"/home/livings/Projects/zen-hardening/set-anon-identity.sh","newString":"set_mac_prop=\"\"\nif nmcli -g 802-11-wireless.mac-address-randomization con show \"$(nmcli -t -f UUID con show | head -1)\" >/dev/null 2>&1; then\n  set_mac_prop=\"802-11-wireless.mac-address-randomization\"\n  # Values differ by NetworkManager version and getting this wrong is SILENT:\n  #   NM >= 1.42 uses a flags enum. nmcli accepts exactly:\n  #       default | never | always\n  #   and the numeric aliases are NOT boolean: 1 means NEVER, not yes.\n  #   Setting 1 therefore turns randomization OFF while looking like success.\n  # Verified on 1.58.1, which rejects \"yes\", \"random\" and \"1\" is \"never\".\n  case \"$(nmcli -f 802-11-wireless.mac-address-randomization con mod \"$(nmcli -t -f UUID con show | head -1)\" 2>&1)\" in\n    *always*) set_mac_val=\"always\" ;;\n    *)        set_mac_val=\"always\" ;;   # modern NM; modern NM is the only NM that has this property\n  esac\nelse\n  set_mac_prop=\"802-11-wireless.mac-address-mode\"\n  set_mac_val=\"random\"\nfi\necho \"  using property: ${set_mac_prop} = ${set_mac_val}\"","oldString":"set_mac_prop=\"\"\nif nmcli -g 802-11-wireless.mac-address-randomization con show \"$(nmcli -t -f UUID con show | head -1)\" >/dev/null 2>&1; then\n  set_mac_prop=\"802-11-wireless.mac-address-randomization\"\n  set_mac_val=\"1\"\nelse\n  set_mac_prop=\"802-11-wireless.mac-address-mode\"\n  set_mac_val=\"random\"\nfi\necho \"  using property: ${set_mac_prop} = ${set_mac_val}\""},"time":{"start":1790454995460}}},"time":1790454995460}');
INSERT INTO event VALUES('evt_0df6f1a07001MNRILnR1ZVb3zh','ses_f211dfcd4ffevS1Yoddwab036g',9167,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df6f0cf3001n4Wv0sj8npox66","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df6f0522001TE00DA0WacMmzM","type":"text","text":"There it is — NM 1.58 accepts exactly `default`, `never`, `always`. And `1` silently mapped to `never`, i.e. my script was *actively disabling* randomization. Fixing the script and applying:","time":{"start":1790454992115,"end":1790454995463}},"time":1790454995463}');
