INSERT INTO event VALUES('evt_0df6f2758001FUYtuaOadq6uyk','ses_f211dfcd4ffevS1Yoddwab036g',9181,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df6f228a001mqYx8iF0xbdweJ","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df6f1a300015Agfc2wdodk2qP","type":"tool","callID":"call_function_j9d83imbuwxs_1","tool":"edit","state":{"status":"running","input":{"filePath":"/home/livings/Projects/zen-hardening/set-anon-identity.sh","newString":"  # Values differ by NetworkManager version and getting this wrong is SILENT:\n  #   NM >= 1.42 uses a flags enum. nmcli accepts exactly:\n  #       default | never | always\n  #   and the numeric aliases are NOT boolean: 1 means NEVER, not yes.\n  #   Setting 1 therefore turns randomization OFF while looking like success.\n  # Verified on 1.58.1, which rejects both \"yes\" and \"random\".\n  set_mac_val=\"always\"","oldString":"  # Values differ by NetworkManager version and getting this wrong is SILENT:\n  #   NM >= 1.42 uses a flags enum. nmcli accepts exactly:\n  #       default | never | always\n  #   and the numeric aliases are NOT boolean: 1 means NEVER, not yes.\n  #   Setting 1 therefore turns randomization OFF while looking like success.\n  # Verified on 1.58.1, which rejects \"yes\", \"random\" and \"1\" is \"never\".\n  case \"$(nmcli -f 802-11-wireless.mac-address-randomization con mod \"$(nmcli -t -f UUID con show | head -1)\" 2>&1)\" in\n    *always*) set_mac_val=\"always\" ;;\n    *)        set_mac_val=\"always\" ;;   # modern NM; modern NM is the only NM that has this property\n  esac"},"time":{"start":1790454998872}}},"time":1790454998872}');
