INSERT INTO event VALUES('evt_0df6f4d32001WBhw8ar3WBeY6B','ses_f211dfcd4ffevS1Yoddwab036g',9225,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df6f4289001aMMNnWa2mVQLmt","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df6f3ba5001RUhz1m8VJMDV19","type":"tool","callID":"call_function_5jj3kqna7t9l_1","tool":"bash","state":{"status":"running","input":{"command":"cd /tmp/opencode/hss\nrsync -a --exclude=''.git'' --exclude=''venv'' --exclude=''__pycache__'' --exclude=''*.bak'' --exclude=''*.pyc'' \\\n      ~/Projects/zen-hardening/ config/zen-hardening/\ngit add -A\ngit -c user.name=opencode -c user.email=opencode@localhost commit -q -m \"Fix MAC randomization: NM flags enum, 1 means never\n\nThe previous fix set 802-11-wireless.mac-address-randomization=1,\nassuming a boolean. It is a flags enum, and the numeric aliases are\nnot boolean: 1 is NEVER, not yes. The setting was therefore silently\nturning randomization OFF, and nmcli helpfully reported ''never''.\n\nNetworkManager 1.58.1 accepts exactly: default | never | always\n(''yes'' and ''random'' are both rejected). Switched to ''always''.\n\nWorth noting this class of failure is invisible by construction: the\nsetting is accepted, reports a plausible value, and does the opposite\nof what was asked. Confirmed on the live interface that randomization\nhad never taken effect -- wlo1 was still broadcasting the hardware MAC\nf4:a4:75:e8:00:b2.\n\nCo-Authored-By: Claude Opus 4.8 (1M context) <noreply@anthropic.com>\" 2>&1 | sed ''s/^/  /''\ngit push -q origin HEAD 2>&1 | sed ''s/^/  /'' && echo \"  [✓] pushed\" || echo \"  [✗] failed\"\ngit log --oneline -1 | sed ''s/^/  /''"},"time":{"start":1790455008562}}},"time":1790455008562}');
