INSERT INTO event VALUES('evt_0df70a8ea001DwBL6DV4u7PJjZ','ses_f20e5cfc2ffeSFa4odnoYLiUOk',2298,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df709fc100177c9L9nHG2ME6n","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df704a52001FgFqmDiAIoeRAU","type":"text","text":"Continuing. The critical ordering constraint I need to verify first: `unlock_time = 0` (permanent lock) is only safe if the admin exemption actually works — and right now it doesn''t, because the group doesn''t exist.","time":{"start":1790455095234,"end":1790455097577}},"time":1790455097577}');
