INSERT INTO event VALUES('evt_0df70c96f001kW0SMMcA9gsK8R','ses_f20e5cfc2ffeSFa4odnoYLiUOk',2356,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df70c9590012EXMNvNZDzK32w","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df70c4dd001kA9u8jNpO9l0fs","type":"tool","callID":"call_function_4hfw4wr09dwt_1","tool":"bash","state":{"status":"running","input":{"command":"sed -n ''95,191p'' /tmp/pf.txt"},"metadata":{"output":""},"time":{"start":1790455105903}}},"time":1790455105903}');
INSERT INTO event VALUES('evt_0df70c971001gD3KQBaG5gBzat','ses_f20e5cfc2ffeSFa4odnoYLiUOk',2357,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df70c9590012EXMNvNZDzK32w","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df70c4dd001kA9u8jNpO9l0fs","type":"tool","callID":"call_function_4hfw4wr09dwt_1","tool":"bash","state":{"status":"running","input":{"command":"sed -n ''95,191p'' /tmp/pf.txt"},"metadata":{"output":""},"time":{"start":1790455105903}}},"time":1790455105905}');
INSERT INTO event VALUES('evt_0df70c97a0011mLB2ivVfip7on','ses_f20e5cfc2ffeSFa4odnoYLiUOk',2358,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df70c9590012EXMNvNZDzK32w","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df70c4dd001kA9u8jNpO9l0fs","type":"tool","callID":"call_function_4hfw4wr09dwt_1","tool":"bash","state":{"status":"running","input":{"command":"sed -n ''95,191p'' /tmp/pf.txt"},"metadata":{"output":"     Individual\t files\twith  the  failure  records are created as owned by the\n     user. This allows pam_faillock.so module to  work\tcorrectly  when\t it  is\n     called from a screensaver.\n\n     Note  that using the module in preauth without the silent option specified\n     in /etc/security/faillock.conf or with requisite control  field  leaks  an\n     information about existence or non-existence of a user account in the sys‐\n     tem  because the failures are not recorded for the unknown users. The mes‐\n     sage about the user account being locked is never displayed for non-exist‐\n     ing user accounts allowing the adversary to infer that  a\tparticular  ac‐\n     count is not existing on a system.\n\n     If\t the  auth stack has not been run prior to the account stack, the logic\n     to reset the failed login counter is intentionally skipped. This  prevents\n     automated\tservices,  such as crond or systemd-user, which might only per‐\n     form account management tasks, from inadvertently clearing a user''s failed\n     attempt records. This ensures the faillock counter is only reset by a ser‐\n     vice that performs a full, successful authentication.\n\nEXAMPLES\n     Here are two possible configuration examples  for\t/etc/pam.d/login.  They\n     make  pam_faillock\t to  lock the account after 4 consecutive failed logins\n     during the default interval of 15 minutes. Root account will be locked  as\n     well. The accounts will be automatically unlocked after 20 minutes.\n\n     In\t the  first example the module is called only in the auth phase and the\n     module does not print any information about the account being  blocked  by\n     pam_faillock.  The\t preauth call can be added to tell users that their lo‐\n     gins are blocked by the module and also to abort the authentication  with‐\n     out even asking for password in such case.\n\n     /etc/security/faillock.conf file example:\n\n\t deny=4\n\t unlock_time=1200\n\t silent\n\n     /etc/pam.d/config file example:\n\n\t auth\t  required\t pam_securetty.so\n\t auth\t  required\t pam_env.so\n\t auth\t  required\t pam_nologin.so\n\t # optionally call: auth requisite pam_faillock.so preauth\n\t # to display the message about account being locked\n\t auth\t  [success=1 default=bad] pam_unix.so\n\t auth\t  [default=die]\t pam_faillock.so authfail\n\t auth\t  sufficient\t pam_faillock.so authsucc\n\t auth\t  required\t pam_deny.so\n\t account  required\t pam_unix.so\n\t password required\t pam_unix.so shadow\n\t session  required\t pam_selinux.so close\n\t session  required\t pam_loginuid.so\n\t session  required\t pam_unix.so\n\t session  required\t pam_selinux.so open\n\n     In\t the  second  example the module is called both in the auth and account\n     phases and the module informs the authenticating user when the account  is\n     locked if silent option is not specified in the faillock.conf.\n\n\t auth\t  required\t pam_securetty.so\n\t auth\t  required\t pam_env.so\n\t auth\t  required\t pam_nologin.so\n\t auth\t  required\t pam_faillock.so preauth\n\t # optionally use requisite above if you do not want to prompt for the password\n\t # on locked accounts\n\t auth\t  sufficient\t pam_unix.so\n\t auth\t  [default=die]\t pam_faillock.so authfail\n\t auth\t  required\t pam_deny.so\n\t account  required\t pam_faillock.so\n\t # if you drop the above call to pam_faillock.so the lock will be done also\n\t # on non-consecutive authentication failures\n\t account  required\t pam_unix.so\n\t password required\t pam_unix.so shadow\n\t session  required\t pam_selinux.so close\n\t session  required\t pam_loginuid.so\n\t session  required\t pam_unix.so\n\t session  required\t pam_selinux.so open\n\nFILES\n     /var/run/faillock/*\n\t the files logging the authentication failures for users\n\n\t Note:\tThese  files  will disappear after reboot on systems configured\n\t with directory /var/run/faillock mounted on virtual memory.  For  per‐\n\t sistent  storage  use\tthe  option  dir=  in  file /etc/security/fail‐\n\t lock.conf.\n\n     /etc/security/faillock.conf\n\t the config file for pam_faillock options\n\nSEE ALSO\n     faillock(8), faillock.conf(5), pam.conf(5), pam.d(5), pam(8)\n\nAUTHOR\n     pam_faillock was written by Tomas Mraz.\n\n[FIXME: source]\t\t\t   01/26/2026\t\t\tPAM_FAILLOCK(8)\n"},"time":{"start":1790455105903}}},"time":1790455105914}');
INSERT INTO event VALUES('evt_0df70c97f001pyIYvkLP83gEn8','ses_f20e5cfc2ffeSFa4odnoYLiUOk',2359,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df70c9590012EXMNvNZDzK32w","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df70c4dd001kA9u8jNpO9l0fs","type":"tool","callID":"call_function_4hfw4wr09dwt_1","tool":"bash","state":{"status":"completed","input":{"command":"sed -n ''95,191p'' /tmp/pf.txt"},"output":"     Individual\t files\twith  the  failure  records are created as owned by the\n     user. This allows pam_faillock.so module to  work\tcorrectly  when\t it  is\n     called from a screensaver.\n\n     Note  that using the module in preauth without the silent option specified\n     in /etc/security/faillock.conf or with requisite control  field  leaks  an\n     information about existence or non-existence of a user account in the sys‐\n     tem  because the failures are not recorded for the unknown users. The mes‐\n     sage about the user account being locked is never displayed for non-exist‐\n     ing user accounts allowing the adversary to infer that  a\tparticular  ac‐\n     count is not existing on a system.\n\n     If\t the  auth stack has not been run prior to the account stack, the logic\n     to reset the failed login counter is intentionally skipped. This  prevents\n     automated\tservices,  such as crond or systemd-user, which might only per‐\n     form account management tasks, from inadvertently clearing a user''s failed\n     attempt records. This ensures the faillock counter is only reset by a ser‐\n     vice that performs a full, successful authentication.\n\nEXAMPLES\n     Here are two possible configuration examples  for\t/etc/pam.d/login.  They\n     make  pam_faillock\t to  lock the account after 4 consecutive failed logins\n     during the default interval of 15 minutes. Root account will be locked  as\n     well. The accounts will be automatically unlocked after 20 minutes.\n\n     In\t the  first example the module is called only in the auth phase and the\n     module does not print any information about the account being  blocked  by\n     pam_faillock.  The\t preauth call can be added to tell users that their lo‐\n     gins are blocked by the module and also to abort the authentication  with‐\n     out even asking for password in such case.\n\n     /etc/security/faillock.conf file example:\n\n\t deny=4\n\t unlock_time=1200\n\t silent\n\n     /etc/pam.d/config file example:\n\n\t auth\t  required\t pam_securetty.so\n\t auth\t  required\t pam_env.so\n\t auth\t  required\t pam_nologin.so\n\t # optionally call: auth requisite pam_faillock.so preauth\n\t # to display the message about account being locked\n\t auth\t  [success=1 default=bad] pam_unix.so\n\t auth\t  [default=die]\t pam_faillock.so authfail\n\t auth\t  sufficient\t pam_faillock.so authsucc\n\t auth\t  required\t pam_deny.so\n\t account  required\t pam_unix.so\n\t password required\t pam_unix.so shadow\n\t session  required\t pam_selinux.so close\n\t session  required\t pam_loginuid.so\n\t session  required\t pam_unix.so\n\t session  required\t pam_selinux.so open\n\n     In\t the  second  example the module is called both in the auth and account\n     phases and the module informs the authenticating user when the account  is\n     locked if silent option is not specified in the faillock.conf.\n\n\t auth\t  required\t pam_securetty.so\n\t auth\t  required\t pam_env.so\n\t auth\t  required\t pam_nologin.so\n\t auth\t  required\t pam_faillock.so preauth\n\t # optionally use requisite above if you do not want to prompt for the password\n\t # on locked accounts\n\t auth\t  sufficient\t pam_unix.so\n\t auth\t  [default=die]\t pam_faillock.so authfail\n\t auth\t  required\t pam_deny.so\n\t account  required\t pam_faillock.so\n\t # if you drop the above call to pam_faillock.so the lock will be done also\n\t # on non-consecutive authentication failures\n\t account  required\t pam_unix.so\n\t password required\t pam_unix.so shadow\n\t session  required\t pam_selinux.so close\n\t session  required\t pam_loginuid.so\n\t session  required\t pam_unix.so\n\t session  required\t pam_selinux.so open\n\nFILES\n     /var/run/faillock/*\n\t the files logging the authentication failures for users\n\n\t Note:\tThese  files  will disappear after reboot on systems configured\n\t with directory /var/run/faillock mounted on virtual memory.  For  per‐\n\t sistent  storage  use\tthe  option  dir=  in  file /etc/security/fail‐\n\t lock.conf.\n\n     /etc/security/faillock.conf\n\t the config file for pam_faillock options\n\nSEE ALSO\n     faillock(8), faillock.conf(5), pam.conf(5), pam.d(5), pam(8)\n\nAUTHOR\n     pam_faillock was written by Tomas Mraz.\n\n[FIXME: source]\t\t\t   01/26/2026\t\t\tPAM_FAILLOCK(8)\n","title":"sed -n ''95,191p'' /tmp/pf.txt","metadata":{"output":"     Individual\t files\twith  the  failure  records are created as owned by the\n     user. This allows pam_faillock.so module to  work\tcorrectly  when\t it  is\n     called from a screensaver.\n\n     Note  that using the module in preauth without the silent option specified\n     in /etc/security/faillock.conf or with requisite control  field  leaks  an\n     information about existence or non-existence of a user account in the sys‐\n     tem  because the failures are not recorded for the unknown users. The mes‐\n     sage about the user account being locked is never displayed for non-exist‐\n     ing user accounts allowing the adversary to infer that  a\tparticular  ac‐\n     count is not existing on a system.\n\n     If\t the  auth stack has not been run prior to the account stack, the logic\n     to reset the failed login counter is intentionally skipped. This  prevents\n     automated\tservices,  such as crond or systemd-user, which might only per‐\n     form account management tasks, from inadvertently clearing a user''s failed\n     attempt records. This ensures the faillock counter is only reset by a ser‐\n     vice that performs a full, successful authentication.\n\nEXAMPLES\n     Here are two possible configuration examples  for\t/etc/pam.d/login.  They\n     make  pam_faillock\t to  lock the account after 4 consecutive failed logins\n     during the default interval of 15 minutes. Root account will be locked  as\n     well. The accounts will be automatically unlocked after 20 minutes.\n\n     In\t the  first example the module is called only in the auth phase and the\n     module does not print any information about the account being  blocked  by\n     pam_faillock.  The\t preauth call can be added to tell users that their lo‐\n     gins are blocked by the module and also to abort the authentication  with‐\n     out even asking for password in such case.\n\n     /etc/security/faillock.conf file example:\n\n\t deny=4\n\t unlock_time=1200\n\t silent\n\n     /etc/pam.d/config file example:\n\n\t auth\t  required\t pam_securetty.so\n\t auth\t  required\t pam_env.so\n\t auth\t  required\t pam_nologin.so\n\t # optionally call: auth requisite pam_faillock.so preauth\n\t # to display the message about account being locked\n\t auth\t  [success=1 default=bad] pam_unix.so\n\t auth\t  [default=die]\t pam_faillock.so authfail\n\t auth\t  sufficient\t pam_faillock.so authsucc\n\t auth\t  required\t pam_deny.so\n\t account  required\t pam_unix.so\n\t password required\t pam_unix.so shadow\n\t session  required\t pam_selinux.so close\n\t session  required\t pam_loginuid.so\n\t session  required\t pam_unix.so\n\t session  required\t pam_selinux.so open\n\n     In\t the  second  example the module is called both in the auth and account\n     phases and the module informs the authenticating user when the account  is\n     locked if silent option is not specified in the faillock.conf.\n\n\t auth\t  required\t pam_securetty.so\n\t auth\t  required\t pam_env.so\n\t auth\t  required\t pam_nologin.so\n\t auth\t  required\t pam_faillock.so preauth\n\t # optionally use requisite above if you do not want to prompt for the password\n\t # on locked accounts\n\t auth\t  sufficient\t pam_unix.so\n\t auth\t  [default=die]\t pam_faillock.so authfail\n\t auth\t  required\t pam_deny.so\n\t account  required\t pam_faillock.so\n\t # if you drop the above call to pam_faillock.so the lock will be done also\n\t # on non-consecutive authentication failures\n\t account  required\t pam_unix.so\n\t password required\t pam_unix.so shadow\n\t session  required\t pam_selinux.so close\n\t session  required\t pam_loginuid.so\n\t session  required\t pam_unix.so\n\t session  required\t pam_selinux.so open\n\nFILES\n     /var/run/faillock/*\n\t the files logging the authentication failures for users\n\n\t Note:\tThese  files  will disappear after reboot on systems configured\n\t with directory /var/run/faillock mounted on virtual memory.  For  per‐\n\t sistent  storage  use\tthe  option  dir=  in  file /etc/security/fail‐\n\t lock.conf.\n\n     /etc/security/faillock.conf\n\t the config file for pam_faillock options\n\nSEE ALSO\n     faillock(8), faillock.conf(5), pam.conf(5), pam.d(5), pam(8)\n\nAUTHOR\n     pam_faillock was written by Tomas Mraz.\n\n[FIXME: source]\t\t\t   01/26/2026\t\t\tPAM_FAILLOCK(8)\n","exit":0,"truncated":false},"time":{"start":1790455105903,"end":1790455105919}}},"time":1790455105919}');
