INSERT INTO event VALUES('evt_0df712cfe001QgWuKBY5LNRTy2','ses_f20e5cfc2ffeSFa4odnoYLiUOk',2409,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df712960001AuqRhqB36neQrk","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df70d947001nrw9CfzCnRBvQi","type":"tool","callID":"call_function_ryf36uiasv50_2","tool":"bash","state":{"status":"running","input":{"command":"echo \"=== pamtester available to empirically test config parsing? ===\"\ncommand -v pamtester >/dev/null && echo \"  yes\" || echo \"  no\"\necho; echo \"=== faillock(8) present? ===\"\ncommand -v faillock >/dev/null && echo \"  yes\" || echo \"  no\"\necho; echo \"=== groupadd available for the shield-admin fix ===\"\ncommand -v groupadd >/dev/null && echo \"  yes\" || echo \"  no\"\necho; echo \"=== repo faillock.conf raw ===\"\ncat ~/Projects/zen-hardening/faillock.conf 2>/dev/null"},"metadata":{"output":"=== pamtester available to empirically test config parsing? ===\n  no\n\n=== faillock(8) present? ===\n  yes\n\n=== groupadd available for the shield-admin fix ===\n  yes\n\n=== repo faillock.conf raw ===\n# /etc/security/faillock.conf — Shield Kitty hardened profile\n#\n# Install:  sudo cp faillock.conf /etc/security/faillock.conf\n#           sudo systemctl restart sddm.service\n# Revert:   sudo cp faillock.conf.orig /etc/security/faillock.conf\n#           sudo systemctl restart sddm.service\n#\n# Two separate controls, and they are not the same thing:\n#\n#   admin_group   members are handled like root. Because even_deny_root is\n#                 NOT set, admin_group members are NEVER locked out. This is\n#                 the \"I cannot be locked out of my own machine\" guarantee.\n#\n#   unlock_time   how long a NORMAL account stays locked. It does not apply to\n#                 admin_group members at all.\n#\n# ---------------------------------------------------------------------------\n# ADMIN GROUP — one member, by design\n# ---------------------------------------------------------------------------\n# The group is `shield-admin`, NOT `wheel`.\n#\n# This matters. pam_faillock''s admin_group takes a GROUP. If it were `wheel`,\n# then every account ever granted sudo would silently inherit the lockout\n# exemption — including any account an attacker talked you into sudo-ing, or\n# any service account added for convenience. The exemption would quietly\n# become \"anyone with sudo\", which is not the same as \"just me\".\n#\n# `shield-admin` contains exactly one member: livings. Adding anyone else is a\n# deliberate, visible action (enroll-admin.sh), not a side effect of ordinary\n# admin work.\n#\n# Verify the membership is still just you:\n#   getent group shield-admin\n# Expected: shield-admin:x:<gid>:livings\n#   getent group shield-admin | tr '','' ''\\n'' | grep -v ''^shield-admin'' | grep -v livings\n# Expected: no output.\n\n# --- Even counts (root) ---\n# NOT enabled. This is what makes the admin exemption possible: without\n# even_deny_root, root is not locked out, and admin_group members are treated\n# the same way. Turning it on would apply lockout to the admin account, which\n# is the exact thing being avoided.\n#\n# The tradeoff, stated once and not repeated: an account in shield-admin is\n# never locked out, so an online password-guessing attack against that one\n# account is not stopped by faillock. The remaining controls for it are\n# password strength and fail2ban, which keys on source IP rather than\n# username. Requested behaviour, not an oversight.\nadmin_group = shield-admin\n\n# --- Tallying (non-admin accounts only) ---\ndeny = 10\n\n# --- Unlock timing (non-admin accounts only) ---\n# 30 seconds, set at user request, down from 1800s. Short unlock means you get\n# locked out LESS, not more; it has no effect on the admin account, which is\n# exempt outright.\nunlock_time = 30\n\n# --- Logging ---\naudit = silent\n"},"time":{"start":1790455131381}}},"time":1790455131390}');
