INSERT INTO event VALUES('evt_0df71a60a001rMSRMwxotnD8MM','ses_f20e5cfc2ffeSFa4odnoYLiUOk',2437,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df71a5c5001T7oypL49htYWjS","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df71a190001lW1iL3rj15W040","type":"tool","callID":"call_function_6ap5eyeoh5vp_1","tool":"read","state":{"status":"completed","input":{"filePath":"/home/livings/Projects/zen-hardening/enroll-admin.sh"},"output":"<path>/home/livings/Projects/zen-hardening/enroll-admin.sh</path>\n<type>file</type>\n<content>\n1: #!/bin/bash\n2: # enroll-admin.sh — manage membership of the shield-admin group.\n3: #\n4: # shield-admin is the pam_faillock admin_group. Members of it are NEVER locked\n5: # out of this machine. That makes membership a security control, not a\n6: # convenience, so adding someone is gated here rather than done with a bare\n7: # `usermod -aG`.\n8: #\n9: #   ./enroll-admin.sh status          show who is exempt, and who is not\n10: #   ./enroll-admin.sh add <user>      add a member (asks why; refuses by default)\n11: #   ./enroll-admin.sh remove <user>   remove a member\n12: #\n13: # Refusal policy: `add` REFUSES to enrol anyone other than the primary admin\n14: # while /etc/shield-kitty/enroll.lock exists. To allow another account you must\n15: # deliberately delete that lock file. Nothing enrols anybody by accident.\n16: \n17: set -uo pipefail\n18: \n19: GROUP=\"shield-admin\"\n20: PRIMARY_ADMIN=\"livings\"\n21: LOCKFILE=\"/etc/shield-kitty/enroll.lock\"\n22: SUDOERS_D=\"/etc/sudoers.d\"\n23: \n24: die() { echo \"ERROR: $*\" >&2; exit 1; }\n25: \n26: require_root() {\n27:     [ \"$(id -u)\" -eq 0 ] || die \"needs root: sudo $0 $*\"\n28: }\n29: \n30: group_exists() { getent group \"$GROUP\" >/dev/null 2>&1; }\n31: \n32: ensure_group() {\n33:     group_exists && return 0\n34:     groupadd --system \"$GROUP\" || die \"could not create group $GROUP\"\n35:     echo \"created system group $GROUP\"\n36: }\n37: \n38: cmd_status() {\n39:     echo \"=== faillock admin_group ===\"\n40:     if grep -qE ''^[[:space:]]*admin_group'' /etc/security/faillock.conf 2>/dev/null; then\n41:         grep -E ''^[[:space:]]*admin_group'' /etc/security/faillock.conf\n42:     else\n43:         echo \"  (admin_group NOT set in /etc/security/faillock.conf — nobody is exempt)\"\n44:     fi\n45: \n46:     echo\n47:     echo \"=== members of $GROUP (these are NEVER locked out) ===\"\n48:     if group_exists; then\n49:         getent group \"$GROUP\"\n50:     else\n51:         echo \"  (group does not exist)\"\n52:     fi\n53: \n54:     echo\n55:     if [ -e \"$LOCKFILE\" ]; then\n56:         echo \"ENROLLMENT: LOCKED — only $PRIMARY_ADMIN may be a member.\"\n57:         echo \"  (lock file: $LOCKFILE)\"\n58:     else\n59:         echo \"ENROLLMENT: OPEN — any account may be added.\"\n60:     fi\n61: \n62:     echo\n63:     echo \"=== accounts that can become members without this script ===\"\n64:     echo \"  anyone who can write to $GROUP via:\"\n65:     echo \"    - root, obviously\"\n66:     echo \"    - $SUDOERS_D/* granting gpasswd/usermod/groupadd\"\n67:     echo \"    - any NSS-backed directory service (LDAP/AD) that manages groups\"\n68:     ls -l \"$SUDOERS_D\" 2>/dev/null | tail -n +2 || echo \"    (cannot list $SUDOERS_D without root)\"\n69: }\n70: \n71: cmd_add() {\n72:     local user=\"${1:-}\"\n73:     [ -n \"$user\" ] || die \"usage: $0 add <user>\"\n74: \n75:     # Policy is checked FIRST, before any other validation. Otherwise an\n76:     # unprivileged run against a nonexistent user reports \"no such user\"\n77:     # instead of the refusal, and — worse — a real user would reach the\n78:     # usermod call before anyone decided whether they should be allowed.\n79:     if [ \"$user\" != \"$PRIMARY_ADMIN\" ] && [ -e \"$LOCKFILE\" ]; then\n80:         echo \"REFUSED: enrolling $user would grant a permanent lockout exemption.\" >&2\n81:         echo >&2\n82:         echo \"  Only $PRIMARY_ADMIN may be in $GROUP while the lock is in place.\" >&2\n83:         echo \"  $user would never be locked out of this machine, and neither\" >&2\n84:         echo \"  would an attacker who guesses $user''s password.\" >&2\n85:         echo >&2\n86:         echo \"  If you genuinely want this, remove the lock and re-run:\" >&2\n87:         echo \"    sudo rm $LOCKFILE && sudo $0 add $user\" >&2\n88:         echo >&2\n89:         echo \"  Re-lock afterwards:\" >&2\n90:         echo \"    sudo $0 lock\" >&2\n91:         exit 2\n92:     fi\n93: \n94:     id \"$user\" >/dev/null 2>&1 || die \"no such user: $user\"\n95:     require_root add \"$user\"\n96:     ensure_group\n97:     usermod -aG \"$GROUP\" \"$user\" || die \"usermod failed\"\n98:     echo \"added $user to $GROUP — this account can no longer be locked out\"\n99:     echo \"reboot or start a new session for group membership to take effect\"\n100:     cmd_status\n101: }\n102: \n103: cmd_remove() {\n104:     local user=\"${1:-}\"\n105:     [ -n \"$user\" ] || die \"usage: $0 remove <user>\"\n106:     [ \"$user\" != \"$PRIMARY_ADMIN\" ] || die \"refusing to remove the primary admin ($user) from $GROUP; that is the account this whole control exists for\"\n107:     require_root remove \"$user\"\n108:     group_exists || die \"group $GROUP does not exist\"\n109:     gpasswd -d \"$user\" \"$GROUP\" >/dev/null || die \"gpasswd failed\"\n110:     echo \"removed $user from $GROUP — faillock now applies to this account\"\n111: }\n112: \n113: cmd_lock() {\n114:     require_root lock\n115:     mkdir -p \"$(dirname \"$LOCKFILE\")\"\n116:     printf ''locked %s by %s\\n'' \"$(date -Is)\" \"$(logname 2>/dev/null || echo root)\" > \"$LOCKFILE\"\n117:     chmod 0644 \"$LOCKFILE\"\n118:     echo \"enrollment locked: only $PRIMARY_ADMIN may be a member of $GROUP\"\n119: }\n120: \n121: cmd_unlock() {\n122:     require_root unlock\n123:     rm -f \"$LOCKFILE\"\n124:     echo \"enrollment OPEN — any account can be added to $GROUP from now on\"\n125:     echo \"re-lock with: sudo $0 lock\"\n126: }\n127: \n128: case \"${1:-status}\" in\n129:     status)  cmd_status ;;\n130:     add)     shift; cmd_add \"$@\" ;;\n131:     remove)  shift; cmd_remove \"$@\" ;;\n132:     lock)    cmd_lock ;;\n133:     unlock)  cmd_unlock ;;\n134:     *)       sed -n ''2,20p'' \"$0\"; exit 1 ;;\n135: esac\n\n(End of file - total 135 lines)\n</content>","title":"home/livings/Projects/zen-hardening/enroll-admin.sh","metadata":{"preview":"#!/bin/bash\n# enroll-admin.sh — manage membership of the shield-admin group.\n#\n# shield-admin is the pam_faillock admin_group. Members of it are NEVER locked\n# out of this machine. That makes membership a security control, not a\n# convenience, so adding someone is gated here rather than done with a bare\n# `usermod -aG`.\n#\n#   ./enroll-admin.sh status          show who is exempt, and who is not\n#   ./enroll-admin.sh add <user>      add a member (asks why; refuses by default)\n#   ./enroll-admin.sh remove <user>   remove a member\n#\n# Refusal policy: `add` REFUSES to enrol anyone other than the primary admin\n# while /etc/shield-kitty/enroll.lock exists. To allow another account you must\n# deliberately delete that lock file. Nothing enrols anybody by accident.\n\nset -uo pipefail\n\nGROUP=\"shield-admin\"\nPRIMARY_ADMIN=\"livings\"","truncated":false,"loaded":[],"display":{"type":"file","path":"/home/livings/Projects/zen-hardening/enroll-admin.sh","text":"#!/bin/bash\n# enroll-admin.sh — manage membership of the shield-admin group.\n#\n# shield-admin is the pam_faillock admin_group. Members of it are NEVER locked\n# out of this machine. That makes membership a security control, not a\n# convenience, so adding someone is gated here rather than done with a bare\n# `usermod -aG`.\n#\n#   ./enroll-admin.sh status          show who is exempt, and who is not\n#   ./enroll-admin.sh add <user>      add a member (asks why; refuses by default)\n#   ./enroll-admin.sh remove <user>   remove a member\n#\n# Refusal policy: `add` REFUSES to enrol anyone other than the primary admin\n# while /etc/shield-kitty/enroll.lock exists. To allow another account you must\n# deliberately delete that lock file. Nothing enrols anybody by accident.\n\nset -uo pipefail\n\nGROUP=\"shield-admin\"\nPRIMARY_ADMIN=\"livings\"\nLOCKFILE=\"/etc/shield-kitty/enroll.lock\"\nSUDOERS_D=\"/etc/sudoers.d\"\n\ndie() { echo \"ERROR: $*\" >&2; exit 1; }\n\nrequire_root() {\n    [ \"$(id -u)\" -eq 0 ] || die \"needs root: sudo $0 $*\"\n}\n\ngroup_exists() { getent group \"$GROUP\" >/dev/null 2>&1; }\n\nensure_group() {\n    group_exists && return 0\n    groupadd --system \"$GROUP\" || die \"could not create group $GROUP\"\n    echo \"created system group $GROUP\"\n}\n\ncmd_status() {\n    echo \"=== faillock admin_group ===\"\n    if grep -qE ''^[[:space:]]*admin_group'' /etc/security/faillock.conf 2>/dev/null; then\n        grep -E ''^[[:space:]]*admin_group'' /etc/security/faillock.conf\n    else\n        echo \"  (admin_group NOT set in /etc/security/faillock.conf — nobody is exempt)\"\n    fi\n\n    echo\n    echo \"=== members of $GROUP (these are NEVER locked out) ===\"\n    if group_exists; then\n        getent group \"$GROUP\"\n    else\n        echo \"  (group does not exist)\"\n    fi\n\n    echo\n    if [ -e \"$LOCKFILE\" ]; then\n        echo \"ENROLLMENT: LOCKED — only $PRIMARY_ADMIN may be a member.\"\n        echo \"  (lock file: $LOCKFILE)\"\n    else\n        echo \"ENROLLMENT: OPEN — any account may be added.\"\n    fi\n\n    echo\n    echo \"=== accounts that can become members without this script ===\"\n    echo \"  anyone who can write to $GROUP via:\"\n    echo \"    - root, obviously\"\n    echo \"    - $SUDOERS_D/* granting gpasswd/usermod/groupadd\"\n    echo \"    - any NSS-backed directory service (LDAP/AD) that manages groups\"\n    ls -l \"$SUDOERS_D\" 2>/dev/null | tail -n +2 || echo \"    (cannot list $SUDOERS_D without root)\"\n}\n\ncmd_add() {\n    local user=\"${1:-}\"\n    [ -n \"$user\" ] || die \"usage: $0 add <user>\"\n\n    # Policy is checked FIRST, before any other validation. Otherwise an\n    # unprivileged run against a nonexistent user reports \"no such user\"\n    # instead of the refusal, and — worse — a real user would reach the\n    # usermod call before anyone decided whether they should be allowed.\n    if [ \"$user\" != \"$PRIMARY_ADMIN\" ] && [ -e \"$LOCKFILE\" ]; then\n        echo \"REFUSED: enrolling $user would grant a permanent lockout exemption.\" >&2\n        echo >&2\n        echo \"  Only $PRIMARY_ADMIN may be in $GROUP while the lock is in place.\" >&2\n        echo \"  $user would never be locked out of this machine, and neither\" >&2\n        echo \"  would an attacker who guesses $user''s password.\" >&2\n        echo >&2\n        echo \"  If you genuinely want this, remove the lock and re-run:\" >&2\n        echo \"    sudo rm $LOCKFILE && sudo $0 add $user\" >&2\n        echo >&2\n        echo \"  Re-lock afterwards:\" >&2\n        echo \"    sudo $0 lock\" >&2\n        exit 2\n    fi\n\n    id \"$user\" >/dev/null 2>&1 || die \"no such user: $user\"\n    require_root add \"$user\"\n    ensure_group\n    usermod -aG \"$GROUP\" \"$user\" || die \"usermod failed\"\n    echo \"added $user to $GROUP — this account can no longer be locked out\"\n    echo \"reboot or start a new session for group membership to take effect\"\n    cmd_status\n}\n\ncmd_remove() {\n    local user=\"${1:-}\"\n    [ -n \"$user\" ] || die \"usage: $0 remove <user>\"\n    [ \"$user\" != \"$PRIMARY_ADMIN\" ] || die \"refusing to remove the primary admin ($user) from $GROUP; that is the account this whole control exists for\"\n    require_root remove \"$user\"\n    group_exists || die \"group $GROUP does not exist\"\n    gpasswd -d \"$user\" \"$GROUP\" >/dev/null || die \"gpasswd failed\"\n    echo \"removed $user from $GROUP — faillock now applies to this account\"\n}\n\ncmd_lock() {\n    require_root lock\n    mkdir -p \"$(dirname \"$LOCKFILE\")\"\n    printf ''locked %s by %s\\n'' \"$(date -Is)\" \"$(logname 2>/dev/null || echo root)\" > \"$LOCKFILE\"\n    chmod 0644 \"$LOCKFILE\"\n    echo \"enrollment locked: only $PRIMARY_ADMIN may be a member of $GROUP\"\n}\n\ncmd_unlock() {\n    require_root unlock\n    rm -f \"$LOCKFILE\"\n    echo \"enrollment OPEN — any account can be added to $GROUP from now on\"\n    echo \"re-lock with: sudo $0 lock\"\n}\n\ncase \"${1:-status}\" in\n    status)  cmd_status ;;\n    add)     shift; cmd_add \"$@\" ;;\n    remove)  shift; cmd_remove \"$@\" ;;\n    lock)    cmd_lock ;;\n    unlock)  cmd_unlock ;;\n    *)       sed -n ''2,20p'' \"$0\"; exit 1 ;;\nesac","lineStart":1,"lineEnd":135,"totalLines":135,"truncated":false}},"time":{"start":1790455162371,"end":1790455162377}}},"time":1790455162378}');
