INSERT INTO event VALUES('evt_0df75355d001rEIBoFAvX5zVUw','ses_f211dfcd4ffevS1Yoddwab036g',9329,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df75315b0013rewGANMlMGK30","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df751a7b001RYlhorcBR0vWBc","type":"tool","callID":"call_function_dy2qrl7rlyai_1","tool":"bash","state":{"status":"running","input":{"command":"u=$(nmcli -t -f UUID,NAME con show | awk -F: ''$2==\"USL - Public\"{print $1}'')\necho \"  randomization setting : $(nmcli -g 802-11-wireless.mac-address-randomization con show \"$u\" 2>&1)\"\necho \"  current kernel MAC    : $(cat /sys/class/net/wlo1/address)\"\necho \"  connection file mtime : $(stat -c%y /etc/NetworkManager/system-connections/\"USL - Public.nmconnection\" 2>/dev/null || echo ''n/a'')\"\necho\necho \"  -> ''never''  = script never ran (config not written)\"\necho \"  -> ''always'' = config written, new MAC pending next activation\""},"time":{"start":1790455395677}}},"time":1790455395677}');
