INSERT INTO event VALUES('evt_0df76c0e0001B01BFN8g7Fl6uq','ses_f20e5cfc2ffeSFa4odnoYLiUOk',2552,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df76ba36001xjrsOjcz2LnbxP","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df76a8dd001w4ySaZvACguRi0","type":"tool","callID":"call_function_6qoguyow0lv5_1","tool":"bash","state":{"status":"running","input":{"command":"cd /tmp\n# Test the exact predicate step 4 uses, against all four real-world states.\nGROUP=shield-admin; PRIMARY_ADMIN=livings\ntest_predicate() {\n  local desc=\"$1\" groupout=\"$2\" conf=\"$3\"\n  if printf ''%s'' \"$groupout\" | tr '','' ''\\n'' | grep -qx \"$PRIMARY_ADMIN\" \\\n     && printf ''%s'' \"$conf\" | grep -qE ''^[[:space:]]*admin_group[[:space:]]*=[[:space:]]*''\"$GROUP\"; then\n    echo \"  $desc -> EXEMPT (proceed)\"\n  else\n    echo \"  $desc -> NOT exempt (ABORT)\"\n  fi\n}\nC=\"admin_group = shield-admin\"\necho \"=== step-4 predicate, four states ===\"\ntest_predicate \"group has livings + config names it  \" \"shield-admin:x:991:livings\" \"$C\"\ntest_predicate \"group MISSING                  \" \"\" \"$C\"\ntest_predicate \"group exists, livings NOT in it \" \"shield-admin:x:991:\" \"$C\"\ntest_predicate \"livings in group, config absent  \" \"shield-admin:x:991:livings\" \"deny = 10\"\ntest_predicate \"group has a DIFFERENT member    \" \"shield-admin:x:991:someone\" \"$C\""},"time":{"start":1790455496928}}},"time":1790455496928}');
