INSERT INTO event VALUES('evt_0df775109001ukC7gokQbVaCHK','ses_f20e5cfc2ffeSFa4odnoYLiUOk',2684,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df77476b001qG828EE17QExo6","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df773b280013JlnW1GcRDU7TQ","type":"tool","callID":"call_function_1hfd5c2bh2jh_1","tool":"bash","state":{"status":"running","input":{"command":"cd ~/Projects/buildlog\nbuildlog fix \"faillock admin exemption PREPARED, NOT deployed (needs sudo). deploy-faillock-admin.sh orders it safely: backup -> create shield-admin -> enrol livings -> READ GROUP DB BACK -> only then install config naming admin_group, then write enroll.lock. Aborts if livings is not verifiably a member, because pam_faillock would otherwise lock the admin out like everyone else. Run: sudo ~/Projects/zen-hardening/deploy-faillock-admin.sh --check | deploy | --revert\" 2>&1 | tail -1\nbuildlog fix \"faillock: fixed ''audit = silent'' (audit/silent are BARE FLAGS not key=value) and fixed group parsing that split on '','' instead of cutting field 4 from ''name:x:gid:mem1,mem2'' -- old check passed unconditionally. unlock_time stays 30s, permanent lockout (0) NOT enabled: no other login users exist on this box anyway, and it is unrecoverable if the exemption breaks\" 2>&1 | tail -1\nbuildlog warn \"3 pam_faillock facts confirmed from man pages: (1) unlock_time=0 = never, needs faillock(8) --reset; (2) default dir /var/run/faillock is tmpfs so tallies+any permanent lock VANISH on reboot -- real permanence needs dir= off tmpfs; (3) admin_group members are treated like root, so even_deny_root would defeat the exemption. Live /etc/security/faillock.conf had no admin_group at all, so livings was lockable\" 2>&1 | tail -1"},"metadata":{"output":""},"time":{"start":1790455533832}}},"time":1790455533833}');
