INSERT INTO event VALUES('evt_0df77932c001YkJiIEU7Zp5NYG','ses_f20e5cfc2ffeSFa4odnoYLiUOk',2746,'message.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","info":{"id":"msg_0df704a48001hpZ7aI1WLbTRqR","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","role":"user","time":{"created":1790455073352},"summary":{"diffs":[]},"agent":"build","model":{"providerID":"opencode","modelID":"big-pickle"}}}');
INSERT INTO event VALUES('evt_0df7926d4003qSm0tez1hrFef2','ses_f211dfcd4ffevS1Yoddwab036g',9349,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df7557c3001bvThn4pgYJjYAU","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df75359c001b3yw68WgAJtF1d","type":"text","text":"Setting is `always` — the script ran. You''re right that activation is needed, but a full reboot is overkill: NetworkManager assigns the randomized MAC at *connection activation*, so a WiFi reconnect does it.\n\n```bash\nnmcli con down \"USL - Public\" && nmcli con up \"USL - Public\" && sleep 5 && cat /sys/class/net/wlo1/address\n```\n\nExpect an address starting `2x`, `6x`, `ax` or `ex` — not `f4:`. Rebooting would also work, but costs a minute and any unsaved work.\n\nNote this is *per-network stable*: NM remembers the random MAC for each SSID, so you get the same fake MAC on `USL - Public` every time. That''s correct — a MAC that changed on every join would break captive portals and look more suspicious, not less.\n\nWhile you do that, fixing the real defect behind your \"all green\": `bootstrap.sh` verified hostname but never MAC, so it reported success on an incomplete identity.","time":{"start":1790455404484,"end":1790455654100}},"time":1790455654100}');
