INSERT INTO event VALUES('evt_0df7952fe001KfHG0pVcAfPSTo','ses_f211dfcd4ffevS1Yoddwab036g',9376,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df7952fe0016msuyJejx7dY1o","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df794a15001bCtzqVFr9dMkRD","type":"tool","callID":"call_function_tn19igan6ppg_1","tool":"edit","state":{"status":"pending","input":{},"raw":""}},"time":1790455665406}');
INSERT INTO event VALUES('evt_0df795d00001NxuV2989xbRl4l','ses_f211dfcd4ffevS1Yoddwab036g',9377,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df7952fe0016msuyJejx7dY1o","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df794a15001bCtzqVFr9dMkRD","type":"tool","callID":"call_function_tn19igan6ppg_1","tool":"edit","state":{"status":"running","input":{"filePath":"/home/livings/Projects/zen-hardening/bootstrap.sh","newString":"  # Identity. Verify the MAC is actually randomized AND the setting is on.\n  # Checking the setting alone is not enough: the value can read ''always''\n  # while the interface still carries the permanent hardware MAC, because\n  # NM only applies a new address at connection activation. Verify the\n  # live address is locally administered (first octet bit 1 set), which\n  # is what distinguishes a randomized MAC from a burned-in one.\n  IFACE=$(nmcli -g GENERAL.DEVICE con show \"$(nmcli -t -f UUID,NAME con show | awk -F: ''$2==\"USL - Public\"{print $1}'')\" 2>/dev/null)\n  [ -z \"$IFACE\" ] && IFACE=wlo1\n  MAC=$(cat \"/sys/class/net/$IFACE/address\" 2>/dev/null || echo unknown)\n  MACRAND=$(nmcli -g 802-11-wireless.mac-address-randomization con show \"USL - Public\" 2>/dev/null || echo unknown)\n  OCTET=$(echo \"$MAC\" | cut -c1-2)\n  case \"$OCTET\" in\n    2*|6*|a*|e*) MACLOC=1 ;;\n    *)            MACLOC=0 ;;\n  esac\n\n  printf ''  %-22s %s\\n'' \"hostname:\"         \"$HOST\"\n  printf ''  %-22s %s\\n'' \"mac ($IFACE):\"     \"$MAC\"\n  printf ''  %-22s %s\\n'' \"mac randomization:\" \"$MACRAND\"\n  echo","oldString":"  printf ''  %-22s %s\\n'' \"hostname:\"         \"$HOST\"\n  echo"},"time":{"start":1790455667968}}},"time":1790455667968}');
INSERT INTO event VALUES('evt_0df795d03001W2C9Y5VALhF5Ez','ses_f211dfcd4ffevS1Yoddwab036g',9378,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df794fcd001HjO2xJYRUuunve","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df794a15001bCtzqVFr9dMkRD","type":"text","text":"Confirmed. `ea:bd:c8:4d:53:a8` — `ea` is a locally-administered unicast prefix, and the hardware MAC is gone. Identity layer is now actually complete.\n\nClosing the gap that let this pass as \"all green\" — the verification table covered hostname but never MAC:","time":{"start":1790455664589,"end":1790455667970}},"time":1790455667971}');
