INSERT INTO event VALUES('evt_0df796b9c001urWbHWmayBrhOQ','ses_f211dfcd4ffevS1Yoddwab036g',9389,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df7961a1001THK1Sxktg83Krn","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df795d2c001BTfSFiug2lsb76","type":"tool","callID":"call_function_v0erwz8yt4bv_1","tool":"edit","state":{"status":"running","input":{"filePath":"/home/livings/Projects/zen-hardening/bootstrap.sh","newString":"  [ \"$HOST\" = \"zero\" ] && ok \"hostname is zero\" || bad \"hostname is ''$HOST''\"\n  [ \"$F2B\" = \"active\" ] && ok \"fail2ban active\" || bad \"fail2ban is ''$F2B''\"\n\n  # Fail closed on identity: a ''passing'' baseline that still broadcasts the\n  # hardware MAC is not anonymous, so treat this as a hard failure rather\n  # than a note. The MAC only changes at activation, so a re-run after a\n  # manual ''nmcli con down/up'' will go from FAIL to OK.\n  if [ \"$MACRAND\" = \"always\" ] && [ \"$MACLOC\" -eq 1 ]; then\n    ok \"MAC randomized ($MAC, locally administered)\"\n  else\n    bad \"MAC NOT randomized — setting=''$MACRAND'' mac=$MAC (locally-administered=$MACLOC)\"\n    note \"setting=''always'' with a non-random MAC means the new address has\"\n    note \"not been activated yet. Apply it with:\"\n    note \"  nmcli con down ''USL - Public'' && nmcli con up ''USL - Public''\"\n  fi","oldString":"  [ \"$HOST\" = \"zero\" ] && ok \"hostname is zero\" || bad \"hostname is ''$HOST''\"\n  [ \"$F2B\" = \"active\" ] && ok \"fail2ban active\" || bad \"fail2ban is ''$F2B''\""},"time":{"start":1790455671708}}},"time":1790455671708}');
