INSERT INTO event VALUES('evt_0df79b362001t2OSzKXuZXHZDK','ses_f211dfcd4ffevS1Yoddwab036g',9465,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df79b361001ihDiYAk1AnZtfB","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df79a9380017RXxg3asZ4wfSG","type":"tool","callID":"call_function_wne8b1vnv0p3_1","tool":"bash","state":{"status":"pending","input":{},"raw":""}},"time":1790455690082}');
INSERT INTO event VALUES('evt_0df79b895001kVc6n6pR4OH8qb','ses_f211dfcd4ffevS1Yoddwab036g',9466,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df79b361001ihDiYAk1AnZtfB","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df79a9380017RXxg3asZ4wfSG","type":"tool","callID":"call_function_wne8b1vnv0p3_1","tool":"bash","state":{"status":"running","input":{"command":"cd /tmp/opencode/hss\nrsync -a --exclude=''.git'' --exclude=''venv'' --exclude=''__pycache__'' --exclude=''*.bak'' --exclude=''*.pyc'' \\\n      ~/Projects/zen-hardening/ config/zen-hardening/\ngit add -A\ngit -c user.name=opencode -c user.email=opencode@localhost commit -q -m \"Verify MAC in bootstrap; discover iface instead of hardcoding wlo0\n\nbootstrap.sh checked the hostname but not the MAC, so it reported\n''BASELINE OK, 0 checks failed'' while the machine was still\nbroadcasting its hardware address. Identity was incomplete and the\nscript said it was fine.\n\nThe check now fails closed: it requires the randomization setting to be\n''always'' AND the live address to be locally administered (first octet\nbit 1 set). Checking the setting alone is insufficient, because NM only\napplies the new address at connection activation, so ''always'' can read\ncorrectly while the interface still carries the burned-in MAC until a\nreconnect happens.\n\nset-home-trusted-zone.sh hardcoded wlo0. Interface names are not stable\nacross machines or reboots, and a stale name lets the firewall bind\nnothing while still reporting success. It now discovers the interface\nfrom the connection and fails loudly if it cannot, rather than binding\na name that may not exist.\n\nCo-Authored-By: Claude Opus 4.8 (1M context) <noreply@anthropic.com>\" 2>&1 | sed ''s/^/  /''\ngit push -q origin HEAD 2>&1 | sed ''s/^/  /'' && echo \"  [✓] pushed\" || echo \"  [✗] failed\"\ngit log --oneline -1 | sed ''s/^/  /''"},"time":{"start":1790455691413}}},"time":1790455691413}');
