INSERT INTO event VALUES('evt_0df7a74a900160nEDiNUPPSLI1','ses_f20e5cfc2ffeSFa4odnoYLiUOk',2758,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df7a6fb2001O9sP3fs5I00HNV","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df7a43f3001M72X0q0yGRVP1x","type":"tool","callID":"call_function_9fs2812x44sv_1","tool":"bash","state":{"status":"running","input":{"command":"echo \"=== is fail2ban installed / running? ===\"\ncommand -v fail2ban-client >/dev/null && echo \"  installed\" || echo \"  NOT installed\"\nsystemctl is-active fail2ban 2>/dev/null | sed ''s/^/  active: /''\nsystemctl is-enabled fail2ban 2>/dev/null | sed ''s/^/  enabled: /''\necho; echo \"=== live jails ===\"\nfail2ban-client status 2>&1 | head -5\necho; echo \"=== current bantime in live config ===\"\ngrep -rhnE \"^\\s*bantime\" /etc/fail2ban/jail.local /etc/fail2ban/jail.d/*.conf 2>/dev/null | head -20 || echo \"  no jail.local / jail.d overrides found\""},"metadata":{"output":""},"time":{"start":1790455739560}}},"time":1790455739561}');
