INSERT INTO event VALUES('evt_0df7fc49f001MdAZ2pVN0UnY7Y','ses_f211dfcd4ffevS1Yoddwab036g',9543,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df7fb821001Guzz20OJAcPnEN","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df7fae68001a1HpqwBWiY7xKk","type":"tool","callID":"call_function_w3hu6cfds7bi_1","tool":"bash","state":{"status":"running","input":{"command":"echo \"═══ BOOT READINESS (read-only, the part that could brick your reboot) ═══\"\necho \"  --- fstab ---\"\ngrep -vE ''^\\s*#|^\\s*$'' /etc/fstab | sed ''s/^/    /''\necho\necho \"  --- fstab syntax + device existence ---\"\nwhile read -r dev mnt fstype opts _; do\n  case \"$dev\" in \\#*|\"\") continue ;; esac\n  if [ -e \"$dev\" ] || [[ \"$dev\" == UUID=* || \"$dev\" == LABEL=* ]]; then\n    if [ -e \"$dev\" ]; then echo \"    [ok] $dev -> $mnt\"; else echo \"    [?] $dev (by $fstype label/uuid) -> $mnt\"; fi\n  else\n    echo \"    [!!] MISSING DEVICE $dev -> $mnt\"\n  fi\ndone < /etc/fstab\necho\necho \"  --- initramfs freshness ---\"\nlr=$(ls -1t /boot/initramfs-linux.img 2>/dev/null | head -1)\nif [ -n \"$lr\" ]; then\n  echo \"    image : $lr\"\n  echo \"    built : $(stat -c%y \"$lr\")\"\n  echo \"    kernel: $(uname -r)\"\n  newest=$(find /usr/lib/modules -maxdepth 1 -mindepth 1 -type d -printf ''%T@ %p\\n'' 2>/dev/null | sort -rn | head -1 | cut -d'' '' -f2-)\n  [ \"$newest\" -a \"$newest\" -nt \"$lr\" ] && echo \"    [!!] MODULES newer than initramfs ($newest) -> regenerate\" || echo \"    [ok] initramfs newer than modules\"\nelse\n  echo \"    [!!] NO initramfs found in /boot\"\nfi"},"metadata":{"output":""},"time":{"start":1790456087711}}},"time":1790456087711}');
INSERT INTO event VALUES('evt_0df7fc4a1001se1jDEfpW5m4ap','ses_f211dfcd4ffevS1Yoddwab036g',9544,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df7fb821001Guzz20OJAcPnEN","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df7fae68001a1HpqwBWiY7xKk","type":"tool","callID":"call_function_w3hu6cfds7bi_1","tool":"bash","state":{"status":"running","input":{"command":"echo \"═══ BOOT READINESS (read-only, the part that could brick your reboot) ═══\"\necho \"  --- fstab ---\"\ngrep -vE ''^\\s*#|^\\s*$'' /etc/fstab | sed ''s/^/    /''\necho\necho \"  --- fstab syntax + device existence ---\"\nwhile read -r dev mnt fstype opts _; do\n  case \"$dev\" in \\#*|\"\") continue ;; esac\n  if [ -e \"$dev\" ] || [[ \"$dev\" == UUID=* || \"$dev\" == LABEL=* ]]; then\n    if [ -e \"$dev\" ]; then echo \"    [ok] $dev -> $mnt\"; else echo \"    [?] $dev (by $fstype label/uuid) -> $mnt\"; fi\n  else\n    echo \"    [!!] MISSING DEVICE $dev -> $mnt\"\n  fi\ndone < /etc/fstab\necho\necho \"  --- initramfs freshness ---\"\nlr=$(ls -1t /boot/initramfs-linux.img 2>/dev/null | head -1)\nif [ -n \"$lr\" ]; then\n  echo \"    image : $lr\"\n  echo \"    built : $(stat -c%y \"$lr\")\"\n  echo \"    kernel: $(uname -r)\"\n  newest=$(find /usr/lib/modules -maxdepth 1 -mindepth 1 -type d -printf ''%T@ %p\\n'' 2>/dev/null | sort -rn | head -1 | cut -d'' '' -f2-)\n  [ \"$newest\" -a \"$newest\" -nt \"$lr\" ] && echo \"    [!!] MODULES newer than initramfs ($newest) -> regenerate\" || echo \"    [ok] initramfs newer than modules\"\nelse\n  echo \"    [!!] NO initramfs found in /boot\"\nfi"},"metadata":{"output":""},"time":{"start":1790456087711}}},"time":1790456087713}');
