INSERT INTO event VALUES('evt_0df7fcd6f001IahfYBJKaS2lWM','ses_f211dfcd4ffevS1Yoddwab036g',9549,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df7fc4a50010skdgPY80PFNNS","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df7fae68001a1HpqwBWiY7xKk","type":"tool","callID":"call_function_w3hu6cfds7bi_2","tool":"bash","state":{"status":"running","input":{"command":"echo \"═══ BOOTLOADER + KERNEL ═══\"\necho \"  --- bootloader packages ---\"\nfor p in grub mkinitcpio linux linux-zen systemd; do\n  v=$(pacman -Q \"$p\" 2>/dev/null | awk ''{print $2}'')\n  printf \"    %-14s %s\\n\" \"$p\" \"${v:-NOT INSTALLED}\"\ndone\necho\necho \"  --- /boot contents ---\"\nls -lh /boot/ 2>/dev/null | tail -12 | sed ''s/^/    /''\necho\necho \"  --- ESP / mount situation ---\"\nfindmnt -no TARGET,SOURCE,FSTYPE /boot 2>/dev/null | sed ''s/^/    /'' || echo \"    /boot not a separate mount\"\nfindmnt -no TARGET,SOURCE,FSTYPE /efi 2>/dev/null | sed ''s/^/    /'' || echo \"    /efi not mounted\"\necho\necho \"  --- grub entries ---\"\ngrep -cE \"^(menuentry|submenu)\" /boot/grub/grub.cfg 2>/dev/null | sed ''s/^/    entries: /'' || echo \"    no /boot/grub/grub.cfg\"\necho \"    default: $(grep -m1 ''^GRUB_DEFAULT='' /etc/default/grub 2>/dev/null)\"\necho \"    timeout: $(grep -m1 ''^GRUB_TIMEOUT='' /etc/default/grub 2>/dev/null)\""},"metadata":{"output":""},"time":{"start":1790456089967}}},"time":1790456089967}');
