INSERT INTO event VALUES('evt_0df7ff3ec001BMkMz7OfPMJEzi','ses_f211dfcd4ffevS1Yoddwab036g',9573,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df7febd0001Oq2H9130M0V9C7","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df7fcdf9001d5fxshwJy3q9Rr","type":"tool","callID":"call_function_7lx5exawmbob_1","tool":"bash","state":{"status":"running","input":{"command":"echo \"═══ CORRECTING MY OWN BAD CHECKS ═══\"\necho \"  initramfs present:\"\nls -1 /boot/initramfs*.img 2>/dev/null | sed ''s/^/    /''\necho\necho \"  --- who generates the initramfs? (mkinitcpio absent) ---\"\nfor p in mkinitcpio dracut dracut-legacy; do\n  v=$(pacman -Q \"$p\" 2>/dev/null | awk ''{print $2}'')\n  printf \"    %-16s %s\\n\" \"$p\" \"${v:-NOT INSTALLED}\"\ndone\necho\necho \"  --- initramfs vs kernel build time ---\"\nk=$(ls -1t /boot/vmlinuz-* 2>/dev/null | head -1)\ni=$(ls -1t /boot/initramfs-*.img 2>/dev/null | grep -v fallback | head -1)\necho \"    kernel    : $k  $(stat -c%y \"$k\" 2>/dev/null)\"\necho \"    initramfs : $i  $(stat -c%y \"$i\" 2>/dev/null)\"\n[ \"$i\" -nt \"$k\" ] && echo \"    [ok] initramfs built at/after kernel\" || echo \"    [!!] initramfs OLDER than kernel\"\necho\necho \"  --- running kernel vs on-disk kernel ---\"\necho \"    running: $(uname -r)\"\necho \"    on-disk: $(basename \"$k\" | sed ''s/^vmlinuz-//'')\""},"metadata":{"output":""},"time":{"start":1790456099820}}},"time":1790456099820}');
