INSERT INTO event VALUES('evt_0df7ff9d4001uthYG9XTVDKrMl','ses_f211dfcd4ffevS1Yoddwab036g',9584,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df7ff3f4001wNye9h8ukh2L21","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df7fcdf9001d5fxshwJy3q9Rr","type":"tool","callID":"call_function_7lx5exawmbob_2","tool":"bash","state":{"status":"running","input":{"command":"echo \"═══ ESP MOUNT STATUS — is /boot/efi actually mounted? ═══\"\nfindmnt -T /boot/efi 2>/dev/null | sed ''s/^/  /''\necho\ngrep -E '' /boot/efi '' /proc/mounts | sed ''s/^/  proc: /'' || echo \"  [!!] /boot/efi NOT in /proc/mounts\"\necho\necho \"  --- journal: did the ESP mount at boot? ---\"\njournalctl -b -o short-iso 2>/dev/null | grep -iE ''boot/efi|F54B-53CA|vfat'' | head -8 | sed ''s/^/  /'' || echo \"  (no matching journal lines)\"\necho\necho \"  --- does the ESP device exist right now? ---\"\nblkid -t UUID=F54B-53CA 2>/dev/null | sed ''s/^/  /'' || echo \"  [!!] UUID F54B-53CA not found by blkid\""},"metadata":{"output":""},"time":{"start":1790456101332}}},"time":1790456101332}');
