INSERT INTO event VALUES('evt_0df7ff9eb001bP3VA1JCAYZzmw','ses_f211dfcd4ffevS1Yoddwab036g',9586,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df7fe96b001dR3c5YPhHPcyDi","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df7fcdf9001d5fxshwJy3q9Rr","type":"text","text":"Two of those are my own check bugs, not system faults: `tmpfs` is virtual (not a block device), and I globbed `initramfs-linux.img` when the real file is `initramfs-linux-zen.img`. But two findings are real and need investigation.","time":{"start":1790456097131,"end":1790456101355}},"time":1790456101355}');
