INSERT INTO event VALUES('evt_0df8243a20014p4ympTx1lEonu','ses_f20e5cfc2ffeSFa4odnoYLiUOk',3332,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df823d08001F2mViEbwswvGK7","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df819c75001MNIokOapFGF9Fa","type":"text","text":"Correction: `1716/tcp`, `1716/udp`, and `5353/udp` all return **no** in the workstation zone, which is bound to `wlo1`. So kdeconnectd''s listener is **not** LAN-reachable — firewalld drops it. My earlier \"unmonitored remote surface\" claim was wrong. Gateways aside, two real gaps remain: the `ignoreip` breadth, and spoofing.\n\nLet me check the notification interface so I integrate rather than reinvent:","time":{"start":1790456249608,"end":1790456251298}},"time":1790456251298}');
