INSERT INTO event VALUES('evt_0df8243aa001Q9YlXPG46DXnpI','ses_f20e5cfc2ffeSFa4odnoYLiUOk',3334,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df8241f90014Tx2w762W2jQFK","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df819c75001MNIokOapFGF9Fa","type":"tool","callID":"call_function_lvb7a5x2zfnw_1","tool":"bash","state":{"status":"running","input":{"command":"cd ~/Projects/shield-kitty\necho \"=== how does shield-kitty send alerts? ===\"\ngrep -nE \"def (notify|send|alert)|notify-send|def main|argparse|add_argument\" shield-kitty-alert.py 2>/dev/null | head -20\necho; echo \"=== systemd unit pattern to follow ===\"\ncat systemd/shield-kitty-watch.service 2>/dev/null"},"metadata":{"output":"=== how does shield-kitty send alerts? ===\n5:Default behaviour is a DESKTOP NOTIFICATION (notify-send). It never takes over\n75:def notify(payload):\n76:    \"\"\"Desktop notification via notify-send. Returns 0 on success.\"\"\"\n83:    if not shutil.which(\"notify-send\"):\n84:        print(\"[shield-kitty] notify-send not found; falling back to terminal\",\n93:        \"notify-send\",\n104:            print(\"[shield-kitty] notify-send failed: {}\".format(r.stderr.strip()),\n272:def main():\n\n=== systemd unit pattern to follow ===\n[Unit]\nDescription=Shield Kitty intrusion watcher (journal tailer)\nDocumentation=file://%h/Projects/shield-kitty/\nAfter=graphical-session.target\n\n[Service]\nType=simple\nExecStart=/usr/bin/python3 %h/Projects/shield-kitty/shield-kitty-watch.py\nRestart=on-failure\nRestartSec=10\n\n# Hardening: this only needs to read the journal and spawn the alert.\n# Lock down everything else.\nNoNewPrivileges=true\nPrivateTmp=true\n# The watcher must read its own script from ~/Projects and the alert must\n# reach the display socket, so ProtectSystem=strict / ProtectHome=read-only\n# caused exit 226/NAMESPACE. Keep the directives that do work.\nProtectKernelTunables=true\nProtectControlGroups=true\nRestrictSUIDSGID=true\n\n[Install]\nWantedBy=default.target\n"},"time":{"start":1790456251290}}},"time":1790456251305}');
