INSERT INTO event VALUES('evt_0df824b75001W9z5jUyYFzzo5W','ses_f20e5cfc2ffeSFa4odnoYLiUOk',3346,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df824a3b0016aMFfQ4ZheCkFb","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df8243c30016HYWjlXx1gMtX2","type":"tool","callID":"call_function_ywtmjtxip58p_1","tool":"bash","state":{"status":"running","input":{"command":"cd ~/Projects/shield-kitty\nsed -n ''75,110p'' shield-kitty-alert.py\necho \"=== notify() signature / payload keys ===\"\ngrep -nE \"payload\\[|payload\\.get\" shield-kitty-alert.py | head -12"},"metadata":{"output":"def notify(payload):\n    \"\"\"Desktop notification via notify-send. Returns 0 on success.\"\"\"\n    sev = payload.get(\"severity\", \"warning\")\n    style = SEVERITY.get(sev, SEVERITY[\"warning\"])\n    head, body = summarize(payload)\n    stamp = payload.get(\"timestamp\") or time.strftime(\"%Y-%m-%d %H:%M:%S\")\n    full = \"{}\\n{}\".format(body, stamp) if body else stamp\n\n    if not shutil.which(\"notify-send\"):\n        print(\"[shield-kitty] notify-send not found; falling back to terminal\",\n              file=sys.stderr)\n        return terminal(payload)\n\n    # The nyan cat, rendered to PNG. Falls back to a stock icon if the\n    # renderer is unavailable.\n    icon = icon_path(sev) or style[\"icon\"]\n\n    cmd = [\n        \"notify-send\",\n        \"--app-name=shield-kitty\",\n        \"--urgency={}\".format(style[\"urgency\"]),\n        \"--icon={}\".format(icon),\n        \"--expire-time={}\".format(style[\"timeout\"]),\n        head,\n        full,\n    ]\n    try:\n        r = subprocess.run(cmd, capture_output=True, text=True, timeout=15)\n        if r.returncode != 0:\n            print(\"[shield-kitty] notify-send failed: {}\".format(r.stderr.strip()),\n                  file=sys.stderr)\n            return terminal(payload)\n        return 0\n    except Exception as exc:\n        print(\"[shield-kitty] notification error: {}\".format(exc), file=sys.stderr)\n        return terminal(payload)\n=== notify() signature / payload keys ===\n"},"time":{"start":1790456253292}}},"time":1790456253301}');
INSERT INTO event VALUES('evt_0df824b78001FbzkgVitK54GC2','ses_f20e5cfc2ffeSFa4odnoYLiUOk',3347,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df824a3b0016aMFfQ4ZheCkFb","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df8243c30016HYWjlXx1gMtX2","type":"tool","callID":"call_function_ywtmjtxip58p_1","tool":"bash","state":{"status":"running","input":{"command":"cd ~/Projects/shield-kitty\nsed -n ''75,110p'' shield-kitty-alert.py\necho \"=== notify() signature / payload keys ===\"\ngrep -nE \"payload\\[|payload\\.get\" shield-kitty-alert.py | head -12"},"metadata":{"output":"def notify(payload):\n    \"\"\"Desktop notification via notify-send. Returns 0 on success.\"\"\"\n    sev = payload.get(\"severity\", \"warning\")\n    style = SEVERITY.get(sev, SEVERITY[\"warning\"])\n    head, body = summarize(payload)\n    stamp = payload.get(\"timestamp\") or time.strftime(\"%Y-%m-%d %H:%M:%S\")\n    full = \"{}\\n{}\".format(body, stamp) if body else stamp\n\n    if not shutil.which(\"notify-send\"):\n        print(\"[shield-kitty] notify-send not found; falling back to terminal\",\n              file=sys.stderr)\n        return terminal(payload)\n\n    # The nyan cat, rendered to PNG. Falls back to a stock icon if the\n    # renderer is unavailable.\n    icon = icon_path(sev) or style[\"icon\"]\n\n    cmd = [\n        \"notify-send\",\n        \"--app-name=shield-kitty\",\n        \"--urgency={}\".format(style[\"urgency\"]),\n        \"--icon={}\".format(icon),\n        \"--expire-time={}\".format(style[\"timeout\"]),\n        head,\n        full,\n    ]\n    try:\n        r = subprocess.run(cmd, capture_output=True, text=True, timeout=15)\n        if r.returncode != 0:\n            print(\"[shield-kitty] notify-send failed: {}\".format(r.stderr.strip()),\n                  file=sys.stderr)\n            return terminal(payload)\n        return 0\n    except Exception as exc:\n        print(\"[shield-kitty] notification error: {}\".format(exc), file=sys.stderr)\n        return terminal(payload)\n=== notify() signature / payload keys ===\n58:    events = payload.get(\"events\", [])\n59:    sev = payload.get(\"severity\", \"warning\")\n77:    sev = payload.get(\"severity\", \"warning\")\n80:    stamp = payload.get(\"timestamp\") or time.strftime(\"%Y-%m-%d %H:%M:%S\")\n139:            self.sev = payload.get(\"severity\", \"warning\")\n210:                     \"time:     {}\".format(self.payload.get(\"timestamp\"))]\n211:            for e in self.payload.get(\"events\", [])[:6]:\n258:    sev = payload.get(\"severity\", \"?\")\n263:    print(\"  time     : {}\".format(payload.get(\"timestamp\")))\n264:    for e in payload.get(\"events\", []):\n"},"time":{"start":1790456253292}}},"time":1790456253304}');
