start_mac=\"$(norm_mac \"$2\")\"\nstop_ip=\"$3\";  stop_mac=\"$(norm_mac \"$4\")\"\n\n# --- flip-flop: same IP, different MAC = spoofing signal\nif [ \"$start_ip\" = \"$stop_ip\" ] && [ -n \"$start_mac\" ] && [ -n \"$stop_mac\" ] \\\n   && [ \"$start_mac\" != \"$stop_mac\" ]; then\n    if is_infrastructure \"$start_ip\"; then\n        log \"FLIP-FLOP on infrastructure addr $start_ip ($start_mac -> $stop_mac) -- not alerting\"\n        exit 0\n    fi\n    log \"FLIP-FLOP $start_ip $start_mac -> $stop_mac\"\n    notify \"critical\" \"ARP spoof: $start_ip claimed two MACs\" \\\n        \"$start_ip was $start_mac, now claims $stop_mac. Not auto-banned: MAC randomisation looks identical. Verify, then ban via the 86400s fail2ban path if real.\"\n    exit 0\nfi\n\n# --- new host: routine. Logged, never alerted.\nlog \"new host $start_ip $start_mac\"\nexit 0\n","filePath":"/home/livings/Projects/zen-hardening/arpwatch-spoof-alert.sh"},"output":"Wrote file successfully.","title":"home/livings/Projects/zen-hardening/arpwatch-spoof-alert.sh","metadata":{"diagnostics":{},"filepath":"/home/livings/Projects/zen-hardening/arpwatch-spoof-alert.sh","exists":false,"truncated":false},"time":{"start":1790456280737,"end":1790456280751}}},"time":1790456280751}');
