INSERT INTO event VALUES('evt_0df82b8a8001VQJnjXEPY6x4f2','ses_f211dfcd4ffevS1Yoddwab036g',9821,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df82ada1001f4vA7ykGFbh2Tj","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df825c09001yi5Vp71u13KN6d","type":"text","text":"Both noted. On the sudoers one — I flagged the risk, and it''s real: I can''t grant NOPASSWD on `nft`, `btrfs`, `firewall-cmd` or `fail2ban-client` directly, because those same binaries can *mutate* state (`nft flush ruleset`, `btrfs subvolume delete`). Allowing them unpassworded is root-equivalent.\n\nSo I''ll scope it properly: root-owned wrappers that take no arguments and run only fixed read-only commands, with sudoers restricted to exactly those.","time":{"start":1790456278433,"end":1790456281256}},"time":1790456281256}');
