INSERT INTO event VALUES('evt_0df82d641001dQ8vNr8rrTT6u6','ses_f20e5cfc2ffeSFa4odnoYLiUOk',3402,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df82ca9f001ZAqzAcdEzW9bV6","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df82bdf7001ngTbNpJYNGyL4e","type":"tool","callID":"call_function_hw4k6r6dayv2_1","tool":"bash","state":{"status":"running","input":{"command":"cd /tmp && rm -rf spoofT && mkdir -p spoofT/Projects/shield-kitty\ncat > spoofT/Projects/shield-kitty/shield-kitty-alert.py <<''PY''\nimport sys, json\nopen(\"/tmp/spoofT/alerted.log\",\"a\").write(sys.argv[1]+\"\\n\")\nPY\nexport HOME=/tmp/spoofT\nexport BDE_ARPWATCH_LOG=/tmp/spoofT/spoof.log\nS=/home/livings/Projects/zen-hardening/arpwatch-spoof-alert.sh\n: > /tmp/spoofT/alerted.log\n\necho \"=== 1. FLIP-FLOP (same IP, two MACs) -> expect ALERT ===\"\n\"$S\" 10.0.0.5 aa:bb:cc:dd:ee:01 10.0.0.5 aa:bb:cc:dd:ee:02\necho \"   alerts: $(wc -l < /tmp/spoofT/alerted.log)\"\n\necho \"=== 2. NEW HOST -> expect NO alert ===\"\n\"$S\" 10.0.0.9 aa:bb:cc:dd:ee:03 10.0.0.9 aa:bb:cc:dd:ee:03\necho \"   alerts: $(wc -l < /tmp/spoofT/alerted.log)  (unchanged = correct)\"\n\necho \"=== 3. INFRASTRUCTURE flip-flop -> expect NO alert ===\"\nBDE_SELF_IPS=10.197.250.246 \"$S\" 10.197.250.246 aa:bb:cc:dd:ee:01 10.197.250.246 aa:bb:cc:dd:ee:09\necho \"   alerts: $(wc -l < /tmp/spoofT/alerted.log)  (unchanged = correct)\"\n\necho \"=== 4. MALFORMED args -> expect log, no crash ===\"\n\"$S\" onlyone; echo \"   exit=$?\"\n\necho \"=== 5. case/dash MAC normalisation (AA-BB-CC-DD-EE-01 vs aa:bb:cc:dd:ee:02) ===\"\n\"$S\" 10.0.0.7 AA-BB-CC-DD-EE-01 10.0.0.7 aa:bb:cc:dd:ee:02\necho \"   alerts: $(wc -l < /tmp/spoofT/alerted.log)  (should be 2: normalised != same MAC)\""},"time":{"start":1790456288833}}},"time":1790456288833}');
