INSERT INTO event VALUES('evt_0df82f7e9001FgHxY6fTyW17a5','ses_f20e5cfc2ffeSFa4odnoYLiUOk',3440,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df82eca0001cZiJXkbFnVqwVj","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df82e33e001pZpKsvNaYj6emr","type":"tool","callID":"call_function_os32rymsuyuo_1","tool":"write","state":{"status":"running","input":{"content":"[Unit]\nDescription=ARP spoof watcher (arpwatch -> Shield Kitty notification)\nDocumentation=file://%h/Projects/zen-hardening/arpwatch-spoof-alert.sh\nAfter=network-online.target\nWants=network-online.target\n\n[Service]\n# arpwatch opens a raw AF_PACKET socket, so it needs CAP_NET_RAW. It is given\n# exactly that and nothing more -- no root shell, no access to the rest of the\n# filesystem beyond reading the hook script.\nExecStart=/usr/sbin/arpwatch -q -u livings -c /home/livings/.local/share/arpwatch/arpwatch.dat -a /home/livings/Projects/zen-hardening/arpwatch-spoof-alert.sh wlo1\nRestart=on-failure\nRestartSec=10\n\n# The exec hook must be able to append to the spoof log and run the notifier.\nReadWritePaths=/var/log\nNoNewPrivileges=true\nPrivateTmp=true\nProtectKernelTunables=true\nProtectKernelModules=true\nProtectControlGroups=true\nRestrictSUIDSGID=true\n# The hook needs to write its log; everything else is read-only.\nProtectSystem=full\nProtectHome=read-only\n\n[Install]\nWantedBy=multi-user.target\n","filePath":"/home/livings/Projects/zen-hardening/arpwatch-spoof.service"},"time":{"start":1790456297449}}},"time":1790456297449}');
INSERT INTO event VALUES('evt_0df82f7eb001aV34zEmVbJQBxK','ses_f20e5cfc2ffeSFa4odnoYLiUOk',3441,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df82eb2c001lQcthYHmcP0bW3","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df82e33e001pZpKsvNaYj6emr","type":"text","text":"Now the systemd unit and a dry-run installer:","time":{"start":1790456294188,"end":1790456297451}},"time":1790456297451}');
