INSERT INTO event VALUES('evt_0df841106001vuSzFojK8di1qJ','ses_f20e5cfc2ffeSFa4odnoYLiUOk',3692,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df841106001oD6plhtxdMx4dB","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df840a81001flu8QLEiFjKtYz","type":"tool","callID":"call_function_7tgjhsly1fjf_1","tool":"bash","state":{"status":"pending","input":{},"raw":""}},"time":1790456369414}');
INSERT INTO event VALUES('evt_0df842530001NTNMDTvFv49fGa','ses_f20e5cfc2ffeSFa4odnoYLiUOk',3693,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df841106001oD6plhtxdMx4dB","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df840a81001flu8QLEiFjKtYz","type":"tool","callID":"call_function_7tgjhsly1fjf_1","tool":"bash","state":{"status":"running","input":{"command":"cd ~/Projects/zen-hardening\nrm -f /tmp/pf.txt /tmp/fc.txt; rm -rf /tmp/spoofT /tmp/spoofT2\ngit add arpwatch-spoof-alert.sh arpwatch-spoof.service install-arpwatch-spoof.sh\ngit commit -q -m \"security: add ARP spoof detection via arpwatch, notifying via Shield Kitty\n\nCloses the one real gap left in local hardening. Nothing on this machine could\ndetect system spoofing: no arpwatch, no suricata, no zeek, no tcpdump, no\ntpm2-tools, and no spoofing logic in any repo. fail2ban structurally cannot do\nthis -- it parses auth logs for repeated failures and has no notion of ARP,\nDHCP, hostname or MAC spoofing. arpwatch is in the extra repo (3.9-1).\n\narpwatch-spoof-alert.sh is the exec hook. It alerts on ONE event: a flip-flop,\na single IP claiming two different MACs. New hosts and departures are routine\nwith DHCP and are logged, never alerted. Own IP and gateway are skipped.\n\nNO AUTO-BAN, deliberately. The 1-day ban stays with fail2ban, which keys on\nreal connection and auth attempts. On this network a flipped MAC is usually\nAndroid or Windows per-SSID MAC randomisation, and the machine sits on a /8\nwith 16.7M addresses of other people on it -- a 24h ban on a flip-flop would\ncut off colleagues and randomising phones, not attackers. This notifies and\nlogs; a human decides.\n\nTwo bugs found by testing, both of which would have failed in production:\n\n- The alert payload was built as events:[\\\"str\\\", ...]. shield-kitty-alert.py\n  calls .get() on each element, so every spoof alert raised AttributeError and\n  was LOST. The schema is events:[{label,count,sample}]. The headline is\n  generated by the alert script, so passing one in was also wrong.\n- The unit ran the hook as root, and the log/db as root, while the installer\n  omitted sudo on the log. notify-send needs the USER session bus, so a\n  root-run hook delivers the alert to nobody. arpwatch now starts as root for\n  the AF_PACKET socket and drops to livings via -u, with both writable paths\n  owned by livings. The DB moved out of ~ so ProtectHome=read-only still holds.\n\nVerified: 7/7 on classification (flip-flop alerts, new host silent, own IP and\ngateway ignored, MAC case/dash normalisation, identical MAC not a flip,\nmalformed args exit 0), plus a live end-to-end delivery through the real\nnotify-send path -- no traceback, notification returned 0.\n\nNOT INSTALLED -- needs root:\n  sudo ~/Projects/zen-hardening/install-arpwatch-spoof.sh --dry-run\n  sudo ~/Projects/zen-hardening/install-arpwatch-spoof.sh\"\ngit log --oneline | head -1"},"time":{"start":1790456374575}}},"time":1790456374576}');
INSERT INTO event VALUES('evt_0df842535001D55z8S3XY9pNRu','ses_f20e5cfc2ffeSFa4odnoYLiUOk',3694,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df840fd4001GCjwp987qsGPha","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df840a81001flu8QLEiFjKtYz","type":"text","text":"All 7 pass. Committing:","time":{"start":1790456369108,"end":1790456374580}},"time":1790456374580}');
