INSERT INTO event VALUES('evt_0df847e88001EH65t8W6j95DvX','ses_f211dfcd4ffevS1Yoddwab036g',9860,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df83174b0012y36NrgnTlA4w4","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df830d870016FEKuKxYYr3qma","type":"tool","callID":"call_function_2wmw8mj5kguf_1","tool":"bash","state":{"status":"running","input":{"command":"quiet=0\nfor i in $(seq 1 20); do\n  busy=\"\"\n  for d in ~/Projects/*/; do\n    [ -d \"$d/.git\" ] || continue\n    t=$(git -C \"$d\" log -1 --format=''%ct'' 2>/dev/null)\n    [ -n \"$t\" ] && [ $(( $(date +%s) - t )) -lt 180 ] && busy=\"$busy $(basename \"$d\")\"\n  done\n  if [ -z \"$busy\" ]; then\n    quiet=$((quiet+1))\n    printf \"  [%02d] quiet %ds\\n\" \"$i\" $((quiet*30))\n    [ \"$quiet\" -ge 4 ] && { echo \"  [ok] repos quiet for 2m -- agents idle\"; break; }\n  else\n    quiet=0\n    printf \"  [%02d] active:%s\\n\" \"$i\" \"$busy\"\n  fi\n  sleep 30\ndone\necho\necho \"  final: most recent commit per repo\"\nfor d in ~/Projects/*/; do\n  [ -d \"$d/.git\" ] || continue\n  printf \"    %-26s %s\\n\" \"$(basename \"$d\")\" \"$(git -C \"$d\" log -1 --format=''%cr  %h'' 2>/dev/null)\"\ndone","timeout":660000},"metadata":{"output":"  [01] active: lin-antimalware\n  [02] active: lin-antimalware\n  [03] active: lin-antimalware\n  [04] active: buildlog lin-antimalware zen-hardening\n"},"time":{"start":1790456307284}}},"time":1790456397448}');
