INSERT INTO event VALUES('evt_0df84bc99001m1q2dAATWzVRFc','ses_f20e5cfc2ffeSFa4odnoYLiUOk',3726,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df84bc91001Ty6arxDMAlcbXc","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df84bc8f0013eI6VZmKsqkA4L","type":"text","text":"sudo ~/Projects/zen-hardening/install-arpwatch-spoof.sh --dry-run\nsudo ~/Projects/zen-hardening/install-arpwatch-spoof.sh\n[sudo] password for livings:\n=== arpwatch spoof detection installer ===\ninterface : wlo1\ndatabase  : /var/lib/arpwatch/arpwatch.dat\nlog       : /var/log/arpwatch-spoof.log\nmode      : DRY RUN\n[1/5] checking prerequisites\nwlo1 present\nERROR: hook not executable: /root/Projects/zen-hardening/arpwatch-spoof-alert.sh\n=== arpwatch spoof detection installer ===\ninterface : wlo1\ndatabase  : /var/lib/arpwatch/arpwatch.dat\nlog       : /var/log/arpwatch-spoof.log\n[1/5] checking prerequisites\nwlo1 present\nERROR: hook not executable: /root/Projects/zen-hardening/arpwatch-spoof-alert.sh "},"time":1790456413337}');
