INSERT INTO event VALUES('evt_0df85de86001Ch7NUMkFdv9o7p','ses_f211dfcd4ffevS1Yoddwab036g',9863,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df83174b0012y36NrgnTlA4w4","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df830d870016FEKuKxYYr3qma","type":"tool","callID":"call_function_2wmw8mj5kguf_1","tool":"bash","state":{"status":"running","input":{"command":"quiet=0\nfor i in $(seq 1 20); do\n  busy=\"\"\n  for d in ~/Projects/*/; do\n    [ -d \"$d/.git\" ] || continue\n    t=$(git -C \"$d\" log -1 --format=''%ct'' 2>/dev/null)\n    [ -n \"$t\" ] && [ $(( $(date +%s) - t )) -lt 180 ] && busy=\"$busy $(basename \"$d\")\"\n  done\n  if [ -z \"$busy\" ]; then\n    quiet=$((quiet+1))\n    printf \"  [%02d] quiet %ds\\n\" \"$i\" $((quiet*30))\n    [ \"$quiet\" -ge 4 ] && { echo \"  [ok] repos quiet for 2m -- agents idle\"; break; }\n  else\n    quiet=0\n    printf \"  [%02d] active:%s\\n\" \"$i\" \"$busy\"\n  fi\n  sleep 30\ndone\necho\necho \"  final: most recent commit per repo\"\nfor d in ~/Projects/*/; do\n  [ -d \"$d/.git\" ] || continue\n  printf \"    %-26s %s\\n\" \"$(basename \"$d\")\" \"$(git -C \"$d\" log -1 --format=''%cr  %h'' 2>/dev/null)\"\ndone","timeout":660000},"metadata":{"output":"  [01] active: lin-antimalware\n  [02] active: lin-antimalware\n  [03] active: lin-antimalware\n  [04] active: buildlog lin-antimalware zen-hardening\n  [05] active: buildlog lin-antimalware zen-hardening\n  [06] active: buildlog zen-hardening\n  [07] active: buildlog zen-hardening\n"},"time":{"start":1790456307284}}},"time":1790456487558}');
INSERT INTO event VALUES('evt_0df85e0a4001uYRCcuExQzd8XJ','ses_f20e5cfc2ffeSFa4odnoYLiUOk',3902,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df85ddd4001mgJgURGwEFs948","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df85d1df001ZsldzV0mIVggdJ","type":"tool","callID":"call_function_09wli25xlm88_1","tool":"edit","state":{"status":"running","input":{"filePath":"/home/livings/Projects/zen-hardening/arpwatch-spoof-alert.sh","newString":"log() { printf ''%s %s\\n'' \"$(date -Is)\" \"$*\" >>\"$LOG\" 2>/dev/null || \\\n        printf ''%s %s\\n'' \"$(date -Is)\" \"$*\" >&2; }","oldString":"log() { printf ''%s %s\\n'' \"$(date -Is)\" \"$*\" >>\"$LOG\" 2>/dev/null || \\\n        printf ''%s %s\\n'' \"$(date -Is)\" \"$*\" >&2; }\n\n# Where to send the notifier''s stderr. If the log is not writable -- wrong\n# ownership, or the installer has not created it yet -- fall back to stderr, so\n# the actual reason a delivery failed is never swallowed.\nlog_or_stderr() {\n    if ! touch \"$LOG\" 2>/dev/null; then echo \"(log $LOG not writable)\" >&2; fi\n    cat >/dev/stderr\n}"},"time":{"start":1790456488100}}},"time":1790456488100}');
