INSERT INTO event VALUES('evt_0df866dfb0013bM7Occ6Ixlv0M','ses_f20e5cfc2ffeSFa4odnoYLiUOk',4020,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df866840001h8n4YhUCuOYtqq","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df866278001ecccYikbhFO3z8","type":"tool","callID":"call_function_ueund0yupdmn_1","tool":"bash","state":{"status":"running","input":{"command":"cd ~/Projects/buildlog\nbuildlog fix \"arpwatch installer aborted under sudo: ''hook not executable: /root/Projects/...''. sudo resets HOME to /root, so \\$HOME/Projects resolved into /root. Fixed by resolving the real home from SUDO_USER via getent and rewriting the unit path + Environment=HOME at install time. Also found a SECOND silent bug the same way: the hook is arpwatch''s child, and arpwatch starts as root then drops privs with -u, which changes uid but NOT the environment -- so the hook had no DISPLAY/DBUS and every spoof notification failed while the log line still appeared. Fixed by reconstructing the session from /run/user/UID/bus. Verified: notify-send with only the bootstrapped vars exits 0, bare env fails ''Cannot autolaunch D-Bus''. commit b39490a\" 2>&1 | tail -1"},"metadata":{"output":""},"time":{"start":1790456524283}}},"time":1790456524283}');
