INSERT INTO event VALUES('evt_0df8f9c3c0015kqYnDqGNbg6Yf','ses_f20e5cfc2ffeSFa4odnoYLiUOk',4055,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df8f9c3a0016cE1IOJ4umNCFr","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df8f9c38001uu2NY2ocTxc9X4","type":"text","text":"arpwatch-spoof.service: Main process exited, code=exited, status=1/FAILURE\nSep 26 14:11:23 zero systemd[1]: arpwatch-spoof.service: Failed withresult ''exit-code''.\nSep 26 14:11:33 zero systemd[1]: arpwatch-spoof.service: Scheduled restart job, restart counter is at 1.\nSep 26 14:11:33 zero systemd[1]: Started ARP spoof watcher (arpwatch-> Shield Kitty notification).\nSep 26 14:11:33 zero arpwatch[312247]: Version 3.9\nSep 26 14:11:33 zero arpwatch[312247]: usage: arpwatch [-CdFNpqsvzZ][-D arpdir] [-f datafile] [-i interface]\nSep 26 14:11:33 zero arpwatch[312247]:          [-P pidfile] [-w watcher@email] [-W watchee@email]\nSep 26 14:11:33 zero arpwatch[312247]:          [-n net[/width]] [-xnet[/width]] [-r file]\nSep 26 14:11:33 zero systemd[1]: arpwatch-spoof.service: Main process exited, code=exited, status=1/FAILURE\nSep 26 14:11:33 zero systemd[1]: arpwatch-spoof.service: Failed withresult ''exit-code''.\nSep 26 14:11:43 zero systemd[1]: arpwatch-spoof.service: Scheduled restart job, restart counter is at 2.\nSep 26 14:11:43 zero systemd[1]: Started ARP spoof watcher (arpwatch-> Shield Kitty notification).\nSep 26 14:11:43 zero arpwatch[312402]: Version 3.9\nSep 26 14:11:43 zero arpwatch[312402]: usage: arpwatch [-CdFNpqsvzZ][-D arpdir] [-f datafile] [-i interface]\nSep 26 14:11:43 zero arpwatch[312402]:          [-P pidfile] [-w watcher@email] [-W watchee@email]\nSep 26 14:11:43 zero arpwatch[312402]:          [-n net[/width]] [-xnet[/width]] [-r file]\nSep 26 14:11:43 zero systemd[1]: arpwatch-spoof.service: Main process exited, code=exited, status=1/FAILURE\nSep 26 14:11:43 zero systemd[1]: arpwatch-spoof.service: Failed withresult ''e