INSERT INTO event VALUES('evt_0df8fba63001wHe6JQ4xHnoRNM','ses_f20e5cfc2ffeSFa4odnoYLiUOk',4067,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df8fb896001BpPu321BrJtqVk","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df8f9c57001x8UTMCHw6w8HbC","type":"text","text":"My `ExecStart` flags are wrong — arpwatch 3.9 is a **different implementation** than the original LBL arpwatch, and there''s no `-a`, `-u`, or `-c`. Let me read the actual man page now that it''s installed:","time":{"start":1790457133206,"end":1790457133667}},"time":1790457133667}');
