INSERT INTO event VALUES('evt_0df905852001TM3y41N075aNbO','ses_f211dfcd4ffevS1Yoddwab036g',9979,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df9053e2001LZ7EmzxXmnDlYz","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df904a71001gWRYwaFZBNEtGl","type":"text","text":"All 7 helpers installed, root-owned 0755. Sudo is intact — the \"password required\" is correct behaviour, meaning the drop-in is active but `sudo -n true` isn''t whitelisted (only the specific helpers are). That''s exactly the intended design.\n\n`Permission denied` on `ls /etc/sudoers.d/audit-readonly` is directory permissions, not a missing file. Testing whether the helpers actually work:","time":{"start":1790457172962,"end":1790457174098}},"time":1790457174098}');
