INSERT INTO event VALUES('evt_0df909cf9001ejp089SIB5tzzX','ses_f20e5cfc2ffeSFa4odnoYLiUOk',4141,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df9093dd001WNt2WXpZVFQ503","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df908264001Z0Ay3Akb967EbI","type":"tool","callID":"call_function_ao6mjv2lz81j_1","tool":"bash","state":{"status":"running","input":{"command":"cd /tmp && rm -rf arpT && mkdir -p arpT\ncat > /tmp/arpT/count.py <<''PY''\nimport sys\nopen(\"/tmp/arpT/alerts.log\",\"a\").write(sys.argv[1]+\"\\n\")\nPY\n# arp.dat format: <mac> <ip> <unix-seconds> [hostname]\ncat > /tmp/arpT/arp.dat <<''EOF''\naa:bb:cc:00:00:01 10.0.0.1 1758000000 host1\naa:bb:cc:00:00:02 10.0.0.2 1758000001\naa:bb:cc:00:00:03 10.0.0.3 1758000002\ndd:ee:ff:00:00:09 10.0.0.3 1758000003\n11:22:33:00:00:04 10.0.0.4 1758000004\n11:22:33:00:00:05 10.0.0.4 1758000005\n22:33:44:00:00:06 127.0.0.1 1758000006\n33:44:55:00:00:07 127.0.0.1 1758000007\n44:55:66:00:00:08 0.0.0.0 1758000008\n55:66:77:00:00:0a 0.0.0.0 1758000009\nEOF\nexport BDE_ARP_DATAFILE=/tmp/arpT/arp.dat BDE_ARP_STATE=/tmp/arpT/state\nexport BDE_ARPWATCH_LOG=/tmp/arpT/scan.log BDE_ALERT=/tmp/arpT/count.py\n: > /tmp/arpT/alerts.log; : > /tmp/arpT/scan.log\nS=/home/livings/Projects/zen-hardening/arpwatch-spoof-scan.sh\necho \"=== scan 1 (should alert on 10.0.0.3 and 10.0.0.4 only) ===\"\n\"$S\"; echo \"  exit=$?\"\npython3 -c \"\nimport json\nfor l in open(''/tmp/arpT/alerts.log''):\n    e=json.loads(l)[''events''][0]\n    print(''   ALERT:'', e[''label''])\n    print(''         '', e[''sample''][:80])\n\""},"time":{"start":1790457191672}}},"time":1790457191673}');
