INSERT INTO event VALUES('evt_0df90bc44001XYMO58DrnlAh1h','ses_f20e5cfc2ffeSFa4odnoYLiUOk',4170,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df90ba51001EGV9Npkukqj66F","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df90af040012pS85h44Um2KN0","type":"reasoning","text":"Correct: only 10.0.0.3 and 10.0.0.4 alerted. The loopback (127.0.0.1) and 0.0.0.0 duplicates were correctly ignored.\n\nNow let me test deduplication (scan 2 should produce 0 new alerts), and a new anomaly appearing.\n\nLet me test.","time":{"start":1790457199185,"end":1790457199684}},"time":1790457199684}');
