INSERT INTO event VALUES('evt_0df91105d001SonruPmuEnjAaM','ses_f20e5cfc2ffeSFa4odnoYLiUOk',4207,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df9100ac001cemkN0Cjhv6249","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df90f742001jLbyAvGXC7DCqc","type":"tool","callID":"call_function_6pd5kua3cl0d_1","tool":"bash","state":{"status":"running","input":{"command":"export BDE_ARP_DATAFILE=/tmp/arpT/arp.dat BDE_ARP_STATE=/tmp/arpT/state\nexport BDE_ARPWATCH_LOG=/tmp/arpT/scan.log BDE_ALERT=/tmp/arpT/count.py\nS=/home/livings/Projects/zen-hardening/arpwatch-spoof-scan.sh\npass=0; fail=0\nchk(){ if [ \"$2\" = \"$3\" ]; then echo \"  PASS  $1\"; pass=$((pass+1)); else echo \"  FAIL  $1 (got ''$2'' want ''$3'')\"; fail=$((fail+1)); fi; }\n\n# 1. clean datafile -> no alerts\nprintf ''aa:bb:cc:00:00:01 10.1.0.1 1758000000\\n'' > /tmp/arpT/clean.dat\nrm -f /tmp/arpT/state2\nBDE_ARP_DATAFILE=/tmp/arpT/clean.dat BDE_ARP_STATE=/tmp/arpT/state2 \"$S\" >/dev/null 2>&1\nchk \"clean datafile -> 0 alerts\" \"$(wc -l < /tmp/arpT/alerts.log | tr -d '' '')\" \"3\"\n\n# 2. MAC case normalisation: same MAC different case must NOT count as 2 MACs\nprintf ''AA:BB:CC:00:00:0A 10.2.0.1 1758000000\\naa:bb:cc:00:00:0a 10.2.0.1 1758000001\\n'' > /tmp/arpT/case.dat\nrm -f /tmp/arpT/state3; b=$(wc -l < /tmp/arpT/alerts.log)\nBDE_ARP_DATAFILE=/tmp/arpT/case.dat BDE_ARP_STATE=/tmp/arpT/state3 \"$S\" >/dev/null 2>&1\nchk \"MAC case-dup not an anomaly\" \"$(wc -l < /tmp/arpT/alerts.log | tr -d '' '')\" \"$b\"\n\n# 3. hostname field must not break parsing\nprintf ''aa:bb:cc:00:00:0b 10.3.0.1 1758000000 myhost\\ncc:dd:ee:00:00:0c 10.3.0.1 1758000001 other\\n'' > /tmp/arpT/hn.dat\nrm -f /tmp/arpT/state4; b=$(wc -l < /tmp/arpT/alerts.log)\nBDE_ARP_DATAFILE=/tmp/arpT/hn.dat BDE_ARP_STATE=/tmp/arpT/state4 \"$S\" >/dev/null 2>&1\nchk \"hostname field parsed\" \"$(wc -l < /tmp/arpT/alerts.log | tr -d '' '')\" \"$((b+1))\"\n\n# 4. empty datafile\n: > /tmp/a