INSERT INTO event VALUES('evt_0df91577b001yaj3GcMWAw74Cr','ses_f20e5cfc2ffeSFa4odnoYLiUOk',4240,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df913fe2001SHQdJlX5M94HAJ","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df913408001pwvzQJXIO3fIkw","type":"tool","callID":"call_function_byjalye03fff_1","tool":"bash","state":{"status":"running","input":{"command":"cd /tmp && rm -rf arpT2 && mkdir -p arpT2\ncp /tmp/arpT/count.py /tmp/arpT2/ 2>/dev/null || cat > /tmp/arpT2/count.py <<''PY''\nimport sys\nopen(\"/tmp/arpT2/alerts.log\",\"a\").write(sys.argv[1]+\"\\n\")\nPY\nexport BDE_ARPWATCH_LOG=/tmp/arpT2/scan.log BDE_ALERT=/tmp/arpT2/count.py\n: > /tmp/arpT2/alerts.log\nS=/home/livings/Projects/zen-hardening/arpwatch-spoof-scan.sh\npass=0; fail=0\nchk(){ if [ \"$2\" = \"$3\" ]; then echo \"  PASS  $1\"; pass=$((pass+1)); else echo \"  FAIL  $1 (got ''$2'' want ''$3'')\"; fail=$((fail+1)); fi; }\na(){ wc -l < /tmp/arpT2/alerts.log | tr -d '' ''; }\nrun(){ rm -f \"/tmp/arpT2/st_$1\"; BDE_ARP_DATAFILE=\"$2\" BDE_ARP_STATE=\"/tmp/arpT2/st_$1\" \"$S\" >/dev/null 2>&1; }\n\n# 1 clean\nprintf ''aa:bb:cc:00:00:01 10.1.0.1 1758000000\\n'' > /tmp/arpT2/clean.dat; run 1 /tmp/arpT2/clean.dat\nchk \"clean -> 0 alerts\" \"$(a)\" \"0\"\n# 2 case-dup of SAME mac must NOT alert\nprintf ''AA:BB:CC:00:00:0A 10.2.0.1 1758000000\\naa:bb:cc:00:00:0a 10.2.0.1 1758000001\\n'' > /tmp/arpT2/case.dat; run 2 /tmp/arpT2/case.dat\nchk \"same MAC different case -> 0\" \"$(a)\" \"0\"\n# 3 genuine two-mac spoof\nprintf ''aa:bb:cc:00:00:0b 10.3.0.1 1758000000\\ncc:dd:ee:00:00:0c 10.3.0.1 1758000001\\n'' > /tmp/arpT2/real.dat; run 3 /tmp/arpT2/real.dat\nchk \"genuine spoof -> 1 alert\" \"$(a)\" \"1\"\n# 4 three macs\nprintf ''aa:bb:cc:00:00:01 10.4.0.1 1\\ncc:dd:ee:00:00:02 10.4.0.1 2\\n11:22:33:00:00:03 10.4.0.1 3\\n'' > /tmp/arpT2/three.dat; run 4 /tmp/arpT2/three.dat\nchk \"three MACs -> 1 alert, count=3\" \"$(python3 -c \"\nimport json;d=json.loads(open(''/tmp/arpT2/alerts.log'').read().strip().split(chr(10))[-1]);print(d[''events''][0][''label''].split()[-2])\")\" \"3\"\n# 5 same MAC across DIFFERENT ips is not an IP anomaly\nprintf ''aa:bb:cc:00:00:01 10.5.0.1 1\\naa:bb:cc:00:00:01 10.5.0.2 2\\n'' > /tmp/arpT2/macmove.dat; run 5 /tmp/arpT2/macmove.dat\nchk \"MAC on 2 IPs -> 0 (not our signal)\" \"$(a)\" \"2\"\n# 6 loopback dup ignored\nprintf ''aa:bb:cc:00:00:01 127.0.0.1 1\\ncc:dd:ee:00:00:02 127.0.0.1 2\\n'' > /tmp/arpT2/lo.dat; run 6 /tmp/arpT2/lo.dat\nchk \"loopback spoof ignored\" \"$(a)\" \"2\"\n# 7 hostname field\nprintf ''aa:bb:cc:00:00:0b 10.6.0.1 1 hostA\\ncc:dd:ee:00:00:0c 10.6.0.1 2 hostB\\n'' > /tmp/arpT2/hn.dat; run 7 /tmp/arpT2/hn.dat\nchk \"hostname field ok\" \"$(a)\" \"3\"\n# 8 empty\n: > /tmp/arpT2/empty.dat; run 8 /tmp/arpT2/empty.dat; chk \"empty no crash\" \"$?\" \"0\"\n# 9 missing\nrun 9 /tmp/arpT2/nope.dat; chk \"missing no crash\" \"$?\" \"0\"\n# 10 real-world scale\npython3 -c \"\nimport random\nrandom.seed(7)\nwith open(''/tmp/arpT2/big.dat'',''w'') as f:\n    for i in range(5000):\n        f.write(''%012x 10.%d.%d.%d %d\\n'' % (random.getrandbits(48), random.randint(0,255), random.randint(0,255), random.randint(1,254), 1758000000+i))\n\"\nt0=$(date +%s%N); run 10 /tmp/arpT2/big.dat; t1=$(date +%s%N)\nchk \"5000 entries, no crash\" \"$?\" \"0\"\necho \"        (scan of 5000 rows took $(( (t1-t0)/1000000 ))ms)\"\necho; echo \"  $pass passed, $fail failed\""},"time":{"start":1790457239419}}},"time":1790457239419}');
