INSERT INTO event VALUES('evt_0df917a83001dKiAMvyYPmtZHl','ses_f20e5cfc2ffeSFa4odnoYLiUOk',4267,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df9176450010aRLy0zucgBJgU","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df915984001BPwkqLhgysucR4","type":"tool","callID":"call_function_5znlrwq9fbr9_1","tool":"bash","state":{"status":"running","input":{"command":"printf ''aa:bb:cc:00:00:0b 10.3.0.1 1758000000\\ncc:dd:ee:00:00:0c 10.3.0.1 1758000001\\n'' > /tmp/dbg.dat\necho \"=== input ===\"; cat /tmp/dbg.dat\necho; echo \"=== my awk, isolated ===\"\nawk ''NF >= 2 {\n        ip = $2\n        mac = tolower($1)\n        if (!(ip in seen)) { seen[ip] = mac; order[ip] = 1; next }\n        n = split(seen[ip], arr, \" \")\n        for (i = 1; i <= n; i++) if (arr[i] == mac) next\n        seen[ip] = seen[ip] \" \" mac\n     }\n     END {\n        for (ip in order) {\n            n = split(seen[ip], arr, \" \")\n            if (n < 2) continue\n            s = arr[1]\n            for (i = 2; i <= n; i++) s = s \",\" arr[i]\n            print ip \" \" s\n        }\n     }'' /tmp/dbg.dat\necho \"  (empty above = the bug)\"\necho; echo \"=== awk version ===\"; awk --version 2>&1 | head -1 || echo \"  mawk/gawk unknown\""},"time":{"start":1790457248387}}},"time":1790457248387}');
