INSERT INTO event VALUES('evt_0df91ea090010qwftEooKABWIB','ses_f20e5cfc2ffeSFa4odnoYLiUOk',4331,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df91df11001g8ZSd3ycoXjrfP","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df91cdf0001Mrm4Q249hI5vMS","type":"tool","callID":"call_function_tdb6melbd7uf_1","tool":"bash","state":{"status":"running","input":{"command":"cd /tmp/at\nexport BDE_ARPWATCH_LOG=/tmp/at/scan.log BDE_ALERT=/tmp/at/count.py\nS=/home/livings/Projects/zen-hardening/arpwatch-spoof-scan.sh\nprintf ''aa:bb:cc:00:00:0b 10.3.0.1 1\\ncc:dd:ee:00:00:0c 10.3.0.1 2\\n'' > d1.dat\nrm -f /tmp/at/dst; : > /tmp/at/alerts.log\necho \"=== scan A (fresh state) -> expect 1 alert ===\"\nBDE_ARP_DATAFILE=/tmp/at/d1.dat BDE_ARP_STATE=/tmp/at/dst \"$S\" >/dev/null 2>&1\necho \"  alerts=$(wc -l < alerts.log)\"\necho \"  state: $(cat dst)\"\necho \"=== scan B (same data, state kept) -> expect 0 new ===\"\nBDE_ARP_DATAFILE=/tmp/at/d1.dat BDE_ARP_STATE=/tmp/at/dst \"$S\" >/dev/null 2>&1\necho \"  alerts=$(wc -l < alerts.log)  <- unchanged means dedup works\"\necho \"=== scan C (a THIRD mac appears) -> expect 1 new ===\"\nprintf ''11:22:33:00:00:03 10.3.0.1 3\\n'' >> d1.dat\nBDE_ARP_DATAFILE=/tmp/at/d1.dat BDE_ARP_STATE=/tmp/at/dst \"$S\" >/dev/null 2>&1\necho \"  alerts=$(wc -l < alerts.log)\"\ntail -1 alerts.log | python3 -c ''import json,sys;print(\"  new:\",json.load(sys.stdin)[\"events\"][0][\"label\"])''\necho \"=== scan D (spoof RESOLVED, mac removed) -> expect 0, state cleared ===\"\nprintf ''aa:bb:cc:00:00:0b 10.3.0.1 1\\n'' > d1.dat\nBDE_ARP_DATAFILE=/tmp/at/d1.dat BDE_ARP_STATE=/tmp/at/dst \"$S\" >/dev/null 2>&1\necho \"  alerts=$(wc -l < alerts.log)  (no new)\"\necho \"  state now: ''$(cat dst)''  <- empty, so it re-alerts if it returns\""},"time":{"start":1790457276937}}},"time":1790457276937}');
INSERT INTO event VALUES('evt_0df91ea0b001hAWKshCilFksPY','ses_f20e5cfc2ffeSFa4odnoYLiUOk',4332,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df91dde1001A3V2iUCg61eU52","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df91cdf0001Mrm4Q249hI5vMS","type":"text","text":"That last failure is my harness again — `run()` deletes the state file first, so dedup can''t possibly work. Let me test dedup without wiping state:","time":{"start":1790457273825,"end":1790457276939}},"time":1790457276939}');
