INSERT INTO event VALUES('evt_0df91ff15001mmMxYTrhbxYG7V','ses_f20e5cfc2ffeSFa4odnoYLiUOk',4356,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df91faac001u0xUT3o297IORL","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df91eb6a001KgVSmKlQ1sIyXt","type":"text","text":"Dedup works (A=1, B=1, C=2, D=2). But scan D exposed a flaw: when anomalies clear, the script exits before updating state, leaving stale data. Let me fix:","time":{"start":1790457281196,"end":1790457282325}},"time":1790457282325}');
