INSERT INTO event VALUES('evt_0df9265d8001m7U0fSHAQFTyDd','ses_f211dfcd4ffevS1Yoddwab036g',10054,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0df9265d5002aQS0oANSBSubm5","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0df9265d5001eCbLaNKNuA7OG6","type":"text","text":"sudo bash /home/livings/Projects/zen-hardening/install-audit-readonly.sh\n[sudo] password for livings:\n[ok] installed 7 read-only helpers\n/etc/sudoers.d/audit-readonly:9:242: syntax error\nlivings ALL=(root) NOPASSWD: /usr/local/sbin/audit-nft, /usr/local/sbin/audit-btrfs, /usr/local/sbin/audit-smart, /usr/local/sbin/audit-dmesg, /usr/local/sbin/audit-firewall, /usr/local/sbin/audit-fail2ban, /usr/local/sbin/audit-journal-err,\n^\n[!!] sudoers INVALID -- removing to avoid a broken sudo\n/etc/sudoers.d/editor: bad permissions, should be mode 0440\n/etc/sudoers.d/insults: bad permissions, should be mode 0440\n/etc/sudoers.d/opencode: bad permissions, should be mode 0440\n/etc/sudoers.d/pwfeedback: bad permissions, should be mode 0440\n/etc/sudoers: parsed OK\n/etc/sudoers.d/10-installer: parsed OK "},"time":1790457308632}');
