INSERT INTO event VALUES('evt_0df946e2c001149UEwXAJyXyxZ','ses_f20e5cfc2ffeSFa4odnoYLiUOk',4530,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df94637b0010TgP5HF6oHJlyk","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df945822001nDRJ2oKsVOIcqI","type":"reasoning","text":"Confirmed: `-q` is the ONLY letter from the man page synopsis that is rejected. It''s a documentation bug in arpwatch 3.9''s man page.\n\nSo I need to remove `-q` from the unit. Let me verify the corrected command parses and gets to the socket stage.\n\nLet me test the full command without -q as non-root — it should parse and then fail on the raw socket (permission), which proves parsing is fine.\n\nLet me verify.\n\nThen decide: without -q, arpwatch logs reports to syslog. Since -s suppresses email and we do our own detection, the syslog reports are just extra noise in the journal. Options:\n- Accept the syslog noise\n- Use `-d` which sends reports to stderr instead of syslog (and inhibits forking). Combined with -F... -d inhibits forking into background, sends reports to stderr. That would put them in the journal. Not obviously better.\n- Just accept it. arpwatch reports are actually useful (they include \"flip flop\" messages!).\n\nActually — the syslog reports are VALUABLE. arpwatch''s own \"flip flop\" detection is authoritative. Since 3.9 can''t exec a hook, we could ALSO parse its syslog output. But my datafile scanner already covers it.\n\nLet me keep it simple: remove -q, accept syslog reports (they go to the journal, which is fine and gives an audit trail).\n\nLet me verify the corrected invocation and update the unit.","time":{"start":1790457439099,"end":1790457441836}},"time":1790457441836}');
