INSERT INTO event VALUES('evt_0df96c0b5001VSPm5wXLRsrBqe','ses_f20e5cfc2ffeSFa4odnoYLiUOk',4676,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0df96bc3f001nYhTw1C5mZSqKQ","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0df9698ff0014pDaigHBeJqYCs","type":"tool","callID":"call_function_edrdjxe49z38_1","tool":"bash","state":{"status":"running","input":{"command":"echo \"=== is arpwatch running right now (foreground, from the parse-check)? ===\"\npgrep -a arpwatch 2>/dev/null | sed ''s/^/  /'' || echo \"  none\"\necho; echo \"=== the service state ===\"\nsystemctl is-active arpwatch-spoof 2>/dev/null | sed ''s/^/  arpwatch-spoof: /''\necho; echo \"=== proof: as ROOT, the parse-check actually starts arpwatch and never returns ===\"\ntimeout 3 /usr/sbin/arpwatch -F -i wlo1 -f /tmp/probe.dat -s -N -z; rc=$?\necho \"  exit=$rc  ($([ $rc = 124 ] && echo ''124 = TIMED OUT, i.e. it was running happily'' || echo \"exited $rc\"))\""},"metadata":{"output":""},"time":{"start":1790457594037}}},"time":1790457594037}');
