INSERT INTO event VALUES('evt_0dfa15388001m72uXS6zGBIA67','ses_f211dfcd4ffevS1Yoddwab036g',10391,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0dfa15052001HeWyL1sApul6xU","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0dfa12dee0012LFgwb7Fk4W3aH","type":"tool","callID":"call_function_j0lct1yjvzkv_1","tool":"bash","state":{"status":"running","input":{"command":"echo \"═══ is PID 287282 owned by systemd, or a stray? ═══\"\ncat /proc/287282/cgroup 2>/dev/null | sed ''s/^/  /''\necho\necho \"  if the path contains ''systemd/user'' -> systemd owns it (good)\"\necho \"  if it shows the session scope or a bare user.slice -> stray process\"\necho\necho \"  ppid 1185 is: $(ps -o comm= -p 1185 2>/dev/null)\""},"time":{"start":1790458286984}}},"time":1790458286984}');
