INSERT INTO event VALUES('evt_0dfa3238e001n1piyrzRYN8rpb','ses_f211dfcd4ffevS1Yoddwab036g',10451,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0dfa319d5001g0tdfRvn7aQ5Q8","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0dfa3023d001iYEVtlrxRQY6FR","type":"text","text":"One more of my own bugs: `recidive in source: as` is nonsense. My ad-hoc `awk` matched a *comment* (\"ENABLED as of 2026-09-26...\") rather than the setting. `bootstrap.sh` uses a stricter pattern requiring `=`, so it''s unaffected — but let me confirm:","time":{"start":1790458403285,"end":1790458405774}},"time":1790458405774}');
