INSERT INTO event VALUES('evt_0dfa3385d001eCSPJHnEOI1fgG','ses_f20e5cfc2ffeSFa4odnoYLiUOk',5090,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0dfa337ee001SXv7cK27iJvOKa","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0dfa2dae9001HszYNa707HN9rP","type":"tool","callID":"call_function_t3k7fpo5mmsf_1","tool":"bash","state":{"status":"running","input":{"command":"man arpwatch 2>/dev/null | col -bx | sed -n ''120,150p''"},"metadata":{"output":"\n     suppressed DECnet flip flop\n          A \"flip flop\" report was suppressed because one of the two  addresses\n          was a DECnet address.\n\nSIGNALS\n     Normally  arpwatch updates arp.dat once every 15 minutes.  The SIGHUP sig‐\n     nal causes it to update immediately.\n\nFILES\n     /usr/local/arpwatch  default directory\n     arp.dat              default ethernet/ip address database\n     ethercodes.dat       vendor ethernet block list\n\nSEE ALSO\n     arpsnmp(8), arp(8), bpf(4), tcpdump(1), pcapture(1), pcap(3)\n\nAUTHORS\n     Craig Leres of the Lawrence Berkeley National Laboratory Network  Research\n     Group, University of California, Berkeley, CA.\n\n     The current version is available via anonymous ftp:\n\n           ftp://ftp.ee.lbl.gov/arpwatch.tar.gz\n\nBUGS\n     Please send bug reports to ⟨arpwatch@ee.lbl.gov⟩.\n\n     Attempts  are  made  to  suppress DECnet flip flops but they aren''t always\n     successful.\n\n"},"time":{"start":1790458411007}}},"time":1790458411101}');
