INSERT INTO event VALUES('evt_0dfa3f0ba001KsNPe1XFG4DtQj','ses_f20e5cfc2ffeSFa4odnoYLiUOk',5227,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0dfa3f0ba001tO92vN4ZttMxD3","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0dfa3ea32001Ru6b08na84vI1f","type":"step-start"},"time":1790458458298}');
