INSERT INTO event VALUES('evt_0dfa802670011rLpWFtKB1hQJH','ses_f20e5cfc2ffeSFa4odnoYLiUOk',5317,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0dfa7ff24001OW1ZC0PKzreTdO","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0dfa7bdd90010TEEcYwzp6BIzM","type":"tool","callID":"call_function_2xs33fz54bhw_1","tool":"bash","state":{"status":"running","input":{"command":"echo \"=== /etc/security/faillock.conf (what pam_faillock.so reads) ===\"\nif [ -r /etc/security/faillock.conf ]; then grep -vE ''^\\s*#|^\\s*$'' /etc/security/faillock.conf | sed ''s/^/  /''; echo \"  --- (uncommented lines above) ---\"; else echo \"  NOT READABLE\"; fi\necho\necho \"=== full pam_faillock stanza with all args ===\"\nsed -n ''1,15p'' /etc/pam.d/system-auth | grep -n \"faillock\" | sed ''s/^/  /''\necho\necho \"=== sddm-autologin also has it? ===\"\ngrep -n \"faillock\" /etc/pam.d/sddm-autologin 2>/dev/null | sed ''s/^/  /''"},"metadata":{"output":"=== /etc/security/faillock.conf (what pam_faillock.so reads) ===\n  deny = 10\n  unlock_time = 30\n  audit = silent\n  --- (uncommented lines above) ---\n\n=== full pam_faillock stanza with all args ===\n  3:auth       required                    pam_faillock.so      preauth\n  8:auth       [default=die]               pam_faillock.so      authfail\n  11:auth       required                    pam_faillock.so      authsucc\n  12:# If you drop the above call to pam_faillock.so the lock will be done also\n\n=== sddm-autologin also has it? ===\n"},"time":{"start":1790458724956}}},"time":1790458724967}');
