INSERT INTO event VALUES('evt_0dfacbea6001zlj4nO6HMOY5uC','ses_f211dfcd4ffevS1Yoddwab036g',10910,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0dfacbea40023BqGGcS5Z6xBXx","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0dfacbea4001Rw94IO9Lm8KeEW","type":"text","text":"sudo -l | tail -3\nsudo audit-nft\nUser livings may run the following commands on zero:\n(ALL) ALL\n(root) NOPASSWD: /usr/local/sbin/audit-nft, /usr/local/sbin/audit-btrfs, /usr/local/sbin/audit-smart, /usr/local/sbin/audit-dmesg, /usr/local/sbin/audit-firewall, /usr/local/sbin/audit-fail2ban, /usr/local/sbin/audit-journal-err\n== firewalld tables ==\ntable inet firewalld\n\n== filter_INPUT chain ==\ntable inet firewalld {\nchain filter_INPUT {\ntype filter hook input priority filter + 10; policy accept;\nct state { established, related } accept\nct status dnat accept\niifname \"lo\" accept\nct state invalid drop\njump filter_INPUT_dispatch\nreject with icmpx admin-prohibited\n}\n}\n\n== reject/drop policy in filter_INPUT ==\ntype filter hook input priority filter + 10; policy accept;\nct state invalid drop\nreject with icmpx admin-prohibited  was the output"},"time":1790459035302}');
