INSERT INTO event VALUES('evt_0dfad0395001A2aB4Uf8LGo8pW','ses_f211dfcd4ffevS1Yoddwab036g',10942,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0dface32a001oifg0BA59ACGu6","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0dfacd56f001Cv6utuDcgG5i6F","type":"text","text":"Sudo fully restored: `(ALL) ALL` with password, plus NOPASSWD for the 7 helpers. `audit-nft` confirms enforcement.\n\nAnd the `arpwatch` warning turns out to be cosmetic — the unit sets `WorkingDirectory=/var/lib/arpwatch` and `-f /var/lib/arpwatch/arp.dat`, so the failed `chdir` to its compiled-in default just falls through to the intended directory. Confirming, then final verification:","time":{"start":1790459044650,"end":1790459052949}},"time":1790459052949}');
