INSERT INTO event VALUES('evt_0dfafff94001kIKk3iL1EdY6DB','ses_f20e5cfc2ffeSFa4odnoYLiUOk',5513,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0dfafef29001RM11JhzwPaIlj7","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0dfafe758001ucDwSjS1Hq0c1D","type":"tool","callID":"call_function_qxd1xbdve7uj_1","tool":"bash","state":{"status":"running","input":{"command":"rm -rf /tmp/w && mkdir -p /tmp/w\ncat > /tmp/w/alert.py <<''PY''\nimport sys\nopen(\"/tmp/w/alerts.log\",\"a\").write(sys.argv[1]+\"\\n\")\nPY\ncd ~/Projects/zen-hardening\nNOW=$(date +%s); OLD=$((NOW - 7200))\nS=./arpwatch-spoof-scan.sh\nrun(){ BDE_ARP_NOW=$NOW BDE_SPOOF_NOW=$NOW BDE_ARP_DATAFILE=\"$1\" BDE_ARP_STATE=\"/tmp/w/st\" \\\n      BDE_ARPWATCH_LOG=/tmp/w/scan.log BDE_ALERT=/tmp/w/alert.py \"$S\" >/dev/null 2>&1; }\nal(){ wc -l < /tmp/w/alerts.log 2>/dev/null | tr -d '' '' || echo 0; }\n\n# THE BUG: laptop A yesterday, laptop B today = ordinary DHCP reassignment\nprintf ''aa:bb:cc:00:00:01 10.1.0.100 %s\\ncc:dd:ee:00:00:02 10.1.0.100 %s\\n'' \"$OLD\" \"$NOW\" > /tmp/w/dhcp.dat\nrm -f /tmp/w/st /tmp/w/alerts.log; run /tmp/w/dhcp.dat\necho \"  DHCP reassignment (old MAC yesterday, new MAC now): $(al) alerts  <- must be 0\"\ngrep -o \"no anomalies\" /tmp/w/scan.log | tail -1 | sed ''s/^/    /''\n\n# REAL spoof: two MACs both seen inside the window\nprintf ''aa:bb:cc:00:00:01 10.2.0.50 %s\\ncc:dd:ee:00:00:02 10.2.0.50 %s\\n'' \"$NOW\" \"$NOW\" > /tmp/w/spoof.dat\nrm -f /tmp/w/st /tmp/w/alerts.log; run /tmp/w/spoof.dat\necho \"  live spoof (both MACs in window):                    $(al) alerts  <- must be 1\"\n\n# both old -> ages out entirely\nprintf ''aa:bb:cc:00:00:01 10.3.0.50 %s\\ncc:dd:ee:00:00:02 10.3.0.50 %s\\n'' \"$OLD\" \"$OLD\" > /tmp/w/old.dat\nrm -f /tmp/w/st /tmp/w/alerts.log; run /tmp/w/old.dat\necho \"  two old MACs (outside window):                      $(al) alerts  <- must be 0\"\n\n# window boundary: one just inside, one just outside\nprintf ''aa:bb:cc:00:00:01 10.4.0.50 %s\\ncc:dd:ee:00:00:02 10.4.0.50 %s\\n'' $((NOW-3599)) $((NOW-3601)) > /tmp/w/edge.dat\nrm -f /tmp/w/st /tmp/w/alerts.log; run /tmp/w/edge.dat\necho \"  boundary 3599s in / 3601s out:                      $(al) alerts  <- must be 0\""},"time":{"start":1790459248531}}},"time":1790459248532}');
INSERT INTO event VALUES('evt_0dfafff95001q4pczzR58cKPJp','ses_f20e5cfc2ffeSFa4odnoYLiUOk',5514,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0dfafee620012Js3Wo8xRpJlQ2","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0dfafe758001ucDwSjS1Hq0c1D","type":"text","text":"Now let me test the window fix against the exact DHCP-reassignment scenario that was broken:","time":{"start":1790459244130,"end":1790459248533}},"time":1790459248533}');
INSERT INTO event VALUES('evt_0dfafff99001ZjrpaIn9gINkaO','ses_f20e5cfc2ffeSFa4odnoYLiUOk',5515,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0dfafef29001RM11JhzwPaIlj7","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0dfafe758001ucDwSjS1Hq0c1D","type":"tool","callID":"call_function_qxd1xbdve7uj_1","tool":"bash","state":{"status":"running","input":{"command":"rm -rf /tmp/w && mkdir -p /tmp/w\ncat > /tmp/w/alert.py <<''PY''\nimport sys\nopen(\"/tmp/w/alerts.log\",\"a\").write(sys.argv[1]+\"\\n\")\nPY\ncd ~/Projects/zen-hardening\nNOW=$(date +%s); OLD=$((NOW - 7200))\nS=./arpwatch-spoof-scan.sh\nrun(){ BDE_ARP_NOW=$NOW BDE_SPOOF_NOW=$NOW BDE_ARP_DATAFILE=\"$1\" BDE_ARP_STATE=\"/tmp/w/st\" \\\n      BDE_ARPWATCH_LOG=/tmp/w/scan.log BDE_ALERT=/tmp/w/alert.py \"$S\" >/dev/null 2>&1; }\nal(){ wc -l < /tmp/w/alerts.log 2>/dev/null | tr -d '' '' || echo 0; }\n\n# THE BUG: laptop A yesterday, laptop B today = ordinary DHCP reassignment\nprintf ''aa:bb:cc:00:00:01 10.1.0.100 %s\\ncc:dd:ee:00:00:02 10.1.0.100 %s\\n'' \"$OLD\" \"$NOW\" > /tmp/w/dhcp.dat\nrm -f /tmp/w/st /tmp/w/alerts.log; run /tmp/w/dhcp.dat\necho \"  DHCP reassignment (old MAC yesterday, new MAC now): $(al) alerts  <- must be 0\"\ngrep -o \"no anomalies\" /tmp/w/scan.log | tail -1 | sed ''s/^/    /''\n\n# REAL spoof: two MACs both seen inside the window\nprintf ''aa:bb:cc:00:00:01 10.2.0.50 %s\\ncc:dd:ee:00:00:02 10.2.0.50 %s\\n'' \"$NOW\" \"$NOW\" > /tmp/w/spoof.dat\nrm -f /tmp/w/st /tmp/w/alerts.log; run /tmp/w/spoof.dat\necho \"  live spoof (both MACs in window):                    $(al) alerts  <- must be 1\"\n\n# both old -> ages out entirely\nprintf ''aa:bb:cc:00:00:01 10.3.0.50 %s\\ncc:dd:ee:00:00:02 10.3.0.50 %s\\n'' \"$OLD\" \"$OLD\" > /tmp/w/old.dat\nrm -f /tmp/w/st /tmp/w/alerts.log; run /tmp/w/old.dat\necho \"  two old MACs (outside window):                      $(al) alerts  <- must be 0\"\n\n# window boundary: one just inside, one just outside\nprintf ''aa:bb:cc:00:00:01 10.4.0.50 %s\\ncc:dd:ee:00:00:02 10.4.0.50 %s\\n'' $((NOW-3599)) $((NOW-3601)) > /tmp/w/edge.dat\nrm -f /tmp/w/st /tmp/w/alerts.log; run /tmp/w/edge.dat\necho \"  boundary 3599s in / 3601s out:                      $(al) alerts  <- must be 0\""},"metadata":{"output":""},"time":{"start":1790459248531}}},"time":1790459248537}');
