side\nprintf ''aa:bb:cc:00:00:01 10.4.0.50 %s\\ncc:dd:ee:00:00:02 10.4.0.50 %s\\n'' $((NOW-3599)) $((NOW-3601)) > /tmp/w/edge.dat\nrm -f /tmp/w/st /tmp/w/alerts.log; run /tmp/w/edge.dat\necho \"  boundary 3599s in / 3601s out:                      $(al) alerts  <- must be 0\""},"metadata":{"output":"/usr/bin/bash: line 11: /tmp/w/alerts.log: No such file or directory\n"},"time":{"start":1790459248531}}},"time":1790459248551}');
