INSERT INTO event VALUES('evt_0dfb012c30012zJ3lvG1TZhwRw','ses_f20e5cfc2ffeSFa4odnoYLiUOk',5532,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0dfb005db001AUE2twZbqoc670","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0dfb000460016wUb2mP4nl2paB","type":"reasoning","text":"The window fix works:\n- DHCP reassignment → 0 alerts (was 1 before the fix) ✓\n- Live spoof → 1 alert ✓\n- Two old MACs → 0 ✓\n- Boundary → 0 ✓ (3599 in window, 3601 outside → only 1 MAC in window → no anomaly) ✓\n\nThe \"No such file\" messages are just my `al()` helper when alerts.log doesn''t exist (zero alerts). Cosmetic in my harness.\n\nLet me verify the boundary more precisely: with 3599 in-window and 3601 out-of-window, only 1 MAC in window → not an anomaly → 0 alerts. Correct.\n\nNow let me re-run the FULL original test suite to make sure I didn''t break anything, adapted with timestamps.\n\nLet me rewrite the complete suite properly with timestamps and the alert-count helper fixed.\n\nThen fix the remaining bugs:\n- ignored entries in state (already fixed as part of the restructure — let me TEST it)\n- installer temp dir leak\n- /run/user/1000 hardcoding\n\nLet me write a comprehensive suite.\n\nLet me test the \"ignored then un-ignored\" scenario:\n1. Run with BDE_SPOOF_IGNORE covering the IP → 0 alerts, state should NOT contain it\n2. Run without ignore → 1 alert (this is the fix; before, it would be \"persists\" → 0)\n\nLet me test that.\n\nLet me write the full suite.","time":{"start":1790459250139,"end":1790459253443}},"time":1790459253443}');
