INSERT INTO event VALUES('evt_0dfb0d5fb001EImeqTZV8PGJeW','ses_f211dfcd4ffevS1Yoddwab036g',11118,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0dfb0a7f7001yjzdXprZF0F00T","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0dfb0967e001ErYQIG5csm2qbR","type":"tool","callID":"call_function_o6i419v3k0h5_1","tool":"write","state":{"status":"running","input":{"content":"# hermes-security-scripts\n\nVerified security baseline for this machine, consolidated from several local\nprojects. Everything here was applied to a live Garuda/Arch install and checked\nagainst runtime state on 2026-09-26.\n\n## What \"verified\" means here\n\nEvery claim in this repo is meant to be checkable against the running system,\nnot against the file contents. That distinction came from experience: several\nsettings in this project were accepted without complaint, reported success, and\ndid something other than what was asked for. Examples that are now regression\ntests in the scripts:\n\n- `802-11-wireless.mac-address-mode` does not exist in NetworkManager 1.58, so\n  `nmcli` errored and the script aborted while having already printed `[ok]`.\n- `802-11-wireless.mac-address-randomization` is a flags enum, not a boolean.\n  `1` means **NEVER**, not yes, so setting it disabled randomization.\n- A `workstation` zone with no ports does not block anything, because firewalld\n  *merges* same-name zones rather than replacing them. A file-based override\n  cannot empty the allowlist.\n- `firewall-cmd --state` reports `running` even while enforcing nothing. The\n  real check is that `table inet firewalld` exists and the input chain\n  terminates in a reject.\n- `systemctl is-active fail2ban` returns 0 before jails register. Readiness has\n  to be measured on the jail list.\n- In `sudo` 1.9.17, `\"\"` after a command path means \"exactly one empty\n  argument\", not \"no arguments\". A rule using it parses cleanly and can never\n  match a real invocation.\n- Whole-tree `visudo -c` exits non-zero for unrelated pre-existing warnings, so\n  gating on it can delete a perfectly valid drop-in.\n\nSo: verify behaviour, not configuration. If a script here prints `[ok]`, treat\nthat as evidence of nothing until an independent check confirms the runtime\nvalue.\n\n## Layout\n\n    config/zen-hardening/\n        bootstrap.sh                  reapply the whole baseline (--check previews)\n        workstation.xml               strict firewalld zone, empty allowlist\n        shield-kitty-fail2ban.local   fail2ban source; recidive bootstrap\n        set-anon-identity.sh          hostname + per-network random MAC\n        set-home-trusted-zone.sh      deferred secure-home profile\n        apply-firewall.sh             idempotent firewall installer\n        unban-self.sh                 root-gated self-ban escape hatch\n        RECOVER-SUDO.sh               non-destructive sudo recovery\n        install-audit-readonly.sh     scoped read-only root helpers\n        install-shield-kitty-units.sh user units + linger, survives reboot\n        fix-sudoers-permissions.sh    classify-then-repair sudoers modes\n        99-hardening.conf             sysctl baseline\n        faillock.conf, install-faillock-admin.sh, enroll-admin.sh\n    scripts/shield-kitty/\n        shield-kitty-watch.py         journal intrusion watcher\n        shield-kitty-alert.py         desktop notifications\n        device-blacklist/             udev quarantine (not installed; needs root)\n\n## Relationship to lifsea-security-suite\n\n`~/Projects/lifsea-security-suite` is a second consolidation created during the\nsame session. It **imports** `buildlog`, `zen-hardening`, `shield-kitty` and\n`shield-kitty-forensics` as subdirectories.\n\nThat means the same content now exists in two places with no automated\nrelationship, and they will drift. Specifically:\n\n- This repo is the one wired to the live system. `bootstrap.sh` and\n  `apply-firewall.sh` are what were run against real firewalld and fail2ban.\n- `lifsea-security-suite` is a newer import whose `zen-hardening` copy was taken\n  at upstream `b39490a`. It does not contain the later fixes committed here\n  (recover script, sudoers classifier correction, audit wrapper fixes).\n\nUntil one is declared canonical, treat changes here as needing to be mirrored\nmanually. Pick one and record the decision in both READMEs rather than leaving\nit implicit.\n\n## Not covered, deliberately\n\n- **SDDM greeter brute force.** `pam-generic` needs `rhost=<IP>`; a local\n  console has no IP, so there is no automated IP-ban mechanism. Mitigation is\n  authentication strength, lid-closed lock, and screen-lock timeout.\n- **`machine-id` and DMI strings.** Not changed. `machine-id` is unique, and\n  making it ephemeral breaks services that bind to it. Renaming the host does\n  not anonymise these.\n- **Anonymous browsing.** The `tor` daemon runs on `127.0.0.1:9050` with no\n  client. That is not anonymity. `torbrowser-launcher` is the correct tool and\n  runs its own independent Tor instance; do not point a normal persistent\n  browser at the system SOCKS port.\n- **Ethernet MACs.** Only Wi-Fi is randomised. Wired MACs need a separate\n  decision.\n","filePath":"/tmp/opencode/hss/README.md"},"time":{"start":1790459303418}}},"time":1790459303419}');
INSERT INTO event VALUES('evt_0dfb0d5fd0012dI1U2qkgN17sm','ses_f211dfcd4ffevS1Yoddwab036g',11119,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0dfb0a67b001kQ8NK2fQ5a9N6p","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0dfb0967e001ErYQIG5csm2qbR","type":"text","text":"`lifsea` was committed 62s ago — still active, so I won''t touch it. I''ll document the relationship in `hermes-security-scripts` (quiet for 263s) and flag the mirror note for later.","time":{"start":1790459291259,"end":1790459303421}},"time":1790459303421}');
INSERT INTO event VALUES('evt_0dfb0d601001Z4Jf1on754QJYp','ses_f211dfcd4ffevS1Yoddwab036g',11120,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0dfb0a7f7001yjzdXprZF0F00T","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0dfb0967e001ErYQIG5csm2qbR","type":"tool","callID":"call_function_o6i419v3k0h5_1","tool":"write","state":{"status":"completed","input":{"content":"# hermes-security-scripts\n\nVerified security baseline for this machine, consolidated from several local\nprojects. Everything here was applied to a live Garuda/Arch install and checked\nagainst runtime state on 2026-09-26.\n\n## What \"verified\" means here\n\nEvery claim in this repo is meant to be checkable against the running system,\nnot against the file contents. That distinction came from experience: several\nsettings in this project were accepted without complaint, reported success, and\ndid something other than what was asked for. Examples that are now regression\ntests in the scripts:\n\n- `802-11-wireless.mac-address-mode` does not exist in NetworkManager 1.58, so\n  `nmcli` errored and the script aborted while having already printed `[ok]`.\n- `802-11-wireless.mac-address-randomization` is a flags enum, not a boolean.\n  `1` means **NEVER**, not yes, so setting it disabled randomization.\n- A `workstation` zone with no ports does not block anything, because firewalld\n  *merges* same-name zones rather than replacing them. A file-based override\n  cannot empty the allowlist.\n- `firewall-cmd --state` reports `running` even while enforcing nothing. The\n  real check is that `table inet firewalld` exists and the input chain\n  terminates in a reject.\n- `systemctl is-active fail2ban` returns 0 before jails register. Readiness has\n  to be measured on the jail list.\n- In `sudo` 1.9.17, `\"\"` after a command path means \"exactly one empty\n  argument\", not \"no arguments\". A rule using it parses cleanly and can never\n  match a real invocation.\n- Whole-tree `visudo -c` exits non-zero for unrelated pre-existing warnings, so\n  gating on it can delete a perfectly valid drop-in.\n\nSo: verify behaviour, not configuration. If a script here prints `[ok]`, treat\nthat as evidence of nothing until an independent check confirms the runtime\nvalue.\n\n## Layout\n\n    config/zen-hardening/\n        bootstrap.sh                  reapply the whole baseline (--check previews)\n        workstation.xml               strict firewalld zone, empty allowlist\n        shield-kitty-fail2ban.local   fail2ban source; recidive bootstrap\n        set-anon-identity.sh          hostname + per-network random MAC\n        set-home-trusted-zone.sh      deferred secure-home profile\n        apply-firewall.sh             idempotent firewall installer\n        unban-self.sh                 root-gated self-ban escape hatch\n        RECOVER-SUDO.sh               non-destructive sudo recovery\n        install-audit-readonly.sh     scoped read-only root helpers\n        install-shield-kitty-units.sh user units + linger, survives reboot\n        fix-sudoers-permissions.sh    classify-then-repair sudoers modes\n        99-hardening.conf             sysctl baseline\n        faillock.conf, install-faillock-admin.sh, enroll-admin.sh\n    scripts/shield-kitty/\n        shield-kitty-watch.py         journal intrusion watcher\n        shield-kitty-alert.py         desktop notifications\n        device-blacklist/             udev quarantine (not installed; needs root)\n\n## Relationship to lifsea-security-suite\n\n`~/Projects/lifsea-security-suite` is a second consolidation created during the\nsame session. It **imports** `buildlog`, `zen-hardening`, `shield-kitty` and\n`shield-kitty-forensics` as subdirectories.\n\nThat means the same content now exists in two places with no automated\nrelationship, and they will drift. Specifically:\n\n- This repo is the one wired to the live system. `bootstrap.sh` and\n  `apply-firewall.sh` are what were run against real firewalld and fail2ban.\n- `lifsea-security-suite` is a newer import whose `zen-hardening` copy was taken\n  at upstream `b39490a`. It does not contain the later fixes committed here\n  (recover script, sudoers classifier correction, audit wrapper fixes).\n\nUntil one is declared canonical, treat changes here as needing to be mirrored\nmanually. Pick one and record the decision in both READMEs rather than leaving\nit implicit.\n\n## Not covered, deliberately\n\n- **SDDM greeter brute force.** `pam-generic` needs `rhost=<IP>`; a local\n  console has no IP, so there is no automated IP-ban mechanism. Mitigation is\n  authentication strength, lid-closed lock, and screen-lock timeout.\n- **`machine-id` and DMI strings.** Not changed. `machine-id` is unique, and\n  making it ephemeral breaks services that bind to it. Renaming the host does\n  not anonymise these.\n- **Anonymous browsing.** The `tor` daemon runs on `127.0.0.1:9050` with no\n  client. That is not anonymity. `torbrowser-launcher` is the correct tool and\n  runs its own independent Tor instance; do not point a normal persistent\n  browser at the system SOCKS port.\n- **Ethernet MACs.** Only Wi-Fi is randomised. Wired MACs need a separate\n  decision.\n","filePath":"/tmp/opencode/hss/README.md"},"output":"Wrote file successfully.","title":"tmp/opencode/hss/README.md","metadata":{"diagnostics":{},"filepath":"/tmp/opencode/hss/README.md","exists":false,"truncated":false},"time":{"start":1790459303418,"end":1790459303425}}},"time":1790459303425}');
