INSERT INTO event VALUES('evt_0dfb0e468001o2JFgvgC623gS1','ses_f20e5cfc2ffeSFa4odnoYLiUOk',5720,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0dfb0de5e001wClWwtxINQr7YL","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0dfb0cee90013ufRk6nM9kvR49","type":"text","text":"Delivery is only logged on output *or* failure — so a successful send is indistinguishable from a silent no-op. Given this session''s theme, let me close that gap by testing the notifier directly:","time":{"start":1790459305566,"end":1790459307112}},"time":1790459307112}');
