INSERT INTO event VALUES('evt_0dfb1339f001Z6FZ4QFAdKObEE','ses_f20e5cfc2ffeSFa4odnoYLiUOk',5783,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0dfb12d2e001mSukwXzQDor68D","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0dfb123620019kZ3HFr8MKoKKs","type":"tool","callID":"call_function_ufeec38r6rj2_1","tool":"bash","state":{"status":"running","input":{"command":"cd ~/Projects/buildlog\nbuildlog fix \"audit pass over the arpwatch work, 4 real defects. CRITICAL: scanner treated arp.dat as current state, but arpwatch only ADDS a row per mac/ip pair and never removes one, so one routine DHCP reassignment (laptop A yesterday, laptop B today, same IP) read as a permanent 2-MAC spoof that alerted once then said ''persists'' forever -- guaranteed false positives on a /8 with lease churn. Fixed with a 1h window over the timestamp field arpwatch already writes; documented trade-off that a continuing spoof ages out after the window since the datafile cannot distinguish ''still spoofing'' from ''seen once''. Also: ignored addresses were written to the state file, so un-ignoring one later made it match ''persists'' and never alert. Installer: two mktemp -u calls left only one dir cleaned, orphaning a dir per root install; now one mktemp -d. Installer: units hardcoded /run/user/1000 while the installer resolved SUDO_USER for the home path; both now derived. 16/16 tests incl. both previously-broken cases; all scripts parse, all 3 units verify, no temp leak, notify path confirmed live. commit 3efc51f\" 2>&1 | tail -1"},"metadata":{"output":""},"time":{"start":1790459327391}}},"time":1790459327391}');
