INSERT INTO event VALUES('evt_0dfb2df36001k7UNfIMpbyaV8G','ses_f20e5cfc2ffeSFa4odnoYLiUOk',5847,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0dfb2db93001nLCuSFNc2OLb4y","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0dfb2bb21001mZOKytgJgcDpBH","type":"text","text":"No problem — wrong interface happens. Picking up the arpwatch work.\n\nBefore you run the installer, one thing needs checking: the live collector is already running with the *old* `ExecStart`, and `systemctl enable --now` won''t restart an already-running service — so it''d never get `-P` and the pidfile the scanner needs:","time":{"start":1790459435923,"end":1790459436854}},"time":1790459436854}');
