INSERT INTO event VALUES('evt_0dfb33799001Xzrs3CJ369kQsi','ses_f211dfcd4ffevS1Yoddwab036g',11297,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0dfb33395001FFLctEFTDQbIyh","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0dfb328d6001U9JkGwHiM99W18","type":"text","text":"Line 167 already rewrites the session-bus path from `$TARGET_UID`, but the `|| echo 1000` fallback is the same silent-wrong-value failure: if `id -u` fails it quietly targets another user''s runtime dir. Making it fail loudly instead:","time":{"start":1790459458453,"end":1790459459481}},"time":1790459459481}');
