INSERT INTO event VALUES('evt_0dfb36d30001ulO8psQBoRvctZ','ses_f211dfcd4ffevS1Yoddwab036g',11340,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0dfb369930010EsoRwMRYmB4tE","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0dfb3575200121j9FlVMbmY9kw","type":"tool","callID":"call_function_vce0w84yw7s0_1","tool":"edit","state":{"status":"running","input":{"filePath":"/home/livings/Projects/zen-hardening/install-shield-kitty-units.sh","newString":"SRC_WATCH=\"$ACCOUNT_HOME/Projects/shield-kitty/systemd\"\nSRC_SEAL=\"$ACCOUNT_HOME/Projects/shield-kitty-forensics/systemd\"\n# These MUST be user units, not system units: their ExecStart uses %h, which in\n# a system unit expands to /root and yields units that can never start.\n# /etc/systemd/user and ~/.config/systemd/user are both read by systemd; the\n# live install on this machine is in the latter. Keep this in sync with\n# `systemctl --user is-enabled` when checking.\nDEST=\"${SHIELD_KITTY_UNIT_DIR:-/etc/systemd/user}\"","oldString":"SRC_WATCH=\"$ACCOUNT_HOME/Projects/shield-kitty/systemd\"\nSRC_SEAL=\"$ACCOUNT_HOME/Projects/shield-kitty-forensics/systemd\""},"time":{"start":1790459473200}}},"time":1790459473200}');
