INSERT INTO event VALUES('evt_0dfb45000001drG7VTiYNggkqy','ses_f211dfcd4ffevS1Yoddwab036g',11538,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0dfb44c47001yJNT02b4R7EdtW","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0dfb43d6f001KjeNtb4GmjXWoH","type":"tool","callID":"call_function_d3afqghozjp1_1","tool":"bash","state":{"status":"running","input":{"command":"echo \"═══ private key present? (contents not shown) ═══\"\nls -l ~/.ssh/ 2>/dev/null | sed ''s/^/  /''\necho\nif [ -f ~/.ssh/id_ed25519 ]; then\n  echo \"  [ok] private key exists\"\n  perms=$(stat -c %a ~/.ssh/id_ed25519)\n  echo \"  perms: $perms $([ \"$perms\" = 600 ] && echo ''(correct)'' || echo ''(ssh will REFUSE this)'')\"\nelse\n  echo \"  [!!] no private key -- cannot push without the agent\"\nfi"},"metadata":{"output":""},"time":{"start":1790459531264}}},"time":1790459531264}');
