INSERT INTO event VALUES('evt_0dfb4c007001gSbBpuR9STdGYa','ses_f211dfcd4ffevS1Yoddwab036g',11613,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0dfb4b60e001ulA6uPk9vC9eya","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0dfb49e430011eMYIuf2X43RRS","type":"text","text":"Definitive: the key is offered and **rejected by GitHub**, while HTTPS to GitHub returns 200. So the network and my firewall are fine — this SSH key is no longer registered on the account, even though it authenticated successfully earlier in this session. That''s not something I can fix without your GitHub access. Assessing what''s at risk:","time":{"start":1790459557390,"end":1790459559943}},"time":1790459559943}');
