INSERT INTO event VALUES('evt_0dfb57b31001W6RpIU6NoOChZg','ses_f20e5cfc2ffeSFa4odnoYLiUOk',5993,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0dfb57b31001iJJq0Z2U7CvqxB","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0dfb574fc001VZYlTEF3L6C9FR","type":"text","text":"","time":{"start":1790459607857}},"time":1790459607857}');
INSERT INTO event VALUES('evt_0dfb58ec8001c7gFwEjFtZP6xX','ses_f20e5cfc2ffeSFa4odnoYLiUOk',5994,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0dfb57b31001iJJq0Z2U7CvqxB","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0dfb574fc001VZYlTEF3L6C9FR","type":"text","text":"Yes, it worked. All three parts:\n\n**`ExecStartPre` → `status=0/SUCCESS`** — the SIGHUP reached the collector. That was the whole point: arpwatch only rewrites `arp.dat` every 15 minutes, and now each scan forces a fresh flush.\n\n**`ExecStart` → `status=0/SUCCESS`**, and the log says `scan: no anomalies` — correct, since you have two entries with two distinct IPs.\n\n**`arp.dat` is finally populated**, 35 seconds after the scan:\n```\ne4:55:a8:e:ae:9c   10.128.128.128   _gateway\nea:bd:c8:4d:53:a8   10.197.250.246  zero\n```\nYour gateway and this machine, with working reverse-DNS. Timestamp decodes to `14:52:10`, one minute before the scan ran — so the data is genuinely fresh, not the stale 101-byte leftover.\n\n`Active: inactive (dead)` is **correct**, not a failure — it''s a `Type=oneshot` unit, so \"inactive\" is its resting state after success.\n\nTwo honest notes:\n\nOnly two entries is expected, not a bug. On a switched WLAN you only see broadcast ARP, so arpwatch sees your gateway and yourself. It''ll slowly accumulate other hosts.\n\nThe vendor lookup I mentioned earlier needs a correction: I said MAC vendor names were missing, and the gateway''s OUI (`e4:55:a8`) still returns nothing. That''s because this 28,098-entry snapshot of `ethercodes.dat` doesn''t list that OUI — not because `-D` is broken. The file is found and readable now, which is what `-D` was for. My earlier claim overstated what you''d see in practice.\n\nSo the arpwatch path is done and verified end to end. Still open, neither blocking:\n\n- **Faillock admin exemption** — prepared in `819c363`, deployed with `sudo ~/Projects/zen-hardening/deploy-faillock-admin.sh`. You''ve never run it.\n- **fail2ban `ignoreip`** — still swallows all of `10.0.0.0/8`.\n- **My own open question** — whether successful alert delivery should log a positive confirmation, since \"no log line\" currently can''t distinguish delivered from dropped.","time":{"start":1790459607857,"end":1790459612872}},"time":1790459612872}');
