INSERT INTO event VALUES('evt_0dfb6a7ab001wUlcYiogTSARNp','ses_f211dfcd4ffevS1Yoddwab036g',11646,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0dfb6a2ca001W46KDdFvxhbbBs","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0dfb68458001XVCw0lbKJCYF4C","type":"tool","callID":"call_function_8qpki6ytwq0q_1","tool":"bash","state":{"status":"running","input":{"command":"echo \"═══ FireDragon present? ═══\"\nfor b in firedragon firefox-esr icecat epiphany konqueror; do\n  p=$(command -v $b 2>/dev/null) && printf \"  [ok]   %-12s %s\\n\" \"$b\" \"$p\" || printf \"  [none] %s\\n\" \"$b\"\ndone\necho\necho \"  any browser package installed?\"\npacman -Qq 2>/dev/null | grep -iE ''fire|chrom|brave|ice|librewolf|firedragon|qute|epiphany|konqueror|vivaldi'' | sed ''s/^/    /'' || echo \"    none\"\necho\necho \"  flatpak/snap?\"\ncommand -v flatpak >/dev/null && flatpak list --app 2>/dev/null | sed ''s/^/    /'' || echo \"    no flatpak\""},"metadata":{"output":""},"time":{"start":1790459684779}}},"time":1790459684779}');
