me/livings/Projects/zen-hardening/git-verified.sh","metadata":{"diagnostics":{},"filepath":"/home/livings/Projects/zen-hardening/git-verified.sh","exists":false,"truncated":false},"time":{"start":1790459731660,"end":1790459731672}}},"time":1790459731672}');
