INSERT INTO event VALUES('evt_0dfb7946b001x92sT1cFCyCmHr','ses_f20e5cfc2ffeSFa4odnoYLiUOk',6070,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0dfb78b9d001rpVFvwh4V8BDuE","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0dfb7854f001493HSdbkScHOu7","type":"tool","callID":"call_function_s15fhu7zmuiu_1","tool":"bash","state":{"status":"running","input":{"command":"rm -rf /tmp/d && mkdir -p /tmp/d\ncat > /tmp/d/ok.py <<''PY''\nimport sys\nPY\ncat > /tmp/d/bad.py <<''PY''\nimport sys\nsys.stderr.write(\"no dbus / not on bus\\n\"); sys.exit(1)\nPY\ncd ~/Projects/zen-hardening\nNOW=$(date +%s)\nprintf ''aa:bb:cc:00:00:0b 10.1.0.1 %s\\ncc:dd:ee:00:00:0c 10.1.0.1 %s\\n'' $NOW $NOW > /tmp/d/spoof.dat\nfor a in ok bad; do\n  rm -f /tmp/d/st /tmp/d/scan.log\n  BDE_SPOOF_NOW=$NOW BDE_ARP_DATAFILE=/tmp/d/spoof.dat BDE_ARP_STATE=/tmp/d/st \\\n  BDE_ARPWATCH_LOG=/tmp/d/scan.log BDE_ALERT=/tmp/d/$a.py ./arpwatch-spoof-scan.sh >/dev/null 2>&1\n  echo \"  alert=$a.py ->\"\n  grep -E \"alert (delivered|DELIVERY)\" /tmp/d/scan.log | sed ''s/^/    /''\ndone\necho\necho \"=== no alert at all leaves an unambiguous trace too ===\"\nrm -f /tmp/d/st /tmp/d/scan.log\nprintf ''aa:bb:cc:00:00:01 10.2.0.1 %s\\n'' $NOW > /tmp/d/clean.dat\nBDE_SPOOF_NOW=$NOW BDE_ARP_DATAFILE=/tmp/d/clean.dat BDE_ARP_STATE=/tmp/d/st \\\nBDE_ARPWATCH_LOG=/tmp/d/scan.log BDE_ALERT=/tmp/d/ok.py ./arpwatch-spoof-scan.sh >/dev/null 2>&1\ntail -1 /tmp/d/scan.log | sed ''s/^/    /''\nfor f in arpwatch-spoof-scan.sh arpwatch-spoof-alert.sh; do bash -n $f && echo \"  syntax OK  $f\"; done"},"time":{"start":1790459745387}}},"time":1790459745387}');
