INSERT INTO event VALUES('evt_0dfb7cccb001ecAijn3uDabtd9','ses_f20e5cfc2ffeSFa4odnoYLiUOk',6122,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0dfb7cccb00163rUNUpb9AAjdC","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0dfb7c612001JMCV3s0rbw0WKq","type":"tool","callID":"call_function_oatm24uvwjhw_1","tool":"bash","state":{"status":"pending","input":{},"raw":""}},"time":1790459759819}');
INSERT INTO event VALUES('evt_0dfb7d574001QLWQo1NFBZHkNf','ses_f20e5cfc2ffeSFa4odnoYLiUOk',6123,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0dfb7cccb00163rUNUpb9AAjdC","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0dfb7c612001JMCV3s0rbw0WKq","type":"tool","callID":"call_function_oatm24uvwjhw_1","tool":"bash","state":{"status":"running","input":{"command":"cd ~/Projects/zen-hardening\ngit add -A\ngit commit -q -m \"log both alert outcomes, so silence is no longer ambiguous\n\nnotify-send is silent on success, and the previous code only logged when the\nnotifier produced output or exited non-zero. A successful send therefore wrote\nnothing at all, which made an empty log mean either ''delivered'' or ''dropped''.\n\nThat ambiguity is the same one that hid the root-session-bus bug, where\nnotifications failed while every status check reported healthy. Four bugs this\nsession shared that shape; this removes the reason it was hard to spot.\n\nBoth the datafile scanner and the exec-hook test path now branch explicitly:\n\n    alert delivered ok for <ip>\n    alert DELIVERY FAILED for <ip> (rc=N): <output>\n\nVerified both branches with a stub notifier that exits 0 silently and one that\nexits 1 with output on stderr, plus the no-anomaly case which still logs\n''scan: no anomalies''. 16/16 of the existing suite still pass; the single failure\nin the combined run was my harness reusing scan.log across cases, confirmed by\nre-running it against a clean log (1 line, as expected).\"\ngit log --oneline | head -1"},"metadata":{"output":""},"time":{"start":1790459762036}}},"time":1790459762036}');
INSERT INTO event VALUES('evt_0dfb7d576001x2bwGC7o0nfq06','ses_f20e5cfc2ffeSFa4odnoYLiUOk',6124,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0dfb7cccb00163rUNUpb9AAjdC","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0dfb7c612001JMCV3s0rbw0WKq","type":"tool","callID":"call_function_oatm24uvwjhw_1","tool":"bash","state":{"status":"running","input":{"command":"cd ~/Projects/zen-hardening\ngit add -A\ngit commit -q -m \"log both alert outcomes, so silence is no longer ambiguous\n\nnotify-send is silent on success, and the previous code only logged when the\nnotifier produced output or exited non-zero. A successful send therefore wrote\nnothing at all, which made an empty log mean either ''delivered'' or ''dropped''.\n\nThat ambiguity is the same one that hid the root-session-bus bug, where\nnotifications failed while every status check reported healthy. Four bugs this\nsession shared that shape; this removes the reason it was hard to spot.\n\nBoth the datafile scanner and the exec-hook test path now branch explicitly:\n\n    alert delivered ok for <ip>\n    alert DELIVERY FAILED for <ip> (rc=N): <output>\n\nVerified both branches with a stub notifier that exits 0 silently and one that\nexits 1 with output on stderr, plus the no-anomaly case which still logs\n''scan: no anomalies''. 16/16 of the existing suite still pass; the single failure\nin the combined run was my harness reusing scan.log across cases, confirmed by\nre-running it against a clean log (1 line, as expected).\"\ngit log --oneline | head -1"},"metadata":{"output":""},"time":{"start":1790459762036}}},"time":1790459762038}');
