INSERT INTO event VALUES('evt_0dfb9de4a001QTZYG4vDDWgmMi','ses_f20e5cfc2ffeSFa4odnoYLiUOk',6154,'message.part.updated.1','{"sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","part":{"id":"prt_0dfb9de46001ALq0zpSi371Gym","sessionID":"ses_f20e5cfc2ffeSFa4odnoYLiUOk","messageID":"msg_0dfb9de45001TmxDT54k80dQ4L","type":"text","text":"i do not have an IT team all my building is local only for me and me alone if anyone is trying to view my machine ban them now"},"time":1790459895370}');
