INSERT INTO event VALUES('evt_0dfbba3b7001OX917IxyXQ05jH','ses_f211dfcd4ffevS1Yoddwab036g',11842,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0dfbb9a68001KgOElGquYWCBkw","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0dfbb8894001qNuU9qBhAQMwli","type":"tool","callID":"call_function_f9ec1bbh6jsv_1","tool":"bash","state":{"status":"running","input":{"command":"echo \"═══ BOOTLOADER — what actually boots this machine? ═══\"\necho \"  ESP mount: $(findmnt -no SOURCE /boot/efi)\"\necho \"  ESP contents:\"\nls -la /boot/efi/ 2>/dev/null | sed ''s/^/      /''\necho\necho \"  recursive tree (dirs only):\"\nfind /boot/efi -maxdepth 3 -type d 2>/dev/null | sed ''s/^/      /''\necho\necho \"  firmware mode: $([ -d /sys/firmware/efi ] && echo UEFI || echo ''BIOS/legacy'')\"\necho \"  secure boot:   $(bootctl status 2>/dev/null | grep -i ''secure boot'' | sed ''s/.*: //'' || mokutil --sb-state 2>/dev/null || echo ''n/a'')\"\necho\necho \"  grub present on disk?\"\ncommand -v grub-install grub-mkconfig 2>/dev/null | sed ''s/^/      /'' || echo \"      no grub tooling\"\nls -1 /boot/grub 2>/dev/null | sed ''s/^/      /'' || echo \"      no /boot/grub\"\necho\necho \"  disk partition table:\"\nlsblk -o NAME,SIZE,FSTYPE,PARTLABEL,PARTTYPE,MOUNTPOINT 2>/dev/null | sed ''s/^/      /''"},"metadata":{"output":""},"time":{"start":1790460011447}}},"time":1790460011447}');
