NO INITRAMFS\"\n  [ \"$mods\" = \"NO\" ] && v=\"NO MODULES\"\n  [ \"$kv\" != \"$mods\" ] && [ \"$mods\" != \"NO\" ] && v=\"KERNEL/MODS MISMATCH\"\n  printf \"  %-4s %-17s %-7s %-7s %-6s %-6s %-6s %s\\n\" \"$n\" \"$date\" \"$fst\" \"$uu\" \"$kern\" \"$ird\" \"$mods\" \"$v\"\ndone"},"metadata":{"output":""},"time":{"start":1790460054986}}},"time":1790460054989}');
