INSERT INTO event VALUES('evt_0dfbc7db0001cS8t8bP6uBDhPa','ses_f211dfcd4ffevS1Yoddwab036g',11953,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0dfbc7059001ZZyuIeLAqxscY1","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0dfbc4eb0001XPKsxY7WvV7EjW","type":"text","text":"`KERNEL/MODS MISMATCH` on all 11 is **my bug again** — Garuda/zen uses unversioned `/boot/vmlinuz-linux-zen`, so stripping `vmlinuz-` yields `linux-zen`, never a version. It can never match. Let me verify that and get real creation dates:","time":{"start":1790460063833,"end":1790460067248}},"time":1790460067248}');
