INSERT INTO event VALUES('evt_0dfbcba89001J08K8Vkm3ojkDC','ses_f211dfcd4ffevS1Yoddwab036g',11997,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0dfbcb1b2001bPZA3qGnHgtWA2","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0dfbc7e30001MirKW2OvebwCYF","type":"tool","callID":"call_function_f6j29s8555rz_2","tool":"bash","state":{"status":"running","input":{"command":"echo \"═══ P2: fstab completeness — does every real mount appear? ═══\"\necho \"  current mounts vs fstab:\"\nfindmnt -no TARGET,FSTYPE | grep -vE ''^(proc|sysfs|devpts|tmpfs /(dev|run|sys|proc)|cgroup|mqueue|hugetlbfs|debugfs|tracefs|configfs|fusectl|ramfs|securityfs|pstore|bpf|efivarfs|binfmt_misc|autofs|nsfs)$'' | sed ''s/^/      /''\necho\necho \"  crypttab entries: $(grep -vcE ''^\\s*#|^\\s*$'' /etc/crypttab 2>/dev/null || echo ''no crypttab'')\"\ngrep -vE ''^\\s*#|^\\s*$'' /etc/crypttab 2>/dev/null | sed ''s/^/      /'' || echo \"      none\"\necho\necho \"═══ P3: snapper timer health (runs at boot/periodically; errors would repeat) ═══\"\nsystemctl list-timers --all --no-pager 2>/dev/null | grep -iE ''snapper|NEXT|LAST'' | sed ''s/^/      /''\necho \"  snapper-timeline.timer: $(systemctl is-active snapper-timeline.timer 2>&1)\"\necho \"  snapper-cleanup.timer:  $(systemctl is-active snapper-cleanup.timer 2>&1)\"\necho\necho \"  last snapper run errors:\"\njournalctl -b -u ''snapper*'' --no-pager -p err 2>/dev/null | tail -5 | sed ''s/^/      /'' || echo \"      none\""},"metadata":{"output":""},"time":{"start":1790460082825}}},"time":1790460082825}');
