INSERT INTO event VALUES('evt_0dfbd244f001Ido2RyF73K2MP4','ses_f211dfcd4ffevS1Yoddwab036g',12046,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0dfbd1f35001DsgpgyZN9zJfjJ","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0dfbd07a0001Yn76lGwiyJl4mV","type":"tool","callID":"call_function_z9tbeulrvud2_1","tool":"bash","state":{"status":"running","input":{"command":"echo \"═══ which initramfs generator is actually in use? ═══\"\nls -d /etc/dracut.conf.d /etc/mkinitcpio.d /etc/mkinitcpio.conf /etc/dracut.conf 2>/dev/null | sed ''s/^/      /''\necho \"  initramfs generator packages:\"\npacman -Qq 2>/dev/null | grep -E ''^(dracut|mkinitcpio)'' | sed ''s/^/      /''\necho \"  mkinitcpio hooks dir: $(ls -d /etc/mkinitcpio.d 2>/dev/null || echo none)\"\necho\necho \"  image magic (what format?):\"\nfile -b /boot/initramfs-linux-zen.img 2>/dev/null | sed ''s/^/      /''\necho\necho \"  garuda-pacman-lock.service actual content:\"\nsystemctl cat garuda-pacman-lock.service 2>/dev/null | grep -E ''ExecStart|Description'' | sed ''s/^/      /''"},"metadata":{"output":""},"time":{"start":1790460109903}}},"time":1790460109903}');
