INSERT INTO event VALUES('evt_0dfbd5908001chNv4CXfVoVgnc','ses_f211dfcd4ffevS1Yoddwab036g',12073,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0dfbd4907001RWzB78bM267o63","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0dfbd24d1001G6XeeCXvuAR7GC","type":"text","text":"Confirmed dracut, so `lsinitcpio` was simply the wrong tool — those \"MISSING\" lines were meaningless. And `garuda-pacman-lock` uses a bare `rm`, which systemd resolves via its default search path, so that''s fine too. **P1 is actually clean.** The initramfs image is root-only, but the highest-value check I *can* do is GRUB''s kernel command line:","time":{"start":1790460119303,"end":1790460123399}},"time":1790460123399}');
