INSERT INTO event VALUES('evt_0dfc2937f001RH8Qe19e9nNB1c','ses_f211dfcd4ffevS1Yoddwab036g',12225,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0dfc2875e001nOvAuhHG5mOYne","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0dfc25638001lMjhrW1bDr4gPB","type":"tool","callID":"call_function_xytb4kxs0bns_2","tool":"bash","state":{"status":"running","input":{"command":"echo \"═══ THE ACTUAL TEST: did Shield Kitty start at BOOT, or at login? ═══\"\necho \"  (linger means it must start BEFORE any login -- that was the whole point)\"\necho\nboot=$(uptime -s 2>/dev/null | tr '' '' ''T'')\nfor u in shield-kitty-watch.service evidence-seal.timer; do\n  act=$(systemctl --user is-active \"$u\" 2>&1)\n  ena=$(systemctl --user is-enabled \"$u\" 2>&1)\n  ts=$(systemctl --user show \"$u\" -p ActiveEnterTimestamp --value 2>/dev/null)\n  printf \"  %-30s active=%-10s enabled=%s\\n\" \"$u\" \"$act\" \"$ena\"\n  printf \"      activated: %s\\n\" \"${ts:-n/a}\"\ndone\necho\necho \"  this login session started at:\"\nloginctl show-session \"$(loginctl 2>/dev/null | awk -v u=\"$USER\" ''$3==u {print $1; exit}'')\" -p ActiveEnterTimestamp --value 2>/dev/null | sed ''s/^/      /''\necho\necho \"  linger (what makes it survive a reboot with no login):\"\nloginctl show-user \"$USER\" -p Linger --value 2>/dev/null | sed ''s/^/      Linger=/''\necho\necho \"  is the watcher really running, and in a systemd cgroup?\"\nsystemctl --user show shield-kitty-watch.service -p MainPID --value 2>/dev/null | sed ''s/^/      MainPID=/''\npid=$(systemctl --user show shield-kitty-watch.service -p MainPID --value 2>/dev/null)\n[ -n \"$pid\" ] && [ \"$pid\" != 0 ] && cat \"/proc/$pid/cgroup\" 2>/dev/null | sed ''s/^/      /''"},"metadata":{"output":""},"time":{"start":1790460466047}}},"time":1790460466047}');
INSERT INTO event VALUES('evt_0dfc29383001FJy1t4jhh6Qr1r','ses_f211dfcd4ffevS1Yoddwab036g',12226,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0dfc2875e001nOvAuhHG5mOYne","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0dfc25638001lMjhrW1bDr4gPB","type":"tool","callID":"call_function_xytb4kxs0bns_2","tool":"bash","state":{"status":"running","input":{"command":"echo \"═══ THE ACTUAL TEST: did Shield Kitty start at BOOT, or at login? ═══\"\necho \"  (linger means it must start BEFORE any login -- that was the whole point)\"\necho\nboot=$(uptime -s 2>/dev/null | tr '' '' ''T'')\nfor u in shield-kitty-watch.service evidence-seal.timer; do\n  act=$(systemctl --user is-active \"$u\" 2>&1)\n  ena=$(systemctl --user is-enabled \"$u\" 2>&1)\n  ts=$(systemctl --user show \"$u\" -p ActiveEnterTimestamp --value 2>/dev/null)\n  printf \"  %-30s active=%-10s enabled=%s\\n\" \"$u\" \"$act\" \"$ena\"\n  printf \"      activated: %s\\n\" \"${ts:-n/a}\"\ndone\necho\necho \"  this login session started at:\"\nloginctl show-session \"$(loginctl 2>/dev/null | awk -v u=\"$USER\" ''$3==u {print $1; exit}'')\" -p ActiveEnterTimestamp --value 2>/dev/null | sed ''s/^/      /''\necho\necho \"  linger (what makes it survive a reboot with no login):\"\nloginctl show-user \"$USER\" -p Linger --value 2>/dev/null | sed ''s/^/      Linger=/''\necho\necho \"  is the watcher really running, and in a systemd cgroup?\"\nsystemctl --user show shield-kitty-watch.service -p MainPID --value 2>/dev/null | sed ''s/^/      MainPID=/''\npid=$(systemctl --user show shield-kitty-watch.service -p MainPID --value 2>/dev/null)\n[ -n \"$pid\" ] && [ \"$pid\" != 0 ] && cat \"/proc/$pid/cgroup\" 2>/dev/null | sed ''s/^/      /''"},"metadata":{"output":""},"time":{"start":1790460466047}}},"time":1790460466051}');
INSERT INTO event VALUES('evt_0dfc293850012Si0r3HCQaClja','ses_f211dfcd4ffevS1Yoddwab036g',12227,'message.part.updated.1','{"sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","part":{"id":"prt_0dfc2803e001s023yCiBsRjIL1","sessionID":"ses_f211dfcd4ffevS1Yoddwab036g","messageID":"msg_0dfc25638001lMjhrW1bDr4gPB","type":"text","text":"Good — but I''m not going to take that on assertion. This is exactly the moment to verify rather than trust, and a fresh boot is better evidence than anything we produced before.","time":{"start":1790460461118,"end":1790460466053}},"time":1790460466053}');
