tal 4\ndrwxr-xr-x 1 livings livings  116 Sep 26 11:11 .\ndrwxr-xr-x 1 livings livings   24 Sep 26 11:11 ..\ndrwxr-xr-x 1 livings livings   28 Sep 26 11:11 alacritty\ndrwxr-xr-x 1 livings livings  114 Sep 26 11:11 fonts\ndrwxr-xr-x 1 livings livings  122 Sep 26 11:12 .git\ndrwxr-xr-x 1 livings livings   64 Sep 26 11:11 gtk\ndrwxr-xr-x 1 livings livings   86 Sep 26 11:11 konsole\ndrwxr-xr-x 1 livings livings   24 Sep 26 11:11 opencode\n-rw-r--r-- 1 livings livings 2027 Sep 26 11:11 README.md\ndrwxr-xr-x 1 livings livings   20 Sep 26 11:11 scripts\ndrwxr-xr-x 1 livings livings   20 Sep 26 11:11 themes\n","exit":0,"truncated":false},"title":"cd /home/livings/Projects/hermes-blood && echo \"=== branch/log ===\" && git log --oneline -5 2>&1 && echo && echo \"=== status ===\" && git status -sb 2>&1 | head -5 && echo && echo \"=== tree ===\" && ls -la","time":{"start":1790446320170,"end":1790446320204}}}');
