places\npreferences\nstatus\n\n--- its index.theme ---\n[Icon Theme]\nName=BeautyLine\nInherits=hicolor,Adwaita,breeze\n\nDirectories=actions/scalable,places/16,places/48,apps/scalable,status/scalable,devices/scalable,mimetypes/scalable\nExample=folder\nDisplayDepth=32\n\nFollowsColorScheme=true\n\nDesktopDefault=48\nDesktopSizes=16,22,32,48,64,128,256\nToolbarDefault=22\nToolbarSizes=16,22,32,48\nMainToolbarDefault=22\nMainToolbarSizes=16,22,32,48\nSmallDefault=16\nSmallSizes=16,22,32,48\nPanelDefault=48\nPanelSizes=16,22,32,48,64,128,256\nDialogDefault=32\nDialogSizes=16,22,32,48,64,128,256\n\nKDE-Extensions=.svg\n\n[devices/scalable]\nContext=Devices\nSize=22\nMinSize=8\nMaxSize=192\nType=Scalable\n\n[actions/scalable]\nContext=Actions\nSize=22\nMinSize=8\nMaxSize=192\nType=Scalable\n\n[actions/scalable]\nContext=Status\nSize=22\nMinSize=8\nMaxSize=192\nType=Scalable\n\n[apps/scalable]\nSize=96\nContext=Applications\nMinSize=8\nMaxSize=512\nType=Scalable\n\n[mimetypes/scalable]\nContext=MimeTypes\nSize=96\nMinSize=8\nMaxSize=512\nType=Scalable\n\n[places/16]\nSize=16\nContext=Places\nMinSize=8\nMaxSize=48\nType=Scalable\n\n\n[places/48]\nSize=48\nContext=Places\nMinSize=48\nMaxSize=512\nType=Scalable\n\n[status/scalable]\nContext=Status\nSize=22\nMinSize=8\nMaxSize=512\nType=Scalable\n","exit":0,"truncated":false},"title":"echo \"=== BeautyLine structure (to mirror) ===\"; ls /usr/share/icons/BeautyLine/; echo; echo \"--- its index.theme ---\"; cat /usr/share/icons/BeautyLine/index.theme","time":{"start":1790446345091,"end":1790446347628}}}');
