INSERT INTO part VALUES('prt_0deec6295001yOFFs46152n79v','msg_0deec532b001pXOVeS7AgAjpYh','ses_f211dfcd4ffevS1Yoddwab036g',1790446428821,1790446430567,'{"type":"tool","tool":"bash","callID":"call_function_x61rs1nu0dm8_1","state":{"status":"completed","input":{"command":"echo \"=== Great Vibes styles (correct query) ===\"\nfc-list --format=''%{family[0]}|%{style[0]}|%{file}\\n'' | grep -i \"great vibes\" | sort -u | sed ''s/^/  /''\necho\necho \"=== does fontconfig synthesize/fallback for GV bold+italic? ===\"\nfc-match \"Great Vibes:bold\"    2>&1 | sed ''s/^/  bold-> /''\nfc-match \"Great Vibes:italic\"  2>&1 | sed ''s/^/  italic-> /''"},"output":"=== Great Vibes styles (correct query) ===\n  Great Vibes|Regular|/home/livings/.local/share/fonts/GreatVibes-Regular.ttf\n\n=== does fontconfig synthesize/fallback for GV bold+italic? ===\n  bold-> GreatVibes-Regular.ttf: \"Great Vibes\" \"Regular\"\n  italic-> GreatVibes-Regular.ttf: \"Great Vibes\" \"Regular\"\n","metadata":{"output":"=== Great Vibes styles (correct query) ===\n  Great Vibes|Regular|/home/livings/.local/share/fonts/GreatVibes-Regular.ttf\n\n=== does fontconfig synthesize/fallback for GV bold+italic? ===\n  bold-> GreatVibes-Regular.ttf: \"Great Vibes\" \"Regular\"\n  italic-> GreatVibes-Regular.ttf: \"Great Vibes\" \"Regular\"\n","exit":0,"truncated":false},"title":"echo \"=== Great Vibes styles (correct query) ===\"\nfc-list --format=''%{family[0]}|%{style[0]}|%{file}\\n'' | grep -i \"great vibes\" | sort -u | sed ''s/^/  /''\necho\necho \"=== does fontconfig synthesize/fallback for GV bold+italic? ===\"\nfc-match \"Great Vibes:bold\"    2>&1 | sed ''s/^/  bold-> /''\nfc-match \"Great Vibes:italic\"  2>&1 | sed ''s/^/  italic-> /''","time":{"start":1790446429840,"end":1790446430567}}}');
INSERT INTO part VALUES('prt_0deec6698001Blab0LbCjHBKvV','msg_0deec532b001pXOVeS7AgAjpYh','ses_f211dfcd4ffevS1Yoddwab036g',1790446429848,1790446430578,'{"type":"tool","tool":"bash","callID":"call_function_x61rs1nu0dm8_2","state":{"status":"completed","input":{"command":"echo \"=== konsolerc ===\"; cat ~/.config/konsolerc 2>&1 | sed ''s/^/  /''\necho; echo \"=== Garuda.profile ===\"; cat ~/.local/share/konsole/Garuda.profile 2>&1 | sed ''s/^/  /''\necho; echo \"=== is konsole installed? ===\"; which konsole 2>&1 || echo \"  konsole NOT installed\"\necho \"=== terminal emulators present ===\"; for t in konsole alacritty gnome-terminal xterm kitty foot; do which $t >/dev/null 2>&1 && echo \"  $t\"; done"},"output":"=== konsolerc ===\n  [Desktop Entry]\n  DefaultProfile=Garuda.profile\n  \n  [General]\n  ConfigVersion=1\n  \n  [KonsoleWindow]\n  RememberWindowSize=true\n  ShowMenuBarByDefault=false\n  \n  [MainWindow]\n  MenuBar=Disabled\n  RestorePositionForNextInstance=true\n  StatusBar=Disabled\n  \n  [UiSettings]\n  ColorScheme=BlackRed\n\n=== Garuda.profile ===\n  [Appearance]\n  ColorScheme=BlackRed\n  Font=Great Vibes,12,-1,5,50,0,0,0,0,0\n  UseFontLineCharacters=true\n  \n  [Cursor Options]\n  CursorShape=2\n  CustomCursorColor=200,16,46\n  UseCustomCursorColor=true\n  \n  [General]\n  Command=/usr/bin/fish\n  Name=Garuda\n  Parent=FALLBACK/\n  TerminalColumns=110\n  \n  [Interaction Options]\n  AutoCopySelectedText=true\n  TrimLeadingSpacesInSelectedText=true\n  TrimTrailingSpacesInSelectedText=true\n  UnderlineFilesEnabled=true\n  \n  [Keyboard]\n  KeyBindings=default\n  \n  [Scrolling]\n  HistoryMode=1\n  \n  [Terminal Features]\n  BlinkingCursorEnabled=true\n\n=== is konsole installed? ===\n/usr/bin/konsole\n=== terminal emulators present ===\n  konsole\n","metadata":{"output":"=== konsolerc ===\n  [Desktop Entry]\n  DefaultProfile=Garuda.profile\n  \n  [General]\n  ConfigVersion=1\n  \n  [KonsoleWindow]\n  RememberWindowSize=true\n  ShowMenuBarByDefault=false\n  \n  [MainWindow]\n  MenuBar=Disabled\n  RestorePositionForNextInstance=true\n  StatusBar=Disabled\n  \n  [UiSettings]\n  ColorScheme=BlackRed\n\n=== Garuda.profile ===\n  [Appearance]\n  ColorScheme=BlackRed\n  Font=Great Vibes,12,-1,5,50,0,0,0,0,0\n  UseFontLineCharacters=true\n  \n  [Cursor Options]\n  CursorShape=2\n  CustomCursorColor=200,16,46\n  UseCustomCursorColor=true\n  \n  [General]\n  Command=/usr/bin/fish\n  Name=Garuda\n  Parent=FALLBACK/\n  TerminalColumns=110\n  \n  [Interaction Options]\n  AutoCopySelectedText=true\n  TrimLeadingSpacesInSelectedText=true\n  TrimTrailingSpacesInSelectedText=true\n  UnderlineFilesEnabled=true\n  \n  [Keyboard]\n  KeyBindings=default\n  \n  [Scrolling]\n  HistoryMode=1\n  \n  [Terminal Features]\n  BlinkingCursorEnabled=true\n\n=== is konsole installed? ===\n/usr/bin/konsole\n=== terminal emulators present ===\n  konsole\n","exit":1,"truncated":false},"title":"echo \"=== konsolerc ===\"; cat ~/.config/konsolerc 2>&1 | sed ''s/^/  /''\necho; echo \"=== Garuda.profile ===\"; cat ~/.local/share/konsole/Garuda.profile 2>&1 | sed ''s/^/  /''\necho; echo \"=== is konsole installed? ===\"; which konsole 2>&1 || echo \"  konsole NOT installed\"\necho \"=== terminal emulators present ===\"; for t in konsole alacritty gnome-terminal xterm kitty foot; do which $t >/dev/null 2>&1 && echo \"  $t\"; done","time":{"start":1790446430553,"end":1790446430578}}}');
