\"=== package state ===\"\npacman -Q nodejs nodejs-lts-iron 2>&1 | sed ''s/^/  /''\necho\necho \"=== satisfy hermes engines? ===\"\nnode -e ''const e={node:\"^22.22.0 || ^24.11.0 || >=26.0.0\"};const v=process.versions.node;const ok=/^26\\./.test(v)||/^24\\./.test(v)||/^22\\./.test(v);console.log(`  node ${v} -> ${ok?\"SATISFIES\":\"FAILS\"} >=22`)'' 2>&1\necho\necho \"=== broken deps? ===\"\npacman -Qkk 2>&1 | grep -i \"missing\\|altered\" | head -5 || echo \"  none\"","time":{"start":1790446854246,"end":1790446861085}}}');
