config/gh/token 2>&1 | sed ''s/^/  /''\necho\necho \"=== perms on the Desktop one (expect 644 = world-readable) ===\"\nstat -c ''  %n  mode=%a  owner=%U  size=%s bytes'' ~/Desktop/token.txt 2>/dev/null\necho\necho \"=== has Baloo already indexed the Desktop? ===\"\npgrep -x baloo_file >/dev/null && echo \"  baloo_file running - .txt is NOT in the exclude list, so it may be indexed\"","time":{"start":1790447966356,"end":1790447966393}}}');
