INSERT INTO part VALUES('prt_0df03ef85001mzfznEbQI5Gfhw','msg_0df03d8c70014tHpKvkhn0dXjE','ses_f211dfcd4ffevS1Yoddwab036g',1790447972229,1790447973162,'{"type":"tool","tool":"bash","callID":"call_function_tcl5a90zjhqd_1","state":{"status":"completed","input":{"command":"for f in ~/.config/gh/token ~/Desktop/token.txt; do\n  echo \"=== $f ===\"\n  awk ''{printf \"  line %d: %d chars, starts %s..., ends ...%s\\n\", NR, length($0), substr($0,1,11), substr($0,length($0)-3)}'' \"$f\" 2>&1\n  printf \"  total lines: %s\\n\" \"$(wc -l < \"$f\")\"\n  echo\ndone"},"output":"=== /home/livings/.config/gh/token ===\n  line 1: 186 chars, starts github_pat_..., ends ...vkZJ\n  total lines: 0\n\n=== /home/livings/Desktop/token.txt ===\n  line 1: 93 chars, starts github_pat_..., ends ...vkZJ\n  total lines: 1\n\n","metadata":{"output":"=== /home/livings/.config/gh/token ===\n  line 1: 186 chars, starts github_pat_..., ends ...vkZJ\n  total lines: 0\n\n=== /home/livings/Desktop/token.txt ===\n  line 1: 93 chars, starts github_pat_..., ends ...vkZJ\n  total lines: 1\n\n","exit":0,"truncated":false},"title":"for f in ~/.config/gh/token ~/Desktop/token.txt; do\n  echo \"=== $f ===\"\n  awk ''{printf \"  line %d: %d chars, starts %s..., ends ...%s\\n\", NR, length($0), substr($0,1,11), substr($0,length($0)-3)}'' \"$f\" 2>&1\n  printf \"  total lines: %s\\n\" \"$(wc -l < \"$f\")\"\n  echo\ndone","time":{"start":1790447973137,"end":1790447973161}}}');
