INSERT INTO part VALUES('prt_0df0425af00124557RvHuvFOrF','msg_0df041b760010tKgY7LipUlWMt','ses_f211dfcd4ffevS1Yoddwab036g',1790447986095,1790447988161,'{"type":"tool","tool":"bash","callID":"call_function_3svkjo5se1gl_1","state":{"status":"completed","input":{"command":"cd /tmp/opencode\nT=$(cat ~/.config/gh/token.clean)\n# page through ALL repos; -L follows pagination\ncurl -sL -H \"Authorization: Bearer $T\" \\\n  \"https://api.github.com/user/repos?per_page=100&affiliation=owner&sort=updated\" \\\n  -o allrepos.json\npython3 - <<''PY''\nimport json\nd=json.load(open(''/tmp/opencode/allrepos.json''))\nprint(f\"  TOTAL REPOS: {len(d)}\")\npub=[r for r in d if not r[''private'']]\npri=[r for r in d if r[''private'']]\nprint(f\"    public  : {len(pub)}\")\nprint(f\"    private : {len(pri)}\")\nprint(f\"    archived: {sum(1 for r in d if r[''archived''])}\")\nprint(f\"    forks   : {sum(1 for r in d if r[''fork''])}\")\nprint()\nfrom collections import Counter\nc=Counter((r[''language''] or ''-'') for r in d)\nprint(\"  by language:\")\nfor k,v in c.most_common(): print(f\"    {k:<22} {v}\")\nPY"},"output":"  TOTAL REPOS: 28\n    public  : 28\n    private : 0\n    archived: 0\n    forks   : 0\n\n  by language:\n    C++                    12\n    -                      6\n    HTML                   3\n    Shell                  3\n    Python                 2\n    Makefile               1\n    Papyrus                1\n","metadata":{"output":"  TOTAL REPOS: 28\n    public  : 28\n    private : 0\n    archived: 0\n    forks   : 0\n\n  by language:\n    C++                    12\n    -                      6\n    HTML                   3\n    Shell                  3\n    Python                 2\n    Makefile               1\n    Papyrus                1\n","exit":0,"truncated":false},"title":"cd /tmp/opencode\nT=$(cat ~/.config/gh/token.clean)\n# page through ALL repos; -L follows pagination\ncurl -sL -H \"Authorization: Bearer $T\" \\\n  \"https://api.github.com/user/repos?per_page=100&affiliation=owner&sort=updated\" \\\n  -o allrepos.json\npython3 - <<''PY''\nimport json\nd=json.load(open(''/tmp/opencode/allrepos.json''))\nprint(f\"  TOTAL REPOS: {len(d)}\")\npub=[r for r in d if not r[''private'']]\npri=[r for r in d if r[''private'']]\nprint(f\"    public  : {len(pub)}\")\nprint(f\"    private : {len(pri)}\")\nprint(f\"    archived: {sum(1 for r in d if r[''archived''])}\")\nprint(f\"    forks   : {sum(1 for r in d if r[''fork''])}\")\nprint()\nfrom collections import Counter\nc=Counter((r[''language''] or ''-'') for r in d)\nprint(\"  by language:\")\nfor k,v in c.most_common(): print(f\"    {k:<22} {v}\")\nPY","time":{"start":1790447987170,"end":1790447988160}}}');
