INSERT INTO part VALUES('prt_0df043ee9001A76Fw8IUNebtYp','msg_0df042dcd001zHG580sZGtdKo6','ses_f211dfcd4ffevS1Yoddwab036g',1790447992553,1790447995117,'{"type":"tool","tool":"bash","callID":"call_function_j4epfuaj87tb_1","state":{"status":"completed","input":{"command":"cd /tmp/opencode\nT=$(cat ~/.config/gh/token.clean)\nfor aff in \"\" \"owner\" \"collaborator\" \"organization_member\"; do\n  label=${aff:-\"(default: owner+collaborator+org_member)\"}\n  n=$(curl -sL -H \"Authorization: Bearer $T\" \"https://api.github.com/user/repos?per_page=100&affiliation=$aff\" | python3 -c \"import json,sys; print(len(json.load(sys.stdin)))\" 2>/dev/null)\n  printf ''  %-40s %s repos\\n'' \"$label\" \"$n\"\ndone"},"output":"  (default: owner+collaborator+org_member) 0 repos\n  owner                                    28 repos\n  collaborator                             0 repos\n  organization_member                      0 repos\n","metadata":{"output":"  (default: owner+collaborator+org_member) 0 repos\n  owner                                    28 repos\n  collaborator                             0 repos\n  organization_member                      0 repos\n","exit":0,"truncated":false},"title":"cd /tmp/opencode\nT=$(cat ~/.config/gh/token.clean)\nfor aff in \"\" \"owner\" \"collaborator\" \"organization_member\"; do\n  label=${aff:-\"(default: owner+collaborator+org_member)\"}\n  n=$(curl -sL -H \"Authorization: Bearer $T\" \"https://api.github.com/user/repos?per_page=100&affiliation=$aff\" | python3 -c \"import json,sys; print(len(json.load(sys.stdin)))\" 2>/dev/null)\n  printf ''  %-40s %s repos\\n'' \"$label\" \"$n\"\ndone","time":{"start":1790447993270,"end":1790447995116}}}');
