= private repo access test (hermes-blood) ===\"\ncurl -s -o /dev/null -w \"  GET /repos/intricos777-dot/hermes-blood -> HTTP %{http_code}\\n\" \\\n  -H \"Authorization: Bearer $T\" https://api.github.com/repos/intricos777-dot/hermes-blood\necho\necho \"=== full inventory ===\"\ncurl -sL -H \"Authorization: Bearer $T\" \"https://api.github.com/user/repos?per_page=100&affiliation=owner&sort=updated\" -o allrepos.json\npython3 - <<''PY''\nimport json\nd=json.load(open(''/tmp/opencode/allrepos.json''))\nif isinstance(d,dict): print(\"  API error:\",d.get(''message'')); raise SystemExit\npri=[r for r in d if r[''private'']]\nprint(f\"  TOTAL: {len(d)}   private: {len(pri)}\")\nPY","time":{"start":1790448120283,"end":1790448124378}}}');
