INSERT INTO part VALUES('prt_0df065c8700144tLqLiMEZ8wOb','msg_0df0655300017Zv4HVCd382p8I','ses_f211dfcd4ffevS1Yoddwab036g',1790448131207,1790448134467,'{"type":"tool","tool":"bash","callID":"call_function_h0x2zczxh4hy_1","state":{"status":"completed","input":{"command":"cd /tmp/opencode\nT=$(cat ~/.config/gh/token.clean)\n# follow every page\ncurl -sL -H \"Authorization: Bearer $T\" \"https://api.github.com/user/repos?per_page=100&affiliation=owner&sort=updated\" -o p1.json\ncurl -sL -H \"Authorization: Bearer $T\" \"https://api.github.com/user/repos?per_page=100&affiliation=owner&sort=updated&page=2\" -o p2.json\npython3 - <<''PY''\nimport json\nd=json.load(open(''/tmp/opencode/p1.json''))+json.load(open(''/tmp/opencode/p2.json''))\nseen=set(); u=[]\nfor r in d:\n    if r[''id''] in seen: continue\n    seen.add(r[''id'']); u.append(r)\njson.dump(u,open(''/tmp/opencode/repos_all.json'',''w''))\npri=[r for r in u if r[''private'']]\nprint(f\"  TRUE TOTAL: {len(u)}\")\nprint(f\"    private : {len(pri)}\")\nprint(f\"    public  : {len(u)-len(pri)}\")\nprint(f\"    archived: {sum(1 for r in u if r[''archived''])}\")\nprint(f\"    empty   : {sum(1 for r in u if r[''size'']==0)}\")\nPY"},"output":"  TRUE TOTAL: 120\n    private : 92\n    public  : 28\n    archived: 0\n    empty   : 3\n","metadata":{"output":"  TRUE TOTAL: 120\n    private : 92\n    public  : 28\n    archived: 0\n    empty   : 3\n","exit":0,"truncated":false},"title":"cd /tmp/opencode\nT=$(cat ~/.config/gh/token.clean)\n# follow every page\ncurl -sL -H \"Authorization: Bearer $T\" \"https://api.github.com/user/repos?per_page=100&affiliation=owner&sort=updated\" -o p1.json\ncurl -sL -H \"Authorization: Bearer $T\" \"https://api.github.com/user/repos?per_page=100&affiliation=owner&sort=updated&page=2\" -o p2.json\npython3 - <<''PY''\nimport json\nd=json.load(open(''/tmp/opencode/p1.json''))+json.load(open(''/tmp/opencode/p2.json''))\nseen=set(); u=[]\nfor r in d:\n    if r[''id''] in seen: continue\n    seen.add(r[''id'']); u.append(r)\njson.dump(u,open(''/tmp/opencode/repos_all.json'',''w''))\npri=[r for r in u if r[''private'']]\nprint(f\"  TRUE TOTAL: {len(u)}\")\nprint(f\"    private : {len(pri)}\")\nprint(f\"    public  : {len(u)-len(pri)}\")\nprint(f\"    archived: {sum(1 for r in u if r[''archived''])}\")\nprint(f\"    empty   : {sum(1 for r in u if r[''size'']==0)}\")\nPY","time":{"start":1790448132310,"end":1790448134466}}}');
