ile\n  that profile ColorScheme  = BlackRed\n  colorscheme file exists: YES\n\n=== 6. shell Konsole launches (fish present?) ===\n  /usr/bin/fish: present\n","exit":0,"truncated":false},"title":"echo \"=== 4. syntax validation ===\"\npython3 -c \"\nimport tomllib,json\ntomllib.load(open(''/home/livings/.config/alacritty/alacritty.toml'',''rb'')); print(''  alacritty.toml: valid TOML'')\njson.load(open(''/home/livings/.config/opencode/themes/voidlit.json'')); print(''  voidlit.json:   valid JSON'')\n\" 2>&1\npython3 -c \"\nimport yaml; yaml.safe_load(open(''/home/livings/.hermes/skins/blood.yaml'')); print(''  blood.yaml:     valid YAML'')\" 2>&1 || echo \"  blood.yaml:     (pyyaml absent, skipped)\"\necho\necho \"=== 5. konsole profile -> colorscheme chain ===\"\np=$(grep -oP ''(?<=^DefaultProfile=).*'' ~/.config/konsolerc)\nc=$(grep -oP ''(?<=^ColorScheme=).*'' ~/.local/share/konsole/${p})\necho \"  konsolerc DefaultProfile = $p\"\necho \"  that profile ColorScheme  = $c\"\n[ -f ~/.local/share/konsole/$c.colorscheme ] && echo \"  colorscheme file exists: YES\" || echo \"  colorscheme file exists: NO\"\necho\necho \"=== 6. shell Konsole launches (fish present?) ===\"\n[ -x /usr/bin/fish ] && echo \"  /usr/bin/fish: present\" || echo \"  /usr/bin/fish: MISSING - Garuda profile would fail\"","time":{"start":1790448202516,"end":1790448202593}}}');
