l | grep -E ''^https?://'' | head -1)\necho \"  url: ${url:-<none found in cmdline>}\"\nhost=$(echo \"$url\" | sed -E ''s|https?://([^/]+)/.*|\\1|'')\n[ -n \"$host\" ] && { echo \"  host: $host\"; timeout 8 getent hosts \"$host\" 2>&1 | head -2 | sed ''s/^/    dns: /'' || echo \"    dns: FAILED\"; }\necho\necho \"=== how long has git-remote-http been open? ===\"\nps -o etime=,stat= -p 59185 2>/dev/null | sed ''s/^/  /''","time":{"start":1790448642718,"end":1790448642905}}}');
