INSERT INTO part VALUES('prt_0df0f6b04001fegAC7KjRWWtLe','msg_0df0f63a6001X3hOD8M2Pxl7T8','ses_f211dfcd4ffevS1Yoddwab036g',1790448724740,1790448725886,'{"type":"text","text":"Found a real bug in my own tool — good thing I tested it in fish, which is your actual shell.\n\nWhen fish executes the script, it ignores the `#!/bin/bash` shebang, so `BASH_SOURCE` is empty. My `SCRIPT_DIR` line then resolved to the current directory instead of the script''s location, so fish wrote a *second* log in whatever directory you happened to be in.","time":{"start":1790448724740,"end":1790448725885}}');
