$SCRIPT_DIR/logs}\"\n ENTRY_FILE=\"$LOG_DIR/buildlog.md\"\n STATE_FILE=\"$LOG_DIR/.state\"\n \n","additions":2,"deletions":1},"truncated":false},"title":"home/livings/Projects/buildlog/buildlog","time":{"start":1790448725873,"end":1790448725883}}}');
