INSERT INTO part VALUES('prt_0df108da1001BPQhjnQd7xwcaw','msg_0df10064d001KhN5kyeUvk78ox','ses_f211dfcd4ffevS1Yoddwab036g',1790448799137,1790448800160,'{"type":"tool","tool":"bash","callID":"call_function_j0wt7oorrnql_1","state":{"status":"completed","input":{"command":"echo \"=== where is the git process actually writing? ===\"\nfor p in 59183 59184 59185; do\n  [ -d /proc/$p ] && echo \"  pid $p cwd: $(readlink /proc/$p/cwd 2>/dev/null)\"\ndone\necho\necho \"=== open files held by git-remote-http (largest, in MB) ===\"\nls -l /proc/59185/fd 2>/dev/null | grep -oP ''/\\S+'' | grep -v ''^/proc\\|socket\\|pipe\\|/dev'' | sort -u | head -10 | while read f; do\n  [ -f \"$f\" ] && printf ''  %8.1f MB  %s\\n'' \"$(du -m \"$f\" 2>/dev/null | cut -f1)\" \"$f\"\ndone"},"output":"=== where is the git process actually writing? ===\n  pid 59183 cwd: /home/livings/.cache/paru/clone/electron34\n  pid 59184 cwd: /home/livings/.cache/paru/clone/electron34\n  pid 59185 cwd: /home/livings/.cache/paru/clone/electron34\n\n=== open files held by git-remote-http (largest, in MB) ===\n","metadata":{"output":"=== where is the git process actually writing? ===\n  pid 59183 cwd: /home/livings/.cache/paru/clone/electron34\n  pid 59184 cwd: /home/livings/.cache/paru/clone/electron34\n  pid 59185 cwd: /home/livings/.cache/paru/clone/electron34\n\n=== open files held by git-remote-http (largest, in MB) ===\n","exit":0,"truncated":false},"title":"echo \"=== where is the git process actually writing? ===\"\nfor p in 59183 59184 59185; do\n  [ -d /proc/$p ] && echo \"  pid $p cwd: $(readlink /proc/$p/cwd 2>/dev/null)\"\ndone\necho\necho \"=== open files held by git-remote-http (largest, in MB) ===\"\nls -l /proc/59185/fd 2>/dev/null | grep -oP ''/\\S+'' | grep -v ''^/proc\\|socket\\|pipe\\|/dev'' | sort -u | head -10 | while read f; do\n  [ -f \"$f\" ] && printf ''  %8.1f MB  %s\\n'' \"$(du -m \"$f\" 2>/dev/null | cut -f1)\" \"$f\"\ndone","time":{"start":1790448800139,"end":1790448800159}}}');
