ache/paru/clone/electron34\n\n=== 20s growth sample ===\n  before: 32496 MB\n  after : 32692 MB\n  delta : 196 MB in 20s\n\n=== chromium clone dir ===\n  32G\t/home/livings/.cache/paru/clone/electron34/chromium-mirror\n  8.0K\t/home/livings/.cache/paru/clone/electron34/chromium-patches-132.tar.bz2\n\n=== what electron34 is fetching ===\n  6:# https://gitlab.com/Matt.Jolly/chromium-patches/-/tags\n  64:source=(\"git+https://github.com/electron/electron.git#tag=v$pkgver\"\n  65:        https://gitlab.com/Matt.Jolly/chromium-patches/-/archive/$_gcc_patches/chromium-patches-$_gcc_patches.tar.bz2\n  79:        chromium-mirror::git+https://github.com/chromium/chromium.git#tag=132.0.6834.210\n  80:        chromium-mirror_third_party_nan::git+https://github.com/nodejs/nan.git#commit=e14bdcd1f72d62bca1d541b66da43130384ec213\n  81:        chromium-mirror_third_party_electron_node::git+https://github.com/nodejs/node.git#tag=v20.19.1\n","exit":0,"truncated":false},"title":"D=~/.cache/paru/clone/electron34\necho \"=== electron34 total size ===\"\ndu -sh $D 2>/dev/null | sed ''s/^/  /''\necho\necho \"=== 20s growth sample ===\"\nb=$(du -sb $D 2>/dev/null | cut -f1)\nsleep 20\na=$(du -sb $D 2>/dev/null | cut -f1)\necho \"  before: $(( b/1024/1024 )) MB\"\necho \"  after : $(( a/1024/1024 )) MB\"\necho \"  delta : $(( (a-b)/1024/1024 )) MB in 20s\"\necho\necho \"=== chromium clone dir ===\"\ndu -sh $D/src/chromium* $D/chromium* 2>/dev/null | sed ''s/^/  /'' | head -3\necho\necho \"=== what electron34 is fetching ===\"\ngrep -nE \"^source|_electronver|chromium\" $D/PKGBUILD 2>/dev/null | head -6 | sed ''s/^/  /''","time":{"start":1790448804830,"end":1790448824859}}}');
