-1,5,50,0,0,0,0,0\n  gtk/kdeglobals:101:menuFont=Great Vibes,10,-1,5,50,0,0,0,0,0\n  gtk/kdeglobals:102:smallestReadableFont=Great Vibes,8,-1,5,50,0,0,0,0,0\n  gtk/kdeglobals:103:toolBarFont=Great Vibes,10,-1,5,50,0,0,0,0,0\n  gtk/kdeglobals:136:font=Great Vibes,10,-1,5,50,0,0,0,0,0\n  gtk/settings.ini:9:gtk-font-name=Great Vibes, 14\n  konsole/Garuda.profile:3:Font=Great Vibes,12,-1,5,50,0,0,0,0,0\n  alacritty/alacritty.toml:73:family = \"Great Vibes\"\n  alacritty/alacritty.toml:77:family = \"Great Vibes\"\n  alacritty/alacritty.toml:81:family = \"Great Vibes\"\n\n=== does repo ship a kdeglobals? ===\n  -rw-r--r-- 1 livings livings 3310 Sep 26 11:11 gtk/kdeglobals\n  99:fixed=Great Vibes,10,-1,5,4,50,0,0,0,0,0\n  100:font=Great Vibes,10,-1,5,50,0,0,0,0,0\n  136:font=Great Vibes,10,-1,5,50,0,0,0,0,0\n","exit":0,"truncated":false},"title":"cd ~/Projects/hermes-blood\necho \"=== repo sources that set font size ===\"\ngrep -rn \"Great Vibes\" gtk/ konsole/ alacritty/ 2>/dev/null | sed ''s/^/  /''\necho\necho \"=== does repo ship a kdeglobals? ===\"\nls -la gtk/kdeglobals 2>/dev/null | sed ''s/^/  /''\ngrep -nE \"^(font|fixed)=\" gtk/kdeglobals 2>/dev/null | sed ''s/^/  /''","time":{"start":1790448995339,"end":1790448995362}}}');
