===\n--- /home/livings/Projects/hermes-blood/scripts/install.sh\n+++ /home/livings/Projects/hermes-blood/scripts/install.sh\n@@ -47,15 +47,24 @@\n \n OC_CONFIG=\"$HOME/.config/opencode/opencode.jsonc\"\n if [ -f \"$OC_CONFIG\" ]; then\n     cp \"$OC_CONFIG\" \"$BACKUP_DIR/opencode.jsonc\" 2>/dev/null || true\n-    if grep -q ''\"theme\"'' \"$OC_CONFIG\" 2>/dev/null; then\n-        sed -i -E ''s/(\"theme\"[[:space:]]*:[[:space:]]*)\"[^\"]*\"/\\1\"voidlit\"/'' \"$OC_CONFIG\"\n-    elif grep -q ''^\\s*\\{'' \"$OC_CONFIG\" 2>/dev/null; then\n-        sed -i -E ''s/^(\\s*)\\}$/\\1  \"theme\": \"voidlit\"\\n}/'' \"$OC_CONFIG\"\n-    else\n-        printf ''{\\n  \"$schema\": \"https://opencode.ai/config.json\",\\n  \"theme\": \"voidlit\"\\n}\\n'' > \"$OC_CONFIG\"\n-    fi\n+    # Rewrite via python so we can never emit malformed JSON (sed on jsonc is fragile:\n+    # it mangles URLs, misses commas, and breaks on trailing comments).\n+    python3 - \"$OC_CONFIG\" << ''PYEOF'' 2>/dev/null || echo \"  [!] could not auto-set theme; set \\\"theme\\\": \\\"voidlit\\\" manually\"\n+import json, re, sys\n+p = sys.argv[1]\n+raw = open(p).read()\n+# strip // and /* */ comments that are not inside strings\n+stripped = re.sub(r''/\\*.*?\\*/'', '''', raw, flags=re.S)\n+stripped = re.sub(r''(?m)(^\\s*|[:,{}\\[\\]])//.*$'', r''\\1'', stripped)\n+try:\n+    cfg = json.loads(stripped)\n+except Exception:\n+    sys.exit(1)\n+cfg[''theme''] = ''voidlit''\n+open(p, ''w'').write(json.dumps(cfg, indent=2) + ''\\n'')\n+PYEOF\n fi\n echo \"  [✓] OpenCode (voidlit installed + activated)\"\n \n # Hermes\n","additions":16,"deletions":7},"truncated":false},"title":"home/livings/Projects/hermes-blood/scripts/install.sh","time":{"start":1790449096356,"end":1790449096368}}}');
