INSERT INTO part VALUES('prt_0df18ac050013TqaZ85LGeOI3r','msg_0df18a44f0010HSEOcm67JAZj0','ses_f211dfcd4ffevS1Yoddwab036g',1790449331205,1790449331451,'{"type":"tool","tool":"edit","callID":"call_function_pv1h74zn4m8m_1","state":{"status":"completed","input":{"filePath":"/home/livings/Projects/zen-hardening/99-hardening.conf","oldString":"# Restrict unprivileged users to their own device nodes\nfs.protected_regular = 1\n# Do not allow users to see other users'' processes (already 1)\nfs.protected_fifos = 2\nfs.protected_regular = 2","newString":"# Restrict unprivileged users to their own device nodes (1 = safe default)\nfs.protected_regular = 1\n# FIFOs in world-writable dirs: only owner may read/write (2 = full)\nfs.protected_fifos = 2"},"output":"Edit applied successfully.","metadata":{"diagnostics":{},"diff":"Index: /home/livings/Projects/zen-hardening/99-hardening.conf\n===================================================================\n--- /home/livings/Projects/zen-hardening/99-hardening.conf\n+++ /home/livings/Projects/zen-hardening/99-hardening.conf\n@@ -44,13 +44,12 @@\n # --- Filesystem ---\n # Hardlink / symlink following only within the same filesystem\n fs.protected_hardlinks = 1\n fs.protected_symlinks = 1\n-# Restrict unprivileged users to their own device nodes\n+# Restrict unprivileged users to their own device nodes (1 = safe default)\n fs.protected_regular = 1\n-# Do not allow users to see other users'' processes (already 1)\n+# FIFOs in world-writable dirs: only owner may read/write (2 = full)\n fs.protected_fifos = 2\n-fs.protected_regular = 2\n \n # --- Process / memory ---\n # Randomize memory layout\n kernel.randomize_va_space = 2\n","filediff":{"file":"/home/livings/Projects/zen-hardening/99-hardening.conf","patch":"Index: /home/livings/Projects/zen-hardening/99-hardening.conf\n===================================================================\n--- /home/livings/Projects/zen-hardening/99-hardening.conf\n+++ /home/livings/Projects/zen-hardening/99-hardening.conf\n@@ -44,13 +44,12 @@\n # --- Filesystem ---\n # Hardlink / symlink following only within the same filesystem\n fs.protected_hardlinks = 1\n fs.protected_symlinks = 1\n-# Restrict unprivileged users to their own device nodes\n+# Restrict unprivileged users to their own device nodes (1 = safe default)\n fs.protected_regular = 1\n-# Do not allow users to see other users'' processes (already 1)\n+# FIFOs in world-writable dirs: only owner may read/write (2 = full)\n fs.protected_fifos = 2\n-fs.protected_regular = 2\n \n # --- Process / memory ---\n # Randomize memory layout\n kernel.randomize_va_space = 2\n","additions":2,"deletions":3},"truncated":false},"title":"home/livings/Projects/zen-hardening/99-hardening.conf","time":{"start":1790449331444,"end":1790449331451}}}');
