INSERT INTO part VALUES('prt_0df1a969d001njQafcm2cqc8TP','msg_0df1a8e57001RI2CfDDbYICvIQ','ses_f20e5cfc2ffeSFa4odnoYLiUOk',1790449456798,1790449457242,'{"type":"tool","tool":"bash","callID":"call_function_dymyqiso2p0x_1","state":{"status":"completed","input":{"command":"pacman -Ql pacman | grep -i \"makepkg/lib\" | head -20; echo \"---\"; grep -n \"makepkg\" /etc/makepkg.conf | grep -i libdir"},"output":"---\n","metadata":{"output":"---\n","exit":1,"truncated":false},"title":"pacman -Ql pacman | grep -i \"makepkg/lib\" | head -20; echo \"---\"; grep -n \"makepkg\" /etc/makepkg.conf | grep -i libdir","time":{"start":1790449457205,"end":1790449457241}}}');
INSERT INTO part VALUES('prt_0df1a9839001BF7q5nNyqVFn88','msg_0df1a8e57001RI2CfDDbYICvIQ','ses_f20e5cfc2ffeSFa4odnoYLiUOk',1790449457209,1790449457224,'{"type":"tool","tool":"bash","callID":"call_function_dymyqiso2p0x_2","state":{"status":"completed","input":{"command":"sed -n ''440,500p'' /home/livings/.cache/paru/clone/electron34/PKGBUILD"},"output":"  # [libvpx]=libvpx\n  # [libwebp]=\"libwebp libwebpdemux.so libwebpmux.so libwebp.so\" # //third_party/libavif:libavif_enc needs //third_party/libwebp:libwebp_sharpyuv\n  [libxml]=\"libxml2 libxml2.so\"\n  [libxslt]=\"libxslt libxslt.so\"\n  [opus]=\"opus libopus.so\"\n  # [re2]=\"re2 libre2.so\" # needs libstdc++\n  # [snappy]=snappy # libsnappy.so # needs libstdc++\n  # [woff2]=\"woff2 libwoff2dec.so\" # needs libstdc++\n  [zlib]=minizip # libminizip.so\n)\n_unwanted_bundled_libs=(\n  $(printf \"%s\\n\" ${!_system_libs[@]} | sed ''s/^libjpeg$/&_turbo/'')\n)\ndepends+=(${_system_libs[@]})\n\n_update_sources() {\n  python makepkg-source-roller.py update \"v$pkgver\" \"$pkgname\"\n  updpkgsums\n}\n\nprepare() {\n  sed -i \"s|@ELECTRON@|${pkgname}|\" electron-launcher.sh\n  sed -i \"s|@ELECTRON@|${pkgname}|\" electron.desktop\n  sed -i \"s|@ELECTRON_NAME@|Electron ${_major_ver}|\" electron.desktop\n\n  rustup toolchain update --profile minimal 1.86.0\n  rustup default 1.86.0\n\n  cp -r chromium-mirror_third_party_depot_tools depot_tools\n  export PATH+=\":$PWD/depot_tools\" DEPOT_TOOLS_UPDATE=0\n  #export VPYTHON_BYPASS=''manually managed python not supported by chrome operations''\n\n  echo \"Putting together electron sources\"\n  # Generate gclient gn args file and prepare-electron-source-tree.sh\n  python makepkg-source-roller.py generate electron/DEPS $pkgname\n  rbash prepare-electron-source-tree.sh \"$CARCH\"\n  mv electron src/electron\n\n  echo \"Running hooks...\"\n  # depot_tools/gclient.py runhooks\n  src/build/landmines.py\n  src/build/util/lastchange.py -o src/build/util/LASTCHANGE\n  src/build/util/lastchange.py -m GPU_LISTS_VERSION \\\n    --revision-id-only --header src/gpu/config/gpu_lists_version.h\n  src/build/util/lastchange.py -m SKIA_COMMIT_HASH \\\n    -s src/third_party/skia --header src/skia/ext/skia_commit_hash.h\n  src/build/util/lastchange.py \\\n    -s src/third_party/dawn --revision src/gpu/webgpu/DAWN_VERSION\n  src/tools/update_pgo_profiles.py --target=linux update \\\n    --gs-url-base=chromium-optimization-profiles/pgo_profiles\n\n  # https://gitlab.archlinux.org/archlinux/packaging/packages/electron32/-/issues/1\n  src/third_party/node/update_npm_deps\n\n  src/electron/script/apply_all_patches.py \\\n      src/electron/patches/config.json\n\n  # https://github.com/nodejs/node/issues/48444\n  export UV_USE_IO_URING=0\n\n  pushd src\n","metadata":{"output":"  # [libvpx]=libvpx\n  # [libwebp]=\"libwebp libwebpdemux.so libwebpmux.so libwebp.so\" # //third_party/libavif:libavif_enc needs //third_party/libwebp:libwebp_sharpyuv\n  [libxml]=\"libxml2 libxml2.so\"\n  [libxslt]=\"libxslt libxslt.so\"\n  [opus]=\"opus libopus.so\"\n  # [re2]=\"re2 libre2.so\" # needs libstdc++\n  # [snappy]=snappy # libsnappy.so # needs libstdc++\n  # [woff2]=\"woff2 libwoff2dec.so\" # needs libstdc++\n  [zlib]=minizip # libminizip.so\n)\n_unwanted_bundled_libs=(\n  $(printf \"%s\\n\" ${!_system_libs[@]} | sed ''s/^libjpeg$/&_turbo/'')\n)\ndepends+=(${_system_libs[@]})\n\n_update_sources() {\n  python makepkg-source-roller.py update \"v$pkgver\" \"$pkgname\"\n  updpkgsums\n}\n\nprepare() {\n  sed -i \"s|@ELECTRON@|${pkgname}|\" electron-launcher.sh\n  sed -i \"s|@ELECTRON@|${pkgname}|\" electron.desktop\n  sed -i \"s|@ELECTRON_NAME@|Electron ${_major_ver}|\" electron.desktop\n\n  rustup toolchain update --profile minimal 1.86.0\n  rustup default 1.86.0\n\n  cp -r chromium-mirror_third_party_depot_tools depot_tools\n  export PATH+=\":$PWD/depot_tools\" DEPOT_TOOLS_UPDATE=0\n  #export VPYTHON_BYPASS=''manually managed python not supported by chrome operations''\n\n  echo \"Putting together electron sources\"\n  # Generate gclient gn args file and prepare-electron-source-tree.sh\n  python makepkg-source-roller.py generate electron/DEPS $pkgname\n  rbash prepare-electron-source-tree.sh \"$CARCH\"\n  mv electron src/electron\n\n  echo \"Running hooks...\"\n  # depot_tools/gclient.py runhooks\n  src/build/landmines.py\n  src/build/util/lastchange.py -o src/build/util/LASTCHANGE\n  src/build/util/lastchange.py -m GPU_LISTS_VERSION \\\n    --revision-id-only --header src/gpu/config/gpu_lists_version.h\n  src/build/util/lastchange.py -m SKIA_COMMIT_HASH \\\n    -s src/third_party/skia --header src/skia/ext/skia_commit_hash.h\n  src/build/util/lastchange.py \\\n    -s src/third_party/dawn --revision src/gpu/webgpu/DAWN_VERSION\n  src/tools/update_pgo_profiles.py --target=linux update \\\n    --gs-url-base=chromium-optimization-profiles/pgo_profiles\n\n  # https://gitlab.archlinux.org/archlinux/packaging/packages/electron32/-/issues/1\n  src/third_party/node/update_npm_deps\n\n  src/electron/script/apply_all_patches.py \\\n      src/electron/patches/config.json\n\n  # https://github.com/nodejs/node/issues/48444\n  export UV_USE_IO_URING=0\n\n  pushd src\n","exit":0,"truncated":false},"title":"sed -n ''440,500p'' /home/livings/.cache/paru/clone/electron34/PKGBUILD","time":{"start":1790449457212,"end":1790449457224}}}');
