s/16/snapshot/usr/share/makepkg/source/git.sh\n/.snapshots/17/snapshot/usr/share/makepkg/source/git.sh\n/.snapshots/18/snapshot/usr/share/makepkg/source/git.sh\n/.snapshots/19/snapshot/usr/share/makepkg/source/git.sh\n/.snapshots/20/snapshot/usr/share/makepkg/source/git.sh\n/.snapshots/21/snapshot/usr/share/makepkg/source/git.sh\n","exit":1,"truncated":false},"title":"ls /usr/share/makepkg/ 2>/dev/null; echo \"--- find ---\"; find / -name \"git.sh\" -path \"*makepkg*\" 2>/dev/null","time":{"start":1790449463162,"end":1790449467344}}}');
