INSERT INTO part VALUES('prt_0df202f6a0011Ad1KLDgBpA5M4','msg_0df2028cf0010Gb8NyooPMVFY6','ses_f211dfcd4ffevS1Yoddwab036g',1790449823594,1790449825544,'{"type":"text","text":"Two problems. The sudo rule can''t tell `livings` from `attacker` — that''s the serious one, since it fired on your own commands. Fixing both:","time":{"start":1790449823594,"end":1790449825542}}');
INSERT INTO part VALUES('prt_0df2033260018agDm0ByRohI5Q','msg_0df2028cf0010Gb8NyooPMVFY6','ses_f211dfcd4ffevS1Yoddwab036g',1790449824550,1790449825563,'{"type":"tool","tool":"edit","callID":"call_function_4bhbkuzp764w_1","state":{"status":"completed","input":{"oldString":"    (\n        \"sudo_failure\",\n        re.compile(r\"sudo:.*(incorrect password|authentication failure|a password is required)\", re.I),\n        \"UNAUTHORIZED PRIVILEGE ESCALATION\",\n        \"critical\",\n    ),","filePath":"/home/livings/Projects/nyan-gfsf-alert/gfsf-watch.py","newString":"    (\n        # sudo: the actor name is the field right after \"sudo:\". \"a password\n        # is required\" fires on every non-interactive sudo attempt, including\n        # the admin''s own — so only flag it when the actor is NOT the local\n        # user. \"incorrect password\" is always a real failure.\n        \"sudo_failure\",\n        re.compile(r\"sudo:.*incorrect password\", re.I),\n        \"UNAUTHORIZED PRIVILEGE ESCALATION\",\n        \"critical\",\n    ),\n    (\n        # Non-interactive sudo attempt from someone other than us.\n        \"sudo_unattended\",\n        re.compile(r\"sudo:\\s*(?P<actor>\\w+)\\s*:.*a password is required\", re.I),\n        \"UNAUTHORIZED PRIVILEGE ESCALATION\",\n        \"critical\",\n    ),"},"output":"Edit applied successfully.","metadata":{"diagnostics":{},"diff":"Index: /home/livings/Projects/nyan-gfsf-alert/gfsf-watch.py\n===================================================================\n--- /home/livings/Projects/nyan-gfsf-alert/gfsf-watch.py\n+++ /home/livings/Projects/nyan-gfsf-alert/gfsf-watch.py\n@@ -65,14 +65,25 @@\n     \"ACCOUNT LOCKOUT TRIGGERED\",\n     \"critical\",\n ),\n (\n+    # sudo: the actor name is the field right after \"sudo:\". \"a password\n+    # is required\" fires on every non-interactive sudo attempt, including\n+    # the admin''s own — so only flag it when the actor is NOT the local\n+    # user. \"incorrect password\" is always a real failure.\n     \"sudo_failure\",\n-    re.compile(r\"sudo:.*(incorrect password|authentication failure|a password is required)\", re.I),\n+    re.compile(r\"sudo:.*incorrect password\", re.I),\n     \"UNAUTHORIZED PRIVILEGE ESCALATION\",\n     \"critical\",\n ),\n (\n+    # Non-interactive sudo attempt from someone other than us.\n+    \"sudo_unattended\",\n+    re.compile(r\"sudo:\\s*(?P<actor>\\w+)\\s*:.*a password is required\", re.I),\n+    \"UNAUTHORIZED PRIVILEGE ESCALATION\",\n+    \"critical\",\n+),\n+(\n     \"sddm_failure\",\n     re.compile(r\"(sddm|lightdm|gdm).*(failed|auth|login).*fail\", re.I),\n     \"LOGIN SCREEN AUTH FAILURE\",\n     \"critical\",\n","filediff":{"file":"/home/livings/Projects/nyan-gfsf-alert/gfsf-watch.py","patch":"Index: /home/livings/Projects/nyan-gfsf-alert/gfsf-watch.py\n===================================================================\n--- /home/livings/Projects/nyan-gfsf-alert/gfsf-watch.py\n+++ /home/livings/Projects/nyan-gfsf-alert/gfsf-watch.py\n@@ -65,14 +65,25 @@\n     \"ACCOUNT LOCKOUT TRIGGERED\",\n     \"critical\",\n ),\n (\n+    # sudo: the actor name is the field right after \"sudo:\". \"a password\n+    # is required\" fires on every non-interactive sudo attempt, including\n+    # the admin''s own — so only flag it when the actor is NOT the local\n+    # user. \"incorrect password\" is always a real failure.\n     \"sudo_failure\",\n-    re.compile(r\"sudo:.*(incorrect password|authentication failure|a password is required)\", re.I),\n+    re.compile(r\"sudo:.*incorrect password\", re.I),\n     \"UNAUTHORIZED PRIVILEGE ESCALATION\",\n     \"critical\",\n ),\n (\n+    # Non-interactive sudo attempt from someone other than us.\n+    \"sudo_unattended\",\n+    re.compile(r\"sudo:\\s*(?P<actor>\\w+)\\s*:.*a password is required\", re.I),\n+    \"UNAUTHORIZED PRIVILEGE ESCALATION\",\n+    \"critical\",\n+),\n+(\n     \"sddm_failure\",\n     re.compile(r\"(sddm|lightdm|gdm).*(failed|auth|login).*fail\", re.I),\n     \"LOGIN SCREEN AUTH FAILURE\",\n     \"critical\",\n","additions":12,"deletions":1},"truncated":false},"title":"home/livings/Projects/nyan-gfsf-alert/gfsf-watch.py","time":{"start":1790449825537,"end":1790449825562}}}');
