INSERT INTO part VALUES('prt_0df203cc200102MUiY9CJ7rHQp','msg_0df203730001egG5vEKcgeOrO5','ses_f211dfcd4ffevS1Yoddwab036g',1790449827010,1790449827992,'{"type":"tool","tool":"edit","callID":"call_function_jlkk5uxpmadb_1","state":{"status":"completed","input":{"oldString":"    (\n        \"ssh_auth_failure\",\n        re.compile(r\"Failed password|Invalid user|authentication failure|PAM.*authentication\", re.I),\n        \"SSH AUTHENTICATION FAILURE\",\n        \"critical\",\n    ),","filePath":"/home/livings/Projects/nyan-gfsf-alert/gfsf-watch.py","newString":"    (\n        \"login_failure\",\n        re.compile(\n            r\"(Failed password for (invalid user )?\"\n            r\"|Invalid user \\S+ from\"\n            r\"|FAILED LOGIN \\d+ FROM\"\n            r\"|pam_unix\\([^)]*:auth\\): authentication failure)\",\n            re.I,\n        ),\n        \"AUTHENTICATION FAILURE\",\n        \"critical\",\n    ),"},"output":"Edit applied successfully.","metadata":{"diagnostics":{},"diff":"Index: /home/livings/Projects/nyan-gfsf-alert/gfsf-watch.py\n===================================================================\n--- /home/livings/Projects/nyan-gfsf-alert/gfsf-watch.py\n+++ /home/livings/Projects/nyan-gfsf-alert/gfsf-watch.py\n@@ -45,11 +45,17 @@\n # Severity: \"critical\" = credential attack on a login surface\n #           \"warning\"  = privilege escalation attempt or physical attach\n RULES = [\n     (\n-        \"ssh_auth_failure\",\n-        re.compile(r\"Failed password|Invalid user|authentication failure|PAM.*authentication\", re.I),\n-        \"SSH AUTHENTICATION FAILURE\",\n+        \"login_failure\",\n+        re.compile(\n+            r\"(Failed password for (invalid user )?\"\n+            r\"|Invalid user \\S+ from\"\n+            r\"|FAILED LOGIN \\d+ FROM\"\n+            r\"|pam_unix\\([^)]*:auth\\): authentication failure)\",\n+            re.I,\n+        ),\n+        \"AUTHENTICATION FAILURE\",\n         \"critical\",\n     ),\n     (\n         # Match pam_faillock''s ACTUAL denial output, not the bare word\n","filediff":{"file":"/home/livings/Projects/nyan-gfsf-alert/gfsf-watch.py","patch":"Index: /home/livings/Projects/nyan-gfsf-alert/gfsf-watch.py\n===================================================================\n--- /home/livings/Projects/nyan-gfsf-alert/gfsf-watch.py\n+++ /home/livings/Projects/nyan-gfsf-alert/gfsf-watch.py\n@@ -45,11 +45,17 @@\n # Severity: \"critical\" = credential attack on a login surface\n #           \"warning\"  = privilege escalation attempt or physical attach\n RULES = [\n     (\n-        \"ssh_auth_failure\",\n-        re.compile(r\"Failed password|Invalid user|authentication failure|PAM.*authentication\", re.I),\n-        \"SSH AUTHENTICATION FAILURE\",\n+        \"login_failure\",\n+        re.compile(\n+            r\"(Failed password for (invalid user )?\"\n+            r\"|Invalid user \\S+ from\"\n+            r\"|FAILED LOGIN \\d+ FROM\"\n+            r\"|pam_unix\\([^)]*:auth\\): authentication failure)\",\n+            re.I,\n+        ),\n+        \"AUTHENTICATION FAILURE\",\n         \"critical\",\n     ),\n     (\n         # Match pam_faillock''s ACTUAL denial output, not the bare word\n","additions":9,"deletions":3},"truncated":false},"title":"home/livings/Projects/nyan-gfsf-alert/gfsf-watch.py","time":{"start":1790449827979,"end":1790449827991}}}');
