INSERT INTO part VALUES('prt_0df204755001MQC41J8PDa4jK0','msg_0df2040aa001S4JiMrdHebQ6PA','ses_f211dfcd4ffevS1Yoddwab036g',1790449829717,1790449831821,'{"type":"tool","tool":"edit","callID":"call_function_m6z9jokmoz1f_1","state":{"status":"completed","input":{"oldString":"def classify(lines: list[str]) -> list[dict]:\n    \"\"\"Run every rule over every line, collect unique hits.\"\"\"\n    found: dict[str, dict] = {}\n    for line in lines:\n        for name, pattern, label, severity in RULES:\n            if not pattern.search(line):\n                continue\n            key = f\"{name}:{label}\"\n            if key in found:\n                found[key][\"count\"] += 1\n            else:\n                found[key] = {\n                    \"rule\": name, \"label\": label,\n                    \"severity\": severity, \"count\": 1,\n                    \"sample\": line.strip()[:200],\n                }\n    return list(found.values())","filePath":"/home/livings/Projects/nyan-gfsf-alert/gfsf-watch.py","newString":"LOCAL_USER = os.environ.get(\"USER\") or getpass.getuser()\n\n\ndef is_local_admin_actor(match: re.Match) -> bool:\n    \"\"\"\n    True if the sudo actor is the logged-in user doing their own thing.\n    Guards the rules that would otherwise fire on normal admin activity.\n    \"\"\"\n    actor = (match.groupdict().get(\"actor\") or \"\").strip().lower()\n    return bool(actor) and actor == LOCAL_USER.lower()\n\n\ndef classify(lines: list[str]) -> list[dict]:\n    \"\"\"Run every rule over every line, collect unique hits.\"\"\"\n    found: dict[str, dict] = {}\n    for line in lines:\n        for name, pattern, label, severity in RULES:\n            m = pattern.search(line)\n            if not m:\n                continue\n            # Skip our own sudo attempts — not an intrusion.\n            if name == \"sudo_unattended\" and is_local_admin_actor(m):\n                continue\n            key = f\"{name}:{label}\"\n            if key in found:\n                found[key][\"count\"] += 1\n            else:\n                found[key] = {\n                    \"rule\": name, \"label\": label,\n                    \"severity\": severity, \"count\": 1,\n                    \"sample\": line.strip()[:200],\n                }\n    return list(found.values())"},"output":"Edit applied successfully.","metadata":{"diagnostics":{},"diff":"Index: /home/livings/Projects/nyan-gfsf-alert/gfsf-watch.py\n===================================================================\n--- /home/livings/Projects/nyan-gfsf-alert/gfsf-watch.py\n+++ /home/livings/Projects/nyan-gfsf-alert/gfsf-watch.py\n@@ -161,15 +161,31 @@\n         pass\n     return \"\"\n \n \n+LOCAL_USER = os.environ.get(\"USER\") or getpass.getuser()\n+\n+\n+def is_local_admin_actor(match: re.Match) -> bool:\n+    \"\"\"\n+    True if the sudo actor is the logged-in user doing their own thing.\n+    Guards the rules that would otherwise fire on normal admin activity.\n+    \"\"\"\n+    actor = (match.groupdict().get(\"actor\") or \"\").strip().lower()\n+    return bool(actor) and actor == LOCAL_USER.lower()\n+\n+\n def classify(lines: list[str]) -> list[dict]:\n     \"\"\"Run every rule over every line, collect unique hits.\"\"\"\n     found: dict[str, dict] = {}\n     for line in lines:\n         for name, pattern, label, severity in RULES:\n-            if not pattern.search(line):\n+            m = pattern.search(line)\n+            if not m:\n                 continue\n+            # Skip our own sudo attempts — not an intrusion.\n+            if name == \"sudo_unattended\" and is_local_admin_actor(m):\n+                continue\n             key = f\"{name}:{label}\"\n             if key in found:\n                 found[key][\"count\"] += 1\n             else:\n","filediff":{"file":"/home/livings/Projects/nyan-gfsf-alert/gfsf-watch.py","patch":"Index: /home/livings/Projects/nyan-gfsf-alert/gfsf-watch.py\n===================================================================\n--- /home/livings/Projects/nyan-gfsf-alert/gfsf-watch.py\n+++ /home/livings/Projects/nyan-gfsf-alert/gfsf-watch.py\n@@ -161,15 +161,31 @@\n         pass\n     return \"\"\n \n \n+LOCAL_USER = os.environ.get(\"USER\") or getpass.getuser()\n+\n+\n+def is_local_admin_actor(match: re.Match) -> bool:\n+    \"\"\"\n+    True if the sudo actor is the logged-in user doing their own thing.\n+    Guards the rules that would otherwise fire on normal admin activity.\n+    \"\"\"\n+    actor = (match.groupdict().get(\"actor\") or \"\").strip().lower()\n+    return bool(actor) and actor == LOCAL_USER.lower()\n+\n+\n def classify(lines: list[str]) -> list[dict]:\n     \"\"\"Run every rule over every line, collect unique hits.\"\"\"\n     found: dict[str, dict] = {}\n     for line in lines:\n         for name, pattern, label, severity in RULES:\n-            if not pattern.search(line):\n+            m = pattern.search(line)\n+            if not m:\n                 continue\n+            # Skip our own sudo attempts — not an intrusion.\n+            if name == \"sudo_unattended\" and is_local_admin_actor(m):\n+                continue\n             key = f\"{name}:{label}\"\n             if key in found:\n                 found[key][\"count\"] += 1\n             else:\n","additions":17,"deletions":1},"truncated":false},"title":"home/livings/Projects/nyan-gfsf-alert/gfsf-watch.py","time":{"start":1790449831812,"end":1790449831820}}}');
