INSERT INTO part VALUES('prt_0df2066e6001teFslTLiNyS0bw','msg_0df206269001x3CXto2Meae7DV','ses_f211dfcd4ffevS1Yoddwab036g',1790449837798,1790449849691,'{"type":"text","text":"8/8 attacks caught, 0/5 false positives. Now the pixel cat:","time":{"start":1790449837798,"end":1790449849690}}');
INSERT INTO part VALUES('prt_0df2067cd001v7sVApsIgq4RkN','msg_0df206269001x3CXto2Meae7DV','ses_f211dfcd4ffevS1Yoddwab036g',1790449838029,1790449849695,'{"type":"tool","tool":"write","callID":"call_function_l65yu785bhgo_1","state":{"status":"completed","input":{"content":"#!/usr/bin/env python3\n\"\"\"\nalert.py — fullscreen pixel-art nyan cat intrusion alert.\n\nUsage:  ./alert.py ''<json payload>''\n        ./alert.py --demo      # trigger with fake data, for testing\n\nDrawn with PyQt6. Falls back to zenity/kdialog, then to a terminal banner,\nso an alert ALWAYS reaches you even if the GUI stack is unhappy.\n\"\"\"\n\nimport json\nimport subprocess\nimport sys\nimport time\n\nDURATION_MS = 12000\n\nCAT = [\n    \"..BBBBB...\",\n    \".BBBBBBB..\",\n    \"BBBBBBBBBB\",\n    \"BBKBBBBKBB\",\n    \"BBBBBBBBBB\",\n    \"BBBBBBBBBB\",\n    \"BBKKKKKBBB\",\n    \"BBBBBBWBBB\",\n    \"BBBBBBBBBB\",\n    \"BBBBBBBBBB\",\n    \"BBKBBBBKBB\",\n    \".BBBBBBB..\",\n    \"..BBBBB...\",\n]\n\nFLAME = [\n    \"..Y.......\",\n    \".YY.Y.Y...\",\n    \"..Y...Y...\",\n    \".Y.Y.Y.Y..\",\n    \"..Y...Y...\",\n    \"..Y.Y.Y...\",\n    \".OYO.YO...\",\n    \"..O...O...\",\n]\n\nDEMO = {\n    \"severity\": \"critical\",\n    \"events\": [\n        {\"rule\": \"login_failure\", \"label\": \"AUTHENTICATION FAILURE\",\n         \"severity\": \"critical\", \"count\": 42, \"sample\": \"Failed password for invalid user admin from 203.0.113.5\"},\n    ],\n    \"timestamp\": \"2026-09-26 12:30:00\",\n}\n\n\ndef gui(payload: dict) -> int:\n    from PyQt6.QtCore import Qt, QTimer\n    from PyQt6.QtGui import QColor, QFont, QPainter\n    from PyQt6.QtWidgets import QApplication, QWidget\n\n    sev = payload.get(\"severity\", \"warning\")\n    crit = sev == \"critical\"\n    bg = QColor(\"#120000\") if crit else QColor(\"#1a1400\")\n    body = QColor(\"#ff2d2d\") if crit else QColor(\"#ffb000\")\n    light = QColor(\"#ffd7d7\") if crit else QColor(\"#fff0c0\")\n    ink = QColor(\"#1a0000\")\n    flame_cols = [QColor(\"#ff3c00\"), QColor(\"#ff8c00\"), QColor(\"#ffd000\")]\n\n    class Alert(QWidget):\n        def __init__(self):\n            super().__init__()\n            self.setWindowTitle(\"INTRUSION ALERT\")\n            self.frames = 0\n\n        def pixel_map(self, rows, palette, cell, ox, oy):\n            out = []\n            for r, row in enumerate(rows):\n                for c, ch in enumerate(row):\n                    if ch == \".\":\n                        continue\n                    color = palette.get(ch)\n                    if color:\n                        out.append((ox + c * cell, oy + r * cell, cell, cell, color))\n            return out\n\n        def paintEvent(self, ev):\n            p = QPainter(self)\n            p.fillRect(self.rect(), bg)\n\n            # drifting starfield, like nyan cat\n            w, h = self.width(), self.height()\n            for i in range(60):\n                x = (i * 137 + self.frames * 7) % w\n                y = (i * 83) % (h // 2)\n                p.fillRect(x, y, 3, 3, QColor(\"#332222\"))\n\n            cw = min(w, 1100) // 24\n            ch = cw // 2\n            total_h = len(CAT) * ch + len(FLAME) * ch\n            ox = (w - 13 * cw) // 2\n            oy = (h - total_h) // 2 - 40\n\n            pal = {\"B\": body, \"K\": ink, \"W\": QColor(\"#ffffff\")}\n            # trail\n            for i, col in enumerate(flame_cols[:2]):\n                p.setPen(col)\n                p.setOpacity(0.25 - i * 0.1)\n                p.drawRect(ox - (3 - i) * cw * 2, oy + ch, 3 * cw * 2, len(CAT) * ch)\n            p.setOpacity(1.0)\n\n            for x, y, ww, hh, color in self.pixel_map(CAT, pal, cw, ox, oy):\n                p.fillRect(x, y, ww, hh, color)\n\n            # animated flames: cycle the palette by frame\n            fpal = {\".\", \"Y\": flame_cols[self.frames % 3], \"O\": flame_cols[0]}\n            foy = oy + len(CAT) * ch\n            for x, y, ww, hh, color in self.pixel_map(FLAME, fpal, ch, ox, foy):\n                p.fillRect(x, y, ww, hh, color)\n\n            # GFSF wordmark\n            p.setPen(light)\n            f = QFont(\"DejaVu Sans Mono\", max(28, cw), QFont.Bold)\n            p.setFont(f)\n            p.drawText(0, foy + len(FLAME) * ch + 70, w, 60,\n                       Qt.AlignmentFlag.AlignHCenter, \"GFSF\")\n\n            # banner\n            p.setPen(QColor(\"#ff2d2d\") if crit else QColor(\"#ffb000\"))\n            bf = QFont(\"DejaVu Sans\", 34, QFont.Bold)\n            p.setFont(bf)\n            p.drawText(0, 60, w, 50, Qt.AlignmentFlag.AlignHCenter,\n                       \"INTRUSION DETECTED\" if crit else \"SECURITY EVENT\")\n\n            # details\n            p.setPen(light)\n            sf = QFont(\"DejaVu Sans Mono\", 13)\n            p.setFont(sf)\n            lines = [f\"severity: {sev}\",\n                     f\"time:     {payload.get(''timestamp'')}\"]\n            for e in payload.get(\"events\", [])[:6]:\n                lines.append(f\"  [{e.get(''count'')}x] {e.get(''label'')}\")\n                if e.get(\"sample\"):\n                    lines.append(f\"        {e[''sample''][:88]}\")\n            y = h - 30 - 22 * len(lines)\n            p.drawText(60, y, w - 120, 22 * len(lines) + 20,\n                       Qt.AlignmentFlag.AlignLeft, \"\\n\".join(lines))\n\n            p.drawText(0, h - 30, w, 20, Qt.AlignmentFlag.AlignHCenter,\n                       \"press ESC or click to dismiss\")\n\n        def keyPressEvent(self, e):\n            if e.key() == Qt.Key.Key_Escape:\n                self.close()\n\n    class Ticker(Alert):\n        def timerEvent(self, e):\n            self.frames += 1\n            self.update()\n\n    app = QApplication(sys.argv)\n    app.setQuitOnLastWindowClosed(True)\n    w = Ticker()\n    w.setWindowFlags(Qt.WindowType.FramelessWindowHint | Qt.WindowType.WindowStaysOnTopHint)\n    w.showFullScreen()\n    t = QTimer()\n    t.timeout.connect(lambda: (w.frames := w.frames + 1, w.update()))\n    t.start(120)\n    QTimer.singleShot(DURATION_MS, w.close)\n    return app.exec()\n\n\ndef terminal(payload: dict) -> int:\n    sev = payload.get(\"severity\", \"?\")\n    bar = \"!\" * 78\n    print(f\"\\n{bar}\\n{''!! INTRUSION DETECTED !!'' if sev == ''critical'' else ''!! SECURITY EVENT !!'':^78}\\n{bar}\")\n    print(f\"  severity : {sev}\")\n    print(f\"  time     : {payload.get(''timestamp'')}\")\n    for e in payload.get(\"events\", []):\n        print(f\"  [{e.get(''count'')}x] {e.get(''label'')}\")\n        if e.get(\"sample\"):\n            print(f\"       {e[''sample''][:88]}\")\n    print(f\"{bar}\\n\")\n    return 0\n\n\ndef main() -> int:\n    if len(sys.argv) > 1 and sys.argv[1] == \"--demo\":\n        payload = DEMO\n    elif len(sys.argv) > 1:\n        try:\n            payload = json.loads(sys.argv[1])\n        except Exception:\n            payload = DEMO\n    else:\n        payload = DEMO\n\n    try:\n        return gui(payload)\n    except Exception as exc:\n        print(f\"[alert] GUI unavailable ({exc}); falling back\", file=sys.stderr)\n        return terminal(payload)\n\n\nif __name__ == \"__main__\":\n    sys.exit(main())\n","filePath":"/home/livings/Projects/nyan-gfsf-alert/alert.py"},"output":"Wrote file successfully.","metadata":{"diagnostics":{},"filepath":"/home/livings/Projects/nyan-gfsf-alert/alert.py","exists":false,"truncated":false},"title":"home/livings/Projects/nyan-gfsf-alert/alert.py","time":{"start":1790449849687,"end":1790449849694}}}');
