itory\necho \"=== remote url (must match makepkg expectation) ===\"; git -C \"$DEST\" config --get remote.origin.url\necho \"=== tag resolves to ===\"; git -C \"$DEST\" rev-parse \"132.0.6834.210^{commit}\"\necho \"=== tag name check (git.sh:133 forgery guard) ===\"; git -C \"$DEST\" tag -l --format=''%(tag)'' \"132.0.6834.210\"\necho \"=== count of tags present ===\"; git -C \"$DEST\" tag -l | wc -l\necho \"=== count of refs present ===\"; git -C \"$DEST\" for-each-ref --format=''%(refname)'' | wc -l","time":{"start":1790449956936,"end":1790449956963}}}');
