etch --all -p 2>&1 | tail -5\necho \"shallow after fetch: $(git -C \"$DEST\" rev-parse --is-shallow-repository)\"\necho \"refs after fetch: $(git -C \"$DEST\" for-each-ref --format=''%(refname)'' | wc -l)\"","time":{"start":1790449965407,"end":1790449978007}}}');
