 runnable? ===\"\nprintf ''hermes  : ''; (hermes --version 2>&1 | head -2) || echo \"not on PATH\"\nprintf ''opencode: ''; (opencode --version 2>&1 | head -2) || echo \"not on PATH\"\nprintf ''void    : ''; (void --version 2>&1 | head -1) || echo \"NOT INSTALLED\"\nprintf ''buildlog: ''; (buildlog tail 1 2>&1 | tail -2) || echo \"not on PATH\"\necho; echo \"=== installed agent packages ===\"; pacman -Q | grep -iE \"hermes|opencode|electron|void\" 2>/dev/null || echo \"none installed\"","time":{"start":1790450321787,"end":1790450322876}}}');
