ache/paru /var/cache/pacman/pkg ~/.cache/yay 2>/dev/null | sed ''s/^/  /''\necho\necho \"  --- paru cache breakdown ---\"\ndu -sh ~/.cache/paru/* 2>/dev/null | sort -rh | head -5 | sed ''s/^/    /''\necho\necho \"  --- orphaned packages (candidates for removal) ---\"\npacman -Qdtq 2>/dev/null | head -20 | sed ''s/^/    /''\necho \"    total: $(pacman -Qdtq 2>/dev/null | wc -l | tr -d '' '')\"","time":{"start":1790450587612,"end":1790450588119}}}');
