                        3.33 MiB\n  gperf                      237.93 KiB\n  gtksourceview3             3.91 MiB\n  libcbor                    188.93 KiB\n  libjcat                    560.63 KiB\n  lld                        7.14 MiB\n  ninja                      423.10 KiB\n  patchutils                 206.42 KiB\n  python-requests            777.58 KiB\n  rust-bindgen               5.55 MiB\n  svt-hevc                   2.24 MiB\n  yarn                       19.26 MiB\n\n=== total ===\n  368 MB across 18 packages\n","exit":0,"truncated":false},"title":"echo \"=== per-package installed size (correct field) ===\"\nfor p in $(pacman -Qdtq 2>/dev/null); do\n  sz=$(pacman -Qi \"$p\" 2>/dev/null | awk -F'': *'' ''/^Installed Size/{print $2}'')\n  printf \"  %-26s %s\\n\" \"$p\" \"${sz:-?}\"\ndone\necho\necho \"=== total ===\"\ntotal=0\nfor p in $(pacman -Qdtq 2>/dev/null); do\n  kb=$(pacman -Qi \"$p\" 2>/dev/null | awk -F'': *'' ''/^Installed Size/{gsub(/[^0-9]/,\"\",$2); print $2}'')\n  [ -n \"$kb\" ] && total=$((total+kb))\ndone\necho \"  $((total/1024)) MB across $(pacman -Qdtq 2>/dev/null | wc -l | tr -d '' '') packages\"","time":{"start":1790450643318,"end":1790450644268}}}');
