INSERT INTO part VALUES('prt_0df2e83db001z6smKotrxaVOXa','msg_0df2e72e90012mRSb7XgOPgQyN','ses_f20e5cfc2ffeSFa4odnoYLiUOk',1790450762715,1790450764768,'{"type":"text","text":"Acknowledged the handoff — and it checks out exactly: `nyan-gfsf-alert` is gone, `shield-kitty` has all three commits (`edb9cd5`, `ffd58fc`, `fe2a4b5`), scripts renamed.\n\nBut the rename left the **installed** unit stale, and this is directly your \"display against me\" bug:\n\n- `~/.config/systemd/user/shield-kitty-watch.service` is **enabled + active**, but both `Documentation=` and `ExecStart=` still point at `~/Projects/nyan-gfsf-alert/` — a path that no longer exists. Any restart dies instantly (`RestartSec=10`, so it crash-loops forever).\n- PID 186750 is still running the **old inode** from the deleted directory, so it works right now purely by accident.\n\nYour real ask is a false-positive one, so let me read the detection logic before changing anything:","time":{"start":1790450762715,"end":1790450764767}}');
INSERT INTO part VALUES('prt_0df2e8bd9001kMhCG0zv2j4Jgm','msg_0df2e72e90012mRSb7XgOPgQyN','ses_f20e5cfc2ffeSFa4odnoYLiUOk',1790450764761,1790450764780,'{"type":"tool","tool":"read","callID":"call_function_hxjtcd9lto4x_1","state":{"status":"completed","input":{"filePath":"/home/livings/Projects/shield-kitty/shield-kitty-watch.py"},"output":"<path>/home/livings/Projects/shield-kitty/shield-kitty-watch.py</path>\n<type>file</type>\n<content>\n1: #!/usr/bin/env python3\n2: \"\"\"\n3: shield-kitty — intrusion event detector.\n4: \n5: Tails the systemd journal for signals that something outside the machine\n6: tried to get in, and fires a fullscreen pixel nyan cat alert on the local\n7: display.\n8: \n9: This is a DETECTION and NOTIFICATION tool. It blocks nothing on its own.\n10: Blocking is the job of pam_faillock (already enabled) and the firewall\n11: (enable with: sudo systemctl enable --now firewalld).\n12: \n13: Design notes:\n14:   - Runs as a per-user service, not root. Least privilege: it only reads\n15:     the journal, which the user is already allowed to do.\n16:   - Uses a cursor file so a restart does not replay old events.\n17:   - Debounces: a burst of failed SSH attempts is one alert, not fifty.\n18:   - Never blocks. If the display cannot be opened, it logs and continues.\n19: \n20: Usage:\n21:   shield-kitty-watch            run in foreground (for testing)\n22:   shield-kitty-watch --selftest run detector once against the last 10 minutes\n23: \"\"\"\n24: \n25: import argparse\n26: import getpass\n27: import json\n28: import os\n29: import re\n30: import subprocess\n31: import sys\n32: import time\n33: from pathlib import Path\n34: \n35: XDG_RUNTIME = Path(os.environ.get(\"XDG_RUNTIME_DIR\", f\"/run/user/{os.getuid()}\"))\n36: STATE_DIR = XDG_RUNTIME / \"shield-kitty\"\n37: CURSOR = STATE_DIR / \"cursor\"\n38: ALERT_SCRIPT = Path(__file__).parent / \"shield-kitty-alert.py\"\n39: LOCK = STATE_DIR / \"watch.lock\"\n40: \n41: # Seconds to suppress further alerts after one fires. A password-spraying\n42: # run produces dozens of failures in seconds; one alert communicates that.\n43: DEBOUNCE = 45\n44: \n45: # --- Detection rules -------------------------------------------------------\n46: # Each rule: (name, compiled regex, human label, severity)\n47: # Severity: \"critical\" = credential attack on a login surface\n48: #           \"warning\"  = privilege escalation attempt or physical attach\n49: RULES = [\n50:     (\n51:         \"login_failure\",\n52:         re.compile(\n53:             r\"(Failed password for (invalid user )?\"\n54:             r\"|Invalid user \\S+ from\"\n55:             r\"|FAILED LOGIN \\d+ FROM\"\n56:             r\"|pam_unix\\([^)]*:auth\\): authentication failure)\",\n57:             re.I,\n58:         ),\n59:         \"AUTHENTICATION FAILURE\",\n60:         \"critical\",\n61:     ),\n62:     (\n63:         # Match pam_faillock''s ACTUAL denial output, not the bare word\n64:         # \"faillock\" — otherwise this fires on the admin''s own\n65:         # `sudo cp /etc/security/faillock.conf` commands.\n66:         \"faillock_denial\",\n67:         re.compile(\n68:             r\"(tries to authenticate but locked out\"\n69:             r\"|pam_faillock\\(authfail\\)\"\n70:             r\"|pam_faillock\\(preauth\\).*(fail|denied)\"\n71:             r\"|Unlocking account \\S+)\"\n72:         ),\n73:         \"ACCOUNT LOCKOUT TRIGGERED\",\n74:         \"critical\",\n75:     ),\n76:     (\n77:         # sudo: the actor name is the field right after \"sudo:\". \"a password\n78:         # is required\" fires on every non-interactive sudo attempt, including\n79:         # the admin''s own — so only flag it when the actor is NOT the local\n80:         # user. \"incorrect password\" is always a real failure.\n81:         \"sudo_failure\",\n82:         re.compile(r\"sudo:.*incorrect password\", re.I),\n83:         \"UNAUTHORIZED PRIVILEGE ESCALATION\",\n84:         \"critical\",\n85:     ),\n86:     (\n87:         # Non-interactive sudo attempt from someone other than us.\n88:         \"sudo_unattended\",\n89:         re.compile(r\"sudo:\\s*(?P<actor>\\w+)\\s*:.*a password is required\", re.I),\n90:         \"UNAUTHORIZED PRIVILEGE ESCALATION\",\n91:         \"critical\",\n92:     ),\n93:     (\n94:         \"sddm_failure\",\n95:         re.compile(r\"(sddm|lightdm|gdm).*(failed|auth|login).*fail\", re.I),\n96:         \"LOGIN SCREEN AUTH FAILURE\",\n97:         \"critical\",\n98:     ),\n99:     (\n100:         \"usb_attach\",\n101:         re.compile(r\"usb .*(?:new high-speed USB device|Product:)\", re.I),\n102:         \"USB DEVICE ATTACHED\",\n103:         \"warning\",\n104:     ),\n105: ]\n106: \n107: \n108: def log(msg: str) -> None:\n109:     print(f\"[shield-kitty] {msg}\", flush=True)\n110: \n111: \n112: def have_journal_access() -> bool:\n113:     \"\"\"Can we actually read the auth log? If not, the detector is useless.\"\"\"\n114:     try:\n115:         r = subprocess.run(\n116:             [\"journalctl\", \"-n\", \"1\", \"--no-pager\", \"-q\"],\n117:             capture_output=True, timeout=10,\n118:         )\n119:         return r.returncode == 0\n120:     except Exception:\n121:         return False\n122: \n123: \n124: def read_cursor() -> str:\n125:     try:\n126:         return CURSOR.read_text().strip()\n127:     except Exception:\n128:         return \"\"\n129: \n130: \n131: def write_cursor(value: str) -> None:\n132:     try:\n133:         CURSOR.write_text(value)\n134:     except Exception:\n135:         pass\n136: \n137: \n138: def fetch_since(since: str, limit: int = 400) -> list[str]:\n139:     \"\"\"Journal lines since cursor. Falls back to a time window on first run.\"\"\"\n140:     cmd = [\"journalctl\", \"--no-pager\", \"-q\", \"-n\", str(limit), \"-o\", \"short-iso\"]\n141:     if since:\n142:         cmd += [\"--after-cursor\", since]\n143:     else:\n144:         cmd += [\"--since\", \"-10min\"]\n145:     try:\n146:         r = subprocess.run(cmd, capture_output=True, text=True, timeout=20)\n147:         return r.stdout.splitlines() if r.returncode == 0 else []\n148:     except Exception:\n149:         return []\n150: \n151: \n152: def latest_cursor() -> str:\n153:     \"\"\"Ask journald for the current end-of-stream position.\"\"\"\n154:     try:\n155:         r = subprocess.run(\n156:             [\"journalctl\", \"--no-pager\", \"-n\", \"1\", \"-o\", \"export\"],\n157:             capture_output=True, text=True, timeout=10,\n158:         )\n159:         for line in r.stdout.splitlines():\n160:             if line.startswith(\"__CURSOR=\"):\n161:                 return line.split(\"=\", 1)[1].strip()\n162:     except Exception:\n163:         pass\n164:     return \"\"\n165: \n166: \n167: LOCAL_USER = os.environ.get(\"USER\") or getpass.getuser()\n168: \n169: \n170: def is_local_admin_actor(match: re.Match) -> bool:\n171:     \"\"\"\n172:     True if the sudo actor is the logged-in user doing their own thing.\n173:     Guards the rules that would otherwise fire on normal admin activity.\n174:     \"\"\"\n175:     actor = (match.groupdict().get(\"actor\") or \"\").strip().lower()\n176:     return bool(actor) and actor == LOCAL_USER.lower()\n177: \n178: \n179: def classify(lines: list[str]) -> list[dict]:\n180:     \"\"\"Run every rule over every line, collect unique hits.\"\"\"\n181:     found: dict[str, dict] = {}\n182:     for line in lines:\n183:         for name, pattern, label, severity in RULES:\n184:             m = pattern.search(line)\n185:             if not m:\n186:                 continue\n187:             # Skip our own sudo attempts — not an intrusion.\n188:             if name == \"sudo_unattended\" and is_local_admin_actor(m):\n189:                 continue\n190:             key = f\"{name}:{label}\"\n191:             if key in found:\n192:                 found[key][\"count\"] += 1\n193:             else:\n194:                 found[key] = {\n195:                     \"rule\": name, \"label\": label,\n196:                     \"severity\": severity, \"count\": 1,\n197:                     \"sample\": line.strip()[:200],\n198:                 }\n199:     return list(found.values())\n200: \n201: \n202: def most_severe(events: list[dict]) -> str:\n203:     if any(e[\"severity\"] == \"critical\" for e in events):\n204:         return \"critical\"\n205:     return \"warning\"\n206: \n207: \n208: def fire_alert(events: list[dict]) -> None:\n209:     payload = {\n210:         \"severity\": most_severe(events),\n211:         \"events\": events,\n212:         \"timestamp\": time.strftime(\"%Y-%m-%d %H:%M:%S\"),\n213:     }\n214:     log(f\"ALERT: {len(events)} event(s), severity={payload[''severity'']}\")\n215:     for e in events:\n216:         log(f\"        {e[''label'']} x{e[''count'']}\")\n217: \n218:     # Detach the display so a slow/fullscreen window never stalls detection.\n219:     try:\n220:         subprocess.Popen(\n221:             [sys.executable, str(ALERT_SCRIPT), json.dumps(payload)],\n222:             stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,\n223:             start_new_session=True,\n224:         )\n225:     except Exception as exc:\n226:         log(f\"could not launch alert display: {exc}\")\n227: \n228: \n229: def selftest() -> int:\n230:     log(f\"selftest: journal access = {have_journal_access()}\")\n231:     lines = fetch_since(\"\", limit=2000)\n232:     log(f\"selftest: scanned {len(lines)} journal lines from last 10min\")\n233:     events = classify(lines)\n234:     if not events:\n235:         print(\"  result: no matching events in window (detector logic OK, nothing firing)\")\n236:         # Prove the rules actually match something.\n237:         probe = \"Sep 26 12:00:00 host sshd[99]: Failed password for invalid user admin from 1.2.3.4 port 22 ssh2\"\n238:         if classify([probe]):\n239:             print(\"  result: rules DO match a known attack string — logic verified\")\n240:             return 0\n241:         print(\"  result: FAILED — rules match nothing, detector is broken\")\n242:         return 1\n243:     for e in events:\n244:         print(f\"  detected: {e[''label'']} x{e[''count'']}\")\n245:     return 0\n246: \n247: \n248: def acquire_lock() -> bool:\n249:     \"\"\"Single-instance guard so a second service start cannot double-fire.\"\"\"\n250:     try:\n251:         import fcntl\n252:         f = open(LOCK, \"w\")\n253:         fcntl.flock(f, fcntl.LOCK_EX | fcntl.LOCK_NB)\n254:         f.write(str(os.getpid()))\n255:         f.flush()\n256:         return True\n257:     except Exception:\n258:         return False\n259: \n260: \n261: def main() -> int:\n262:     ap = argparse.ArgumentParser()\n263:     ap.add_argument(\"--selftest\", action=\"store_true\")\n264:     args = ap.parse_args()\n265: \n266:     if args.selftest:\n267:         return selftest()\n268: \n269:     if not have_journal_access():\n270:         log(\"FATAL: cannot read the journal.\")\n271:         log(\"Add yourself to the systemd-journal group:\")\n272:         log(\"  sudo usermod -aG systemd-journal $USER\")\n273:         log(\"Then log out and back in. Refusing to run blind.\")\n274:         return 1\n275: \n276:     STATE_DIR.mkdir(parents=True, exist_ok=True)\n277:     if not acquire_lock():\n278:         log(\"another watcher is already running; exiting\")\n279:         return 0\n280: \n281:     cursor = read_cursor() or latest_cursor()\n282:     write_cursor(cursor)\n283:     log(f\"watching journal from cursor {cursor[:16] or ''(fresh start)''}\")\n284: \n285:     last_fire = 0.0\n286:     while True:\n287:         lines = fetch_since(cursor)\n288:         if lines:\n289:             cursor = latest_cursor() or cursor\n290:             write_cursor(cursor)\n291:             events = classify(lines)\n292:             if events and (time.time() - last_fire) > DEBOUNCE:\n293:                 fire_alert(events)\n294:                 last_fire = time.time()\n295:         time.sleep(3)\n296: \n297: \n298: if __name__ == \"__main__\":\n299:     try:\n300:         sys.exit(main())\n301:     except KeyboardInterrupt:\n302:         sys.exit(0)\n\n(End of file - total 302 lines)\n</content>","metadata":{"preview":"#!/usr/bin/env python3\n\"\"\"\nshield-kitty — intrusion event detector.\n\nTails the systemd journal for signals that something outside the machine\ntried to get in, and fires a fullscreen pixel nyan cat alert on the local\ndisplay.\n\nThis is a DETECTION and NOTIFICATION tool. It blocks nothing on its own.\nBlocking is the job of pam_faillock (already enabled) and the firewall\n(enable with: sudo systemctl enable --now firewalld).\n\nDesign notes:\n  - Runs as a per-user service, not root. Least privilege: it only reads\n    the journal, which the user is already allowed to do.\n  - Uses a cursor file so a restart does not replay old events.\n  - Debounces: a burst of failed SSH attempts is one alert, not fifty.\n  - Never blocks. If the display cannot be opened, it logs and continues.\n\nUsage:","truncated":false,"loaded":[],"display":{"type":"file","path":"/home/livings/Projects/shield-kitty/shield-kitty-watch.py","text":"#!/usr/bin/env python3\n\"\"\"\nshield-kitty — intrusion event detector.\n\nTails the systemd journal for signals that something outside the machine\ntried to get in, and fires a fullscreen pixel nyan cat alert on the local\ndisplay.\n\nThis is a DETECTION and NOTIFICATION tool. It blocks nothing on its own.\nBlocking is the job of pam_faillock (already enabled) and the firewall\n(enable with: sudo systemctl enable --now firewalld).\n\nDesign notes:\n  - Runs as a per-user service, not root. Least privilege: it only reads\n    the journal, which the user is already allowed to do.\n  - Uses a cursor file so a restart does not replay old events.\n  - Debounces: a burst of failed SSH attempts is one alert, not fifty.\n  - Never blocks. If the display cannot be opened, it logs and continues.\n\nUsage:\n  shield-kitty-watch            run in foreground (for testing)\n  shield-kitty-watch --selftest run detector once against the last 10 minutes\n\"\"\"\n\nimport argparse\nimport getpass\nimport json\nimport os\nimport re\nimport subprocess\nimport sys\nimport time\nfrom pathlib import Path\n\nXDG_RUNTIME = Path(os.environ.get(\"XDG_RUNTIME_DIR\", f\"/run/user/{os.getuid()}\"))\nSTATE_DIR = XDG_RUNTIME / \"shield-kitty\"\nCURSOR = STATE_DIR / \"cursor\"\nALERT_SCRIPT = Path(__file__).parent / \"shield-kitty-alert.py\"\nLOCK = STATE_DIR / \"watch.lock\"\n\n# Seconds to suppress further alerts after one fires. A password-spraying\n# run produces dozens of failures in seconds; one alert communicates that.\nDEBOUNCE = 45\n\n# --- Detection rules -------------------------------------------------------\n# Each rule: (name, compiled regex, human label, severity)\n# Severity: \"critical\" = credential attack on a login surface\n#           \"warning\"  = privilege escalation attempt or physical attach\nRULES = [\n    (\n        \"login_failure\",\n        re.compile(\n            r\"(Failed password for (invalid user )?\"\n            r\"|Invalid user \\S+ from\"\n            r\"|FAILED LOGIN \\d+ FROM\"\n            r\"|pam_unix\\([^)]*:auth\\): authentication failure)\",\n            re.I,\n        ),\n        \"AUTHENTICATION FAILURE\",\n        \"critical\",\n    ),\n    (\n        # Match pam_faillock''s ACTUAL denial output, not the bare word\n        # \"faillock\" — otherwise this fires on the admin''s own\n        # `sudo cp /etc/security/faillock.conf` commands.\n        \"faillock_denial\",\n        re.compile(\n            r\"(tries to authenticate but locked out\"\n            r\"|pam_faillock\\(authfail\\)\"\n            r\"|pam_faillock\\(preauth\\).*(fail|denied)\"\n            r\"|Unlocking account \\S+)\"\n        ),\n        \"ACCOUNT LOCKOUT TRIGGERED\",\n        \"critical\",\n    ),\n    (\n        # sudo: the actor name is the field right after \"sudo:\". \"a password\n        # is required\" fires on every non-interactive sudo attempt, including\n        # the admin''s own — so only flag it when the actor is NOT the local\n        # user. \"incorrect password\" is always a real failure.\n        \"sudo_failure\",\n        re.compile(r\"sudo:.*incorrect password\", re.I),\n        \"UNAUTHORIZED PRIVILEGE ESCALATION\",\n        \"critical\",\n    ),\n    (\n        # Non-interactive sudo attempt from someone other than us.\n        \"sudo_unattended\",\n        re.compile(r\"sudo:\\s*(?P<actor>\\w+)\\s*:.*a password is required\", re.I),\n        \"UNAUTHORIZED PRIVILEGE ESCALATION\",\n        \"critical\",\n    ),\n    (\n        \"sddm_failure\",\n        re.compile(r\"(sddm|lightdm|gdm).*(failed|auth|login).*fail\", re.I),\n        \"LOGIN SCREEN AUTH FAILURE\",\n        \"critical\",\n    ),\n    (\n        \"usb_attach\",\n        re.compile(r\"usb .*(?:new high-speed USB device|Product:)\", re.I),\n        \"USB DEVICE ATTACHED\",\n        \"warning\",\n    ),\n]\n\n\ndef log(msg: str) -> None:\n    print(f\"[shield-kitty] {msg}\", flush=True)\n\n\ndef have_journal_access() -> bool:\n    \"\"\"Can we actually read the auth log? If not, the detector is useless.\"\"\"\n    try:\n        r = subprocess.run(\n            [\"journalctl\", \"-n\", \"1\", \"--no-pager\", \"-q\"],\n            capture_output=True, timeout=10,\n        )\n        return r.returncode == 0\n    except Exception:\n        return False\n\n\ndef read_cursor() -> str:\n    try:\n        return CURSOR.read_text().strip()\n    except Exception:\n        return \"\"\n\n\ndef write_cursor(value: str) -> None:\n    try:\n        CURSOR.write_text(value)\n    except Exception:\n        pass\n\n\ndef fetch_since(since: str, limit: int = 400) -> list[str]:\n    \"\"\"Journal lines since cursor. Falls back to a time window on first run.\"\"\"\n    cmd = [\"journalctl\", \"--no-pager\", \"-q\", \"-n\", str(limit), \"-o\", \"short-iso\"]\n    if since:\n        cmd += [\"--after-cursor\", since]\n    else:\n        cmd += [\"--since\", \"-10min\"]\n    try:\n        r = subprocess.run(cmd, capture_output=True, text=True, timeout=20)\n        return r.stdout.splitlines() if r.returncode == 0 else []\n    except Exception:\n        return []\n\n\ndef latest_cursor() -> str:\n    \"\"\"Ask journald for the current end-of-stream position.\"\"\"\n    try:\n        r = subprocess.run(\n            [\"journalctl\", \"--no-pager\", \"-n\", \"1\", \"-o\", \"export\"],\n            capture_output=True, text=True, timeout=10,\n        )\n        for line in r.stdout.splitlines():\n            if line.startswith(\"__CURSOR=\"):\n                return line.split(\"=\", 1)[1].strip()\n    except Exception:\n        pass\n    return \"\"\n\n\nLOCAL_USER = os.environ.get(\"USER\") or getpass.getuser()\n\n\ndef is_local_admin_actor(match: re.Match) -> bool:\n    \"\"\"\n    True if the sudo actor is the logged-in user doing their own thing.\n    Guards the rules that would otherwise fire on normal admin activity.\n    \"\"\"\n    actor = (match.groupdict().get(\"actor\") or \"\").strip().lower()\n    return bool(actor) and actor == LOCAL_USER.lower()\n\n\ndef classify(lines: list[str]) -> list[dict]:\n    \"\"\"Run every rule over every line, collect unique hits.\"\"\"\n    found: dict[str, dict] = {}\n    for line in lines:\n        for name, pattern, label, severity in RULES:\n            m = pattern.search(line)\n            if not m:\n                continue\n            # Skip our own sudo attempts — not an intrusion.\n            if name == \"sudo_unattended\" and is_local_admin_actor(m):\n                continue\n            key = f\"{name}:{label}\"\n            if key in found:\n                found[key][\"count\"] += 1\n            else:\n                found[key] = {\n                    \"rule\": name, \"label\": label,\n                    \"severity\": severity, \"count\": 1,\n                    \"sample\": line.strip()[:200],\n                }\n    return list(found.values())\n\n\ndef most_severe(events: list[dict]) -> str:\n    if any(e[\"severity\"] == \"critical\" for e in events):\n        return \"critical\"\n    return \"warning\"\n\n\ndef fire_alert(events: list[dict]) -> None:\n    payload = {\n        \"severity\": most_severe(events),\n        \"events\": events,\n        \"timestamp\": time.strftime(\"%Y-%m-%d %H:%M:%S\"),\n    }\n    log(f\"ALERT: {len(events)} event(s), severity={payload[''severity'']}\")\n    for e in events:\n        log(f\"        {e[''label'']} x{e[''count'']}\")\n\n    # Detach the display so a slow/fullscreen window never stalls detection.\n    try:\n        subprocess.Popen(\n            [sys.executable, str(ALERT_SCRIPT), json.dumps(payload)],\n            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,\n            start_new_session=True,\n        )\n    except Exception as exc:\n        log(f\"could not launch alert display: {exc}\")\n\n\ndef selftest() -> int:\n    log(f\"selftest: journal access = {have_journal_access()}\")\n    lines = fetch_since(\"\", limit=2000)\n    log(f\"selftest: scanned {len(lines)} journal lines from last 10min\")\n    events = classify(lines)\n    if not events:\n        print(\"  result: no matching events in window (detector logic OK, nothing firing)\")\n        # Prove the rules actually match something.\n        probe = \"Sep 26 12:00:00 host sshd[99]: Failed password for invalid user admin from 1.2.3.4 port 22 ssh2\"\n        if classify([probe]):\n            print(\"  result: rules DO match a known attack string — logic verified\")\n            return 0\n        print(\"  result: FAILED — rules match nothing, detector is broken\")\n        return 1\n    for e in events:\n        print(f\"  detected: {e[''label'']} x{e[''count'']}\")\n    return 0\n\n\ndef acquire_lock() -> bool:\n    \"\"\"Single-instance guard so a second service start cannot double-fire.\"\"\"\n    try:\n        import fcntl\n        f = open(LOCK, \"w\")\n        fcntl.flock(f, fcntl.LOCK_EX | fcntl.LOCK_NB)\n        f.write(str(os.getpid()))\n        f.flush()\n        return True\n    except Exception:\n        return False\n\n\ndef main() -> int:\n    ap = argparse.ArgumentParser()\n    ap.add_argument(\"--selftest\", action=\"store_true\")\n    args = ap.parse_args()\n\n    if args.selftest:\n        return selftest()\n\n    if not have_journal_access():\n        log(\"FATAL: cannot read the journal.\")\n        log(\"Add yourself to the systemd-journal group:\")\n        log(\"  sudo usermod -aG systemd-journal $USER\")\n        log(\"Then log out and back in. Refusing to run blind.\")\n        return 1\n\n    STATE_DIR.mkdir(parents=True, exist_ok=True)\n    if not acquire_lock():\n        log(\"another watcher is already running; exiting\")\n        return 0\n\n    cursor = read_cursor() or latest_cursor()\n    write_cursor(cursor)\n    log(f\"watching journal from cursor {cursor[:16] or ''(fresh start)''}\")\n\n    last_fire = 0.0\n    while True:\n        lines = fetch_since(cursor)\n        if lines:\n            cursor = latest_cursor() or cursor\n            write_cursor(cursor)\n            events = classify(lines)\n            if events and (time.time() - last_fire) > DEBOUNCE:\n                fire_alert(events)\n                last_fire = time.time()\n        time.sleep(3)\n\n\nif __name__ == \"__main__\":\n    try:\n        sys.exit(main())\n    except KeyboardInterrupt:\n        sys.exit(0)","lineStart":1,"lineEnd":302,"totalLines":302,"truncated":false}},"title":"home/livings/Projects/shield-kitty/shield-kitty-watch.py","time":{"start":1790450764765,"end":1790450764779}}}');
