INTRUSION ALERT\")\n134:                       _Qt.AlignmentFlag.AlignHCenter, \"SHIELD KITTY\")\n139:            p.drawText(0, 60, w, 50, _Qt.AlignmentFlag.AlignHCenter,\n145:            lines = [f\"severity: {self.sev}\",\n153:                       _Qt.AlignmentFlag.AlignLeft, \"\\n\".join(lines))\n155:            p.drawText(0, h - 30, w, 20, _Qt.AlignmentFlag.AlignHCenter,\n160:            if e.key() == _Qt.Key.Key_Escape:\n175:    app.setQuitOnLastWindowClosed(True)\n178:    w.setWindowFlags(Qt.WindowType.FramelessWindowHint | Qt.WindowType.WindowStaysOnTopHint)\n179:    w.showFullScreen()\n193:    sev = payload.get(\"severity\", \"?\")\n196:    print(f\"  severity : {sev}\")\n","exit":0,"truncated":false},"title":"cd ~/Projects/shield-kitty && grep -nE \"severity|fullscreen|Window|setGeometry|showFullScreen|setWindowFlags|Qt\\.|Tool|frameless\" shield-kitty-alert.py | head -30","time":{"start":1790450781491,"end":1790450781506}}}');
