et(\"events\", []) or []\n+    for e in items:\n+        s = e.get(\"severity\") or top or \"unknown\"\n         sev_count[s] = sev_count.get(s, 0) + 1\n+    if not items and top:\n+        sev_count[top] = sev_count.get(top, 0) + 1\n \n print(\"=\" * 72)\n print(\"  SHIELD KITTY — INCIDENT REPORT\")\n print(\"=\" * 72)\n","filediff":{"file":"/home/livings/Projects/shield-kitty-forensics/evidence.py","patch":"Index: /home/livings/Projects/shield-kitty-forensics/evidence.py\n===================================================================\n--- /home/livings/Projects/shield-kitty-forensics/evidence.py\n+++ /home/livings/Projects/shield-kitty-forensics/evidence.py\n@@ -252,11 +252,18 @@\n records = [r for r in read_chain() if r.get(\"ts_unix\", 0) >= cutoff]\n \n sev_count = {}\n for r in records:\n-    for e in (r.get(\"event\", {}).get(\"events\", []) or [r.get(\"event\", {})]):\n-        s = e.get(\"severity\", \"unknown\")\n+    # Payload shape is {\"severity\": <str>, \"events\": [ {label, count, ...} ]}.\n+    # Fall back to the event object''s own severity if the top-level is absent.\n+    ev = r.get(\"event\", {})\n+    top = ev.get(\"severity\")\n+    items = ev.get(\"events\", []) or []\n+    for e in items:\n+        s = e.get(\"severity\") or top or \"unknown\"\n         sev_count[s] = sev_count.get(s, 0) + 1\n+    if not items and top:\n+        sev_count[top] = sev_count.get(top, 0) + 1\n \n print(\"=\" * 72)\n print(\"  SHIELD KITTY — INCIDENT REPORT\")\n print(\"=\" * 72)\n","additions":9,"deletions":2},"truncated":false},"title":"home/livings/Projects/shield-kitty-forensics/evidence.py","time":{"start":1790450792690,"end":1790450792699}}}');
