 2, in <module>\nFileNotFoundError: [Errno 2] No such file or directory: ''shield-kitty-watch.py''\nTraceback (most recent call last):\n  File \"<string>\", line 1, in <module>\n    import ast; ast.parse(open(''shield-kitty-watch.py'').read()); print(''  [✓] syntax OK'')\n                          ~~~~^^^^^^^^^^^^^^^^^^^^^^^^^\nFileNotFoundError: [Errno 2] No such file or directory: ''shield-kitty-watch.py''\ngrep: shield-kitty-watch.py: No such file or directory\n","metadata":{"output":"/usr/bin/bash: line 1: cd: /home/livings/Projects/nyan-gfsf-alert: No such file or directory\nTraceback (most recent call last):\n  File \"<stdin>\", line 2, in <module>\nFileNotFoundError: [Errno 2] No such file or directory: ''shield-kitty-watch.py''\nTraceback (most recent call last):\n  File \"<string>\", line 1, in <module>\n    import ast; ast.parse(open(''shield-kitty-watch.py'').read()); print(''  [✓] syntax OK'')\n                          ~~~~^^^^^^^^^^^^^^^^^^^^^^^^^\nFileNotFoundError: [Errno 2] No such file or directory: ''shield-kitty-watch.py''\ngrep: shield-kitty-watch.py: No such file or directory\n","exit":0,"truncated":false},"title":"cd ~/Projects/nyan-gfsf-alert\npython3 - <<''PY''\np=''shield-kitty-watch.py''\ns=open(p).read()\n\ns=s.replace(\n''''''ALERT_SCRIPT = Path(__file__).parent / \"shield-kitty-alert.py\"'''''',\n''''''ALERT_SCRIPT = Path(__file__).parent / \"shield-kitty-alert.py\"\n# Tamper-evident evidence store. Optional: if this repo is not present the\n# watcher still fires alerts, it just does not build a court-defensible record.\nEVIDENCE = Path.home() / \"Projects/shield-kitty-forensics/evidence.py\"'''''')\n\ns=s.replace(\n''''''    # Detach the display so a slow/fullscreen window never stalls detection.'''''',\n''''''    # Append to the tamper-evident evidence chain BEFORE displaying. If the\n    # log write fails we still alert — losing evidence is bad but staying\n    # silent about an intrusion is worse.\n    if EVIDENCE.exists():\n        try:\n            subprocess.run(\n                [sys.executable, str(EVIDENCE), \"record\", \"--event\", json.dumps(payload)],\n                capture_output=True, timeout=20,\n            )\n        except Exception as exc:\n            log(f\"evidence logging failed: {exc}\")\n    else:\n        log(f\"evidence store not found at {EVIDENCE}; alert only, no proof\")\n\n    # Detach the display so a slow/fullscreen window never stalls detection.'''''')\nopen(p,''w'').write(s)\nprint(\"  [✓] watcher wired to evidence store\")\nPY\npython3 -c \"import ast; ast.parse(open(''shield-kitty-watch.py'').read()); print(''  [✓] syntax OK'')\"\ngrep -n \"EVIDENCE\" shield-kitty-watch.py | head -4 | sed ''s/^/  /''","time":{"start":1790450798662,"end":1790450798751}}}');
