INSERT INTO part VALUES('prt_0df307c3f001rllBuJr8yLt949','msg_0df3070e8001xa8hRfQvizt8zT','ses_f20e5cfc2ffeSFa4odnoYLiUOk',1790450891839,1790450892805,'{"type":"tool","tool":"edit","callID":"call_function_xctfjjcdgh7v_1","state":{"status":"error","input":{"filePath":"/home/livings/Projects/shield-kitty/shield-kitty-watch.py","newString":"    last_fire = 0.0\n    while True:\n        lines = fetch_since(cursor)\n        if lines:\n            cursor = latest_cursor() or cursor\n            write_cursor(cursor)\n            events = classify(lines)\n            if events and (time.time() - last_fire) > DEBOUNCE:\n                # Only a critical event is allowed to take over the display.\n                # Warnings are journal-only; see log_events().\n                crit = [e for e in events if e[\"severity\"] == \"critical\"]\n                warn = [e for e in events if e[\"severity\"] != \"critical\"]\n                if warn:\n                    log_events(warn)\n                if crit:\n                    fire_alert(crit)\n                    last_fire = time.time()\n        time.sleep(3)","oldString":"    last_fire = 0.0\n    while True:\n        lines = fetch_since(cursor)\n        if lines:\n            cursor = latest_cursor() or cursor\n            write_cursor(cursor)\n            events = classify(lines)\n            if events and (time.time() - last_fire) > DEBOUNCE:\n                fire_alert(events)\n                last_fire = time.time()\n        time.sleep(3)"},"error":"Could not find oldString in the file. It must match exactly, including whitespace, indentation, and line endings.","time":{"start":1790450892784,"end":1790450892804}}}');
