INSERT INTO part VALUES('prt_0df33bca3001OYhj2mbDb0BGFv','msg_0df33b2070016p8XPfa3pFum40','ses_f211dfcd4ffevS1Yoddwab036g',1790451104931,1790451104998,'{"type":"tool","tool":"bash","callID":"call_function_edmnzxh8qats_1","state":{"status":"completed","input":{"command":"man faillock.conf 2>/dev/null | col -b | grep -A12 \"^\\s*admin_group\" | head -20 | sed ''s/^/  /''"},"output":"       admin_group=name\n  \t If a group name is specified with this option, members\t of  the  group\n  \t will  be  handled by this module the same as the root account (the op‐\n  \t tions even_deny_root and root_unlock_time will apply to them.\tBy  de‐\n  \t fault the option is not set.\n  \n  EXAMPLES\n       /etc/security/faillock.conf file example:\n  \n  \t deny=4\n  \t unlock_time=1200\n  \t silent\n  \n","metadata":{"output":"       admin_group=name\n  \t If a group name is specified with this option, members\t of  the  group\n  \t will  be  handled by this module the same as the root account (the op‐\n  \t tions even_deny_root and root_unlock_time will apply to them.\tBy  de‐\n  \t fault the option is not set.\n  \n  EXAMPLES\n       /etc/security/faillock.conf file example:\n  \n  \t deny=4\n  \t unlock_time=1200\n  \t silent\n  \n","exit":0,"truncated":false},"title":"man faillock.conf 2>/dev/null | col -b | grep -A12 \"^\\s*admin_group\" | head -20 | sed ''s/^/  /''","time":{"start":1790451104938,"end":1790451104997}}}');
