o \"═══ HOST REPO CANDIDATES for buildlog (both must be PRIVATE) ═══\"\nfor r in security-audit-2026 rocket-build-system; do\n  curl -s -H \"Authorization: Bearer $T\" \"https://api.github.com/repos/intricos777-dot/$r\" | python3 -c \"\nimport json,sys\nd=json.load(sys.stdin)\nprint(f\\\"  {d[''name'']:<24} private={d[''private'']}  pushed={d[''pushed_at''][:10]}  {(d.get(''description'') or '''')[:45]}\\\")\"\ndone\necho\necho \"  --- security-audit-2026/logs/ contents ---\"\ncurl -s -H \"Authorization: Bearer $T\" \"https://api.github.com/repos/intricos777-dot/security-audit-2026/contents/logs\" | python3 -c \"\nimport json,sys\nd=json.load(sys.stdin)\nprint(''      (empty)'' if isinstance(d,dict) or not d else ''\\n''.join(f\\\"      {f[''name'']}\\\" for f in d))\"","time":{"start":1790451960109,"end":1790451961033}}}');
