/expatbuilder.py\", line 908, in parse\n    result = builder.parseFile(fp)\n  File \"/usr/lib/python3.14/xml/dom/expatbuilder.py\", line 204, in parseFile\n    parser.Parse(buffer, False)\n    ~~~~~~~~~~~~^^^^^^^^^^^^^^^\nxml.parsers.expat.ExpatError: not well-formed (invalid token): line 5, column 32\n  A  enroll-admin.sh\n  M  faillock.conf\n  M  firewalld-workstation.conf\n  A  install-faillock-admin.sh\n  A  set-anon-identity.sh\n  A  set-home-trusted-zone.sh\n  A  shield-kitty-fail2ban.local\n","exit":0,"truncated":false},"title":"cd ~/Projects/zen-hardening\npython3 -c \"import xml.dom.minidom,sys; xml.dom.minidom.parse(''firewalld-workstation.conf''); print(''  [ok] valid XML'')\"\nrm -f faillock.conf.1800s.bak faillock.conf.pre-admin.bak\ngit add -A\ngit status --porcelain | sed ''s/^/  /''","time":{"start":1790452825854,"end":1790452825919}}}');
