INSERT INTO part VALUES('prt_0df4f78d20014YaId58sDY0stY','msg_0df4f708500179blkktvt835Hh','ses_f20e5cfc2ffeSFa4odnoYLiUOk',1790452922579,1790452925052,'{"type":"tool","tool":"bash","callID":"call_function_5umf3lk9vigw_1","state":{"status":"completed","input":{"command":"mkdir -p ~/.cache/paru/clone/electron34\ncd ~/.cache/paru/clone/electron34\ngit clone --depth 1 https://aur.archlinux.org/electron34.git . 2>&1 | tail -5\necho \"=== PKGBUILD ok? ===\"; ls -la PKGBUILD .SRCINFO 2>/dev/null | head\necho \"=== pinned chromium tag ===\"; grep -oE ''chromium-mirror::git\\+[^#]+#tag=[0-9.]+'' PKGBUILD","timeout":180000},"output":"Cloning into ''.''...\n=== PKGBUILD ok? ===\n-rw-r--r-- 1 livings livings 54748 Sep 26 13:02 PKGBUILD\n-rw-r--r-- 1 livings livings 45418 Sep 26 13:02 .SRCINFO\n=== pinned chromium tag ===\nchromium-mirror::git+https://github.com/chromium/chromium.git#tag=132.0.6834.210\n","metadata":{"output":"Cloning into ''.''...\n=== PKGBUILD ok? ===\n-rw-r--r-- 1 livings livings 54748 Sep 26 13:02 PKGBUILD\n-rw-r--r-- 1 livings livings 45418 Sep 26 13:02 .SRCINFO\n=== pinned chromium tag ===\nchromium-mirror::git+https://github.com/chromium/chromium.git#tag=132.0.6834.210\n","exit":0,"truncated":false},"title":"mkdir -p ~/.cache/paru/clone/electron34\ncd ~/.cache/paru/clone/electron34\ngit clone --depth 1 https://aur.archlinux.org/electron34.git . 2>&1 | tail -5\necho \"=== PKGBUILD ok? ===\"; ls -la PKGBUILD .SRCINFO 2>/dev/null | head\necho \"=== pinned chromium tag ===\"; grep -oE ''chromium-mirror::git\\+[^#]+#tag=[0-9.]+'' PKGBUILD","time":{"start":1790452923301,"end":1790452925052}}}');
