INSERT INTO part VALUES('prt_0df525a950017Kr3e8E60aFljh','msg_0df525381001zyXRwvW4r0PT2C','ses_f211dfcd4ffevS1Yoddwab036g',1790453111445,1790453112625,'{"type":"tool","tool":"bash","callID":"call_function_vkur5h50yfhj_1","state":{"status":"completed","input":{"command":"cd /tmp/opencode\npython3 - <<''PY'' 2>&1 | sed ''s/^/  /''\nfrom firewall.core.io.zone import Zone\nimport inspect\nz = Zone()\nprint(\"  Zone() defaults, read straight off the object:\")\nfor a in (\"services\",\"protocols\",\"masquerade\",\"icmp_blocks\",\"forward\",\"target\"):\n    try: print(f\"     {a:<12} = {getattr(z,a)!r}\")\n    except Exception as e: print(f\"     {a:<12} ! {e}\")\nPY"},"output":"    Zone() defaults, read straight off the object:\n       services     = []\n       protocols    = []\n       masquerade   = False\n       icmp_blocks  = []\n       forward      = True\n       target       = ''{chain}_{zone}''\n","metadata":{"output":"    Zone() defaults, read straight off the object:\n       services     = []\n       protocols    = []\n       masquerade   = False\n       icmp_blocks  = []\n       forward      = True\n       target       = ''{chain}_{zone}''\n","exit":0,"truncated":false},"title":"cd /tmp/opencode\npython3 - <<''PY'' 2>&1 | sed ''s/^/  /''\nfrom firewall.core.io.zone import Zone\nimport inspect\nz = Zone()\nprint(\"  Zone() defaults, read straight off the object:\")\nfor a in (\"services\",\"protocols\",\"masquerade\",\"icmp_blocks\",\"forward\",\"target\"):\n    try: print(f\"     {a:<12} = {getattr(z,a)!r}\")\n    except Exception as e: print(f\"     {a:<12} ! {e}\")\nPY","time":{"start":1790453112528,"end":1790453112625}}}');
