WALL STATE ═══\"\nfirewall-cmd --state 2>&1 | sed ''s/^/  state : /''\necho \"  default zone: $(firewall-cmd --get-default-zone 2>&1)\"\necho \"  nft firewalld tables: $(nft list tables 2>/dev/null | grep -c firewalld)\"\necho\necho \"═══ IS THE ZONE ACTUALLY ENFORCING? ═══\"\necho \"  --- workstation zone services ---\"\nfirewall-cmd --zone=workstation --list-services 2>&1 | sed ''s/^/    /''\necho \"  --- what wlo1 is actually bound to ---\"\nfirewall-cmd --get-zone-of-interface=wlo0 2>&1 | sed ''s/^/    /''\nnmcli -g connection.zone dev show wlo1 2>&1 | sed ''s/^/    wlo1 zone: /''","time":{"start":1790453262445,"end":1790453266977}}}');
