state=$(firewall-cmd --state) nft_tables=$(nft list tables 2>/dev/null | grep -ci firewalld) wlo1_zone=$(firewall-cmd --get-zone-of-interface=wlo1)\"\necho\necho \"  -> the script''s final block requires: state=running AND nft>0 AND zone=workstation\"\necho \"     right now: nft_tables=0 and zone=''no zone'', so it would exit 2 (FAIL).\"\necho \"     it cannot report success on your current broken state.\"","time":{"start":1790453696131,"end":1790453698834}}}');
