9 faillock.conf\n  -rw-r--r-- 1 livings livings 1664 Sep 26 13:01 firewalld-workstation.conf\n  drwxr-xr-x 1 livings livings  144 Sep 26 13:08 .git\n  -rw-r--r-- 1 livings livings   19 Sep 26 13:06 .gitignore\n  -rwxr-xr-x 1 livings livings 4252 Sep 26 13:00 install-faillock-admin.sh\n  -rwxr-xr-x 1 livings livings 4957 Sep 26 12:54 set-anon-identity.sh\n  -rwxr-xr-x 1 livings livings 4474 Sep 26 12:59 set-home-trusted-zone.sh\n  -rw-r--r-- 1 livings livings 5283 Sep 26 12:40 shield-kitty-fail2ban.local\n  -rwxr-xr-x 1 livings livings 5118 Sep 26 13:04 unban-self.sh\n  -rw-r--r-- 1 livings livings 1760 Sep 26 13:05 workstation.xml\n","exit":0,"truncated":false},"title":"echo \"═══ DOES IT EXIST RIGHT NOW? ═══\"\nls -la /home/livings/Projects/zen-hardening/ 2>&1 | sed ''s/^/  /''","time":{"start":1790453738414,"end":1790453738427}}}');
