INSERT INTO part VALUES('prt_0df5ddc15001dslQLk8N6HxT14','msg_0df5dd2870017ZYd0VfqjK9gwh','ses_f211dfcd4ffevS1Yoddwab036g',1790453865494,1790453865508,'{"type":"tool","tool":"read","callID":"call_function_bfz5xsc11vld_1","state":{"status":"completed","input":{"filePath":"/home/livings/Projects/zen-hardening/unban-self.sh"},"output":"<path>/home/livings/Projects/zen-hardening/unban-self.sh</path>\n<type>file</type>\n<content>\n1: #!/bin/bash\n2: # unban-self.sh — remove fail2ban bans against YOUR OWN current addresses.\n3: #\n4: # WHY THIS EXISTS\n5: #\n6: # The fail2ban policy uses bantime = -1 (permanent) on sddm, sudo and sshd.\n7: # ignoreip covers loopback and RFC1918, so on your home wifi you cannot ban\n8: # yourself. But the moment you connect over a PUBLIC address — tethering, a\n9: # cafe, an airport — your address is no longer in ignoreip, and four\n10: # fat-fingered sudo passwords permanently bans you from your own machine, on\n11: # every port, with no expiry.\n12: #\n13: # This script is the escape hatch. It reads your CURRENT addresses and clears\n14: # bans against exactly those, so you can always get back in from the console\n15: # you are sitting at.\n16: #\n17: # Usage:\n18: #   ./unban-self.sh            unban every current address of this machine\n19: #   ./unban-self.sh <ip>       unban one specific address\n20: #   ./unban-self.sh --list     show current addresses and whether any are banned\n21: #\n22: # It only ever touches addresses that are yours right now. It cannot unban an\n23: # arbitrary attacker, and it will not clear a ban on an address you do not\n24: # currently hold.\n25: \n26: set -uo pipefail\n27: \n28: die() { echo \"ERROR: $*\" >&2; exit 1; }\n29: \n30: command -v fail2ban-client >/dev/null 2>&1 || die \"fail2ban-client not found\"\n31: \n32: # The addresses this machine holds right now.\n33: current_addresses() {\n34:     {\n35:         ip -4 addr show scope global 2>/dev/null |\n36:             awk ''/inet /{split($2,a,\"/\"); print a[1]}''\n37:         ip -6 addr show scope global 2>/dev/null |\n38:             awk ''/inet6 /{split($2,a,\"/\"); print a[1]}''\n39:     } | grep -v ''^fe80::'' | sort -u\n40: }\n41: \n42: banned_in_jail() {\n43:     # Echo the banned IPs for a jail, one per line. Empty if none/unreadable.\n44:     fail2ban-client status \"$1\" 2>/dev/null |\n45:         awk ''/Currently banned:/{flag=1; next} /Total banned:/{flag=0} flag'' |\n46:         tr '','' ''\\n'' | sed ''s/^[[:space:]]*//; s/[[:space:]]*$//'' |\n47:         grep -v ''^$''\n48: }\n49: \n50: jails() {\n51:     fail2ban-client status 2>/dev/null |\n52:         awk ''/Jail list:/{flag=1; next} flag'' |\n53:         tr '','' ''\\n'' | sed ''s/^[[:space:]]*//; s/[[:space:]]*$//'' |\n54:         grep -v ''^$''\n55: }\n56: \n57: # --- Input validation FIRST, so a typo is reported as a typo rather than as\n58: # --- a permissions problem, and never reaches a command.\n59: if [ $# -ge 1 ] && [ \"$1\" != \"--list\" ] && [ \"$1\" != \"-l\" ]; then\n60:     if ! [[ \"$1\" =~ ^[0-9a-fA-F:.]+$ ]]; then\n61:         die \"not a valid IP address: $1\"\n62:     fi\n63: fi\n64: \n65: # fail2ban''s control socket is root-only (mode 0700 on\n66: # /var/run/fail2ban/fail2ban.sock), so EVERY subcommand here needs root --\n67: # including the read-only ones. Verified: `fail2ban-client status` without root\n68: # returns \"Permission denied to socket\". Offering an unprivileged --list that\n69: # silently shows an empty jail list would be worse than useless: it would look\n70: # like \"nobody is banned\" at exactly the moment you need to know you are.\n71: if [ \"$(id -u)\" -ne 0 ]; then\n72:     die \"needs root: sudo $0 $*\"\n73: fi\n74: \n75: cmd_list() {\n76:     echo \"=== addresses this machine currently holds ===\"\n77:     local addrs; addrs=\"$(current_addresses)\"\n78:     if [ -z \"$addrs\" ]; then\n79:         echo \"  (none — no global-scope address. Connected by cable? Check ''ip a'')\"\n80:     else\n81:         echo \"$addrs\" | sed ''s/^/  /''\n82:     fi\n83: \n84:     echo\n85:     echo \"=== per-jail banned list, marking YOUR addresses ===\"\n86:     local j any=0\n87:     for j in $(jails); do\n88:         echo \"  [$j]\"\n89:         local banned; banned=\"$(banned_in_jail \"$j\")\"\n90:         if [ -z \"$banned\" ]; then\n91:             echo \"    (nobody banned)\"\n92:             continue\n93:         fi\n94:         while read -r ip; do\n95:             [ -n \"$ip\" ] || continue\n96:             if echo \"$addrs\" | grep -qxF \"$ip\"; then\n97:                 echo \"    $ip   <-- THIS IS YOU — run: sudo $0\"\n98:                 any=1\n99:             else\n100:                 echo \"    $ip\"\n101:             fi\n102:         done <<< \"$banned\"\n103:     done\n104: \n105:     [ \"$any\" -eq 1 ] && echo && echo \"You are banned. Clear it with: sudo $0\"\n106:     return 0\n107: }\n108: \n109: cmd_unban_one() {\n110:     local target=\"$1\" cleared=0 j\n111:     for j in $(jails); do\n112:         if banned_in_jail \"$j\" | grep -qxF \"$target\"; then\n113:             if fail2ban-client set \"$j\" unbanip \"$target\" >/dev/null 2>&1; then\n114:                 echo \"  unbanned $target from $j\"\n115:                 cleared=1\n116:             else\n117:                 echo \"  FAILED to unban $target from $j\" >&2\n118:             fi\n119:         fi\n120:     done\n121:     [ \"$cleared\" -eq 1 ] || echo \"  $target was not banned anywhere\"\n122: }\n123: \n124: case \"${1:-}\" in\n125:     --list|-l)\n126:         cmd_list\n127:         ;;\n128:     \"\")\n129:         echo \"=== clearing bans against this machine''s current addresses ===\"\n130:         addrs=\"$(current_addresses)\"\n131:         if [ -z \"$addrs\" ]; then\n132:             die \"no global-scope address found; pass one explicitly: $0 <ip>\"\n133:         fi\n134:         echo \"$addrs\" | sed ''s/^/  address: /''\n135:         for ip in $addrs; do\n136:             cmd_unban_one \"$ip\"\n137:         done\n138:         echo\n139:         echo \"Note: firewalld rich rules are applied by fail2ban''s action; if a\"\n140:         echo \"ban persists, check: firewall-cmd --list-rich-rules\"\n141:         ;;\n142:     *)\n143:         if ! [[ \"$1\" =~ ^[0-9a-fA-F:.]+$ ]]; then\n144:             die \"not a valid address: $1\"\n145:         fi\n146:         echo \"=== unban $1 ===\"\n147:         cmd_unban_one \"$1\"\n148:         ;;\n149: esac\n\n(End of file - total 149 lines)\n</content>","metadata":{"preview":"#!/bin/bash\n# unban-self.sh — remove fail2ban bans against YOUR OWN current addresses.\n#\n# WHY THIS EXISTS\n#\n# The fail2ban policy uses bantime = -1 (permanent) on sddm, sudo and sshd.\n# ignoreip covers loopback and RFC1918, so on your home wifi you cannot ban\n# yourself. But the moment you connect over a PUBLIC address — tethering, a\n# cafe, an airport — your address is no longer in ignoreip, and four\n# fat-fingered sudo passwords permanently bans you from your own machine, on\n# every port, with no expiry.\n#\n# This script is the escape hatch. It reads your CURRENT addresses and clears\n# bans against exactly those, so you can always get back in from the console\n# you are sitting at.\n#\n# Usage:\n#   ./unban-self.sh            unban every current address of this machine\n#   ./unban-self.sh <ip>       unban one specific address\n#   ./unban-self.sh --list     show current addresses and whether any are banned","truncated":false,"loaded":[],"display":{"type":"file","path":"/home/livings/Projects/zen-hardening/unban-self.sh","text":"#!/bin/bash\n# unban-self.sh — remove fail2ban bans against YOUR OWN current addresses.\n#\n# WHY THIS EXISTS\n#\n# The fail2ban policy uses bantime = -1 (permanent) on sddm, sudo and sshd.\n# ignoreip covers loopback and RFC1918, so on your home wifi you cannot ban\n# yourself. But the moment you connect over a PUBLIC address — tethering, a\n# cafe, an airport — your address is no longer in ignoreip, and four\n# fat-fingered sudo passwords permanently bans you from your own machine, on\n# every port, with no expiry.\n#\n# This script is the escape hatch. It reads your CURRENT addresses and clears\n# bans against exactly those, so you can always get back in from the console\n# you are sitting at.\n#\n# Usage:\n#   ./unban-self.sh            unban every current address of this machine\n#   ./unban-self.sh <ip>       unban one specific address\n#   ./unban-self.sh --list     show current addresses and whether any are banned\n#\n# It only ever touches addresses that are yours right now. It cannot unban an\n# arbitrary attacker, and it will not clear a ban on an address you do not\n# currently hold.\n\nset -uo pipefail\n\ndie() { echo \"ERROR: $*\" >&2; exit 1; }\n\ncommand -v fail2ban-client >/dev/null 2>&1 || die \"fail2ban-client not found\"\n\n# The addresses this machine holds right now.\ncurrent_addresses() {\n    {\n        ip -4 addr show scope global 2>/dev/null |\n            awk ''/inet /{split($2,a,\"/\"); print a[1]}''\n        ip -6 addr show scope global 2>/dev/null |\n            awk ''/inet6 /{split($2,a,\"/\"); print a[1]}''\n    } | grep -v ''^fe80::'' | sort -u\n}\n\nbanned_in_jail() {\n    # Echo the banned IPs for a jail, one per line. Empty if none/unreadable.\n    fail2ban-client status \"$1\" 2>/dev/null |\n        awk ''/Currently banned:/{flag=1; next} /Total banned:/{flag=0} flag'' |\n        tr '','' ''\\n'' | sed ''s/^[[:space:]]*//; s/[[:space:]]*$//'' |\n        grep -v ''^$''\n}\n\njails() {\n    fail2ban-client status 2>/dev/null |\n        awk ''/Jail list:/{flag=1; next} flag'' |\n        tr '','' ''\\n'' | sed ''s/^[[:space:]]*//; s/[[:space:]]*$//'' |\n        grep -v ''^$''\n}\n\n# --- Input validation FIRST, so a typo is reported as a typo rather than as\n# --- a permissions problem, and never reaches a command.\nif [ $# -ge 1 ] && [ \"$1\" != \"--list\" ] && [ \"$1\" != \"-l\" ]; then\n    if ! [[ \"$1\" =~ ^[0-9a-fA-F:.]+$ ]]; then\n        die \"not a valid IP address: $1\"\n    fi\nfi\n\n# fail2ban''s control socket is root-only (mode 0700 on\n# /var/run/fail2ban/fail2ban.sock), so EVERY subcommand here needs root --\n# including the read-only ones. Verified: `fail2ban-client status` without root\n# returns \"Permission denied to socket\". Offering an unprivileged --list that\n# silently shows an empty jail list would be worse than useless: it would look\n# like \"nobody is banned\" at exactly the moment you need to know you are.\nif [ \"$(id -u)\" -ne 0 ]; then\n    die \"needs root: sudo $0 $*\"\nfi\n\ncmd_list() {\n    echo \"=== addresses this machine currently holds ===\"\n    local addrs; addrs=\"$(current_addresses)\"\n    if [ -z \"$addrs\" ]; then\n        echo \"  (none — no global-scope address. Connected by cable? Check ''ip a'')\"\n    else\n        echo \"$addrs\" | sed ''s/^/  /''\n    fi\n\n    echo\n    echo \"=== per-jail banned list, marking YOUR addresses ===\"\n    local j any=0\n    for j in $(jails); do\n        echo \"  [$j]\"\n        local banned; banned=\"$(banned_in_jail \"$j\")\"\n        if [ -z \"$banned\" ]; then\n            echo \"    (nobody banned)\"\n            continue\n        fi\n        while read -r ip; do\n            [ -n \"$ip\" ] || continue\n            if echo \"$addrs\" | grep -qxF \"$ip\"; then\n                echo \"    $ip   <-- THIS IS YOU — run: sudo $0\"\n                any=1\n            else\n                echo \"    $ip\"\n            fi\n        done <<< \"$banned\"\n    done\n\n    [ \"$any\" -eq 1 ] && echo && echo \"You are banned. Clear it with: sudo $0\"\n    return 0\n}\n\ncmd_unban_one() {\n    local target=\"$1\" cleared=0 j\n    for j in $(jails); do\n        if banned_in_jail \"$j\" | grep -qxF \"$target\"; then\n            if fail2ban-client set \"$j\" unbanip \"$target\" >/dev/null 2>&1; then\n                echo \"  unbanned $target from $j\"\n                cleared=1\n            else\n                echo \"  FAILED to unban $target from $j\" >&2\n            fi\n        fi\n    done\n    [ \"$cleared\" -eq 1 ] || echo \"  $target was not banned anywhere\"\n}\n\ncase \"${1:-}\" in\n    --list|-l)\n        cmd_list\n        ;;\n    \"\")\n        echo \"=== clearing bans against this machine''s current addresses ===\"\n        addrs=\"$(current_addresses)\"\n        if [ -z \"$addrs\" ]; then\n            die \"no global-scope address found; pass one explicitly: $0 <ip>\"\n        fi\n        echo \"$addrs\" | sed ''s/^/  address: /''\n        for ip in $addrs; do\n            cmd_unban_one \"$ip\"\n        done\n        echo\n        echo \"Note: firewalld rich rules are applied by fail2ban''s action; if a\"\n        echo \"ban persists, check: firewall-cmd --list-rich-rules\"\n        ;;\n    *)\n        if ! [[ \"$1\" =~ ^[0-9a-fA-F:.]+$ ]]; then\n            die \"not a valid address: $1\"\n        fi\n        echo \"=== unban $1 ===\"\n        cmd_unban_one \"$1\"\n        ;;\nesac","lineStart":1,"lineEnd":149,"totalLines":149,"truncated":false}},"title":"home/livings/Projects/zen-hardening/unban-self.sh","time":{"start":1790453865499,"end":1790453865507}}}');
