INSERT INTO part VALUES('prt_0df5e707b001aT410INOlea1nK','msg_0df5e6794001rgXA5gFpWDO1EI','ses_f20e5cfc2ffeSFa4odnoYLiUOk',1790453903483,1790453903606,'{"type":"tool","tool":"bash","callID":"call_function_i35wc6098yrp_1","state":{"status":"completed","input":{"command":"ps -eo pid,comm 2>/dev/null | grep -E \"git|index-pack\" | head; echo \"--- du ---\"; du -sh ~/.cache/paru/clone/electron34 2>/dev/null; df -h / | tail -1","timeout":180000},"output":"--- du ---\n1.3G\t/home/livings/.cache/paru/clone/electron34\n/dev/mapper/luks-8c39203b-6764-4e5c-b1a9-6dedb64c05c1  477G   16G  459G   4% /\n","metadata":{"output":"--- du ---\n1.3G\t/home/livings/.cache/paru/clone/electron34\n/dev/mapper/luks-8c39203b-6764-4e5c-b1a9-6dedb64c05c1  477G   16G  459G   4% /\n","exit":0,"truncated":false},"title":"ps -eo pid,comm 2>/dev/null | grep -E \"git|index-pack\" | head; echo \"--- du ---\"; du -sh ~/.cache/paru/clone/electron34 2>/dev/null; df -h / | tail -1","time":{"start":1790453903570,"end":1790453903606}}}');
INSERT INTO part VALUES('prt_0df5e70f7001nGuppaIgMrNCsa','msg_0df5e6794001rgXA5gFpWDO1EI','ses_f20e5cfc2ffeSFa4odnoYLiUOk',1790453903608,1790453903608,'{"reason":"tool-calls","type":"step-finish","tokens":{"total":110431,"input":65,"output":91,"reasoning":0,"cache":{"write":0,"read":110275}},"cost":0}');
