INSERT INTO part VALUES('prt_0df5eab6f001BEL2D4z1RBcsM3','msg_0df5ea29200105JKWhIIo74uFv','ses_f20e5cfc2ffeSFa4odnoYLiUOk',1790453918575,1790453980209,'{"type":"tool","tool":"bash","callID":"call_function_vea9c6v1ie2t_1","state":{"status":"completed","input":{"command":"cd ~/Projects/buildlog\ngit add seed-vcs-sources.sh\ngit commit -q -m \"seed-vcs-sources.sh: stop deep-falling-back on unfetchable pins\n\nA tag pin that will not fetch shallowly fell through to the default branch\nat --depth 50. For nodejs/node (pinned #tag=v20.19.1) that pulled 331,695\nobjects / 600MB of history to satisfy a pin makepkg resolves in one clone.\nStall rate was ~2 repos per 3 minutes.\n\n- unfetchable tag/branch pins now DEFER instead of falling back\n- last-resort branch fetch is depth 1, not 50\n- every fetch wrapped in a timeout so one slow host cannot stall the seed\"\nrm -f /home/livings/.cache/paru/seed.log\nnohup bash seed-vcs-sources.sh ~/.cache/paru/clone/electron34 > /home/livings/.cache/paru/seed.log 2>&1 &\necho \"restarted, pid $!\"\nsleep 60\necho \"=== progress: $(grep -cE ''^  (ok|warn|skip|DEFER|FAIL)'' /home/livings/.cache/paru/seed.log) / 165 ===\"\ntail -8 /home/livings/.cache/paru/seed.log","timeout":120000},"output":"restarted, pid 224928\n=== progress: 164 / 165 ===\n  DEFER  chromium-mirror_third_party_dawn_third_party_protobuf ( not fetchable shallowly; makepkg will clone)\n  DEFER  chromium-mirror_third_party_dawn_tools_protoc_wrapper ( not fetchable shallowly; makepkg will clone)\n  DEFER  chromium-mirror_third_party_dawn_third_party_jsoncpp ( not fetchable shallowly; makepkg will clone)\n  DEFER  chromium-mirror_third_party_dawn_third_party_langsvr ( not fetchable shallowly; makepkg will clone)\n  DEFER  chromium-mirror_third_party_dawn_third_party_partition_alloc ( not fetchable shallowly; makepkg will clone)\n  DEFER  chromium-mirror_third_party_openscreen_src_third_party_tinycbor_src ( not fetchable shallowly; makepkg will clone)\n\ndone. verify with: du -sh /home/livings/.cache/paru/clone/electron34\n","metadata":{"output":"restarted, pid 224928\n=== progress: 164 / 165 ===\n  DEFER  chromium-mirror_third_party_dawn_third_party_protobuf ( not fetchable shallowly; makepkg will clone)\n  DEFER  chromium-mirror_third_party_dawn_tools_protoc_wrapper ( not fetchable shallowly; makepkg will clone)\n  DEFER  chromium-mirror_third_party_dawn_third_party_jsoncpp ( not fetchable shallowly; makepkg will clone)\n  DEFER  chromium-mirror_third_party_dawn_third_party_langsvr ( not fetchable shallowly; makepkg will clone)\n  DEFER  chromium-mirror_third_party_dawn_third_party_partition_alloc ( not fetchable shallowly; makepkg will clone)\n  DEFER  chromium-mirror_third_party_openscreen_src_third_party_tinycbor_src ( not fetchable shallowly; makepkg will clone)\n\ndone. verify with: du -sh /home/livings/.cache/paru/clone/electron34\n","exit":0,"truncated":false},"title":"cd ~/Projects/buildlog\ngit add seed-vcs-sources.sh\ngit commit -q -m \"seed-vcs-sources.sh: stop deep-falling-back on unfetchable pins\n\nA tag pin that will not fetch shallowly fell through to the default branch\nat --depth 50. For nodejs/node (pinned #tag=v20.19.1) that pulled 331,695\nobjects / 600MB of history to satisfy a pin makepkg resolves in one clone.\nStall rate was ~2 repos per 3 minutes.\n\n- unfetchable tag/branch pins now DEFER instead of falling back\n- last-resort branch fetch is depth 1, not 50\n- every fetch wrapped in a timeout so one slow host cannot stall the seed\"\nrm -f /home/livings/.cache/paru/seed.log\nnohup bash seed-vcs-sources.sh ~/.cache/paru/clone/electron34 > /home/livings/.cache/paru/seed.log 2>&1 &\necho \"restarted, pid $!\"\nsleep 60\necho \"=== progress: $(grep -cE ''^  (ok|warn|skip|DEFER|FAIL)'' /home/livings/.cache/paru/seed.log) / 165 ===\"\ntail -8 /home/livings/.cache/paru/seed.log","time":{"start":1790453920180,"end":1790453980207}}}');
