log/seed-vcs-sources.sh","patch":"Index: /home/livings/Projects/buildlog/seed-vcs-sources.sh\n===================================================================\n--- /home/livings/Projects/buildlog/seed-vcs-sources.sh\n+++ /home/livings/Projects/buildlog/seed-vcs-sources.sh\n@@ -102,22 +102,33 @@\n fi\n \n echo\n echo \"== DEPS repos ==\"\n-# shellcheck disable=SC2013\n-sed -n ''/^source=(/,/^)/p'' \"$PKGBUILD\" \\\n-  | grep -oE ''[A-Za-z0-9_.-]+::git\\+https?://[^#]+'' \\\n-  | while IFS= read -r entry; do\n-        name=\"${entry%%::*}\"\n-        rest=\"${entry#*::git+}\"\n-        url=\"${rest%%#*}\"\n-        frag=\"\"\n-        case \"$rest\" in\n-            *\"#\"*) frag=\"${rest#*#}\" ;;\n-        esac\n-        url=\"${url%.git}\"\n-        [ \"$name\" = \"chromium-mirror\" ] && continue\n-        seed_one \"$name\" \"$url\" \"$frag\"\n-    done\n+# Parse in bash, not grep. Several source names contain ''+'' (libc++_src,\n+# libc++abi_src), which a [A-Za-z0-9_.-] character class silently truncates --\n+# that split them into bogus names like \"_src\" and left every fragment empty.\n+# Take each whitespace-delimited token whole and split it ourselves.\n+for entry in $(sed -n ''/^source=(/,/^)/p'' \"$PKGBUILD\" \\\n+                | tr '' \\t'' ''\\n\\n'' | grep ''::git+''); do\n+    entry=\"${entry%\\\"}\"; entry=\"${entry#\\\"}\"\n+    [ -z \"$entry\" ] && continue\n+    case \"$entry\" in\n+        *\"::git+\"*) ;;\n+        *) continue ;;\n+    esac\n \n+    name=\"${entry%%::*}\"\n+    rest=\"${entry#*::git+}\"\n+    url=\"${rest%%#*}\"\n+    frag=\"\"\n+    case \"$rest\" in\n+        *\"#\"*) frag=\"${rest#*#}\" ;;\n+    esac\n+    frag=\"${frag%\\\"}\"; frag=\"${frag#\\\"}\"\n+    url=\"${url%.git}\"\n+\n+    [ \"$name\" = \"chromium-mirror\" ] && continue\n+    seed_one \"$name\" \"$url\" \"$frag\"\n+done\n+\n echo\n echo \"done. verify with: du -sh $PKGDIR\"\n","additions":26,"deletions":15},"truncated":false},"title":"home/livings/Projects/buildlog/seed-vcs-sources.sh","time":{"start":1790453993707,"end":1790453993718}}}');
