ess.mac-address-denylist,802-11-wireless.mac-address-randomization,802-11-wireless.mtu,802-11-wireless.seen-bssids,802-11-wireless.hidden,802-11-wireless.powersave,802-11-wireless.wake-on-wlan,802-11-wireless.ap-isolation,802-11-wireless.channel-width\n  lo             mode=<unset>    mac=<random per net>\n\n  current kernel-level MAC: f4:a4:75:e8:00:b2\n\n  NOTE: mode must read ''random''. ''stable''/''preserve'' = permanent MAC.\n","metadata":{"output":"═══ MAC RANDOMIZATION — did set-anon-identity.sh actually work? ═══\nError: ''connection show'': invalid field ''802-11-wireless.mac-address-mode''; allowed fields: 802-11-wireless.ssid,802-11-wireless.mode,802-11-wireless.band,802-11-wireless.channel,802-11-wireless.bssid,802-11-wireless.mac-address,802-11-wireless.cloned-mac-address,802-11-wireless.generate-mac-address-mask,802-11-wireless.mac-address-blacklist,802-11-wireless.mac-address-denylist,802-11-wireless.mac-address-randomization,802-11-wireless.mtu,802-11-wireless.seen-bssids,802-11-wireless.hidden,802-11-wireless.powersave,802-11-wireless.wake-on-wlan,802-11-wireless.ap-isolation,802-11-wireless.channel-width\n  USL - Public   mode=<unset>    mac=<random per net>\nError: ''connection show'': invalid field ''802-11-wireless.mac-address-mode''; allowed fields: 802-11-wireless.ssid,802-11-wireless.mode,802-11-wireless.band,802-11-wireless.channel,802-11-wireless.bssid,802-11-wireless.mac-address,802-11-wireless.cloned-mac-address,802-11-wireless.generate-mac-address-mask,802-11-wireless.mac-address-blacklist,802-11-wireless.mac-address-denylist,802-11-wireless.mac-address-randomization,802-11-wireless.mtu,802-11-wireless.seen-bssids,802-11-wireless.hidden,802-11-wireless.powersave,802-11-wireless.wake-on-wlan,802-11-wireless.ap-isolation,802-11-wireless.channel-width\n  lo             mode=<unset>    mac=<random per net>\n\n  current kernel-level MAC: f4:a4:75:e8:00:b2\n\n  NOTE: mode must read ''random''. ''stable''/''preserve'' = permanent MAC.\n","exit":0,"truncated":false},"title":"echo \"═══ MAC RANDOMIZATION — did set-anon-identity.sh actually work? ═══\"\nfor c in $(nmcli -t -f UUID connection show --active 2>/dev/null | cut -d: -f1); do\n  nm=$(nmcli -g connection.id con show \"$c\")\n  mode=$(nmcli -g 802-11-wireless.mac-address-mode con show \"$c\")\n  mac=$(nmcli -g 802-11-wireless.mac-address con show \"$c\")\n  printf \"  %-14s mode=%-10s mac=%s\\n\" \"$nm\" \"${mode:-<unset>}\" \"${mac:-<random per net>}\"\ndone\necho\necho \"  current kernel-level MAC: $(cat /sys/class/net/wlo1/address)\"\necho\necho \"  NOTE: mode must read ''random''. ''stable''/''preserve'' = permanent MAC.\"","time":{"start":1790454607501,"end":1790454611110}}}');
INSERT INTO part VALUES('prt_0df692e90001Sm873fhh8xwNp0','msg_0df690752001yMA1fNZE8c542G','ses_f211dfcd4ffevS1Yoddwab036g',1790454607504,1790454608740,'{"type":"tool","tool":"bash","callID":"call_function_3nxn5yfkfxpg_2","state":{"status":"completed","input":{"command":"echo \"═══ HOSTNAME / IDENTITY — re-verify end state ═══\"\necho \"  hostname        : $(hostname)\"\necho \"  /etc/hostname   : $(cat /etc/hostname)\"\necho \"  /etc/hosts      : $(grep ''^127.0.1.1'' /etc/hosts)\"\necho \"  pretty          : $(hostnamectl --pretty 2>/dev/null)\"\necho\necho \"═══ anything still leaking the old name? ═══\"\ngrep -rIl \"living-asustuf\" /etc 2>/dev/null | head -5 | sed ''s/^/  /'' || echo \"  [ok] no /etc references to the old hostname\""},"output":"═══ HOSTNAME / IDENTITY — re-verify end state ═══\n  hostname        : zero\n  /etc/hostname   : zero\n  /etc/hosts      : 127.0.1.1\tzero\n  pretty          : \n\n═══ anything still leaking the old name? ═══\n","metadata":{"output":"═══ HOSTNAME / IDENTITY — re-verify end state ═══\n  hostname        : zero\n  /etc/hostname   : zero\n  /etc/hosts      : 127.0.1.1\tzero\n  pretty          : \n\n═══ anything still leaking the old name? ═══\n","exit":0,"truncated":false},"title":"echo \"═══ HOSTNAME / IDENTITY — re-verify end state ═══\"\necho \"  hostname        : $(hostname)\"\necho \"  /etc/hostname   : $(cat /etc/hostname)\"\necho \"  /etc/hosts      : $(grep ''^127.0.1.1'' /etc/hosts)\"\necho \"  pretty          : $(hostnamectl --pretty 2>/dev/null)\"\necho\necho \"═══ anything still leaking the old name? ═══\"\ngrep -rIl \"living-asustuf\" /etc 2>/dev/null | head -5 | sed ''s/^/  /'' || echo \"  [ok] no /etc references to the old hostname\"","time":{"start":1790454608622,"end":1790454608739}}}');
INSERT INTO part VALUES('prt_0df693ca8001LezTDV0vr4SclZ','msg_0df690752001yMA1fNZE8c542G','ses_f211dfcd4ffevS1Yoddwab036g',1790454611112,1790454611113,'{"reason":"tool-calls","type":"step-finish","tokens":{"total":125123,"input":22,"output":433,"reasoning":471,"cache":{"write":0,"read":124197}},"cost":0}');
INSERT INTO part VALUES('prt_0df694757001g8cO3CmmTqFq9U','msg_0df693cc3001j5kxqIZqFW1JS5','ses_f211dfcd4ffevS1Yoddwab036g',1790454613847,1790454613848,'{"type":"step-start"}');
INSERT INTO part VALUES('prt_0df69475a001I4iZUjmPyo1aIO','msg_0df693cc3001j5kxqIZqFW1JS5','ses_f211dfcd4ffevS1Yoddwab036g',1790454613850,1790454620348,'{"type":"reasoning","text":"Two important findings:\n\n1. **MAC randomization was NOT applied.** The property is `802-11-wireless.mac-address-randomization` in this NetworkManager version, NOT `802-11-wireless.mac-address-mode`. So my script''s `nmcli -g 802-11-wireless.mac-address-mode` failed silently (I had `2>/dev/null` and `|| true`-ish handling), and the randomization never got set. The current MAC is still `f4:a4:75:e8:00:b2` — the real hardware MAC.\n\nActually wait — in my script I used:\n```bash\nif nmcli -g 802-11-wireless.mac-address-mode con show \"$uuid\" 2>/dev/null | grep -qx random; then\n```\nThe property doesn''t exist → nmcli errors → output is empty → grep doesn''t match → so it goes to the else branch → `nmcli con mod \"$uuid\" 802-11-wireless.mac-address-mode random`. But that property doesn''t exist either, so `nmcli con mod` would FAIL. And my script didn''t check that... let me look. I had:\n```bash\nnmcli con mod \"$uuid\" 802-11-wireless.mac-address-mode random\nCHANGED=1\necho \"  [ok] ''${con_id}'': mac-address-mode -> random\"\n```\nNo error check! So it printed \"[ok]\" even if nmcli errored. Wait, but `set -euo pipefail` is on, so a failing command would abort the script. Hmm — `nmcli con mod` returning non-zero with `set -e` would exit the script. Unless it succeeded.\n\nActually — the correct property in NetworkManager is `802-11-wireless.mac-address-randomization` (values: 0=permanent/default, 1=random, 2=stable). Older NM used `mac-address-mode`. This NM version doesn''t have `mac-address-mode`.\n\nSo my script would have hit `set -e` and died at that line, meaning the DHCP hostname step (step 3) never ran either! Let me verify: step 2 is the MAC step. If `nmcli con mod` failed, `set -e` aborts before step 3.\n\nBut the hostname part (step 1) already completed. So the script partially ran: hostname done, MAC failed, DHCP suppression never ran.\n\nLet me verify the DHCP send-hostname state.\n\nAlso `nmcli` printed errors which means my `2>/dev/null` didn''t suppress them in the `-g` call... Actually the errors I see are from MY diagnostic command just now, not from the script. The script had `2>/dev/null` on the `-g` call but not on `nmcli con mod`. So the script would have shown the error.\n\nAnyway — the facts:\n- MAC randomization: NOT set. MAC is still the real one.\n- The property name is wrong for this NM version.\n- The script likely aborted at step 2, so DHCP hostname suppression (step 3) never ran.\n\nLet me fix the script to use the correct property and make it robust, and apply it.\n\n2. **Hostname fully verified as `zero`** everywhere, no /etc leakage.\n\nLet me fix the script properly. This is a real bug I need to own.\n\nLet me check the correct property and the current values.","time":{"start":1790454613850,"end":1790454620346}}');
INSERT INTO part VALUES('prt_0df6960be001NdMGZg4SbLlthS','msg_0df693cc3001j5kxqIZqFW1JS5','ses_f211dfcd4ffevS1Yoddwab036g',1790454620350,1790454621981,'{"type":"text","text":"Found a real bug in my own script. MAC randomization was **never applied** — `wlo1` is still broadcasting `f4:a4:75:e8:00:b2`, your actual hardware MAC.","time":{"start":1790454620350,"end":1790454621979}}');
INSERT INTO part VALUES('prt_0df69621d0011hpg90PaA564Ck','msg_0df693cc3001j5kxqIZqFW1JS5','ses_f211dfcd4ffevS1Yoddwab036g',1790454620701,1790454622053,'{"type":"tool","tool":"bash","callID":"call_function_69io2znjxqm9_1","state":{"status":"completed","input":{"command":"echo \"═══ ROOT CAUSE: wrong property name for this NetworkManager ═══\"\nnmcli -v | sed ''s/^/  /''\necho\necho \"  my script used:  802-11-wireless.mac-address-mode      <-- does not exist\"\necho \"  correct here:   802-11-wireless.mac-address-randomization\"\necho\necho \"═══ CURRENT VALUE (0=permanent 1=random 2=stable) ═══\"\nfor c in $(nmcli -t -f UUID connection show --active 2>/dev/null | cut -d: -f1); do\n  nm=$(nmcli -g connection.id con show \"$c\")\n  r=$(nmcli -g 802-11-wireless.mac-address-randomization con show \"$c\" 2>/dev/null)\n  d=$(nmcli -g 802-11-wireless.mac-address-denylist con show \"$c\" 2>/dev/null)\n  printf \"  %-14s randomization=%-4s denylist=%s\\n\" \"$nm\" \"${r:-0}\" \"${d:-<none>}\"\ndone\necho\necho \"  0 or unset = permanent hardware MAC in use\""},"output":"═══ ROOT CAUSE: wrong property name for this NetworkManager ═══\n  nmcli tool, version 1.58.1-1\n\n  my script used:  802-11-wireless.mac-address-mode      <-- does not exist\n  correct here:   802-11-wireless.mac-address-randomization\n\n═══ CURRENT VALUE (0=permanent 1=random 2=stable) ═══\n  USL - Public   randomization=default denylist=<none>\n  lo             randomization=0    denylist=<none>\n\n  0 or unset = permanent hardware MAC in use\n","metadata":{"output":"═══ ROOT CAUSE: wrong property name for this NetworkManager ═══\n  nmcli tool, version 1.58.1-1\n\n  my script used:  802-11-wireless.mac-address-mode      <-- does not exist\n  correct here:   802-11-wireless.mac-address-randomization\n\n═══ CURRENT VALUE (0=permanent 1=random 2=stable) ═══\n  USL - Public   randomization=default denylist=<none>\n  lo             randomization=0    denylist=<none>\n\n  0 or unset = permanent hardware MAC in use\n","exit":0,"truncated":false},"title":"echo \"═══ ROOT CAUSE: wrong property name for this NetworkManager ═══\"\nnmcli -v | sed ''s/^/  /''\necho\necho \"  my script used:  802-11-wireless.mac-address-mode      <-- does not exist\"\necho \"  correct here:   802-11-wireless.mac-address-randomization\"\necho\necho \"═══ CURRENT VALUE (0=permanent 1=random 2=stable) ═══\"\nfor c in $(nmcli -t -f UUID connection show --active 2>/dev/null | cut -d: -f1); do\n  nm=$(nmcli -g connection.id con show \"$c\")\n  r=$(nmcli -g 802-11-wireless.mac-address-randomization con show \"$c\" 2>/dev/null)\n  d=$(nmcli -g 802-11-wireless.mac-address-denylist con show \"$c\" 2>/dev/null)\n  printf \"  %-14s randomization=%-4s denylist=%s\\n\" \"$nm\" \"${r:-0}\" \"${d:-<none>}\"\ndone\necho\necho \"  0 or unset = permanent hardware MAC in use\"","time":{"start":1790454621963,"end":1790454622052}}}');
INSERT INTO part VALUES('prt_0df696766001alkDPzWkPex9Ki','msg_0df693cc3001j5kxqIZqFW1JS5','ses_f211dfcd4ffevS1Yoddwab036g',1790454622054,1790454622055,'{"reason":"tool-calls","type":"step-finish","tokens":{"total":126718,"input":561,"output":329,"reasoning":707,"cache":{"write":0,"read":125121}},"cost":0}');
INSERT INTO part VALUES('prt_0df69701e001PE71duQ5PD1VLI','msg_0df696782001EH1z55MY5VXciY','ses_f211dfcd4ffevS1Yoddwab036g',1790454624286,1790454624287,'{"type":"step-start"}');
INSERT INTO part VALUES('prt_0df697020001Q1SsmUYLhHpidq','msg_0df696782001EH1z55MY5VXciY','ses_f211dfcd4ffevS1Yoddwab036g',1790454624288,1790454629408,'{"type":"text","text":"Confirmed. `randomization=default` (0) — permanent MAC. My script used `mac-address-mode`, which this NetworkManager 1.58 doesn''t have, so `nmcli con mod` failed and `set -e` aborted the script at step 2 — which also means **step 3, DHCP hostname suppression, never ran.** Fixing both:","time":{"start":1790454624288,"end":1790454629407}}');
INSERT INTO part VALUES('prt_0df697352001D8gpqzmbPC3bJL','msg_0df696782001EH1z55MY5VXciY','ses_f211dfcd4ffevS1Yoddwab036g',1790454625106,1790454629417,'{"type":"tool","tool":"edit","callID":"call_function_32v8xq8i08sl_1","state":{"status":"completed","input":{"filePath":"/home/livings/Projects/zen-hardening/set-anon-identity.sh","newString":"hr \"2. Per-network random MAC on wifi\"\n\n# Without this, NetworkManager uses the permanent hardware MAC on every\n# network the machine ever joins, which is the strongest cross-network\n# tracking signal there is.\n#\n# PROPERTY NAME DIFFERS BY NetworkManager VERSION. Verified on 1.58.1:\n#   802-11-wireless.mac-address-randomization   (this version)\n#       0 = default, 1 = random (per network), 2 = stable\n# Older releases used 802-11-wireless.mac-address-mode with values\n# random/stable/preserve. Detect which one this build accepts rather than\n# assuming, and fail loudly if neither works -- a silent no-op here means\n# the hardware MAC keeps broadcasting.\nset_mac_prop=\"\"\nif nmcli -g 802-11-wireless.mac-address-randomization con show \"$(nmcli -t -f UUID con show | head -1)\" >/dev/null 2>&1; then\n  set_mac_prop=\"802-11-wireless.mac-address-randomization\"\n  set_mac_val=\"1\"\nelse\n  set_mac_prop=\"802-11-wireless.mac-address-mode\"\n  set_mac_val=\"random\"\nfi\necho \"  using property: ${set_mac_prop} = ${set_mac_val}\"\n\nwhile read -r uuid; do\n  [ -z \"$uuid\" ] && continue\n  con_id=$(nmcli -g connection.id con show \"$uuid\")\n  cur=$(nmcli -g \"$set_mac_prop\" con show \"$uuid\" 2>/dev/null)\n  if [ \"$cur\" = \"$set_mac_val\" ] || [ \"$cur\" = \"random\" ]; then\n    echo \"  ''${con_id}'': already randomized — skipping\"\n  else\n    if ! nmcli con mod \"$uuid\" \"$set_mac_prop\" \"$set_mac_val\"; then\n      echo \"  [!!] FAILED to set MAC randomization on ''${con_id}''\" >&2\n      MAC_FAILED=1\n    else\n      CHANGED=1\n      echo \"  [ok] ''${con_id}'': mac randomization -> ${set_mac_val}\"\n    fi\n  fi\ndone < <(nmcli -t -f UUID,TYPE con show | awk -F: ''$2==\"802-11-wireless\"{print $1}'')","oldString":"hr \"2. Per-network random MAC on wifi\"\n\n# Without this, NetworkManager uses the permanent hardware MAC on every\n# network the machine ever joins, which is the strongest cross-network\n# tracking signal there is.\nwhile read -r uuid; do\n  [ -z \"$uuid\" ] && continue\n  con_id=$(nmcli -g connection.id con show \"$uuid\")\n  if nmcli -g 802-11-wireless.mac-address-mode con show \"$uuid\" 2>/dev/null | grep -qx random; then\n    echo \"  ''${con_id}'': already random — skipping\"\n  else\n    nmcli con mod \"$uuid\" 802-11-wireless.mac-address-mode random\n    CHANGED=1\n    echo \"  [ok] ''${con_id}'': mac-address-mode -> random\"\n  fi\ndone < <(nmcli -t -f UUID,TYPE con show | awk -F: ''$2==\"802-11-wireless\"{print $1}'')"},"output":"Edit applied successfully.","metadata":{"diagnostics":{},"diff":"Index: /home/livings/Projects/zen-hardening/set-anon-identity.sh\n===================================================================\n--- /home/livings/Projects/zen-hardening/set-anon-identity.sh\n+++ /home/livings/Projects/zen-hardening/set-anon-identity.sh\n@@ -47,17 +47,40 @@\n \n # Without this, NetworkManager uses the permanent hardware MAC on every\n # network the machine ever joins, which is the strongest cross-network\n # tracking signal there is.\n+#\n+# PROPERTY NAME DIFFERS BY NetworkManager VERSION. Verified on 1.58.1:\n+#   802-11-wireless.mac-address-randomization   (this version)\n+#       0 = default, 1 = random (per network), 2 = stable\n+# Older releases used 802-11-wireless.mac-address-mode with values\n+# random/stable/preserve. Detect which one this build accepts rather than\n+# assuming, and fail loudly if neither works -- a silent no-op here means\n+# the hardware MAC keeps broadcasting.\n+set_mac_prop=\"\"\n+if nmcli -g 802-11-wireless.mac-address-randomization con show \"$(nmcli -t -f UUID con show | head -1)\" >/dev/null 2>&1; then\n+  set_mac_prop=\"802-11-wireless.mac-address-randomization\"\n+  set_mac_val=\"1\"\n+else\n+  set_mac_prop=\"802-11-wireless.mac-address-mode\"\n+  set_mac_val=\"random\"\n+fi\n+echo \"  using property: ${set_mac_prop} = ${set_mac_val}\"\n+\n while read -r uuid; do\n   [ -z \"$uuid\" ] && continue\n   con_id=$(nmcli -g connection.id con show \"$uuid\")\n-  if nmcli -g 802-11-wireless.mac-address-mode con show \"$uuid\" 2>/dev/null | grep -qx random; then\n-    echo \"  ''${con_id}'': already random — skipping\"\n+  cur=$(nmcli -g \"$set_mac_prop\" con show \"$uuid\" 2>/dev/null)\n+  if [ \"$cur\" = \"$set_mac_val\" ] || [ \"$cur\" = \"random\" ]; then\n+    echo \"  ''${con_id}'': already randomized — skipping\"\n   else\n-    nmcli con mod \"$uuid\" 802-11-wireless.mac-address-mode random\n-    CHANGED=1\n-    echo \"  [ok] ''${con_id}'': mac-address-mode -> random\"\n+    if ! nmcli con mod \"$uuid\" \"$set_mac_prop\" \"$set_mac_val\"; then\n+      echo \"  [!!] FAILED to set MAC randomization on ''${con_id}''\" >&2\n+      MAC_FAILED=1\n+    else\n+      CHANGED=1\n+      echo \"  [ok] ''${con_id}'': mac randomization -> ${set_mac_val}\"\n+    fi\n   fi\n done < <(nmcli -t -f UUID,TYPE con show | awk -F: ''$2==\"802-11-wireless\"{print $1}'')\n \n hr \"3. Suppress DHCP hostname on every connection\"\n","filediff":{"file":"/home/livings/Projects/zen-hardening/set-anon-identity.sh","patch":"Index: /home/livings/Projects/zen-hardening/set-anon-identity.sh\n===================================================================\n--- /home/livings/Projects/zen-hardening/set-anon-identity.sh\n+++ /home/livings/Projects/zen-hardening/set-anon-identity.sh\n@@ -47,17 +47,40 @@\n \n # Without this, NetworkManager uses the permanent hardware MAC on every\n # network the machine ever joins, which is the strongest cross-network\n # tracking signal there is.\n+#\n+# PROPERTY NAME DIFFERS BY NetworkManager VERSION. Verified on 1.58.1:\n+#   802-11-wireless.mac-address-randomization   (this version)\n+#       0 = default, 1 = random (per network), 2 = stable\n+# Older releases used 802-11-wireless.mac-address-mode with values\n+# random/stable/preserve. Detect which one this build accepts rather than\n+# assuming, and fail loudly if neither works -- a silent no-op here means\n+# the hardware MAC keeps broadcasting.\n+set_mac_prop=\"\"\n+if nmcli -g 802-11-wireless.mac-address-randomization con show \"$(nmcli -t -f UUID con show | head -1)\" >/dev/null 2>&1; then\n+  set_mac_prop=\"802-11-wireless.mac-address-randomization\"\n+  set_mac_val=\"1\"\n+else\n+  set_mac_prop=\"802-11-wireless.mac-address-mode\"\n+  set_mac_val=\"random\"\n+fi\n+echo \"  using property: ${set_mac_prop} = ${set_mac_val}\"\n+\n while read -r uuid; do\n   [ -z \"$uuid\" ] && continue\n   con_id=$(nmcli -g connection.id con show \"$uuid\")\n-  if nmcli -g 802-11-wireless.mac-address-mode con show \"$uuid\" 2>/dev/null | grep -qx random; then\n-    echo \"  ''${con_id}'': already random — skipping\"\n+  cur=$(nmcli -g \"$set_mac_prop\" con show \"$uuid\" 2>/dev/null)\n+  if [ \"$cur\" = \"$set_mac_val\" ] || [ \"$cur\" = \"random\" ]; then\n+    echo \"  ''${con_id}'': already randomized — skipping\"\n   else\n-    nmcli con mod \"$uuid\" 802-11-wireless.mac-address-mode random\n-    CHANGED=1\n-    echo \"  [ok] ''${con_id}'': mac-address-mode -> random\"\n+    if ! nmcli con mod \"$uuid\" \"$set_mac_prop\" \"$set_mac_val\"; then\n+      echo \"  [!!] FAILED to set MAC randomization on ''${con_id}''\" >&2\n+      MAC_FAILED=1\n+    else\n+      CHANGED=1\n+      echo \"  [ok] ''${con_id}'': mac randomization -> ${set_mac_val}\"\n+    fi\n   fi\n done < <(nmcli -t -f UUID,TYPE con show | awk -F: ''$2==\"802-11-wireless\"{print $1}'')\n \n hr \"3. Suppress DHCP hostname on every connection\"\n","additions":28,"deletions":5},"truncated":false},"title":"home/livings/Projects/zen-hardening/set-anon-identity.sh","time":{"start":1790454629406,"end":1790454629416}}}');
