INSERT INTO part VALUES('prt_0df698fb8001wXJRQuUuLEaT2R','msg_0df69844a001Oq7atFBtc5gSuH','ses_f211dfcd4ffevS1Yoddwab036g',1790454632376,1790454633522,'{"type":"tool","tool":"bash","callID":"call_function_n0j9w87ommai_1","state":{"status":"completed","input":{"command":"cd ~/Projects/zen-hardening\npython3 - <<''PY''\nimport re\np=''set-anon-identity.sh''; s=open(p).read()\ns=s.replace(''CHANGED=0'',''CHANGED=0\\nMAC_FAILED=0'')\n# surface the failure at the end instead of silently succeeding\ns=s.replace(''''''hr \"Result\"'''''',''''''hr \"Result\"\n\nif [ \"$MAC_FAILED\" -eq 1 ]; then\n  echo \"  [!!] AT LEAST ONE CONNECTION FAILED MAC RANDOMIZATION.\" >&2\n  echo \"       Your permanent hardware MAC may still be broadcasting.\" >&2\nfi'''''')\nopen(p,''w'').write(s)\nprint(\"  [ok] MAC_FAILED tracking added\")\nPY\nbash -n set-anon-identity.sh && echo \"  [ok] syntax valid\""},"output":"  [ok] MAC_FAILED tracking added\n  [ok] syntax valid\n","metadata":{"output":"  [ok] MAC_FAILED tracking added\n  [ok] syntax valid\n","exit":0,"truncated":false},"title":"cd ~/Projects/zen-hardening\npython3 - <<''PY''\nimport re\np=''set-anon-identity.sh''; s=open(p).read()\ns=s.replace(''CHANGED=0'',''CHANGED=0\\nMAC_FAILED=0'')\n# surface the failure at the end instead of silently succeeding\ns=s.replace(''''''hr \"Result\"'''''',''''''hr \"Result\"\n\nif [ \"$MAC_FAILED\" -eq 1 ]; then\n  echo \"  [!!] AT LEAST ONE CONNECTION FAILED MAC RANDOMIZATION.\" >&2\n  echo \"       Your permanent hardware MAC may still be broadcasting.\" >&2\nfi'''''')\nopen(p,''w'').write(s)\nprint(\"  [ok] MAC_FAILED tracking added\")\nPY\nbash -n set-anon-identity.sh && echo \"  [ok] syntax valid\"","time":{"start":1790454633486,"end":1790454633521}}}');
