INSERT INTO part VALUES('prt_0df69e1550010Xwu4jWd2mFeoO','msg_0df69d815001Smd9LAMuFNo14i','ses_f211dfcd4ffevS1Yoddwab036g',1790454653269,1790454655142,'{"type":"tool","tool":"bash","callID":"call_function_i2a98rjehsho_1","state":{"status":"completed","input":{"command":"echo \"═══ IS TOR ACTUALLY CONNECTED, OR IDLE? ═══\"\njournalctl -u tor -S \"-2h\" --no-pager 2>&1 | tail -8 | sed ''s/^/  /''\necho\necho \"  no output above = tor has logged nothing, which for a healthy\"\necho \"  quiet tor is normal. Confirm via the control port instead:\"\ncat <<''EOF''\n  sudo tor-control 127.0.0.1 9051 <<< ''GETINFO status/bootstrap-phase'' 2>/dev/null\n  # or simply check tor is proxying:\n  curl --socks5-hostname 127.0.0.1:9050 -s https://check.torproject.org/api/ip\nEOF"},"output":"═══ IS TOR ACTUALLY CONNECTED, OR IDLE? ═══\n  Sep 26 12:55:43 zero Tor[209878]: Bootstrapped 55% (loading_descriptors): Loading relay descriptors\n  Sep 26 12:55:44 zero Tor[209878]: Bootstrapped 62% (loading_descriptors): Loading relay descriptors\n  Sep 26 12:55:45 zero Tor[209878]: Bootstrapped 68% (loading_descriptors): Loading relay descriptors\n  Sep 26 12:55:45 zero Tor[209878]: Bootstrapped 73% (loading_descriptors): Loading relay descriptors\n  Sep 26 12:55:45 zero Tor[209878]: Bootstrapped 75% (enough_dirinfo): Loaded enough directory info to build circuits\n  Sep 26 12:55:45 zero Tor[209878]: Bootstrapped 90% (ap_handshake_done): Handshake finished with a relay to build circuits\n  Sep 26 12:55:45 zero Tor[209878]: Bootstrapped 95% (circuit_create): Establishing a Tor circuit\n  Sep 26 12:55:46 zero Tor[209878]: Bootstrapped 100% (done): Done\n\n  no output above = tor has logged nothing, which for a healthy\n  quiet tor is normal. Confirm via the control port instead:\n  sudo tor-control 127.0.0.1 9051 <<< ''GETINFO status/bootstrap-phase'' 2>/dev/null\n  # or simply check tor is proxying:\n  curl --socks5-hostname 127.0.0.1:9050 -s https://check.torproject.org/api/ip\n","metadata":{"output":"═══ IS TOR ACTUALLY CONNECTED, OR IDLE? ═══\n  Sep 26 12:55:43 zero Tor[209878]: Bootstrapped 55% (loading_descriptors): Loading relay descriptors\n  Sep 26 12:55:44 zero Tor[209878]: Bootstrapped 62% (loading_descriptors): Loading relay descriptors\n  Sep 26 12:55:45 zero Tor[209878]: Bootstrapped 68% (loading_descriptors): Loading relay descriptors\n  Sep 26 12:55:45 zero Tor[209878]: Bootstrapped 73% (loading_descriptors): Loading relay descriptors\n  Sep 26 12:55:45 zero Tor[209878]: Bootstrapped 75% (enough_dirinfo): Loaded enough directory info to build circuits\n  Sep 26 12:55:45 zero Tor[209878]: Bootstrapped 90% (ap_handshake_done): Handshake finished with a relay to build circuits\n  Sep 26 12:55:45 zero Tor[209878]: Bootstrapped 95% (circuit_create): Establishing a Tor circuit\n  Sep 26 12:55:46 zero Tor[209878]: Bootstrapped 100% (done): Done\n\n  no output above = tor has logged nothing, which for a healthy\n  quiet tor is normal. Confirm via the control port instead:\n  sudo tor-control 127.0.0.1 9051 <<< ''GETINFO status/bootstrap-phase'' 2>/dev/null\n  # or simply check tor is proxying:\n  curl --socks5-hostname 127.0.0.1:9050 -s https://check.torproject.org/api/ip\n","exit":0,"truncated":false},"title":"echo \"═══ IS TOR ACTUALLY CONNECTED, OR IDLE? ═══\"\njournalctl -u tor -S \"-2h\" --no-pager 2>&1 | tail -8 | sed ''s/^/  /''\necho\necho \"  no output above = tor has logged nothing, which for a healthy\"\necho \"  quiet tor is normal. Confirm via the control port instead:\"\ncat <<''EOF''\n  sudo tor-control 127.0.0.1 9051 <<< ''GETINFO status/bootstrap-phase'' 2>/dev/null\n  # or simply check tor is proxying:\n  curl --socks5-hostname 127.0.0.1:9050 -s https://check.torproject.org/api/ip\nEOF","time":{"start":1790454655115,"end":1790454655141}}}');
