hardening\nfor n in 40 60 80 90 100 105 110 115 120 122; do\n  if head -n \"$n\" bootstrap.sh | bash -n 2>/dev/null; then r=\"ok\"; else r=\"ERR: $(head -n \"$n\" bootstrap.sh | bash -n 2>&1 | head -1 | cut -c1-60)\"; fi\n  printf \"  first %3d lines: %s\\n\" \"$n\" \"$r\"\ndone","time":{"start":1790454782255,"end":1790454782315}}}');
