INSERT INTO part VALUES('prt_0df6d902100181Km2x73d9cUTj','msg_0df6d86ef001U5b305O3HQ3BsH','ses_f20e5cfc2ffeSFa4odnoYLiUOk',1790454894625,1790454894645,'{"type":"tool","tool":"read","callID":"call_function_l1j9e171b7eh_1","state":{"status":"completed","input":{"filePath":"/home/livings/Projects/bde-security-biometrics/pam/modules/bde-auth"},"output":"<path>/home/livings/Projects/bde-security-biometrics/pam/modules/bde-auth</path>\n<type>file</type>\n<content>\n1: #!/usr/bin/env python3\n2: \"\"\"\n3: BDE PAM Authentication Helper\n4: Captures bioelectric resonance signature and verifies against enrolled profile.\n5: Exit 0 = granted, Exit 1 = denied.\n6: \"\"\"\n7: import json\n8: import os\n9: import socket\n10: import sys\n11: import struct\n12: import hashlib\n13: \n14: SOCKET_PATH = os.environ.get(\"BDE_SOCK\", \"/run/user/1000/bde-daemon.sock\")\n15: \n16: def talk(payload: bytes) -> dict:\n17:     s = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)\n18:     s.settimeout(10.0)\n19:     s.connect(SOCKET_PATH)\n20:     s.sendall(json.dumps({\n21:         \"action\": \"verify\",\n22:         \"identity\": \"user\",\n23:         \"payload\": payload.hex()\n24:     }).encode())\n25:     data = b\"\"\n26:     while True:\n27:         chunk = s.recv(4096)\n28:         if not chunk:\n29:             break\n30:         data += chunk\n31:         if b\"\\n\" in data:\n32:             break\n33:     s.close()\n34:     return json.loads(data.decode() or \"{}\")\n35: \n36: def capture_live() -> bytes:\n37:     s = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)\n38:     s.settimeout(15.0)\n39:     s.connect(SOCKET_PATH)\n40:     s.sendall(json.dumps({\"action\": \"capture\"}).encode())\n41:     data = b\"\"\n42:     while True:\n43:         chunk = s.recv(4096)\n44:         if not chunk:\n45:             break\n46:         data += chunk\n47:         if b\"\\n\" in data:\n48:             break\n49:     s.close()\n50:     resp = json.loads(data.decode() or \"{}\")\n51:     if resp.get(\"status\") == \"ok\":\n52:         sig = resp.get(\"signature\", {})\n53:         return bytes.fromhex(sig.get(\"raw_bytes\", \"\"))\n54:     return b\"\"\n55: \n56: def verify_against_profile(identity: str, live_bytes: bytes) -> dict:\n57:     profile_path = f\"/var/lib/bde-daemon/{identity}.profile\"\n58:     if not os.path.exists(profile_path):\n59:         return {\"status\": \"denied\", \"reason\": \"no_profile\"}\n60:     stored_bytes = open(profile_path, \"rb\").read()\n61:     if len(stored_bytes) != len(live_bytes):\n62:         return {\"status\": \"denied\", \"reason\": \"feature_mismatch\"}\n63:     n = len(stored_bytes) // 8\n64:     if n == 0:\n65:         return {\"status\": \"denied\", \"reason\": \"empty_profile\"}\n66:     stored_arr = list(struct.unpack(f\"{n}d\", stored_bytes))\n67:     live_arr = list(struct.unpack(f\"{n}d\", live_bytes))\n68:     mean_s = sum(stored_arr) / n\n69:     mean_l = sum(live_arr) / n\n70:     cov = sum((s - mean_s) * (l - mean_l) for s, l in zip(stored_arr, live_arr)) / n\n71:     std_s = (sum((s - mean_s) ** 2 for s in stored_arr) / n) ** 0.5\n72:     std_l = (sum((l - mean_l) ** 2 for l in live_arr) / n) ** 0.5\n73:     if std_s == 0 or std_l == 0:\n74:         return {\"status\": \"denied\", \"reason\": \"zero_variance\"}\n75:     corr = cov / (std_s * std_l)\n76:     return {\"status\": \"granted\" if corr >= 0.85 else \"denied\", \"correlation\": round(corr, 4)}\n77: \n78: def main():\n79:     identity = os.environ.get(\"PAM_USER\", \"user\")\n80:     try:\n81:         live_bytes = capture_live()\n82:         if not live_bytes:\n83:             sys.exit(1)\n84:         result = verify_against_profile(identity, live_bytes)\n85:         if result.get(\"status\") == \"granted\":\n86:             sys.exit(0)\n87:         sys.exit(1)\n88:     except Exception:\n89:         sys.exit(1)\n90: \n91: if __name__ == \"__main__\":\n92:     main()\n\n(End of file - total 92 lines)\n</content>","metadata":{"preview":"#!/usr/bin/env python3\n\"\"\"\nBDE PAM Authentication Helper\nCaptures bioelectric resonance signature and verifies against enrolled profile.\nExit 0 = granted, Exit 1 = denied.\n\"\"\"\nimport json\nimport os\nimport socket\nimport sys\nimport struct\nimport hashlib\n\nSOCKET_PATH = os.environ.get(\"BDE_SOCK\", \"/run/user/1000/bde-daemon.sock\")\n\ndef talk(payload: bytes) -> dict:\n    s = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)\n    s.settimeout(10.0)\n    s.connect(SOCKET_PATH)\n    s.sendall(json.dumps({","truncated":false,"loaded":[],"display":{"type":"file","path":"/home/livings/Projects/bde-security-biometrics/pam/modules/bde-auth","text":"#!/usr/bin/env python3\n\"\"\"\nBDE PAM Authentication Helper\nCaptures bioelectric resonance signature and verifies against enrolled profile.\nExit 0 = granted, Exit 1 = denied.\n\"\"\"\nimport json\nimport os\nimport socket\nimport sys\nimport struct\nimport hashlib\n\nSOCKET_PATH = os.environ.get(\"BDE_SOCK\", \"/run/user/1000/bde-daemon.sock\")\n\ndef talk(payload: bytes) -> dict:\n    s = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)\n    s.settimeout(10.0)\n    s.connect(SOCKET_PATH)\n    s.sendall(json.dumps({\n        \"action\": \"verify\",\n        \"identity\": \"user\",\n        \"payload\": payload.hex()\n    }).encode())\n    data = b\"\"\n    while True:\n        chunk = s.recv(4096)\n        if not chunk:\n            break\n        data += chunk\n        if b\"\\n\" in data:\n            break\n    s.close()\n    return json.loads(data.decode() or \"{}\")\n\ndef capture_live() -> bytes:\n    s = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)\n    s.settimeout(15.0)\n    s.connect(SOCKET_PATH)\n    s.sendall(json.dumps({\"action\": \"capture\"}).encode())\n    data = b\"\"\n    while True:\n        chunk = s.recv(4096)\n        if not chunk:\n            break\n        data += chunk\n        if b\"\\n\" in data:\n            break\n    s.close()\n    resp = json.loads(data.decode() or \"{}\")\n    if resp.get(\"status\") == \"ok\":\n        sig = resp.get(\"signature\", {})\n        return bytes.fromhex(sig.get(\"raw_bytes\", \"\"))\n    return b\"\"\n\ndef verify_against_profile(identity: str, live_bytes: bytes) -> dict:\n    profile_path = f\"/var/lib/bde-daemon/{identity}.profile\"\n    if not os.path.exists(profile_path):\n        return {\"status\": \"denied\", \"reason\": \"no_profile\"}\n    stored_bytes = open(profile_path, \"rb\").read()\n    if len(stored_bytes) != len(live_bytes):\n        return {\"status\": \"denied\", \"reason\": \"feature_mismatch\"}\n    n = len(stored_bytes) // 8\n    if n == 0:\n        return {\"status\": \"denied\", \"reason\": \"empty_profile\"}\n    stored_arr = list(struct.unpack(f\"{n}d\", stored_bytes))\n    live_arr = list(struct.unpack(f\"{n}d\", live_bytes))\n    mean_s = sum(stored_arr) / n\n    mean_l = sum(live_arr) / n\n    cov = sum((s - mean_s) * (l - mean_l) for s, l in zip(stored_arr, live_arr)) / n\n    std_s = (sum((s - mean_s) ** 2 for s in stored_arr) / n) ** 0.5\n    std_l = (sum((l - mean_l) ** 2 for l in live_arr) / n) ** 0.5\n    if std_s == 0 or std_l == 0:\n        return {\"status\": \"denied\", \"reason\": \"zero_variance\"}\n    corr = cov / (std_s * std_l)\n    return {\"status\": \"granted\" if corr >= 0.85 else \"denied\", \"correlation\": round(corr, 4)}\n\ndef main():\n    identity = os.environ.get(\"PAM_USER\", \"user\")\n    try:\n        live_bytes = capture_live()\n        if not live_bytes:\n            sys.exit(1)\n        result = verify_against_profile(identity, live_bytes)\n        if result.get(\"status\") == \"granted\":\n            sys.exit(0)\n        sys.exit(1)\n    except Exception:\n        sys.exit(1)\n\nif __name__ == \"__main__\":\n    main()","lineStart":1,"lineEnd":92,"totalLines":92,"truncated":false}},"title":"home/livings/Projects/bde-security-biometrics/pam/modules/bde-auth","time":{"start":1790454894631,"end":1790454894645}}}');
