INSERT INTO part VALUES('prt_0df6f0a8d001ePHOcqKKNTNCRx','msg_0df6f0522001TE00DA0WacMmzM','ses_f211dfcd4ffevS1Yoddwab036g',1790454991501,1790454992114,'{"type":"reasoning","text":"NM 1.58.1 accepts only: `default`, `never`, `always`.\n\nSo the correct value is `always`. And `1` mapped to `never` (flag 1 = NO).\n\nLet me set `always` and verify, then reconnect to get a new MAC.","time":{"start":1790454991501,"end":1790454992113}}');
INSERT INTO part VALUES('prt_0df6f0cf3001n4Wv0sj8npox66','msg_0df6f0522001TE00DA0WacMmzM','ses_f211dfcd4ffevS1Yoddwab036g',1790454992115,1790454995463,'{"type":"text","text":"There it is — NM 1.58 accepts exactly `default`, `never`, `always`. And `1` silently mapped to `never`, i.e. my script was *actively disabling* randomization. Fixing the script and applying:","time":{"start":1790454992115,"end":1790454995463}}');
INSERT INTO part VALUES('prt_0df6f0f30001EARJ1pYUga9WtT','msg_0df6f0522001TE00DA0WacMmzM','ses_f211dfcd4ffevS1Yoddwab036g',1790454992688,1790454995474,'{"type":"tool","tool":"edit","callID":"call_function_i932wg84m38z_1","state":{"status":"completed","input":{"filePath":"/home/livings/Projects/zen-hardening/set-anon-identity.sh","newString":"set_mac_prop=\"\"\nif nmcli -g 802-11-wireless.mac-address-randomization con show \"$(nmcli -t -f UUID con show | head -1)\" >/dev/null 2>&1; then\n  set_mac_prop=\"802-11-wireless.mac-address-randomization\"\n  # Values differ by NetworkManager version and getting this wrong is SILENT:\n  #   NM >= 1.42 uses a flags enum. nmcli accepts exactly:\n  #       default | never | always\n  #   and the numeric aliases are NOT boolean: 1 means NEVER, not yes.\n  #   Setting 1 therefore turns randomization OFF while looking like success.\n  # Verified on 1.58.1, which rejects \"yes\", \"random\" and \"1\" is \"never\".\n  case \"$(nmcli -f 802-11-wireless.mac-address-randomization con mod \"$(nmcli -t -f UUID con show | head -1)\" 2>&1)\" in\n    *always*) set_mac_val=\"always\" ;;\n    *)        set_mac_val=\"always\" ;;   # modern NM; modern NM is the only NM that has this property\n  esac\nelse\n  set_mac_prop=\"802-11-wireless.mac-address-mode\"\n  set_mac_val=\"random\"\nfi\necho \"  using property: ${set_mac_prop} = ${set_mac_val}\"","oldString":"set_mac_prop=\"\"\nif nmcli -g 802-11-wireless.mac-address-randomization con show \"$(nmcli -t -f UUID con show | head -1)\" >/dev/null 2>&1; then\n  set_mac_prop=\"802-11-wireless.mac-address-randomization\"\n  set_mac_val=\"1\"\nelse\n  set_mac_prop=\"802-11-wireless.mac-address-mode\"\n  set_mac_val=\"random\"\nfi\necho \"  using property: ${set_mac_prop} = ${set_mac_val}\""},"output":"Edit applied successfully.","metadata":{"diagnostics":{},"diff":"Index: /home/livings/Projects/zen-hardening/set-anon-identity.sh\n===================================================================\n--- /home/livings/Projects/zen-hardening/set-anon-identity.sh\n+++ /home/livings/Projects/zen-hardening/set-anon-identity.sh\n@@ -59,9 +59,18 @@\n # the hardware MAC keeps broadcasting.\n set_mac_prop=\"\"\n if nmcli -g 802-11-wireless.mac-address-randomization con show \"$(nmcli -t -f UUID con show | head -1)\" >/dev/null 2>&1; then\n   set_mac_prop=\"802-11-wireless.mac-address-randomization\"\n-  set_mac_val=\"1\"\n+  # Values differ by NetworkManager version and getting this wrong is SILENT:\n+  #   NM >= 1.42 uses a flags enum. nmcli accepts exactly:\n+  #       default | never | always\n+  #   and the numeric aliases are NOT boolean: 1 means NEVER, not yes.\n+  #   Setting 1 therefore turns randomization OFF while looking like success.\n+  # Verified on 1.58.1, which rejects \"yes\", \"random\" and \"1\" is \"never\".\n+  case \"$(nmcli -f 802-11-wireless.mac-address-randomization con mod \"$(nmcli -t -f UUID con show | head -1)\" 2>&1)\" in\n+    *always*) set_mac_val=\"always\" ;;\n+    *)        set_mac_val=\"always\" ;;   # modern NM; modern NM is the only NM that has this property\n+  esac\n else\n   set_mac_prop=\"802-11-wireless.mac-address-mode\"\n   set_mac_val=\"random\"\n fi\n","filediff":{"file":"/home/livings/Projects/zen-hardening/set-anon-identity.sh","patch":"Index: /home/livings/Projects/zen-hardening/set-anon-identity.sh\n===================================================================\n--- /home/livings/Projects/zen-hardening/set-anon-identity.sh\n+++ /home/livings/Projects/zen-hardening/set-anon-identity.sh\n@@ -59,9 +59,18 @@\n # the hardware MAC keeps broadcasting.\n set_mac_prop=\"\"\n if nmcli -g 802-11-wireless.mac-address-randomization con show \"$(nmcli -t -f UUID con show | head -1)\" >/dev/null 2>&1; then\n   set_mac_prop=\"802-11-wireless.mac-address-randomization\"\n-  set_mac_val=\"1\"\n+  # Values differ by NetworkManager version and getting this wrong is SILENT:\n+  #   NM >= 1.42 uses a flags enum. nmcli accepts exactly:\n+  #       default | never | always\n+  #   and the numeric aliases are NOT boolean: 1 means NEVER, not yes.\n+  #   Setting 1 therefore turns randomization OFF while looking like success.\n+  # Verified on 1.58.1, which rejects \"yes\", \"random\" and \"1\" is \"never\".\n+  case \"$(nmcli -f 802-11-wireless.mac-address-randomization con mod \"$(nmcli -t -f UUID con show | head -1)\" 2>&1)\" in\n+    *always*) set_mac_val=\"always\" ;;\n+    *)        set_mac_val=\"always\" ;;   # modern NM; modern NM is the only NM that has this property\n+  esac\n else\n   set_mac_prop=\"802-11-wireless.mac-address-mode\"\n   set_mac_val=\"random\"\n fi\n","additions":10,"deletions":1},"truncated":false},"title":"home/livings/Projects/zen-hardening/set-anon-identity.sh","time":{"start":1790454995460,"end":1790454995474}}}');
