tl list-timers --all 2>/dev/null | grep -i -E \"heal|shield|self\" || echo \"  no self-heal timer on this machine\"\nls -la /etc/cron.d/ 2>/dev/null | grep -iE \"heal|shield\" || echo \"  no self-heal cron entries\"","time":{"start":1790455097572,"end":1790455097596}}}');
