nism in the repos ===\"\ngrep -rlniE \"guest|quarantine|deny_banned|banned\" --include=\"*.sh\" --include=\"*.rules\" --include=\"*.conf\" . 2>/dev/null | head\necho; echo \"=== device blacklist state (the ''ban'' mechanism) ===\"\nls /etc/udev/rules.d/*shield* 2>/dev/null || echo \"  no shield device blacklist rules installed\"\nls -d /var/lib/shield-kitty 2>/dev/null || echo \"  no /var/lib/shield-kitty quarantine dir\"","time":{"start":1790455161187,"end":1790455161211}}}');
