| sed ''s/^/  /''\necho \"  size: $(stat -c%s ~/.config/gh/token.clean 2>/dev/null) bytes\"\necho \"  mode: $(stat -c%a ~/.config/gh/token.clean 2>/dev/null)\"","time":{"start":1790455288370,"end":1790455288399}}}');
