INSERT INTO part VALUES('prt_0df776a9f001RebOhhUIR4lTwA','msg_0df77661d001gifk5lrStayQk9','ses_f20e5cfc2ffeSFa4odnoYLiUOk',1790455540383,1790455541638,'{"type":"tool","tool":"bash","callID":"call_function_ukc6kndx84he_1","state":{"status":"completed","input":{"command":"cd ~/Projects/buildlog\nbuildlog note \"pam_faillock facts confirmed from local man pages: (1) unlock_time=0 means NEVER - needs ''faillock --user X --reset'' as root, and man page warns it is an easy DoS target; (2) default dir /var/run/faillock is tmpfs so tallies AND any permanent lock vanish on reboot - real permanence needs dir= off tmpfs; (3) admin_group members are handled like root, so setting even_deny_root would defeat the exemption entirely. Live /etc/security/faillock.conf had NO admin_group, so livings was lockable; recover with ''sudo faillock --user livings --reset''\" 2>&1 | tail -1\necho; echo \"=== commit the journal ===\"\ngit add -A && git commit -q -m \"log: faillock admin exemption prepared, pam_faillock semantics confirmed\" && git log --oneline | head -1"},"output":"  [✓] logged: pam_faillock facts confirmed from local man pages: (1) unlock_time=0 means NEVER - needs ''faillock --user X --reset'' as root, and man page warns it is an easy DoS target; (2) default dir /var/run/faillock is tmpfs so tallies AND any permanent lock vanish on reboot - real permanence needs dir= off tmpfs; (3) admin_group members are handled like root, so setting even_deny_root would defeat the exemption entirely. Live /etc/security/faillock.conf had NO admin_group, so livings was lockable; recover with ''sudo faillock --user livings --reset''\n\n=== commit the journal ===\nOn branch master\nnothing to commit, working tree clean\n","metadata":{"output":"  [✓] logged: pam_faillock facts confirmed from local man pages: (1) unlock_time=0 means NEVER - needs ''faillock --user X --reset'' as root, and man page warns it is an easy DoS target; (2) default dir /var/run/faillock is tmpfs so tallies AND any permanent lock vanish on reboot - real permanence needs dir= off tmpfs; (3) admin_group members are handled like root, so setting even_deny_root would defeat the exemption entirely. Live /etc/security/faillock.conf had NO admin_group, so livings was lockable; recover with ''sudo faillock --user livings --reset''\n\n=== commit the journal ===\nOn branch master\nnothing to commit, working tree clean\n","exit":1,"truncated":false},"title":"cd ~/Projects/buildlog\nbuildlog note \"pam_faillock facts confirmed from local man pages: (1) unlock_time=0 means NEVER - needs ''faillock --user X --reset'' as root, and man page warns it is an easy DoS target; (2) default dir /var/run/faillock is tmpfs so tallies AND any permanent lock vanish on reboot - real permanence needs dir= off tmpfs; (3) admin_group members are handled like root, so setting even_deny_root would defeat the exemption entirely. Live /etc/security/faillock.conf had NO admin_group, so livings was lockable; recover with ''sudo faillock --user livings --reset''\" 2>&1 | tail -1\necho; echo \"=== commit the journal ===\"\ngit add -A && git commit -q -m \"log: faillock admin exemption prepared, pam_faillock semantics confirmed\" && git log --oneline | head -1","time":{"start":1790455541609,"end":1790455541637}}}');
