FAILED UNITS ═══\"\nf=$(systemctl list-units --state=failed --no-legend --no-pager 2>/dev/null)\nif [ -z \"$f\" ]; then echo \"  [ok] none failed\"; else echo \"$f\" | awk ''{printf \"  [!!] %-38s %s\\n\",$1,$4}''; fi\necho\necho \"  --- units we installed/enabled ---\"\nfor u in firewalld fail2ban tor shield-kitty-watch.service evidence-seal.timer; do\n  printf \"    %-26s %-10s enabled=%s\\n\" \"$u\" \"$(systemctl is-active $u 2>/dev/null)\" \"$(systemctl is-enabled $u 2>/dev/null)\"\ndone\necho\necho \"  --- timers ---\"\nsystemctl list-timers --all --no-pager 2>/dev/null | head -8 | sed ''s/^/    /''","time":{"start":1790456107379,"end":1790456107443}}}');
