pwatch\n  Version         : 3.9-1\n","exit":0,"truncated":false},"title":"echo \"=== real local subnet (the /8 mask may not be the true broadcast domain) ===\"\nip route show default 2>/dev/null | sed ''s/^/  default: /''\nip -4 route show scope link 2>/dev/null | sed ''s/^/  link: /''\necho; echo \"=== gateway + neighbours actually seen ===\"\nip neigh show 2>/dev/null | head -8 | sed ''s/^/  /''\necho; echo \"=== arpwatch available in repos? ===\"\npacman -Si arpwatch 2>/dev/null | grep -E \"^(Name|Version|Repository)\" | sed ''s/^/  /'' || echo \"  arpwatch not in repos\"","time":{"start":1790456118910,"end":1790456119122}}}');
