md-analyze verify /etc/systemd/system/*.service 2>&1 | grep -iE ''error|unknown|not found'' | head -10 | sed ''s/^/    /'' || echo \"    [ok] no unit config errors\"\necho\necho \"  --- critical-chain ---\"\nsystemd-analyze critical-chain 2>/dev/null | head -12 | sed ''s/^/    /''","time":{"start":1790456141538,"end":1790456142470}}}');
