forward: no\n    masquerade: no\n    forward-ports: \n    source-ports: \n    icmp-blocks: \n    rich rules: \n","exit":0,"truncated":false},"title":"echo \"=== what is pid 1535 on :1716? ===\"\nps -o pid,ppid,user,comm,args -p 1535 2>/dev/null | sed ''s/^/  /'' || echo \"  pid gone\"\necho; echo \"=== is it systemd-managed at all? ===\"\ncat /proc/1535/cgroup 2>/dev/null | head -2 | sed ''s/^/  /''\necho; echo \"=== workstation zone: full config ===\"\nfirewall-cmd --zone=workstation --list-all 2>/dev/null | sed ''s/^/  /'' | head -20","time":{"start":1790456141470,"end":1790456179547}}}');
