          loopback-only          ?\n  tcp      *:1716                   [!!] ALL INTERFACES    users:((\"kdeconnectd\",pid=1535,fd=16))\n  udp      0.0.0.0:5353             [!!] ALL INTERFACES    ?\n  udp      *:1716                   [!!] ALL INTERFACES    users:((\"kdeconnectd\",pid=1535,fd=15))\n  udp      [::]:5353                [!!] ALL INTERFACES    ?\n\n  --- anything reachable from another host? ---\n    [!!] 0.0.0.0:5353\n    [!!] *:1716\n    [!!] [::]:5353\n","exit":0,"truncated":false},"title":"echo \"═══ EXPOSED LISTENERS (attack surface) ═══\"\nss -tulpnH 2>/dev/null | awk ''{print $1,$5,$7}'' | sort -u | while read -r p a n; do\n  case \"$a\" in\n    127.0.0.1:*|\\[::1\\]:*|::1:*) bind=\"loopback-only\" ;;\n    *:*) bind=\"[!!] ALL INTERFACES\" ;;\n    *) bind=\"local\" ;;\n  esac\n  printf \"  %-8s %-24s %-22s %s\\n\" \"$p\" \"$a\" \"$bind\" \"${n:-?}\"\ndone | sort -u | head -25\necho\necho \"  --- anything reachable from another host? ---\"\next=$(ss -tulpnH 2>/dev/null | awk ''$5 !~ /127\\.|::1/ {print $5}'' | sort -u)\n[ -z \"$ext\" ] && echo \"    [ok] nothing bound beyond loopback\" || echo \"$ext\" | sed ''s/^/    [!!] /''","time":{"start":1790456149359,"end":1790456149392}}}');
