-n \"$t\" ] && age=$(( $(date +%s) - t )) && [ \"$age\" -lt 180 ] && printf \"    %-26s committed %ss ago\\n\" \"$n\" \"$age\"\ndone\necho \"  (none listed = no repo activity in last 3 min)\"","time":{"start":1790456172602,"end":1790456172674}}}');
