              ~~~~^^\n    File \"/home/livings/Projects/shield-kitty/shield-kitty-alert.py\", line 296, in main\n      return notify(payload)\n    File \"/home/livings/Projects/shield-kitty/shield-kitty-alert.py\", line 79, in notify\n      head, body = summarize(payload)\n                   ~~~~~~~~~^^^^^^^^^\n    File \"/home/livings/Projects/shield-kitty/shield-kitty-alert.py\", line 64, in summarize\n      body = \"{} x{}\".format(top.get(\"label\", \"SECURITY EVENT\"), top.get(\"count\", 1))\n                             ^^^^^^^\n  AttributeError: ''str'' object has no attribute ''get''\n","exit":0,"truncated":false},"title":"cd /tmp/spoofT\nexport BDE_ARPWATCH_LOG=/tmp/spoofT/real.log\n: > real.log\necho \"=== hook -> REAL shield-kitty alert (spoof event) ===\"\n/home/livings/Projects/zen-hardening/arpwatch-spoof-alert.sh 10.0.0.5 aa:bb:cc:dd:ee:01 10.0.0.5 aa:bb:cc:dd:ee:02\necho \"  exit=$?\"\necho; echo \"=== hook stderr/stdout (notify-send result) ===\"\ncat real.log | sed ''s/^/  /''","time":{"start":1790456343110,"end":1790456343188}}}');
