INSERT INTO part VALUES('prt_0df83b7d4001gQ8NfZJ4haIWSq','msg_0df83aaa70016hXd2q1Up4Rn7F','ses_f20e5cfc2ffeSFa4odnoYLiUOk',1790456346580,1790456346597,'{"type":"tool","tool":"bash","callID":"call_function_0nbawvun5mbn_1","state":{"status":"completed","input":{"command":"cd ~/Projects/shield-kitty\nsed -n ''50,75p'' shield-kitty-alert.py"},"output":"         \"severity\": \"critical\", \"count\": 42, \"sample\": \"Failed password for invalid user admin from 203.0.113.5\"},\n    ],\n    \"timestamp\": \"2026-09-26 12:30:00\",\n}\n\n\ndef summarize(payload):\n    \"\"\"One-line body sized for a notification popup.\"\"\"\n    events = payload.get(\"events\", [])\n    sev = payload.get(\"severity\", \"warning\")\n    head = \"SHIELD KITTY\" if sev == \"critical\" else \"SHIELD KITTY (warning)\"\n    if not events:\n        return head, \"\"\n    top = events[0]\n    body = \"{} x{}\".format(top.get(\"label\", \"SECURITY EVENT\"), top.get(\"count\", 1))\n    extra = events[1:4]\n    if extra:\n        body += \"  ·  \" + \", \".join(\n            \"{} x{}\".format(e.get(\"label\", \"\"), e.get(\"count\", 1)) for e in extra\n        )\n    if len(events) > 4:\n        body += \"  ·  +{} more\".format(len(events) - 4)\n    return head, body\n\n\ndef notify(payload):\n","metadata":{"output":"         \"severity\": \"critical\", \"count\": 42, \"sample\": \"Failed password for invalid user admin from 203.0.113.5\"},\n    ],\n    \"timestamp\": \"2026-09-26 12:30:00\",\n}\n\n\ndef summarize(payload):\n    \"\"\"One-line body sized for a notification popup.\"\"\"\n    events = payload.get(\"events\", [])\n    sev = payload.get(\"severity\", \"warning\")\n    head = \"SHIELD KITTY\" if sev == \"critical\" else \"SHIELD KITTY (warning)\"\n    if not events:\n        return head, \"\"\n    top = events[0]\n    body = \"{} x{}\".format(top.get(\"label\", \"SECURITY EVENT\"), top.get(\"count\", 1))\n    extra = events[1:4]\n    if extra:\n        body += \"  ·  \" + \", \".join(\n            \"{} x{}\".format(e.get(\"label\", \"\"), e.get(\"count\", 1)) for e in extra\n        )\n    if len(events) > 4:\n        body += \"  ·  +{} more\".format(len(events) - 4)\n    return head, body\n\n\ndef notify(payload):\n","exit":0,"truncated":false},"title":"cd ~/Projects/shield-kitty\nsed -n ''50,75p'' shield-kitty-alert.py","time":{"start":1790456346584,"end":1790456346597}}}');
