rdening/arpwatch-spoof-alert.sh\n===================================================================\n--- /home/livings/Projects/zen-hardening/arpwatch-spoof-alert.sh\n+++ /home/livings/Projects/zen-hardening/arpwatch-spoof-alert.sh\n@@ -109,9 +109,9 @@\n         exit 0\n     fi\n     log \"FLIP-FLOP $start_ip $start_mac -> $stop_mac\"\n     notify \"critical\" \"ARP spoof: $start_ip claimed two MACs\" \\\n-        \"$start_ip was $start_mac, now claims $stop_mac. Not auto-banned: MAC randomisation looks identical. Verify, then ban via the 86400s fail2ban path if real.\"\n+        \"was $start_mac, now $stop_mac. Not auto-banned: MAC randomisation looks identical. Verify, then ban via the 86400s fail2ban path if real.\"\n     exit 0\n fi\n \n # --- new host: routine. Logged, never alerted.\n","additions":1,"deletions":1},"truncated":false},"title":"home/livings/Projects/zen-hardening/arpwatch-spoof-alert.sh","time":{"start":1790456358357,"end":1790456358369}}}');
