INSERT INTO part VALUES('prt_0df83fdd6001a2ZvK81fGEhNS2','msg_0df83f30900157I4LU4QTyXBL3','ses_f20e5cfc2ffeSFa4odnoYLiUOk',1790456364502,1790456367726,'{"type":"tool","tool":"bash","callID":"call_function_b7g7dnu09wyx_1","state":{"status":"completed","input":{"command":"cd /tmp && rm -rf spoofT2 && mkdir -p spoofT2/Projects/shield-kitty\ncat > spoofT2/Projects/shield-kitty/shield-kitty-alert.py <<''PY''\nimport sys\nopen(\"/tmp/spoofT2/alerted.log\",\"a\").write(sys.argv[1]+\"\\n\")\nPY\nexport HOME=/tmp/spoofT2 BDE_ARPWATCH_LOG=/tmp/spoofT2/s.log\nS=/home/livings/Projects/zen-hardening/arpwatch-spoof-alert.sh\n: > /tmp/spoofT2/alerted.log\npass=0; fail=0\nchk(){ if [ \"$2\" = \"$3\" ]; then echo \"  PASS  $1\"; pass=$((pass+1)); else echo \"  FAIL  $1 (got $2 want $3)\"; fail=$((fail+1)); fi; }\na(){ wc -l < /tmp/spoofT2/alerted.log | tr -d '' ''; }\n\n\"$S\" 10.0.0.5 aa:bb:cc:dd:ee:01 10.0.0.5 aa:bb:cc:dd:ee:02 >/dev/null 2>&1\nchk \"flip-flop alerts\" \"$(a)\" \"1\"\n\"$S\" 10.0.0.9 aa:bb:cc:dd:ee:03 10.0.0.9 aa:bb:cc:dd:ee:03 >/dev/null 2>&1\nchk \"new host silent\" \"$(a)\" \"1\"\nBDE_SELF_IPS=10.197.250.246 \"$S\" 10.197.250.246 aa:bb:cc:dd:ee:01 10.197.250.246 aa:bb:cc:dd:ee:09 >/dev/null 2>&1\nchk \"own-IP flip-flop ignored\" \"$(a)\" \"1\"\nBDE_GATEWAYS=10.128.128.128 \"$S\" 10.128.128.128 aa:bb:cc:dd:ee:01 10.128.128.128 aa:bb:cc:dd:ee:09 >/dev/null 2>&1\nchk \"gateway flip-flop ignored\" \"$(a)\" \"1\"\n\"$S\" 10.0.0.7 AA-BB-CC-DD-EE-01 10.0.0.7 aa:bb:cc:dd:ee:02 >/dev/null 2>&1\nchk \"MAC case/dash normalised\" \"$(a)\" \"2\"\n\"$S\" 10.0.0.8 aa:bb:cc:dd:ee:04 10.0.0.8 aa:bb:cc:dd:ee:04 >/dev/null 2>&1\nchk \"identical MAC not a flip\" \"$(a)\" \"2\"\n\"$S\" bad >/dev/null 2>&1; chk \"malformed args exit 0\" \"$?\" \"0\"\necho; echo \"  payload keys: $(python3 -c \"import json;d=json.loads(open(''/tmp/spoofT2/alerted.log'').readline());print(list(d.keys()), list(d[''events''][0].keys()))\")\"\necho; echo \"  $pass passed, $fail failed\""},"output":"  PASS  flip-flop alerts\n  PASS  new host silent\n  PASS  own-IP flip-flop ignored\n  PASS  gateway flip-flop ignored\n  PASS  MAC case/dash normalised\n  PASS  identical MAC not a flip\n  PASS  malformed args exit 0\n\n  payload keys: [''severity'', ''timestamp'', ''events''] [''label'', ''count'', ''sample'']\n\n  7 passed, 0 failed\n","metadata":{"output":"  PASS  flip-flop alerts\n  PASS  new host silent\n  PASS  own-IP flip-flop ignored\n  PASS  gateway flip-flop ignored\n  PASS  MAC case/dash normalised\n  PASS  identical MAC not a flip\n  PASS  malformed args exit 0\n\n  payload keys: [''severity'', ''timestamp'', ''events''] [''label'', ''count'', ''sample'']\n\n  7 passed, 0 failed\n","exit":0,"truncated":false},"title":"cd /tmp && rm -rf spoofT2 && mkdir -p spoofT2/Projects/shield-kitty\ncat > spoofT2/Projects/shield-kitty/shield-kitty-alert.py <<''PY''\nimport sys\nopen(\"/tmp/spoofT2/alerted.log\",\"a\").write(sys.argv[1]+\"\\n\")\nPY\nexport HOME=/tmp/spoofT2 BDE_ARPWATCH_LOG=/tmp/spoofT2/s.log\nS=/home/livings/Projects/zen-hardening/arpwatch-spoof-alert.sh\n: > /tmp/spoofT2/alerted.log\npass=0; fail=0\nchk(){ if [ \"$2\" = \"$3\" ]; then echo \"  PASS  $1\"; pass=$((pass+1)); else echo \"  FAIL  $1 (got $2 want $3)\"; fail=$((fail+1)); fi; }\na(){ wc -l < /tmp/spoofT2/alerted.log | tr -d '' ''; }\n\n\"$S\" 10.0.0.5 aa:bb:cc:dd:ee:01 10.0.0.5 aa:bb:cc:dd:ee:02 >/dev/null 2>&1\nchk \"flip-flop alerts\" \"$(a)\" \"1\"\n\"$S\" 10.0.0.9 aa:bb:cc:dd:ee:03 10.0.0.9 aa:bb:cc:dd:ee:03 >/dev/null 2>&1\nchk \"new host silent\" \"$(a)\" \"1\"\nBDE_SELF_IPS=10.197.250.246 \"$S\" 10.197.250.246 aa:bb:cc:dd:ee:01 10.197.250.246 aa:bb:cc:dd:ee:09 >/dev/null 2>&1\nchk \"own-IP flip-flop ignored\" \"$(a)\" \"1\"\nBDE_GATEWAYS=10.128.128.128 \"$S\" 10.128.128.128 aa:bb:cc:dd:ee:01 10.128.128.128 aa:bb:cc:dd:ee:09 >/dev/null 2>&1\nchk \"gateway flip-flop ignored\" \"$(a)\" \"1\"\n\"$S\" 10.0.0.7 AA-BB-CC-DD-EE-01 10.0.0.7 aa:bb:cc:dd:ee:02 >/dev/null 2>&1\nchk \"MAC case/dash normalised\" \"$(a)\" \"2\"\n\"$S\" 10.0.0.8 aa:bb:cc:dd:ee:04 10.0.0.8 aa:bb:cc:dd:ee:04 >/dev/null 2>&1\nchk \"identical MAC not a flip\" \"$(a)\" \"2\"\n\"$S\" bad >/dev/null 2>&1; chk \"malformed args exit 0\" \"$?\" \"0\"\necho; echo \"  payload keys: $(python3 -c \"import json;d=json.loads(open(''/tmp/spoofT2/alerted.log'').readline());print(list(d.keys()), list(d[''events''][0].keys()))\")\"\necho; echo \"  $pass passed, $fail failed\"","time":{"start":1790456367574,"end":1790456367725}}}');
