s compared to.\n SELF_IPS=\"${BDE_SELF_IPS:-}\"\n GW_IPS=\"${BDE_GATEWAYS:-}\"\n","filediff":{"file":"/home/livings/Projects/zen-hardening/arpwatch-spoof-alert.sh","patch":"Index: /home/livings/Projects/zen-hardening/arpwatch-spoof-alert.sh\n===================================================================\n--- /home/livings/Projects/zen-hardening/arpwatch-spoof-alert.sh\n+++ /home/livings/Projects/zen-hardening/arpwatch-spoof-alert.sh\n@@ -79,16 +79,8 @@\n \n log() { printf ''%s %s\\n'' \"$(date -Is)\" \"$*\" >>\"$LOG\" 2>/dev/null || \\\n         printf ''%s %s\\n'' \"$(date -Is)\" \"$*\" >&2; }\n \n-# Where to send the notifier''s stderr. If the log is not writable -- wrong\n-# ownership, or the installer has not created it yet -- fall back to stderr, so\n-# the actual reason a delivery failed is never swallowed.\n-log_or_stderr() {\n-    if ! touch \"$LOG\" 2>/dev/null; then echo \"(log $LOG not writable)\" >&2; fi\n-    cat >/dev/stderr\n-}\n-\n # The host''s own address and the gateway must never be reported as a victim of\n # spoofing -- they are the reference points everything else is compared to.\n SELF_IPS=\"${BDE_SELF_IPS:-}\"\n GW_IPS=\"${BDE_GATEWAYS:-}\"\n","additions":0,"deletions":8},"truncated":false},"title":"home/livings/Projects/zen-hardening/arpwatch-spoof-alert.sh","time":{"start":1790456488100,"end":1790456488115}}}');
