INSERT INTO part VALUES('prt_0df8612a2001YK19K1Qiyp3l10','msg_0df8605f7001zimjoYs4buPcuM','ses_f20e5cfc2ffeSFa4odnoYLiUOk',1790456500898,1790456501764,'{"type":"tool","tool":"bash","callID":"call_function_5nsebcmk9kiz_1","state":{"status":"completed","input":{"command":"echo \"=== does notify-send work with ONLY the bootstrapped vars? ===\"\nenv -i PATH=\"$PATH\" HOME=/root \\\n  XDG_RUNTIME_DIR=/run/user/1000 \\\n  DBUS_SESSION_BUS_ADDRESS=unix:path=/run/user/1000/bus \\\n  WAYLAND_DISPLAY=wayland-0 \\\n  notify-send --app-name=spoof-test \"spoof test\" \"proving bare-env delivery\" 2>&1 | sed ''s/^/  /''\necho \"  notify-send exit=$?\"\necho\necho \"=== and with NOTHING (proving it would have failed before) ===\"\nenv -i PATH=\"$PATH\" HOME=/root notify-send \"t\" \"t\" 2>&1 | sed ''s/^/  /''\necho \"  exit=$?\""},"output":"=== does notify-send work with ONLY the bootstrapped vars? ===\n  notify-send exit=0\n\n=== and with NOTHING (proving it would have failed before) ===\n  Failed to show notification: Cannot autolaunch D-Bus without X11 $DISPLAY\n  exit=0\n","metadata":{"output":"=== does notify-send work with ONLY the bootstrapped vars? ===\n  notify-send exit=0\n\n=== and with NOTHING (proving it would have failed before) ===\n  Failed to show notification: Cannot autolaunch D-Bus without X11 $DISPLAY\n  exit=0\n","exit":0,"truncated":false},"title":"echo \"=== does notify-send work with ONLY the bootstrapped vars? ===\"\nenv -i PATH=\"$PATH\" HOME=/root \\\n  XDG_RUNTIME_DIR=/run/user/1000 \\\n  DBUS_SESSION_BUS_ADDRESS=unix:path=/run/user/1000/bus \\\n  WAYLAND_DISPLAY=wayland-0 \\\n  notify-send --app-name=spoof-test \"spoof test\" \"proving bare-env delivery\" 2>&1 | sed ''s/^/  /''\necho \"  notify-send exit=$?\"\necho\necho \"=== and with NOTHING (proving it would have failed before) ===\"\nenv -i PATH=\"$PATH\" HOME=/root notify-send \"t\" \"t\" 2>&1 | sed ''s/^/  /''\necho \"  exit=$?\"","time":{"start":1790456501723,"end":1790456501763}}}');
