INSERT INTO part VALUES('prt_0df8621d8001d4cSnFKYRgoBPW','msg_0df86161b001ME2JW0FzbBENQB','ses_f20e5cfc2ffeSFa4odnoYLiUOk',1790456504792,1790456505521,'{"type":"reasoning","text":"Confirmed:\n- With the bootstrapped vars (XDG_RUNTIME_DIR, DBUS_SESSION_BUS_ADDRESS, WAYLAND_DISPLAY), notify-send succeeds (exit 0, no error).\n- With nothing, it fails with \"Cannot autolaunch D-Bus without X11 $DISPLAY\".\n\nSo the session env bootstrap is essential and works. The hook now fixes it.\n\nLet me re-run the full test suite to make sure the classification tests still pass, then commit.\n\nLet me run the 7-test suite again plus the bare-env test.","time":{"start":1790456504792,"end":1790456505520}}');
