ot flip (got 0 want 2)\n  PASS  malformed args exit 0\n\n  1 passed, 6 failed\n","metadata":{"output":"  FAIL  flip-flop alerts (got 0 want 1)\n  FAIL  new host silent (got 0 want 1)\n  FAIL  own IP ignored (got 0 want 1)\n  FAIL  gateway ignored (got 0 want 1)\n  FAIL  MAC normalised (got 0 want 2)\n  FAIL  identical MAC not flip (got 0 want 2)\n  PASS  malformed args exit 0\n\n  1 passed, 6 failed\n","exit":0,"truncated":false},"title":"cd /tmp && rm -rf s3 && mkdir -p s3\nexport BDE_ARPWATCH_LOG=/tmp/s3/s.log\nS=/home/livings/Projects/zen-hardening/arpwatch-spoof-alert.sh\n# count real notifications by pointing BDE_ALERT at a counter\ncat > /tmp/s3/count.sh <<''SH''\n#!/bin/bash\necho \"$1\" >> /tmp/s3/alerts.log\nSH\nchmod +x /tmp/s3/count.sh\nexport BDE_ALERT=/tmp/s3/count.sh\n: > /tmp/s3/alerts.log\npass=0; fail=0\nchk(){ if [ \"$2\" = \"$3\" ]; then echo \"  PASS  $1\"; pass=$((pass+1)); else echo \"  FAIL  $1 (got $2 want $3)\"; fail=$((fail+1)); fi; }\na(){ wc -l < /tmp/s3/alerts.log | tr -d '' ''; }\n\n\"$S\" 10.0.0.5 aa:bb:cc:dd:ee:01 10.0.0.5 aa:bb:cc:dd:ee:02 >/dev/null 2>&1; chk \"flip-flop alerts\" \"$(a)\" \"1\"\n\"$S\" 10.0.0.9 aa:bb:cc:dd:ee:03 10.0.0.9 aa:bb:cc:dd:ee:03 >/dev/null 2>&1; chk \"new host silent\" \"$(a)\" \"1\"\nBDE_SELF_IPS=10.197.250.246 \"$S\" 10.197.250.246 aa:bb:cc:dd:ee:01 10.197.250.246 aa:bb:cc:dd:ee:09 >/dev/null 2>&1; chk \"own IP ignored\" \"$(a)\" \"1\"\nBDE_GATEWAYS=10.128.128.128 \"$S\" 10.128.128.128 aa:bb:cc:dd:ee:01 10.128.128.128 aa:bb:cc:dd:ee:09 >/dev/null 2>&1; chk \"gateway ignored\" \"$(a)\" \"1\"\n\"$S\" 10.0.0.7 AA-BB-CC-DD-EE-01 10.0.0.7 aa:bb:cc:dd:ee:02 >/dev/null 2>&1; chk \"MAC normalised\" \"$(a)\" \"2\"\n\"$S\" 10.0.0.8 aa:bb:cc:dd:ee:04 10.0.0.8 aa:bb:cc:dd:ee:04 >/dev/null 2>&1; chk \"identical MAC not flip\" \"$(a)\" \"2\"\n\"$S\" bad >/dev/null 2>&1; chk \"malformed args exit 0\" \"$?\" \"0\"\necho; echo \"  $pass passed, $fail failed\"","time":{"start":1790456508486,"end":1790456508687}}}');
