INSERT INTO part VALUES('prt_0df90be430016dihm4tG2WcfC7','msg_0df90af040012pS85h44Um2KN0','ses_f20e5cfc2ffeSFa4odnoYLiUOk',1790457200196,1790457202206,'{"type":"tool","tool":"bash","callID":"call_function_uoohf5rokagm_1","state":{"status":"completed","input":{"command":"export BDE_ARP_DATAFILE=/tmp/arpT/arp.dat BDE_ARP_STATE=/tmp/arpT/state\nexport BDE_ARPWATCH_LOG=/tmp/arpT/scan.log BDE_ALERT=/tmp/arpT/count.py\nS=/home/livings/Projects/zen-hardening/arpwatch-spoof-scan.sh\nbefore=$(wc -l < /tmp/arpT/alerts.log)\necho \"=== scan 2: identical data -> expect 0 NEW alerts (dedup) ===\"\n\"$S\"; after=$(wc -l < /tmp/arpT/alerts.log)\necho \"  alerts before=$before after=$after  -> $([ \"$after\" = \"$before\" ] && echo ''PASS: no re-alert'' || echo ''FAIL: re-alerted'')\"\ngrep -c \"persists, not re-alerting\" /tmp/arpT/scan.log | sed ''s/^/  \"persists\" log lines: /''\n\necho; echo \"=== scan 3: add a NEW spoof -> expect exactly 1 new alert ===\"\necho \"99:88:77:00:00:0b 10.0.0.5 1758000010\" >> /tmp/arpT/arp.dat\nbefore=$(wc -l < /tmp/arpT/alerts.log)\n\"$S\"; after=$(wc -l < /tmp/arpT/alerts.log)\necho \"  new alerts: $((after-before))  -> $([ $((after-before)) = 1 ] && echo ''PASS'' || echo ''FAIL'')\"\ntail -1 /tmp/arpT/alerts.log | python3 -c \"import json,sys; print(''   ALERT:'', json.load(sys.stdin)[''events''][0][''label''])\""},"output":"=== scan 2: identical data -> expect 0 NEW alerts (dedup) ===\n  alerts before=2 after=2  -> PASS: no re-alert\n  \"persists\" log lines: 2\n\n=== scan 3: add a NEW spoof -> expect exactly 1 new alert ===\n  new alerts: 0  -> FAIL\n   ALERT: ARP spoof: 10.0.0.4 claimed by 2 MACs\n","metadata":{"output":"=== scan 2: identical data -> expect 0 NEW alerts (dedup) ===\n  alerts before=2 after=2  -> PASS: no re-alert\n  \"persists\" log lines: 2\n\n=== scan 3: add a NEW spoof -> expect exactly 1 new alert ===\n  new alerts: 0  -> FAIL\n   ALERT: ARP spoof: 10.0.0.4 claimed by 2 MACs\n","exit":0,"truncated":false},"title":"export BDE_ARP_DATAFILE=/tmp/arpT/arp.dat BDE_ARP_STATE=/tmp/arpT/state\nexport BDE_ARPWATCH_LOG=/tmp/arpT/scan.log BDE_ALERT=/tmp/arpT/count.py\nS=/home/livings/Projects/zen-hardening/arpwatch-spoof-scan.sh\nbefore=$(wc -l < /tmp/arpT/alerts.log)\necho \"=== scan 2: identical data -> expect 0 NEW alerts (dedup) ===\"\n\"$S\"; after=$(wc -l < /tmp/arpT/alerts.log)\necho \"  alerts before=$before after=$after  -> $([ \"$after\" = \"$before\" ] && echo ''PASS: no re-alert'' || echo ''FAIL: re-alerted'')\"\ngrep -c \"persists, not re-alerting\" /tmp/arpT/scan.log | sed ''s/^/  \"persists\" log lines: /''\n\necho; echo \"=== scan 3: add a NEW spoof -> expect exactly 1 new alert ===\"\necho \"99:88:77:00:00:0b 10.0.0.5 1758000010\" >> /tmp/arpT/arp.dat\nbefore=$(wc -l < /tmp/arpT/alerts.log)\n\"$S\"; after=$(wc -l < /tmp/arpT/alerts.log)\necho \"  new alerts: $((after-before))  -> $([ $((after-before)) = 1 ] && echo ''PASS'' || echo ''FAIL'')\"\ntail -1 /tmp/arpT/alerts.log | python3 -c \"import json,sys; print(''   ALERT:'', json.load(sys.stdin)[''events''][0][''label''])\"","time":{"start":1790457201800,"end":1790457202205}}}');
