erts.log)\n\"$S\"; after=$(wc -l < /tmp/arpT/alerts.log)\nn=$((after-before))\necho \"  new alerts: $n  -> $([ \"$n\" = 1 ] && echo ''PASS'' || echo ''FAIL'')\"\ntail -1 /tmp/arpT/alerts.log | python3 -c \"import json,sys; e=json.load(sys.stdin)[''events''][0]; print(''   ALERT:'', e[''label'']); print(''          '', e[''sample''][:95])\"","time":{"start":1790457214433,"end":1790457214763}}}');
