INSERT INTO part VALUES('prt_0df9205e2001mKT9eFA5hRwVxL','msg_0df91ff31001aGWeCpLhWW1z7a','ses_f20e5cfc2ffeSFa4odnoYLiUOk',1790457284067,1790457286001,'{"type":"tool","tool":"bash","callID":"call_function_s375tfy0un81_1","state":{"status":"completed","input":{"command":"cd /tmp/at\nexport BDE_ARPWATCH_LOG=/tmp/at/scan.log BDE_ALERT=/tmp/at/count.py\nS=/home/livings/Projects/zen-hardening/arpwatch-spoof-scan.sh\nprintf ''aa:bb:cc:00:00:0b 10.3.0.1 1\\ncc:dd:ee:00:00:0c 10.3.0.1 2\\n'' > e1.dat\nrm -f /tmp/at/est; : > /tmp/at/alerts.log\nBDE_ARP_DATAFILE=/tmp/at/e1.dat BDE_ARP_STATE=/tmp/at/est \"$S\" >/dev/null 2>&1\necho \"  A (spoof present)     alerts=$(wc -l < alerts.log)  state=''$(cat est)''\"\nprintf ''aa:bb:cc:00:00:0b 10.3.0.1 1\\n'' > e1.dat\nBDE_ARP_DATAFILE=/tmp/at/e1.dat BDE_ARP_STATE=/tmp/at/est \"$S\" >/dev/null 2>&1\necho \"  B (spoof resolved)    alerts=$(wc -l < alerts.log)  state=''$(cat est)''  <- cleared\"\nprintf ''cc:dd:ee:00:00:0c 10.3.0.1 2\\ndd:ee:ff:00:00:0d 10.3.0.1 3\\n'' > e1.dat\nBDE_ARP_DATAFILE=/tmp/at/e1.dat BDE_ARP_STATE=/tmp/at/est \"$S\" >/dev/null 2>&1\necho \"  C (spoof RETURNS)     alerts=$(wc -l < alerts.log)  <- re-alerted, not swallowed\""},"output":"  A (spoof present)     alerts=1  state=''10.3.0.1 aa:bb:cc:00:00:0b,cc:dd:ee:00:00:0c''\n  B (spoof resolved)    alerts=1  state=''''  <- cleared\n  C (spoof RETURNS)     alerts=2  <- re-alerted, not swallowed\n","metadata":{"output":"  A (spoof present)     alerts=1  state=''10.3.0.1 aa:bb:cc:00:00:0b,cc:dd:ee:00:00:0c''\n  B (spoof resolved)    alerts=1  state=''''  <- cleared\n  C (spoof RETURNS)     alerts=2  <- re-alerted, not swallowed\n","exit":0,"truncated":false},"title":"cd /tmp/at\nexport BDE_ARPWATCH_LOG=/tmp/at/scan.log BDE_ALERT=/tmp/at/count.py\nS=/home/livings/Projects/zen-hardening/arpwatch-spoof-scan.sh\nprintf ''aa:bb:cc:00:00:0b 10.3.0.1 1\\ncc:dd:ee:00:00:0c 10.3.0.1 2\\n'' > e1.dat\nrm -f /tmp/at/est; : > /tmp/at/alerts.log\nBDE_ARP_DATAFILE=/tmp/at/e1.dat BDE_ARP_STATE=/tmp/at/est \"$S\" >/dev/null 2>&1\necho \"  A (spoof present)     alerts=$(wc -l < alerts.log)  state=''$(cat est)''\"\nprintf ''aa:bb:cc:00:00:0b 10.3.0.1 1\\n'' > e1.dat\nBDE_ARP_DATAFILE=/tmp/at/e1.dat BDE_ARP_STATE=/tmp/at/est \"$S\" >/dev/null 2>&1\necho \"  B (spoof resolved)    alerts=$(wc -l < alerts.log)  state=''$(cat est)''  <- cleared\"\nprintf ''cc:dd:ee:00:00:0c 10.3.0.1 2\\ndd:ee:ff:00:00:0d 10.3.0.1 3\\n'' > e1.dat\nBDE_ARP_DATAFILE=/tmp/at/e1.dat BDE_ARP_STATE=/tmp/at/est \"$S\" >/dev/null 2>&1\necho \"  C (spoof RETURNS)     alerts=$(wc -l < alerts.log)  <- re-alerted, not swallowed\"","time":{"start":1790457285744,"end":1790457285999}}}');
