en-hardening/arpwatch-spoof-scan.sh\"\n+UNIT_DST_DIR=/etc/systemd/system\n \n run() { if [ \"$DRY\" = 1 ]; then echo \"  [dry-run] $*\"; else \"$@\"; fi; }\n \n echo \"=== arpwatch spoof detection installer ===\"\n","additions":2,"deletions":0},"truncated":false},"title":"home/livings/Projects/zen-hardening/install-arpwatch-spoof.sh","time":{"start":1790457288163,"end":1790457288173}}}');
