atch\n  [dry-run] sudo install -m 0644 -o root -g root /dev/null /var/lib/arpwatch/arp.dat\n    existing /var/log/arpwatch-spoof.log preserved\n\n=== unit ExecStart now ===\n  ExecStart=/usr/sbin/arpwatch -F -i wlo1 -f /var/lib/arpwatch/arp.dat -s -N -z\n\n=== unit verify ===\n","exit":0,"truncated":false},"title":"cd ~/Projects/zen-hardening\nenv -i HOME=/root SUDO_USER=livings PATH=\"$PATH\" TERM=dumb bash install-arpwatch-spoof.sh --dry-run 2>&1 | sed -n ''1,16p''\necho\necho \"=== unit ExecStart now ===\"\ngrep \"^ExecStart\" arpwatch-spoof.service | sed ''s/^/  /''\necho\necho \"=== unit verify ===\"\nsystemd-analyze verify arpwatch-spoof.service 2>&1 | head -3 | sed ''s/^/  /'' || echo \"  OK\"","time":{"start":1790457465873,"end":1790457465982}}}');
