ery failed\"\n      25\t    [ -n \"$out\" ] && log \"alert: $out\"\n      26\tdone <<<\"$newly\"\n      27\t\n      28\tlog \"scan: $count new anomal$( [ \"$count\" = 1 ] && echo y || echo ies)\"\n","metadata":{"output":"  39:ALERT=\"${BDE_ALERT:-$(dirname \"$HERE\")/shield-kitty/shield-kitty-alert.py}\"\n  90:    echo \"  alert    : $ALERT\"\n  182:    [ -f \"$ALERT\" ] || { log \"alert script missing at $ALERT\"; continue; }\n  183:    out=\"$(python3 \"$ALERT\" \"$payload\" 2>&1)\" || log \"alert delivery failed\"\n--- context around the alert invocation ---\n       1\t\n       2\tcount=$(printf ''%s'' \"$newly\" | grep -c .)\n       3\tbootstrap_session_env\n       4\twhile read -r ip macs; do\n       5\t    [ -n \"$ip\" ] || continue\n       6\t    n=$(awk -F, ''{print NF}'' <<<\"$macs\")\n       7\t    log \"SPOOF $ip claimed by $n MACs: $macs\"\n       8\t    payload=$(python3 - \"$ip\" \"$macs\" \"$n\" <<''PY''\n       9\timport json, sys\n      10\tip, macs, n = sys.argv[1], sys.argv[2], sys.argv[3]\n      11\tprint(json.dumps({\n      12\t    \"severity\": \"critical\",\n      13\t    \"events\": [{\n      14\t        \"label\": \"ARP spoof: {} claimed by {} MACs\".format(ip, n),\n      15\t        \"count\": 1,\n      16\t        \"sample\": \"MACs: {}. Not auto-banned: DHCP re-use and MAC randomisation \"\n      17\t                  \"look identical. Verify, then ban via the 86400s fail2ban path \"\n      18\t                  \"if real.\".format(macs),\n      19\t    }],\n      20\t}))\n      21\tPY\n      22\t)\n      23\t    [ -f \"$ALERT\" ] || { log \"alert script missing at $ALERT\"; continue; }\n      24\t    out=\"$(python3 \"$ALERT\" \"$payload\" 2>&1)\" || log \"alert delivery failed\"\n      25\t    [ -n \"$out\" ] && log \"alert: $out\"\n      26\tdone <<<\"$newly\"\n      27\t\n      28\tlog \"scan: $count new anomal$( [ \"$count\" = 1 ] && echo y || echo ies)\"\n","exit":0,"truncated":false},"title":"cd ~/Projects/zen-hardening\ngrep -n \"