$h >/dev/null 2>&1 && echo \"    [ok] $h -> $(command -v $h)\" || echo \"    [no] $h\"; done\necho\necho \"  in official repos?\"\npacman -Si torbrowser-launcher >/dev/null 2>&1 && echo \"    [ok] available in pacman\" || echo \"    [no] not in official repos (AUR only)\"\necho\necho \"  related official packages:\"\nfor p in tor firefox; do v=$(pacman -Q \"$p\" 2>/dev/null | awk ''{print $2}''); printf \"    %-12s %s\\n\" \"$p\" \"${v:-not installed}\"; done\necho\necho \"  current tor status:\"\nsystemctl is-active tor | sed ''s/^/    /''\nss -tln 2>/dev/null | grep 9050 | sed ''s/^/    /''","time":{"start":1790459130366,"end":1790459130707}}}');
