INSERT INTO part VALUES('prt_0dfae4d290011kKDKhnNsIyKKJ','msg_0dfae38a5001PuD65FJEUdF3ax','ses_f211dfcd4ffevS1Yoddwab036g',1790459137321,1790459138750,'{"type":"tool","tool":"bash","callID":"call_function_qnfbl7sryxyj_1","state":{"status":"completed","input":{"command":"echo \"═══ which repository provides torbrowser-launcher? ═══\"\npacman -Si torbrowser-launcher 2>/dev/null | grep -E ''^(Repository|Name|Version|Validated By|Signed By)'' | sed ''s/^/  /''\necho\necho \"  --- configured repos ---\"\ngrep -E ''^\\[|^Server'' /etc/pacman.conf 2>/dev/null | grep -v ''^\\s*$'' | sed ''s/^/    /'' | head -20\necho\necho \"  --- is chaotic-aur enabled? ---\"\ngrep -A2 -i chaotic /etc/pacman.conf 2>/dev/null | sed ''s/^/    /'' || echo \"    not configured\""},"output":"═══ which repository provides torbrowser-launcher? ═══\n  Repository      : extra\n  Name            : torbrowser-launcher\n  Version         : 0.3.9-1\n  Validated By    : SHA-256 Sum  Signature\n\n  --- configured repos ---\n    [options]\n    [garuda]\n    [core]\n    [extra]\n    [multilib]\n    [chaotic-aur]\n\n  --- is chaotic-aur enabled? ---\n    Include = /etc/pacman.d/chaotic-mirrorlist\n    \n    [core]\n    --\n    [chaotic-aur]\n    Include = /etc/pacman.d/chaotic-mirrorlist\n    \n    # An example of a custom package repository.  See the pacman manpage for\n","metadata":{"output":"═══ which repository provides torbrowser-launcher? ═══\n  Repository      : extra\n  Name            : torbrowser-launcher\n  Version         : 0.3.9-1\n  Validated By    : SHA-256 Sum  Signature\n\n  --- configured repos ---\n    [options]\n    [garuda]\n    [core]\n    [extra]\n    [multilib]\n    [chaotic-aur]\n\n  --- is chaotic-aur enabled? ---\n    Include = /etc/pacman.d/chaotic-mirrorlist\n    \n    [core]\n    --\n    [chaotic-aur]\n    Include = /etc/pacman.d/chaotic-mirrorlist\n    \n    # An example of a custom package repository.  See the pacman manpage for\n","exit":0,"truncated":false},"title":"echo \"═══ which repository provides torbrowser-launcher? ═══\"\npacman -Si torbrowser-launcher 2>/dev/null | grep -E ''^(Repository|Name|Version|Validated By|Signed By)'' | sed ''s/^/  /''\necho\necho \"  --- configured repos ---\"\ngrep -E ''^\\[|^Server'' /etc/pacman.conf 2>/dev/null | grep -v ''^\\s*$'' | sed ''s/^/    /'' | head -20\necho\necho \"  --- is chaotic-aur enabled? ---\"\ngrep -A2 -i chaotic /etc/pacman.conf 2>/dev/null | sed ''s/^/    /'' || echo \"    not configured\"","time":{"start":1790459138554,"end":1790459138750}}}');
