; }\ndone\n[ \"$found\" -eq 0 ] && echo \"    [!!] NONE — no browser installed at all\"\necho\necho \"  available in repos:\"\nfor p in firefox chromium; do pacman -Si $p >/dev/null 2>&1 && echo \"    [ok] $p ($(pacman -Si $p 2>/dev/null | awk ''/^Repository/{print $2}''))\"; done\necho\necho \"  ^ revoking a token needs a browser. GitHub also warns against\"\necho \"    logging in over Tor, so Tor Browser is the wrong tool for this.\"","time":{"start":1790459147380,"end":1790459148129}}}');
