s.stdin)[\"events\"][0][\"label\"].split()[-2])'')\" 3\n\nprintf ''aa:bb:cc:00:00:01 10.5.0.1 %s\\naa:bb:cc:00:00:01 10.5.0.2 %s\\n'' $NOW $NOW > /tmp/w/5.dat\nreset; run /tmp/w/5.dat; chk \"one MAC on two IPs (not a signal)\" \"$(al)\" 0\n\nprintf ''aa:bb:cc:00:00:01 127.0.0.1 %s\\ncc:dd:ee:00:00:02 127.0.0.1 %s\\n'' $NOW $NOW > /tmp/w/6.dat\nreset; run /tmp/w/6.dat; chk \"loopback ignored\" \"$(al)\" 0\n\nprintf ''aa:bb:cc:00:00:0b 10.6.0.1 %s hostA\\ncc:dd:ee:00:00:0c 10.6.0.1 %s hostB\\n'' $NOW $NOW > /tmp/w/7.dat\nreset; run /tmp/w/7.dat; chk \"hostname field parsed\" \"$(al)\" 1\n\n: > /tmp/w/8.dat; reset; run /tmp/w/8.dat; chk \"empty datafile\" \"$?\" 0\nreset; run /tmp/w/nodat.dat; chk \"missing datafile\" \"$?\" 0\n\nprintf ''dd:ee:ff:00:00:01 10.9.0.1 %s\\n11:22:33:00:00:02 10.9.0.1 %s\\n'' $NOW $NOW > /tmp/w/9.dat\nreset; run /tmp/w/9.dat env BDE_SPOOF_IGNORE=10.9.0.0/24; chk \"BDE_SPOOF_IGNORE suppresses\" \"$(al)\" 0\nchk \"  ...and is absent from state\" \"$(grep -c 10.9.0.1 /tmp/w/st 2>/dev/null || echo 0)\" 0\nreset; run /tmp/w/9.dat; chk \"un-ignoring it DOES alert (state fix)\" \"$(al)\" 1\n\nreset; run /tmp/w/3.dat; b=$(al); run /tmp/w/3.dat; chk \"dedup: no re-alert\" \"$(al)\" \"$b\"\n\nprintf ''aa:bb:cc:00:00:01 10.1.0.100 %s\\ncc:dd:ee:00:00:02 10.1.0.100 %s\\n'' $OLD $NOW > /tmp/w/10.dat\nreset; run /tmp/w/10.dat; chk \"DHCP reassignment not a spoof\" \"$(al)\" 0\n\nprintf ''garbage no timestamp here\\n'' > /tmp/w/11.dat\nreset; run /tmp/w/11.dat; chk \"malformed row does not crash\" \"$?\" 0\necho; echo \"  $p passed, $f failed\"","time":{"start":1790459260615,"end":1790459261334}}}');
