ng user''s home (got ''$TARGET_HOME'')\" >&2\n    exit 1\n}\nHOOK=\"$TARGET_HOME/Projects/zen-hardening/arpwatch-spoof-alert.sh\"\nSCAN=\"$TARGET_HOME/Projects/zen-hardening/arpwatch-spoof-scan.sh\"\nUNIT_DST_DIR=/etc/systemd/system\n\n# Keep in one place and shared with the unit via the parse-check below, so the","truncated":true,"loaded":[],"display":{"type":"file","path":"/home/livings/Projects/zen-hardening/install-arpwatch-spoof.sh","text":"# Resolve the REAL user''s home. Under sudo, $HOME is /root, so every path into\n# the user''s own ~/Projects silently becomes /root/Projects/... and the script\n# reports the hook as missing. SUDO_USER names whoever actually invoked it.\nSUDO_USER_NAME=\"${SUDO_USER:-}\"\nif [ -n \"$SUDO_USER_NAME\" ]; then\n    TARGET_HOME=\"$(getent passwd \"$SUDO_USER_NAME\" | cut -d: -f6)\"\nelse\n    TARGET_HOME=\"$HOME\"\nfi\n[ -n \"$TARGET_HOME\" ] && [ -d \"$TARGET_HOME\" ] || {\n    echo \"ERROR: cannot resolve the invoking user''s home (got ''$TARGET_HOME'')\" >&2\n    exit 1\n}\nHOOK=\"$TARGET_HOME/Projects/zen-hardening/arpwatch-spoof-alert.sh\"\nSCAN=\"$TARGET_HOME/Projects/zen-hardening/arpwatch-spoof-scan.sh\"\nUNIT_DST_DIR=/etc/systemd/system\n\n# Keep in one place and shared with the unit via the parse-check below, so the","lineStart":24,"lineEnd":41,"totalLines":178,"truncated":true}},"title":"home/livings/Projects/zen-hardening/install-arpwatch-spoof.sh","time":{"start":1790459272601,"end":1790459272612}}}');
