K  fix-sudoers-permissions.sh\n  OK  install-arpwatch-spoof.sh\n  OK  install-audit-readonly.sh\n  OK  install-faillock-admin.sh\n  OK  install-shield-kitty-units.sh\n  OK  RECOVER-SUDO.sh\n  OK  set-anon-identity.sh\n  OK  set-home-trusted-zone.sh\n  OK  unban-self.sh\n\n=== all units verify ===\n  arpwatch-spoof-scan.service      OK\n  arpwatch-spoof.service           OK\n  arpwatch-spoof-scan.timer        OK\n\n=== the manual test hook still delivers? ===\n  payload valid JSON: True\n","exit":0,"truncated":false},"title":"cd ~/Projects/zen-hardening\necho \"=== all shell scripts parse ===\"\nfor f in *.sh; do bash -n \"$f\" 2>&1 | sed \"s/^/  $f: /\" || true; bash -n \"$f\" && echo \"  OK  $f\"; done\necho\necho \"=== all units verify ===\"\nfor u in *.service *.timer; do printf \"  %-32s \" \"$u\"; o=$(systemd-analyze verify \"$u\" 2>&1 | grep -vi \"not executable\"); [ -z \"$o\" ] && echo OK || echo \"$o\"; done\necho\necho \"=== the manual test hook still delivers? ===\"\nrm -f /tmp/w/alerts.log\npython3 - <<''PY''\nimport json,subprocess,sys\npayload=json.dumps({\"severity\":\"critical\",\"events\":[{\"label\":\"test\",\"count\":1,\"sample\":\"s\"}]})\nprint(\"  payload valid JSON:\", bool(json.loads(payload)))\nPY\nBDE_ALERT=./arpwatch-spoof-alert.sh ./arpwatch-spoof-alert.sh 2>&1 | tail -3 | sed ''s/^/  /''","time":{"start":1790459288161,"end":1790459288420}}}');
