INSERT INTO part VALUES('prt_0dfb10e5e001cc7908NILiL2Qm','msg_0dfb1092d001ri7j7FO6OVk6at','ses_f20e5cfc2ffeSFa4odnoYLiUOk',1790459317854,1790459323187,'{"type":"text","text":"Notification path confirmed working. Let me commit the audit fixes:","time":{"start":1790459317854,"end":1790459323187}}');
INSERT INTO part VALUES('prt_0dfb10ec80014JM6Cyqen13xDR','msg_0dfb1092d001ri7j7FO6OVk6at','ses_f20e5cfc2ffeSFa4odnoYLiUOk',1790459317960,1790459323204,'{"type":"tool","tool":"bash","callID":"call_function_ljruwvu5i951_1","state":{"status":"completed","input":{"command":"cd ~/Projects/zen-hardening\ngit add -A\ngit commit -q -m \"fix: scanner read arp.dat as current state, but it is append-only history\n\nAudit pass over the arpwatch work. Four real defects, one of them serious.\n\nCRITICAL -- permanent false positives on ordinary DHCP reassignment.\n\narpwatch only ever ADDS a row to arp.dat, the first time it sees a mac/ip pair,\nand never removes one. So a single routine lease change leaves this forever:\n\n    10.197.250.100  aa:bb:cc:00:00:01   <- laptop A, yesterday\n    10.197.250.100  cc:dd:ee:00:00:02   <- laptop B, today\n\nThe scanner compared every MAC it had ever seen for an IP, so it called that a\nspoof, alerted once, and then reported ''persists'' on every scan forever. On a\n/8 with constant lease churn this fires on innocent devices, and a monitor that\ncries wolf gets ignored. Fixed with a 1h window (BDE_SPOOF_WINDOW) over the\ntimestamp field, which arpwatch already writes: a historical change ages out, a\nlive conflict is inside the window.\n\nThe trade-off is real and documented rather than hidden: arpwatch does not\nre-append a pair it already knows, so a *continuing* spoof is only visible for\nWINDOW seconds after first sighting. The datafile cannot distinguish ''still\nspoofing'' from ''seen once''. Window set generously to favour catching attacks;\narpwatch''s own flip-flop reports keep going to the journal regardless.\n\nAlso fixed: ignored addresses were written into the state file, so if one was\never recorded under BDE_SPOOF_IGNORE and the ignore later removed, it matched\nas ''persists'' and could never alert at all. State now holds only what is\nactually being reported.\n\nInstaller: the probe used two separate mktemp -u calls, so only the datafile''s\ndirectory was cleaned up -- under root, where the probe really runs, arpwatch\nwrote the pidfile and orphaned a directory per install. Now one mktemp -d\nshared by both paths (-u also races, since it only prints a name).\n\nInstaller: units hardcode /run/user/1000 for the session bus while the\ninstaller carefully resolved SUDO_USER for the home path, so it was user-aware\nin one place and hardcoded in another. Both are now derived and rewritten.\n\nVerified 16/16 including the two cases that were broken: DHCP reassignment\n(now silent) and un-ignoring a previously ignored address (now alerts). All\nscripts parse, all three units pass systemd-analyze verify, no temp-dir leak,\nidentity rewriting checked against a simulated second user, and the notify path\nconfirmed live via --test-notify.\"\ngit log --oneline | head -1"},"output":"3efc51f fix: scanner read arp.dat as current state, but it is append-only history\n","metadata":{"output":"3efc51f fix: scanner read arp.dat as current state, but it is append-only history\n","exit":0,"truncated":false},"title":"cd ~/Projects/zen-hardening\ngit add -A\ngit commit -q -m \"fix: scanner read arp.dat as current state, but it is append-only history\n\nAudit pass over the arpwatch work. Four real defects, one of them serious.\n\nCRITICAL -- permanent false positives on ordinary DHCP reassignment.\n\narpwatch only ever ADDS a row to arp.dat, the first time it sees a mac/ip pair,\nand never removes one. So a single routine lease change leaves this forever:\n\n    10.197.250.100  aa:bb:cc:00:00:01   <- laptop A, yesterday\n    10.197.250.100  cc:dd:ee:00:00:02   <- laptop B, today\n\nThe scanner compared every MAC it had ever seen for an IP, so it called that a\nspoof, alerted once, and then reported ''persists'' on every scan forever. On a\n/8 with constant lease churn this fires on innocent devices, and a monitor that\ncries wolf gets ignored. Fixed with a 1h window (BDE_SPOOF_WINDOW) over the\ntimestamp field, which arpwatch already writes: a historical change ages out, a\nlive conflict is inside the window.\n\nThe trade-off is real and documented rather than hidden: arpwatch does not\nre-append a pair it already knows, so a *continuing* spoof is only visible for\nWINDOW seconds after first sighting. The datafile cannot distinguish ''still\nspoofing'' from ''seen once''. Window set generously to favour catching attacks;\narpwatch''s own flip-flop reports keep going to the journal regardless.\n\nAlso fixed: ignored addresses were written into the state file, so if one was\never recorded under BDE_SPOOF_IGNORE and the ignore later removed, it matched\nas ''persists'' and could never alert at all. State now holds only what is\nactually being reported.\n\nInstaller: the probe used two separate mktemp -u calls, so only the datafile''s\ndirectory was cleaned up -- under root, where the probe really runs, arpwatch\nwrote the pidfile and orphaned a directory per install. Now one mktemp -d\nshared by both paths (-u also races, since it only prints a name).\n\nInstaller: units hardcode /run/user/1000 for the session bus while the\ninstaller carefully resolved SUDO_USER for the home path, so it was user-aware\nin one place and hardcoded in another. Both are now derived and rewritten.\n\nVerified 16/16 including the two cases that were broken: DHCP reassignment\n(now silent) and un-ignoring a previously ignored address (now alerts). All\nscripts parse, all three units pass systemd-analyze verify, no temp-dir leak,\nidentity rewriting checked against a simulated second user, and the notify path\nconfirmed live via --test-notify.\"\ngit log --oneline | head -1","time":{"start":1790459323179,"end":1790459323203}}}');
