rep -rIl --exclude-dir=.git -iE \"token interface|token ui|tokenui\" . 2>/dev/null | sed ''s/^/  /'' | head -10 || echo \"  none\"\necho\necho \"=== opencode config: is there a token-related command/agent? ===\"\nls ~/.config/opencode/ 2>/dev/null | sed ''s/^/  /''","time":{"start":1790459393145,"end":1790459395090}}}');
