}\"\n       6\t\n       7\tif [[ \"${1:-}\" == \"--remove\" ]]; then\n       8\t  echo \"Removing audit helpers...\"\n       9\t  rm -f \"$SUDOERS_FILE\"\n      10\t  for h in \"${HELPERS[@]}\"; do rm -f \"/usr/local/sbin/$h\"; done\n      11\t  echo \"  [ok] removed. Verify with: sudo -l\"\n\n  --- simulated: what would each script target under pkexec? ---\n  install-arpwatch-spoof.sh      under pkexec -> TARGET_HOME=/root, TARGET_UID=0\n  install-shield-kitty-units.sh  under pkexec -> ACCOUNT=livings, SRC=$HOME=/root/...\n  install-audit-readonly.sh      under pkexec -> grants NOPASSWD to ''root'' (useless)\n","exit":0,"truncated":false},"title":"cd /home/livings/Projects/zen-hardening\necho \"═══ how is SUDO_USER_NAME actually derived? (install-audit-readonly.sh:40-50) ═══\"\nsed -n ''40,50p'' install-audit-readonly.sh | cat -n | sed ''s/^/  /''\necho\necho \"  --- simulated: what would each script target under pkexec? ---\"\nsim(){ # $1=script $2=what it derives\n  printf \"  %-30s under pkexec -> %s\\n\" \"$1\" \"$2\"\n}\nsim \"install-arpwatch-spoof.sh\" \"TARGET_HOME=/root, TARGET_UID=0\"\nsim \"install-shield-kitty-units.sh\" \"ACCOUNT=livings, SRC=\\$HOME=/root/...\"\nsim \"install-audit-readonly.sh\" \"grants NOPASSWD to ''root'' (useless)\"","time":{"start":1790459437668,"end":1790459437679}}}');
