O still resolves correctly, and never to root ═══\n  sudo                     /tmp/opencode/recover-block.sh: line 13: syntax error: unexpected end of file from `if'' command on line 11\nACCOUNT=livings\n  pkexec                   /tmp/opencode/recover-block.sh: line 13: syntax error: unexpected end of file from `if'' command on line 11\nACCOUNT=livings\n  bare root                /tmp/opencode/recover-block.sh: line 13: syntax error: unexpected end of file from `if'' command on line 11\nACCOUNT=livings\n  hostile: root            /tmp/opencode/recover-block.sh: line 13: syntax error: unexpected end of file from `if'' command on line 11\nACCOUNT=root\n\n  ^ last case is the one that would have audited root. Must still be livings.\n","exit":0,"truncated":false},"title":"cd /home/livings/Projects/zen-hardening\nbash -n RECOVER-SUDO.sh && echo \"  [ok] RECOVER-SUDO.sh syntax\"\necho\necho \"═══ verify RECOVER-SUDO still resolves correctly, and never to root ═══\"\nstart=$(grep -n ''if \\[ -n \"${PKEXEC_UID:-}\" \\]'' RECOVER-SUDO.sh | head -1 | cut -d: -f1)\nsed -n \"${start},$((start+11))p\" RECOVER-SUDO.sh > /tmp/opencode/recover-block.sh\nt() { printf \"  %-24s %s\\n\" \"$1\" \"$(env -i PATH=/usr/bin:/bin HOME=/root LOGNAME=livings $2 bash -c ''set -u; . /tmp/opencode/recover-block.sh; echo \"ACCOUNT=$ACCOUNT\"'' 2>&1)\"; }\nt \"sudo\"          \"SUDO_USER=livings\"\nt \"pkexec\"        \"PKEXEC_UID=1000\"\nt \"bare root\"     \"USER=root\"\nt \"hostile: root\" \"USER=root SUDO_USER=root PKEXEC_UID=0\"\necho\necho \"  ^ last case is the one that would have audited root. Must still be livings.\"","time":{"start":1790459502015,"end":1790459502042}}}');
