cho \"  [ok] extracted block parses cleanly (14 lines)\" || echo \"  [FAIL] still bad\"\necho\necho \"═══ executing the real block, four invocations ═══\"\nt() { printf \"  %-26s %s\\n\" \"$1\" \"$(env -i PATH=/usr/bin:/bin HOME=/root LOGNAME=livings $2 bash -c ''. /tmp/opencode/recover-block.sh; echo \"ACCOUNT=$ACCOUNT\"'' 2>&1 | tail -1)\"; }\nt \"sudo\"                \"SUDO_USER=livings\"\nt \"pkexec\"              \"PKEXEC_UID=1000\"\nt \"bare root\"           \"USER=root\"\nt \"hostile PKEXEC_UID=0\" \"PKEXEC_UID=0 USER=root\"\necho\necho \"  every row must be livings; a ''root'' row means it would audit root.\"","time":{"start":1790459512067,"end":1790459512105}}}');
