INSERT INTO part VALUES('prt_0dfb7bdfa001i25FUek33tbuqw','msg_0dfb7b5af001MQBOFEbPmTtlxC','ses_f20e5cfc2ffeSFa4odnoYLiUOk',1790459756026,1790459756749,'{"type":"reasoning","text":"The \"alert log line present\" test got 6 instead of 1. That''s because the log file accumulates across all the test runs in the suite (I only reset alerts.log, not scan.log). So there were 5 prior \"alert delivered ok\" lines plus this one = 6.\n\nThat''s a harness artifact, not a bug. Let me verify by resetting the log too.\n\nLet me re-check that single case with a clean log.","time":{"start":1790459756026,"end":1790459756747}}');
