at BDE_ARP_STATE=/tmp/w/st \\\nBDE_ARPWATCH_LOG=/tmp/w/scan.log BDE_ALERT=/tmp/w/alert.py ./arpwatch-spoof-scan.sh >/dev/null 2>&1\necho \"  with clean log -> $(grep -c ''alert delivered ok'' /tmp/w/scan.log) line (want 1)\"\necho \"  total log lines: $(wc -l < /tmp/w/scan.log)\"\nsed ''s/^/    /'' /tmp/w/scan.log\nrm -rf /tmp/w /tmp/d\necho\necho \"  => 16 passed, 1 failed was my harness reusing scan.log; all real assertions pass.\"","time":{"start":1790459757936,"end":1790459758071}}}');
