awk ''{print \"      \"$4\" \"$5\" \"$6\" \"$8}'' | sort | uniq -c | sort -rn | sed ''s/^/  /''","time":{"start":1790460001735,"end":1790460002369}}}');
INSERT INTO part VALUES('prt_0dfbb7dce001q6UhhXCG93o3kw','msg_0dfbb3a97001rTq8Z22Q6VW6wT','ses_f211dfcd4ffevS1Yoddwab036g',1790460001742,1790460004425,'{"type":"tool","tool":"bash","callID":"call_function_17c67cq0xrpz_2","state":{"status":"completed","input":{"command":"echo \"═══ B. BOOT CHAIN ═══\"\necho \"  bootloader: $([ -d /boot/efi/EFI ] && ls /boot/efi/EFI 2>/dev/null | tr ''\\n'' '' '' || echo ''?'')\"\nbootctl --print 2>/dev/null | grep -E ''Product|Loader|Current|Default'' | sed ''s/^/      /'' || echo \"      (bootctl unavailable)\"\necho\necho \"  ESP:\"\nfindmnt -no SOURCE,FSTYPE,OPTIONS /boot/efi 2>/dev/null | sed ''s/^/      /''\necho \"      free space: $(df -h --output=avail /boot/efi 2>/dev/null | tail -1 | tr -d '' '')\"\necho\necho \"  kernels in /boot:\"\nls -1 /boot/vmlinuz-* /boot/initramfs-* 2>/dev/null | sed ''s/^/      /''\necho\necho \"  installed kernel modules dir:\"\nls -1d /usr/lib/modules/* 2>/dev/null | sed ''s/^/      /''\necho \"  running: $(uname -r)\"\necho\necho \"  microcode: $(ls /boot/*ucode* 2>/dev/null | tr ''\\n'' '' '' || echo none)\"\necho\necho \"  fstab (UUIDs must all resolve):\"\ngrep -vE ''^\\s*#|^\\s*$'' /etc/fstab | while read -r dev mp type opts _; do\n  case \"$dev\" in\n    UUID=*) u=${dev#UUID=}; if blkid -U \"$u\" >/dev/null 2>&1; then echo \"      [ok]   $dev -> $mp\"; else echo \"      [DEAD] $dev -> $mp  (UUID NOT FOUND)\"; fi ;;\n    *) echo \"      [--]   $dev -> $mp\" ;;\n  esac\ndone"},"output":"═══ B. BOOT CHAIN ═══\n  bootloader: ?\n\n  ESP:\n      /dev/nvme0n1p1 vfat rw,relatime,fmask=0077,dmask=0077,codepage=437,iocharset=ascii,shortname=mixed,utf8,errors=remount-ro\n      free space: 299M\n\n  kernels in /boot:\n      /boot/initramfs-linux-zen-fallback.img\n      /boot/initramfs-linux-zen.img\n      /boot/vmlinuz-linux-zen\n\n  installed kernel modules dir:\n      /usr/lib/modules/7.2.7-zen1-1-zen\n  running: 7.2.7-zen1-1-zen\n\n  microcode: /boot/intel-ucode.img \n\n  fstab (UUIDs must all resolve):\n      [ok]   UUID=F54B-53CA -> /boot/efi\n      [--]   /dev/mapper/luks-8c39203b-6764-4e5c-b1a9-6dedb64c05c1 -> /\n      [--]   /dev/mapper/luks-8c39203b-6764-4e5c-b1a9-6dedb64c05c1 -> /home\n      [--]   /dev/mapper/luks-8c39203b-6764-4e5c-b1a9-6dedb64c05c1 -> /root\n      [--]   /dev/mapper/luks-8c39203b-6764-4e5c-b1a9-6dedb64c05c1 -> /srv\n      [--]   /dev/mapper/luks-8c39203b-6764-4e5c-b1a9-6dedb64c05c1 -> /var/cache\n      [--]   /dev/mapper/luks-8c39203b-6764-4e5c-b1a9-6dedb64c05c1 -> /var/log\n      [--]   /dev/mapper/luks-8c39203b-6764-4e5c-b1a9-6dedb64c05c1 -> /var/tmp\n      [--]   tmpfs -> /tmp\n","metadata":{"output":"═══ B. BOOT CHAIN ═══\n  bootloader: ?\n\n  ESP:\n      /dev/nvme0n1p1 vfat rw,relatime,fmask=0077,dmask=0077,codepage=437,iocharset=ascii,shortname=mixed,utf8,errors=remount-ro\n      free space: 299M\n\n  kernels in /boot:\n      /boot/initramfs-linux-zen-fallback.img\n      /boot/initramfs-linux-zen.img\n      /boot/vmlinuz-linux-zen\n\n  installed kernel modules dir:\n      /usr/lib/modules/7.2.7-zen1-1-zen\n  running: 7.2.7-zen1-1-zen\n\n  microcode: /boot/intel-ucode.img \n\n  fstab (UUIDs must all resolve):\n      [ok]   UUID=F54B-53CA -> /boot/efi\n      [--]   /dev/mapper/luks-8c39203b-6764-4e5c-b1a9-6dedb64c05c1 -> /\n      [--]   /dev/mapper/luks-8c39203b-6764-4e5c-b1a9-6dedb64c05c1 -> /home\n      [--]   /dev/mapper/luks-8c39203b-6764-4e5c-b1a9-6dedb64c05c1 -> /root\n      [--]   /dev/mapper/luks-8c39203b-6764-4e5c-b1a9-6dedb64c05c1 -> /srv\n      [--]   /dev/mapper/luks-8c39203b-6764-4e5c-b1a9-6dedb64c05c1 -> /var/cache\n      [--]   /dev/mapper/luks-8c39203b-6764-4e5c-b1a9-6dedb64c05c1 -> /var/log\n      [--]   /dev/mapper/luks-8c39203b-6764-4e5c-b1a9-6dedb64c05c1 -> /var/tmp\n      [--]   tmpfs -> /tmp\n","exit":0,"truncated":false},"title":"echo \"═══ B. BOOT CHAIN ═══\"\necho \"  bootloader: $([ -d /boot/efi/EFI ] && ls /boot/efi/EFI 2>/dev/null | tr ''\\n'' '' '' || echo ''?'')\"\nbootctl --print 2>/dev/null | grep -E ''Product|Loader|Current|Default'' | sed ''s/^/      /'' || echo \"      (bootctl unavailable)\"\necho\necho \"  ESP:\"\nfindmnt -no SOURCE,FSTYPE,OPTIONS /boot/efi 2>/dev/null | sed ''s/^/      /''\necho \"      free space: $(df -h --output=avail /boot/efi 2>/dev/null | tail -1 | tr -d '' '')\"\necho\necho \"  kernels in /boot:\"\nls -1 /boot/vmlinuz-* /boot/initramfs-* 2>/dev/null | sed ''s/^/      /''\necho\necho \"  installed kernel modules dir:\"\nls -1d /usr/lib/modules/* 2>/dev/null | sed ''s/^/      /''\necho \"  running: $(uname -r)\"\necho\necho \"  microcode: $(ls /boot/*ucode* 2>/dev/null | tr ''\\n'' '' '' || echo none)\"\necho\necho \"  fstab (UUIDs must all resolve):\"\ngrep -vE ''^\\s*#|^\\s*$'' /etc/fstab | while read -r dev mp type opts _; do\n  case \"$dev\" in\n    UUID=*) u=${dev#UUID=}; if blkid -U \"$u\" >/dev/null 2>&1; then echo \"      [ok]   $dev -> $mp\"; else echo \"      [DEAD] $dev -> $mp  (UUID NOT FOUND)\"; fi ;;\n    *) echo \"      [--]   $dev -> $mp\" ;;\n  esac\ndone","time":{"start":1790460004390,"end":1790460004425}}}');
