dows RDP              |xrdp,freerdp                                             |3389\"\n  \"TeamViewer               |teamviewer                                              |5938\"\n  \"AnyDesk                  |anydesk                                                 |7070\"\n  \"NoMachine                 |nomachine                                               |4000\"","truncated":true,"loaded":[],"display":{"type":"file","path":"/home/livings/Projects/zen-hardening/block-remote-viewing.sh","text":"#\n# Usage:\n#   ./block-remote-viewing.sh --check    # report, change nothing\n#   sudo ./block-remote-viewing.sh      # apply, reload, verify\n\nset -euo pipefail\n\nZONE=\"${FIREWALLD_ZONE:-workstation}\"\nRUN=1\n[ \"${1:-}\" = \"--check\" ] && RUN=0\n\nlog() { printf ''  %s\\n'' \"$*\"; }\n\n# description|tools|ports (space separated; ranges allowed)\nGROUPS=(\n  \"VNC/RFB remote desktop   |x11vnc,tigervnc,realvnc,tightvnc,krfb,vino            |5900-5910 5800-5810 5500\"\n  \"Windows RDP              |xrdp,freerdp                                             |3389\"\n  \"TeamViewer               |teamviewer                                              |5938\"\n  \"AnyDesk                  |anydesk                                                 |7070\"\n  \"NoMachine                 |nomachine                                               |4000\"","lineStart":30,"lineEnd":49,"totalLines":123,"truncated":true}},"title":"home/livings/Projects/zen-hardening/block-remote-viewing.sh","time":{"start":1790460452807,"end":1790460452834}}}');
