INSERT INTO part VALUES('prt_0dfc33b4d001cow00Ck7zfI760','msg_0dfc2f4a0001gUC96iVPHZaHyv','ses_f20e5cfc2ffeSFa4odnoYLiUOk',1790460509005,1790460513202,'{"type":"text","text":"Found it. **`GROUPS` is a bash builtin readonly array** holding your group IDs — `livings(1000), realtime(983), video(989), lp(992), input(998), wheel(967)`. Six values, exactly what showed up. My array assignment was silently discarded and the builtin read instead. Renaming:","time":{"start":1790460509005,"end":1790460513202}}');
